def _encode_column_to_binary(series: pd.Series) -> pd.Series:
    """Map boolean-like values to 0/1 without wiping already-numeric 0/1 columns.

    The old path used astype(str).map({...}) which turns float 1.0 → "1.0"
    (not in the map) → NaN for every row.
    """
    BOOL_MAP = {
        "true": 1, "false": 0, "1": 1, "0": 0, "t": 1, "f": 0,
        "yes": 1, "no": 0, "vrai": 1, "faux": 0, "oui": 1, "non": 0,
        "y": 1, "n": 0,
    }

    def _one(v):
        if v is None:
            return None
        try:
            if pd.isna(v):
                return None
        except (TypeError, ValueError):
            pass
        if isinstance(v, (bool, np.bool_)):
            return int(bool(v))
        # Numeric 0/1 (int, float, numpy scalars) — keep as int
        if isinstance(v, (int, np.integer)) and not isinstance(v, (bool, np.bool_)):
            if int(v) in (0, 1):
                return int(v)
        if isinstance(v, (float, np.floating)):
            if float(v) in (0.0, 1.0):
                return int(v)
        s = str(v).strip().lower()
        if s in ("", "nan", "none", "null", "na", "n/a", "nat"):
            return None
        # "1.0" / "0.0"
        if s.endswith(".0") and s[:-2].lstrip("+-").isdigit():
            s = s[:-2]
        if s in BOOL_MAP:
            return BOOL_MAP[s]
        # Last resort: numeric parse
        try:
            fv = float(s)
            if fv in (0.0, 1.0):
                return int(fv)
        except (TypeError, ValueError):
            pass
        return None

    return series.map(_one)


def _normalize_category_key(v):
    """Normalize category values so PG 'true' matches pandas True → 'True' → 'true'.

    Without this, Label Encoding builds mapping from CAST(... AS TEXT) = 'true'/'false'
    but applies via Series.astype(str) which yields 'True'/'False' → all NaN → empty dataset.
    """
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except (TypeError, ValueError):
        pass
    if isinstance(v, (bool, np.bool_)):
        return "true" if bool(v) else "false"
    if isinstance(v, (int, np.integer)) and not isinstance(v, (bool, np.bool_)):
        return str(int(v))
    if isinstance(v, (float, np.floating)):
        if float(v).is_integer():
            return str(int(v))
        return str(float(v))
    s = str(v).strip().lower()
    if s in ("", "nan", "none", "null", "na", "n/a", "nat"):
        return None
    if s in ("true", "t", "yes", "y", "vrai", "oui"):
        return "true"
    if s in ("false", "f", "no", "n", "faux", "non"):
        return "false"
    if s.endswith(".0") and s[:-2].lstrip("+-").isdigit():
        return s[:-2]
    return s


