connection_pool = None

def init_connection_pool():
    global connection_pool
    if connection_pool is None:
        connection_pool = SimpleConnectionPool(
            minconn=1,
            maxconn=10,
            **DB_CONFIG
        )






@contextmanager
def get_db_connection():
    global connection_pool
    if connection_pool is None:
        raise RuntimeError("Connection pool is not initialized.")
    conn = None
    try:
        conn = connection_pool.getconn()
        yield conn  # Now yielding the connection directly
    finally:
        if conn:
            connection_pool.putconn(conn)


def normalize_dataset_name(name: str) -> str:
    """
    Normalize a user-provided dataset name for storage as a table name:
    lowercase, spaces -> underscores, collapse/trim underscores.
    """
    if not name:
        return ""
    s = str(name).strip().lower()
    s = re.sub(r"\s+", "_", s)
    s = re.sub(r"_+", "_", s)
    s = s.strip("_")
    return s


def validate_normalized_dataset_name(normalized: str) -> None:
    """Raise HTTPException(400) if normalized name is invalid for storage."""
    if not normalized:
        raise HTTPException(status_code=400, detail="Invalid dataset name")
    if normalized[0].isdigit():
        raise HTTPException(
            status_code=400,
            detail="Dataset name cannot start with a number. Please start with a letter.",
        )
    if not re.match(r"^[a-z_][a-z0-9_]{0,49}$", normalized):
        raise HTTPException(
            status_code=400,
            detail="Invalid dataset name. After cleanup, only letters, numbers and underscores are allowed (max 50 characters), and it must start with a letter.",
        )
    reserved = {"null", "undefined", "select", "insert", "delete", "update", "drop", "create"}
    if normalized in reserved:
        raise HTTPException(status_code=400, detail="This name is reserved and cannot be used")


# Safe SQL identifiers for user-provided column names (upload / save-to-db)
_COLUMN_NAME_RE = re.compile(r"^[a-zA-Z_][a-zA-Z0-9_]{0,62}$")
_RESERVED_COLUMN_NAMES = {"id"}


def validate_column_name(col_name: str) -> None:
    """Raise HTTPException(400) if a column name is unsafe for SQL identifiers."""
    if col_name is None or str(col_name).strip() == "":
        raise HTTPException(status_code=400, detail="Column name cannot be empty")
    name = str(col_name).strip()
    if name.lower() in _RESERVED_COLUMN_NAMES:
        raise HTTPException(
            status_code=400,
            detail="Column name 'id' is reserved. Please rename that column.",
        )
    if not _COLUMN_NAME_RE.match(name):
        raise HTTPException(
            status_code=400,
            detail=(
                f"Invalid column name '{name}'. "
                "Use only letters, numbers and underscores; "
                "must start with a letter or underscore (max 63 characters)."
            ),
        )


def validate_column_names(columns: list) -> None:
    """Validate all column names and reject duplicates (case-insensitive)."""
    seen = set()
    for col_name in columns:
        validate_column_name(col_name)
        key = str(col_name).strip().lower()
        if key in seen:
            raise HTTPException(
                status_code=400,
                detail=f"Duplicate column name '{col_name}'. Column names must be unique.",
            )
        seen.add(key)


_TABLE_IDENT_RE = re.compile(r"^[a-z_][a-z0-9_]{0,62}$")


def normalize_table_ident(name: str) -> str:
    """Normalize and validate a PostgreSQL table identifier (lowercase)."""
    if name is None or str(name).strip() == "":
        raise HTTPException(status_code=400, detail="Table name is required")
    table = str(name).strip().lower()
    if not _TABLE_IDENT_RE.match(table):
        raise HTTPException(status_code=400, detail="Invalid table name")
    return table


def user_owns_table(cur, table_name: str, user_id: str) -> bool:
    cur.execute(
        """
        SELECT 1 FROM user_tables_metadata
        WHERE table_name = %s AND owner_id = %s
        """,
        (table_name, user_id),
    )
    return cur.fetchone() is not None


def physical_table_exists(cur, table_name: str) -> bool:
    cur.execute(
        """
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = %s
        """,
        (table_name,),
    )
    return cur.fetchone() is not None


def assert_owns_table(cur, table_name: str, user_id: str, *, label: str = "table") -> str:
    table_name = normalize_table_ident(table_name)
    if not user_owns_table(cur, table_name, user_id):
        raise HTTPException(status_code=403, detail=f"Access denied to {label}")
    return table_name


def assert_reset_copy_access(cur, source_db: str, target_db: str, user_id: str):
    """
    Source must be owned. Target must be owned, or (if it does not exist yet)
    must be a safe aux name (_reset/_backup/_numerized) derived from an owned base.
    Returns normalized (source_table, target_table).
    """
    source_table = normalize_table_ident(source_db)
    target_table = normalize_table_ident(target_db)

    if not user_owns_table(cur, source_table, user_id):
        raise HTTPException(status_code=403, detail="Access denied to source table")

    if user_owns_table(cur, target_table, user_id):
        return source_table, target_table

    if physical_table_exists(cur, target_table):
        raise HTTPException(status_code=403, detail="Access denied to target table")

    bases = {source_table}
    for suf in ("_reset", "_backup", "_numerized"):
        if source_table.endswith(suf):
            bases.add(source_table[: -len(suf)])

    allowed_new = set()
    for base in bases:
        if not base:
            continue
        allowed_new.add(f"{base}_reset")
        allowed_new.add(f"{base}_backup")
        allowed_new.add(f"{base}_numerized")

    if target_table not in allowed_new:
        raise HTTPException(status_code=403, detail="Access denied to target table")

    return source_table, target_table


def physical_columns(cur, table_name: str) -> list:
    cur.execute(
        """
        SELECT column_name
        FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = %s
        ORDER BY ordinal_position
        """,
        (table_name,),
    )
    return [row[0] for row in cur.fetchall()]


def replace_table_from(cur, source_table: str, target_table: str) -> int:
    """
    Drop target and recreate it as a full copy of source (schema + data).
    Safe when column count/names changed (e.g. one-hot 4 → 6).
    """
    if not physical_table_exists(cur, source_table):
        raise HTTPException(status_code=404, detail=f"Source table '{source_table}' not found")
    cur.execute(
        sql.SQL("DROP TABLE IF EXISTS {} CASCADE").format(sql.Identifier(target_table))
    )
    cur.execute(
        sql.SQL("CREATE TABLE {} AS SELECT * FROM {}").format(
            sql.Identifier(target_table),
            sql.Identifier(source_table),
        )
    )
    cur.execute(sql.SQL("SELECT COUNT(*) FROM {}").format(sql.Identifier(target_table)))
    return cur.fetchone()[0] or 0


def _json_or_default(value, default="[]"):
    import json as _json
    if value is None:
        return default
    if isinstance(value, (dict, list)):
        return _json.dumps(value)
    return value


def upsert_metadata_from_source(cur, source_table: str, target_table: str, user_id: str) -> None:
    """
    Copy pipeline metadata from source_table → target_table for this owner.
    columns always taken from the physical target table after clone.
    """
    cols = physical_columns(cur, target_table)
    cur.execute(
        """
        SELECT target_column, model_type, applied_actions, stage,
               modification_history, dataset_info
        FROM user_tables_metadata
        WHERE table_name = %s AND owner_id = %s
        """,
        (source_table, user_id),
    )
    row = cur.fetchone()
    if row:
        target_column, model_type, applied_actions, stage, modification_history, dataset_info = row
        applied_actions = _json_or_default(applied_actions, "[]")
        modification_history = _json_or_default(modification_history, "[]")
        stage = stage or "group_optimizer"
    else:
        target_column = None
        model_type = None
        applied_actions = "[]"
        modification_history = "[]"
        stage = "group_optimizer"
        dataset_info = None

    if _meta_row_exists(cur, target_table, user_id):
        cur.execute(
            """
            UPDATE user_tables_metadata
            SET
                columns = %s,
                target_column = %s,
                model_type = %s,
                applied_actions = %s,
                stage = %s,
                modification_history = %s,
                dataset_info = %s,
                updated_at = NOW()
            WHERE table_name = %s AND owner_id = %s
            """,
            (
                cols,
                target_column,
                model_type,
                applied_actions,
                stage,
                modification_history,
                dataset_info,
                target_table,
                user_id,
            ),
        )
    else:
        cur.execute(
            """
            INSERT INTO user_tables_metadata
                (table_name, owner_id, columns, target_column, model_type,
                 applied_actions, stage, modification_history, dataset_info,
                 created_at, updated_at)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, NOW(), NOW())
            """,
            (
                target_table,
                user_id,
                cols,
                target_column,
                model_type,
                applied_actions,
                stage,
                modification_history,
                dataset_info,
            ),
        )


def ensure_checkpoint_exists(cur, base_table: str, user_id: str) -> str:
    """Ensure {base}_reset exists; create from base if missing."""
    reset_table = f"{base_table}_reset"
    if not physical_table_exists(cur, reset_table):
        replace_table_from(cur, base_table, reset_table)
        upsert_metadata_from_source(cur, base_table, reset_table, user_id)
    return reset_table


@router.post("/dataset/save-checkpoint")
async def dataset_save_checkpoint(
    source_db: str = Body(..., embed=True),
    current_user_id: str = Depends(get_current_user2),
):
    """
    Save: overwrite {bd}_reset with current working table (schema+data+metadata).
    Handles column add/rename/drop (DROP + CREATE AS).
    """
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            base = assert_owns_table(cur, source_db, current_user_id, label="dataset")
            if not physical_table_exists(cur, base):
                raise HTTPException(status_code=404, detail="Working dataset table not found")
            reset_table = f"{base}_reset"
            rows = replace_table_from(cur, base, reset_table)
            upsert_metadata_from_source(cur, base, reset_table, current_user_id)
            conn.commit()
            return {
                "status": "success",
                "action": "checkpoint_saved",
                "message": "Checkpoint saved: reset copy updated from current dataset.",
                "rows": rows,
                "reset_table": reset_table,
            }
        except HTTPException:
            conn.rollback()
            raise
        except Exception as e:
            conn.rollback()
            raise HTTPException(status_code=500, detail=f"Save checkpoint failed: {str(e)}")


@router.post("/dataset/reset-to-checkpoint")
async def dataset_reset_to_checkpoint(
    source_db: str = Body(..., embed=True),
    current_user_id: str = Depends(get_current_user2),
):
    """
    Reset: overwrite working table with {bd}_reset (schema+data+metadata).
    Handles schema mismatch between current and checkpoint.
    """
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            base = assert_owns_table(cur, source_db, current_user_id, label="dataset")
            reset_table = f"{base}_reset"
            if not physical_table_exists(cur, reset_table):
                raise HTTPException(
                    status_code=404,
                    detail="Reset checkpoint not found. Use Save first, or continue from a previous stage.",
                )
            if not user_owns_table(cur, reset_table, current_user_id):
                # Allow restore if aux was created without meta but base is owned
                if not physical_table_exists(cur, reset_table):
                    raise HTTPException(status_code=403, detail="Access denied to reset checkpoint")
            rows = replace_table_from(cur, reset_table, base)
            upsert_metadata_from_source(cur, reset_table, base, current_user_id)
            conn.commit()
            return {
                "status": "success",
                "action": "reset_from_checkpoint",
                "message": "Dataset restored from reset checkpoint.",
                "rows": rows,
            }
        except HTTPException:
            conn.rollback()
            raise
        except Exception as e:
            conn.rollback()
            raise HTTPException(status_code=500, detail=f"Reset failed: {str(e)}")


@router.post("/create-reset-copy2")
async def create_reset_copy(
    source_db: str = Body(..., embed=True),
    target_db: str = Body(None, embed=True),
    reset: bool = Body(False, embed=True),
    current_user_id: str = Depends(get_current_user2)
):
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            source_table = normalize_table_ident(source_db)
            if target_db:
                target_table = normalize_table_ident(target_db)
            else:
                base = source_table.replace("_numerized", "")
                target_table = f"{base}_reset"
            source_table, target_table = assert_reset_copy_access(
                cur, source_table, target_table, current_user_id
            )

            print(f"🔄 DEBUG RESET COPY:")
            print(f"   Source: {source_table}")
            print(f"   Target: {target_table}")
            print(f"   Reset mode: {reset}")
            print(f"   User ID: {current_user_id}")

            # 1. Vérifier que la source existe dans les métadonnées
            cur.execute("""
                SELECT columns FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
            """, (source_table, current_user_id))
            source_info = cur.fetchone()
            
            print(f"   Source found in metadata: {bool(source_info)}")
            
            if not source_info:
                raise HTTPException(404, "Source database not found")

            # 2. Compter les lignes AVANT l'opération
            try:
                cur.execute(f"SELECT COUNT(*) FROM {source_table}")
                source_count_before = cur.fetchone()[0]
                print(f"   Lignes dans {source_table} (source): {source_count_before}")
            except Exception as e:
                print(f"   ❌ Impossible de compter les lignes source: {e}")
                source_count_before = "N/A"

            try:
                cur.execute(f"SELECT COUNT(*) FROM {target_table}")
                target_count_before = cur.fetchone()[0]
                print(f"   Lignes dans {target_table} (target avant): {target_count_before}")
            except Exception as e:
                print(f"   ℹ️ Impossible de compter les lignes target (table peut ne pas exister): {e}")
                target_count_before = "N/A"

            # 3. Supprimer la table target si elle existe
            print(f"   Suppression de {target_table}...")
            cur.execute(f"DROP TABLE IF EXISTS {target_table}")
            print(f"   ✅ Table {target_table} supprimée")

            # 4. Créer la nouvelle table avec les données de la source
            print(f"   Création de {target_table} depuis {source_table}...")
            cur.execute(f"""
                CREATE TABLE {target_table} AS
                SELECT * FROM {source_table}
            """)
            rows_copied = cur.rowcount
            print(f"   ✅ Table créée, lignes copiées: {rows_copied}")

            # 5. Compter les lignes APRÈS l'opération
            try:
                cur.execute(f"SELECT COUNT(*) FROM {target_table}")
                target_count_after = cur.fetchone()[0]
                print(f"   Lignes dans {target_table} (target après): {target_count_after}")
            except Exception as e:
                print(f"   ❌ Impossible de compter les lignes après copie: {e}")
                target_count_after = "N/A"

            # 6. Mettre à jour les métadonnées (TOUJOURS, même en mode reset)
            print(f"   Mise à jour des métadonnées...")
            cur.execute("""
                INSERT INTO user_tables_metadata
                (table_name, owner_id, columns, created_at)
                VALUES (%s, %s, %s, NOW())
                ON CONFLICT (table_name, owner_id) DO UPDATE
                SET columns = EXCLUDED.columns,
                    updated_at = NOW()
            """, (target_table, current_user_id, source_info[0]))
            print(f"   ✅ Métadonnées mises à jour")

            # 7. Commit
            conn.commit()
            print(f"   ✅ Transaction commitée avec succès")

            return {
                "status": "success",
                "message": f"Data copied from {source_table} to {target_table}",
                "rows_copied": rows_copied,
                "source_count": source_count_before,
                "target_count_before": target_count_before,
                "target_count_after": target_count_after,
                "action": "replaced"
            }

        except HTTPException:
            conn.rollback()
            raise
        except Exception as e:
            print(f"   ❌ ERREUR CRITIQUE: {str(e)}")
            conn.rollback()
            print(f"   🔄 Transaction rollback")
            raise HTTPException(500, f"Copy error: {str(e)}")

@router.post("/save-to-db")
async def save_to_db(
    data: SaveDataRequest,
    current_user_id: str = Depends(get_current_user2)
):
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            
            # 1. Validation et préparation du nom de table
            # Espaces → _, majuscules → minuscules (accepte saisie libre côté UI)
            table_name = normalize_dataset_name(data.bdName)
            validate_normalized_dataset_name(table_name)

            # Enforce dataset quota (same rule as check-dataset-limit / Upload UI).
            # Auxiliary copies (_reset / _backup / _numerized) do not count toward the 10.
            MAX_DATASETS_PER_USER = 10
            is_auxiliary = (
                table_name.endswith("_reset")
                or table_name.endswith("_backup")
                or table_name.endswith("_numerized")
            )
            if not is_auxiliary:
                cur.execute("""
                    SELECT COUNT(*) FROM user_tables_metadata
                    WHERE owner_id = %s
                    AND table_name !~ '_(reset|numerized|backup)$'
                """, (current_user_id,))
                dataset_count = cur.fetchone()[0] or 0
                if dataset_count >= MAX_DATASETS_PER_USER:
                    raise HTTPException(
                        status_code=400,
                        detail=(
                            "Dataset limit reached (maximum 10). "
                            "Delete a dataset before uploading a new one."
                        ),
                    )

            # 2. Vérifier si la table existe déjà
            cur.execute("""
                SELECT 1 FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            if cur.fetchone():
                raise HTTPException(status_code=400, detail="Table already exists")

            # 3. Création de la table avec les colonnes sélectionnées
            if not data.rows:
                raise HTTPException(status_code=400, detail="No data to save")
            if not data.columns:
                raise HTTPException(status_code=400, detail="No columns to save")

            # Sanitize column names before any SQL (blocks injection via column names)
            validate_column_names(data.columns)
            data.columns = [str(c).strip() for c in data.columns]

            column_types = []  # list of (col_name, pg_type)
            ALLOWED_PG_TYPES = {"TEXT", "BOOLEAN", "INTEGER", "BIGINT", "FLOAT8"}
            
            # ✅ CORRECTION : Détection de types PLUS PRUDENTE avec BIGINT pour les grands nombres
            for col_idx, col_name in enumerate(data.columns):
                col_key = f"col{col_idx}"
                
                # Analyser TOUTES les valeurs de la colonne pour détecter le type
                values = []
                for row in data.rows:
                    if col_key in row and row[col_key] not in [None, "", "NA", "NaN", "null"]:
                        values.append(row[col_key])
                
                if not values:
                    # Colonne vide → TEXT
                    pg_type = "TEXT"
                else:
                    # ✅ LOGIQUE AMÉLIORÉE : Vérifier TOUTES les valeurs avant de décider du type
                    all_boolean = True
                    all_integer = True
                    all_bigint = True  # Nouveau: pour détecter si on a besoin de BIGINT
                    all_float = True
                    
                    # Constante pour la limite INTEGER
                    INT_MAX = 2147483647
                    INT_MIN = -2147483648
                    
                    for value in values:
                        # Test booléen
                        if isinstance(value, bool):
                            continue
                        if str(value).lower() in ['true', 'false', 'yes', 'no', '0', '1']:
                            continue
                        all_boolean = False
                        
                        # Test entier - ATTENTION: doit être un ENTIER SANS DÉCIMALES
                        if isinstance(value, int):
                            # Vérifier si c'est un grand nombre qui nécessite BIGINT
                            if value > INT_MAX or value < INT_MIN:
                                all_integer = False
                                # continue pour BIGINT
                            continue
                            
                        try:
                            # Vérifier que c'est bien un entier (pas de décimales)
                            str_val = str(value).strip()
                            if '.' in str_val:
                                all_integer = False
                                all_bigint = False
                            else:
                                int_val = int(str_val)
                                # Si la valeur dépasse les limites INTEGER, on a besoin de BIGINT
                                if int_val > INT_MAX or int_val < INT_MIN:
                                    all_integer = False
                                    # all_bigint reste True
                                else:
                                    # C'est un entier normal
                                    pass
                        except (ValueError, TypeError):
                            all_integer = False
                            all_bigint = False
                        
                        # Test float
                        if isinstance(value, float):
                            continue
                        try:
                            float(str(value))
                        except (ValueError, TypeError):
                            all_float = False
                    
                    # Déterminer le type le plus spécifique possible
                    if all_boolean:
                        pg_type = "BOOLEAN"
                    elif all_integer:
                        pg_type = "INTEGER"
                    elif all_bigint:
                        # Si ce ne sont pas des INTEGER mais peuvent être des BIGINT
                        pg_type = "BIGINT"
                    elif all_float:
                        pg_type = "FLOAT8"
                    else:
                        # Par défaut, utiliser TEXT pour éviter tout problème
                        pg_type = "TEXT"

                if pg_type not in ALLOWED_PG_TYPES:
                    pg_type = "TEXT"
                column_types.append((col_name, pg_type))

            # 4. Safe CREATE TABLE with sql.Identifier (no raw f-string identifiers)
            col_defs = [sql.SQL("id SERIAL PRIMARY KEY")]
            for col_name, pg_type in column_types:
                col_defs.append(
                    sql.SQL("{} {}").format(sql.Identifier(col_name), sql.SQL(pg_type))
                )
            cur.execute(
                sql.SQL("CREATE TABLE {} ({})").format(
                    sql.Identifier(table_name),
                    sql.SQL(", ").join(col_defs),
                )
            )

            # 5. Insertion des données avec conversion automatique des types
            type_by_col = {name: ptype for name, ptype in column_types}
            successful_rows = 0
            for row_idx, row in enumerate(data.rows):
                cols = []
                vals = []
                
                for col_idx, col_name in enumerate(data.columns):
                    col_key = f"col{col_idx}"
                    if col_key in row:
                        value = row[col_key]
                        
                        # Conversion des valeurs spéciales
                        if value in ["", "NA", "NaN", "null"]:
                            value = None
                        elif value is not None:
                            try:
                                col_type = type_by_col.get(col_name)
                                if col_type == "BIGINT":
                                    value = int(float(str(value)))
                                elif col_type == "INTEGER":
                                    value = int(float(str(value)))
                                elif col_type == "FLOAT8":
                                    value = float(str(value))
                                elif col_type == "BOOLEAN":
                                    if str(value).lower() in ['true', 'yes', '1']:
                                        value = True
                                    elif str(value).lower() in ['false', 'no', '0']:
                                        value = False
                            except (ValueError, TypeError):
                                pass
                        
                        cols.append(col_name)
                        vals.append(value)
                
                if cols:
                    try:
                        insert_sql = sql.SQL("INSERT INTO {} ({}) VALUES ({})").format(
                            sql.Identifier(table_name),
                            sql.SQL(", ").join(sql.Identifier(c) for c in cols),
                            sql.SQL(", ").join([sql.Placeholder()] * len(cols)),
                        )
                        cur.execute(insert_sql, vals)
                        successful_rows += 1
                    except Exception as insert_error:
                        logger.error(f"Insert error row {row_idx}: {insert_error}")
                        raise insert_error

            # 6. Sauvegarde des métadonnées
            cur.execute("""
                INSERT INTO user_tables_metadata 
                (table_name, owner_id, columns, created_at, target_column, model_type, updated_at, stage, applied_actions)
                VALUES (%s, %s, %s, NOW(), NULL, NULL, NULL, 'target_selection', NULL)
                ON CONFLICT (table_name, owner_id) DO NOTHING
            """, (table_name, current_user_id, data.columns))

            conn.commit()
            return {
                "message": "Data saved successfully",
                "table": table_name,
                "columns": data.columns,
                "rows_inserted": successful_rows
            }

        except Exception as e:
            if conn:
                conn.rollback()
            print(f"ERREUR DÉTAILLÉE: {str(e)}")
            raise HTTPException(
                status_code=500, 
                detail=f"Error while saving: {str(e)}"
            )
        finally:
            if conn:
                conn.close()



@router.post("/save-modification-history")
async def save_modification_history(
    data: dict,
    current_user_id: str = Depends(get_current_user2)
):
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            table_name = data["bdName"].lower()
            
            # Vérifier l'accès
            cur.execute("""
                SELECT 1 FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            
            if not cur.fetchone():
                raise HTTPException(404, "Table not found or access denied")
            
            modification = data["modification"]
            
            # Vérifier si la colonne modification_history existe
            cur.execute("""
                SELECT column_name 
                FROM information_schema.columns 
                WHERE table_name = 'user_tables_metadata' 
                AND column_name = 'modification_history'
            """)
            
            if not cur.fetchone():
                # Ajouter la colonne si elle n'existe pas
                cur.execute("""
                    ALTER TABLE user_tables_metadata 
                    ADD COLUMN modification_history JSONB DEFAULT '[]'::JSONB
                """)
            
            # Récupérer l'historique actuel
            cur.execute("""
                SELECT modification_history 
                FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            
            result = cur.fetchone()
            current_history = result[0] if result and result[0] else []
            if isinstance(current_history, str):
                try:
                    current_history = json.loads(current_history)
                except Exception:
                    current_history = []
            if not isinstance(current_history, list):
                current_history = []

            # Aplatir : le frontend envoie parfois une liste [{...}] — ne pas
            # l'imbriquer (sinon is_modified ne matche plus jamais).
            def _flatten_mods(item, out):
                if isinstance(item, list):
                    for x in item:
                        _flatten_mods(x, out)
                elif isinstance(item, dict):
                    out.append(item)

            flat_new = []
            _flatten_mods(modification, flat_new)
            # Aussi aplatir l'historique existant (données legacy imbriquées)
            flat_existing = []
            _flatten_mods(current_history, flat_existing)
            flat_existing.extend(flat_new)
            
            # Mettre à jour l'historique
            cur.execute("""
                UPDATE user_tables_metadata 
                SET modification_history = %s
                WHERE table_name = %s AND owner_id = %s
            """, (json.dumps(flat_existing), table_name, current_user_id))
            
            conn.commit()
            
            return {"message": "Modification history saved", "history": flat_existing}
            
        except Exception as e:
            conn.rollback()
            raise HTTPException(500, f"Error saving modification history: {str(e)}")

