@router.post("/check-create-backup")
async def check_create_backup(
    data: dict = Body(...),
    current_user_id: str = Depends(get_current_user2)
):
    """
    Start from scratch:
    - first time: create _backup + _reset from working table
    - later: working = backup, reset = backup, clear pipeline metadata
    """
    try:
        bd_name = data.get("bdName")
        if not bd_name:
            raise HTTPException(status_code=400, detail="bdName is required")

        with get_db_connection() as conn:
            try:
                conn.autocommit = False
                cur = conn.cursor()

                table_name = assert_owns_table(cur, bd_name, current_user_id, label="dataset")
                if not physical_table_exists(cur, table_name):
                    raise HTTPException(
                        status_code=404,
                        detail=f"Physical table '{table_name}' is missing (orphan metadata).",
                    )

                backup_table_name = f"{table_name}_backup"
                reset_table_name = f"{table_name}_reset"
                backup_exists = physical_table_exists(cur, backup_table_name)

                if not backup_exists:
                    replace_table_from(cur, table_name, backup_table_name)
                    replace_table_from(cur, table_name, reset_table_name)
                    original_columns = physical_columns(cur, table_name)

                    reset_pipeline_metadata(
                        cur, backup_table_name, current_user_id, original_columns
                    )
                    reset_pipeline_metadata(
                        cur, reset_table_name, current_user_id, original_columns
                    )
                    reset_pipeline_metadata(
                        cur,
                        table_name,
                        current_user_id,
                        original_columns,
                        mark_backup=True,
                    )
                    action = "backup_created"
                    message = "Backup created successfully"
                else:
                    if not physical_table_exists(cur, backup_table_name):
                        raise HTTPException(
                            status_code=404,
                            detail=f"Backup table '{backup_table_name}' not found",
                        )

                    keep_dataset_info = None
                    _pg_savepoint(cur, "sp_read_dataset_info")
                    try:
                        cur.execute(
                            """
                            SELECT dataset_info FROM user_tables_metadata
                            WHERE table_name = %s AND owner_id = %s
                            """,
                            (table_name, current_user_id),
                        )
                        info_row = cur.fetchone()
                        keep_dataset_info = info_row[0] if info_row else None
                        _pg_release(cur, "sp_read_dataset_info")
                    except Exception as e:
                        print(f"⚠️ dataset_info read skipped: {e}")
                        _pg_rollback_to(cur, "sp_read_dataset_info")
                        keep_dataset_info = None

                    derived_tables = [
                        f"{table_name}_numerized",
                        f"{table_name}_cleaned",
                        f"{table_name}_processed",
                        f"{table_name}_encoded",
                    ]
                    for derived_table in derived_tables:
                        cur.execute(
                            sql.SQL("DROP TABLE IF EXISTS {} CASCADE").format(
                                sql.Identifier(derived_table)
                            )
                        )
                        cur.execute(
                            """
                            DELETE FROM user_tables_metadata
                            WHERE table_name = %s AND owner_id = %s
                            """,
                            (derived_table, current_user_id),
                        )

                    # Recreate working + reset from backup (handles schema changes)
                    replace_table_from(cur, backup_table_name, table_name)
                    replace_table_from(cur, backup_table_name, reset_table_name)
                    original_columns = physical_columns(cur, table_name)

                    reset_pipeline_metadata(
                        cur,
                        table_name,
                        current_user_id,
                        original_columns,
                        dataset_info=keep_dataset_info,
                        mark_backup=True,
                    )
                    reset_pipeline_metadata(
                        cur,
                        reset_table_name,
                        current_user_id,
                        original_columns,
                        dataset_info=keep_dataset_info,
                    )

                    _pg_savepoint(cur, "sp_cleanup_extra")
                    try:
                        cur.execute(
                            """
                            SELECT 1 FROM information_schema.tables
                            WHERE table_schema = 'public'
                              AND table_name = 'preprocessing_metadata'
                            """
                        )
                        if cur.fetchone():
                            cur.execute(
                                "DELETE FROM preprocessing_metadata WHERE table_name = %s",
                                (table_name,),
                            )
                        cur.execute(
                            """
                            SELECT 1 FROM information_schema.tables
                            WHERE table_schema = 'public'
                              AND table_name = 'model_metadata'
                            """
                        )
                        if cur.fetchone():
                            cur.execute(
                                """
                                DELETE FROM model_metadata
                                WHERE dataset_name = %s AND user_id = %s
                                """,
                                (table_name, current_user_id),
                            )
                        _pg_release(cur, "sp_cleanup_extra")
                    except Exception as e:
                        print(f"⚠️ extra metadata cleanup skipped: {e}")
                        _pg_rollback_to(cur, "sp_cleanup_extra")

                    action = "dataset_reset_from_backup"
                    message = "Dataset reset from backup (working + reset + metadata cleared)"

                conn.commit()
                return {"status": "success", "action": action, "message": message}
            except Exception:
                conn.rollback()
                raise

    except HTTPException:
        raise
    except Exception as e:
        import traceback
        print(f"❌ check-create-backup failed: {e}")
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=f"Operation failed: {str(e)}")

@router.get("/get-data")
async def get_data(
    bdName: str,
    current_user_id: str = Depends(get_current_user2)
):
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()

            # Vérifier l'accès
            cur.execute("""
                SELECT columns FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (bdName.lower(), current_user_id))
            
            if not cur.fetchone():
                raise HTTPException(404, "Table not found or access denied")
            
            # Récupérer toutes les colonnes (y compris id)
            cur.execute("""
                SELECT column_name 
                FROM information_schema.columns 
                WHERE table_name = %s
                ORDER BY ordinal_position
            """, (bdName.lower(),))
            
            all_columns = [row[0] for row in cur.fetchall()]
            data_columns = [col for col in all_columns if col != 'id']
            
            # Requête avec toutes les colonnes
            query = sql.SQL("SELECT {} FROM {}").format(
                sql.SQL(", ").join(map(sql.Identifier, all_columns)),
                sql.Identifier(bdName.lower())
            )
            
            cur.execute(query)
            rows = []
            for row in cur.fetchall():
                row_dict = {'id': row[0]}  # Première colonne est l'ID
                for i, col in enumerate(data_columns, 1):
                    row_dict[f"col{i-1}"] = row[i]
                rows.append(row_dict)

            return {
                "name": bdName,
                "columns": data_columns,
                "rows": rows
            }

        except psycopg2.Error as e:
            raise HTTPException(500, f"PostgreSQL error: {e.pgerror}")
        except Exception as e:
            raise HTTPException(500, f"Server error: {str(e)}")

@router.get("/get-data_with-id")
async def get_data(
    bdName: str,
    page: int = 0,
    page_size: int = 100,
    current_user_id: str = Depends(get_current_user2)
):
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            search_name = bdName.lower()
            
            # Vérifier l'accès
            cur.execute("""
                SELECT table_name FROM user_tables_metadata 
                WHERE LOWER(table_name) = %s AND owner_id = %s
            """, (search_name, current_user_id))
            
            result = cur.fetchone()
            if not result:
                raise HTTPException(404, f"Table '{bdName}' not found")
            
            actual_table_name = result[0]
            
            # Récupérer les colonnes
            cur.execute("""
                SELECT column_name, data_type 
                FROM information_schema.columns 
                WHERE table_name = %s
                ORDER BY ordinal_position
            """, (actual_table_name,))
            
            columns_info = cur.fetchall()
            all_columns = [row[0] for row in columns_info]
            data_columns = [col for col in all_columns if col != 'id']
            
            # Compter le nombre total de lignes
            cur.execute(f'SELECT COUNT(*) FROM "{actual_table_name}"')
            total_rows = cur.fetchone()[0]
            
            # Récupérer les données avec pagination
            offset = page * page_size
            quoted_columns = ', '.join([f'"{col}"' for col in all_columns])
            query = f'SELECT {quoted_columns} FROM "{actual_table_name}" ORDER BY id LIMIT %s OFFSET %s'
            
            print(f"DEBUG: Executing paginated query: {query} with page={page}, page_size={page_size}")
            cur.execute(query, (page_size, offset))
            
            rows_data = cur.fetchall()
            print(f"DEBUG: Fetched {len(rows_data)} rows for page {page}")
            
            # Formater les données
            rows = []
            for row_idx, row in enumerate(rows_data):
                row_dict = {'id': row[0]}  # L'ID original
                
                col_index = 0
                for i, (col_name, _) in enumerate(columns_info):
                    if col_name == 'id':
                        continue
                    row_dict[f"col{col_index}"] = row[i]
                    col_index += 1
                    
                rows.append(row_dict)
            
            return {
                "name": bdName,
                "columns": data_columns,
                "rows": rows,
                "total_rows": total_rows,
                "page": page,
                "page_size": page_size,
                "total_pages": (total_rows + page_size - 1) // page_size
            }

        except Exception as e:
            print(f"DEBUG: Server error: {str(e)}")
            raise HTTPException(500, f"Server error: {str(e)}")


@router.post("/save-target-column")
async def save_target_column(
    data: SaveTargetColumnRequest,
    current_user_id: str = Depends(get_current_user2)
):
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            table_name = data.dataset_name.lower()

            # 1. Vérifier que la table principale existe et que l'utilisateur a les droits
            cur.execute("""
                SELECT 1 FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            
            if not cur.fetchone():
                raise HTTPException(
                    status_code=404,
                    detail="Table not found or access denied"
                )

            # 2. Update WORKING table metadata only.
            # Do NOT write target into _reset: Reset must restore the checkpoint
            # (upload / last Save), which typically has no target yet.
            cur.execute("""
                UPDATE user_tables_metadata
                SET 
                    target_column = %s,
                    model_type = %s,
                    updated_at = NOW()
                WHERE table_name = %s AND owner_id = %s
                RETURNING *
            """, (
                data.target_column if data.target_column != "no-target-column" else None,
                'unsupervised' if data.target_column == "no-target-column" else 'supervised',
                table_name,
                current_user_id
            ))

            updated = cur.fetchone()
            if not updated:
                raise HTTPException(
                    status_code=500,
                    detail="Failed to update metadata"
                )

            conn.commit()
            
            return {
                "message": "Target column saved successfully!",
                "is_unsupervised": data.target_column == "no-target-column"
            }

        except psycopg2.Error as e:
            if conn:
                conn.rollback()
            raise HTTPException(
                status_code=500,
                detail=f"Database error: {e.pgerror}"
            )
        except Exception as e:
            raise HTTPException(
                status_code=500, 
                detail=f"Error saving configuration: {str(e)}"
            )
        finally:
            if conn:
                conn.close()











































async def save_applied_action_directly(bd_name: str, action: str, parameters: dict, current_user_id: str):
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            
            # 1. Vérifier si la table existe
            cur.execute("""
                SELECT applied_actions FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
                FOR UPDATE
            """, (bd_name.lower(), current_user_id))
            
            result = cur.fetchone()
            if not result:
                raise Exception("Table not found")
            
            # 2. Récupérer les actions existantes
            existing_actions = result[0] if result[0] else []
            
            # 3. Formater l'action
            if action.startswith("standard:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "standard_scaling",
                    "description": f"Standard scaling on {source_column}",
                    "source_column": source_column,
                    "parameters": {
                        "mean": parameters.get("mean"),
                        "std": parameters.get("std"),
                        "fitted_on_train": parameters.get("fitted_on_train", False),
                        "timestamp": datetime.now().isoformat()
                    }
                }
            elif action.startswith("minmax:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "minmax_normalization",
                    "description": f"MinMax normalization on {source_column}",
                    "source_column": source_column,
                    "parameters": {
                        "min": parameters.get("min"),
                        "max": parameters.get("max"),
                        "data_min": parameters.get("data_min"),
                        "data_max": parameters.get("data_max"),
                        "fitted_on_train": parameters.get("fitted_on_train", False),
                        "clip": parameters.get("clip", False),
                        "timestamp": datetime.now().isoformat()
                    }
                }
            elif action.startswith("label:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "label_encoding",
                    "description": f"Label encoding on {source_column}",
                    "source_column": source_column,
                    "parameters": {
                        "mapping": parameters.get("mapping", {}),
                        "categories": parameters.get("categories", []),
                        "timestamp": datetime.now().isoformat()
                    }
                }
            elif action.startswith("onehot:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "onehot_encoding",
                    "description": f"One-hot encoding on {source_column}",
                    "source_column": source_column,
                    "parameters": {
                        "categories": parameters.get("categories", []),
                        "new_columns": parameters.get("new_columns", []),
                        "timestamp": datetime.now().isoformat()
                    }
                }
            elif action.startswith("log_transform:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "log_transformation",
                    "description": f"Log transformation on {source_column}",
                    "source_column": source_column,
                    "parameters": {
                        "base": parameters.get("base", "natural"),
                        "offset": parameters.get("offset", 1),
                        "timestamp": datetime.now().isoformat()
                    }
                }
            elif action.startswith("delete:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "column_deletion",
                    "description": f"Column deletion: {source_column}",
                    "source_column": source_column,
                    "timestamp": datetime.now().isoformat()
                }
            elif action.startswith("regex_extract:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "regex_extraction",
                    "description": f"Regex extraction on {source_column}",
                    "source_column": source_column,
                    "parameters": {
                        "pattern": parameters.get("pattern"),
                        "output_column": parameters.get("output_column"),
                        "original_pattern": parameters.get("original_pattern"),
                        "case_insensitive": parameters.get("case_insensitive", False),
                        "extract_mode": parameters.get("extract_mode", "first"),
                        "cast_numeric": parameters.get("cast_numeric", False),
                        "delete_source": parameters.get("delete_source", False),
                        "validate_kind": parameters.get("validate_kind"),
                        "timestamp": datetime.now().isoformat(),
                    },
                }
            else:
                new_action = {
                    "action": action,
                    "timestamp": datetime.now().isoformat(),
                    "parameters": parameters
                }
            
            # 4. Ajouter à la liste
            updated_actions = existing_actions + [new_action]
            
            # 5. Mettre à jour la base de données
            cur.execute("""
                UPDATE user_tables_metadata
                SET applied_actions = %s::jsonb,
                    updated_at = NOW()
                WHERE table_name = %s AND owner_id = %s
                RETURNING applied_actions
            """, (json.dumps(updated_actions), bd_name.lower(), current_user_id))
            
            updated_result = cur.fetchone()
            conn.commit()
            
            if not updated_result:
                raise Exception("Failed to verify update")
            
            return True
            
        except Exception as e:
            conn.rollback()
            raise Exception(f"Error saving applied action: {str(e)}")


@router.post("/process-numerisation")
async def process_numerisation(
    request: NumerisationRequest,
    current_user_id: str = Depends(get_current_user2)
):
    try:
        # 1. Déterminer les noms de tables
        original_bd_name = request.bdName.replace("_numerized", "")
        # Alias interne : les transformations s'appliquent DIRECTEMENT sur la table originale.
        # On ne crée plus de version "_numerized" dans le workflow ; l'original est la table de travail
        # (la version "_reset" reste disponible pour annuler / restaurer).
        numerized_bd_name = original_bd_name

        # Vérifier que la table de travail (originale) existe
        with get_db_connection() as conn:
            cur = conn.cursor()
            cur.execute("""
                SELECT 1 FROM information_schema.tables 
                WHERE table_name = %s
            """, (numerized_bd_name.lower(),))
            numerized_exists = cur.fetchone() is not None
        
        # La table source est toujours la table de travail (originale)
        source_table = numerized_bd_name if numerized_exists else original_bd_name
        
        # 2. Charger les données depuis la source (seulement la page courante)
        with get_db_connection() as conn:
            cur = conn.cursor()
            
            # Vérifier si split_type existe dans la table source
            cur.execute("""
                SELECT column_name 
                FROM information_schema.columns 
                WHERE table_name = %s AND column_name = 'split_type'
            """, (source_table.lower(),))
            has_split = cur.fetchone() is not None
            
            # Récupérer toutes les colonnes (sauf id)
            cur.execute("""
                SELECT column_name 
                FROM information_schema.columns 
                WHERE table_name = %s AND column_name != 'id'
                ORDER BY ordinal_position
            """, (source_table.lower(),))
            columns = [row[0] for row in cur.fetchall()]
            
            cur.execute(
                sql.SQL("SELECT {} FROM {}").format(
                    sql.SQL(", ").join(map(sql.Identifier, columns)),
                    sql.Identifier(source_table.lower())
                )
            )
            
            rows = []
            for row in cur.fetchall():
                row_dict = {col: value for col, value in zip(columns, row)}
                rows.append(row_dict)

        # 3. Préparer le DataFrame (seulement la page courante)
        full_df = pd.DataFrame(rows)
        
        # 4. Appliquer les transformations
        transformations_applied = []
        standard_params = []
        label_params = []  # Nouveau: stocker les paramètres label
        onehot_params = []  # Nouveau: stocker les paramètres onehot
        
        for config in request.configurations:
            col_name = config['column']
            if col_name == 'split_type':
               continue
            method = config['method']
            params = config.get('parameters', {})

            if method == 'binary':
                # Robust 0/1 encoding. Plain .astype(str).map used to turn numeric
                # 1/0 into "1.0"/"0.0" (unmapped → NaN → empty columns).
                full_df[col_name] = _encode_column_to_binary(full_df[col_name])
                transformations_applied.append(f"{col_name} → Binary encoding")

            elif method == 'invert':
                bin_col = _encode_column_to_binary(full_df[col_name])
                full_df[col_name] = bin_col.map(
                    lambda v: (1 - int(v)) if v is not None and not (isinstance(v, float) and pd.isna(v)) else None
                )
                transformations_applied.append(f"{col_name} → Boolean inversion")

            elif method == 'onehot':
                # 🔥 Récupérer TOUTES les catégories UNIQUES depuis la base de données
                with get_db_connection() as conn:
                    cur = conn.cursor()
                    cur.execute(f"""
                        SELECT DISTINCT CAST("{col_name}" AS TEXT)
                        FROM {source_table.lower()}
                        WHERE "{col_name}" IS NOT NULL 
                          AND CAST("{col_name}" AS TEXT) != ''
                          AND CAST("{col_name}" AS TEXT) != 'null'
                          AND CAST("{col_name}" AS TEXT) != 'NaN'
                    """)
                    distinct_values = [row[0] for row in cur.fetchall() if row[0] not in [None, '', 'null', 'NaN']]
                    
                    if len(distinct_values) > 50:
                        raise ValueError(f"Column {col_name} has too many unique values ({len(distinct_values)}) for one-hot encoding")
                    
                    # Normalize so PG 'true' matches pandas True
                    unique_categories = sorted({
                        k for k in (_normalize_category_key(v) for v in distinct_values) if k is not None
                    })
                
                for category in unique_categories:
                    new_col_name = f"{col_name}_{category}"
                    full_df[new_col_name] = full_df[col_name].map(
                        lambda v, cat=category: 1 if _normalize_category_key(v) == cat else 0
                    )
                
                full_df.drop(columns=[col_name], inplace=True)
                
                onehot_params.append({
                    'bd_name': numerized_bd_name,
                    'action': f"onehot:{col_name}",
                    'parameters': {
                        "categories": unique_categories,
                        "new_columns": [f"{col_name}_{c}" for c in unique_categories]
                    },
                    'current_user_id': current_user_id
                })
                
                transformations_applied.append(
                    f"{col_name} → One-Hot Encoding (created {len(unique_categories)} new columns)"
                )

            elif method == 'label':
                try:
                    with get_db_connection() as conn:
                        cur = conn.cursor()
                        cur.execute(f"""
                            SELECT DISTINCT CAST("{col_name}" AS TEXT)
                            FROM {source_table.lower()}
                            WHERE "{col_name}" IS NOT NULL 
                              AND CAST("{col_name}" AS TEXT) != ''
                              AND CAST("{col_name}" AS TEXT) != 'null'
                              AND CAST("{col_name}" AS TEXT) != 'NaN'
                        """)
                        distinct_values = [row[0] for row in cur.fetchall() if row[0] not in [None, '', 'null', 'NaN']]
                        unique_categories = sorted({
                            k for k in (_normalize_category_key(v) for v in distinct_values) if k is not None
                        })
                    
                    category_mapping = {category: idx for idx, category in enumerate(unique_categories)}
                    
                    # Normalize each cell before lookup (fixes True/'true' mismatch → all-NaN)
                    full_df[col_name] = full_df[col_name].map(
                        lambda v: category_mapping.get(_normalize_category_key(v))
                    )
                    
                    full_df[col_name] = full_df[col_name].where(pd.notna(full_df[col_name]), None)
                    
                    label_params.append({
                        'bd_name': numerized_bd_name,
                        'action': f"label:{col_name}",
                        'parameters': {
                            "mapping": category_mapping,
                            "categories": unique_categories
                        },
                        'current_user_id': current_user_id
                    })
                    
                    transformations_applied.append(
                        f"{col_name} → Label Encoding ({len(unique_categories)} categories)"
                    )
                    
                except Exception as e:
                    raise ValueError(f"Error en Label Encoding pour {col_name}: {str(e)}")

            elif method == 'frequency':
                try:
                    # Fréquences RELATIVES — train only when split exists (anti leakage)
                    split_filter = ""
                    if has_split:
                        split_filter = "AND split_type = 'train'"
                    with get_db_connection() as conn:
                        cur = conn.cursor()
                        cur.execute(f"""
                            SELECT CAST("{col_name}" AS TEXT) AS v, COUNT(*)::bigint AS c
                            FROM {source_table.lower()}
                            WHERE "{col_name}" IS NOT NULL
                              AND BTRIM(CAST("{col_name}" AS TEXT)) <> ''
                              AND LOWER(BTRIM(CAST("{col_name}" AS TEXT))) NOT IN ('null', 'nan', 'none')
                              {split_filter}
                            GROUP BY CAST("{col_name}" AS TEXT)
                        """)
                        rows_freq = cur.fetchall()
                        total_freq = sum(int(r[1]) for r in rows_freq) or 1
                        freq_map = {str(r[0]): float(r[1]) / float(total_freq) for r in rows_freq}

                    full_df[col_name] = full_df[col_name].astype(str).map(
                        lambda x: freq_map.get(x, 0.0) if x not in ('nan', 'None', 'null', '') else None
                    )
                    full_df[col_name] = pd.to_numeric(full_df[col_name], errors='coerce')

                    scope = "train only" if has_split else "full dataset"
                    transformations_applied.append(
                        f"{col_name} → Frequency Encoding (relative, {len(freq_map)} categories, {scope})"
                    )
                except Exception as e:
                    raise ValueError(f"Error in Frequency Encoding for {col_name}: {str(e)}")

            elif method == 'target':
               if has_split:
                   train_mask = full_df['split_type'] == 'train'
                   encoder = ce.TargetEncoder(cols=[col_name])
                   encoder.fit(full_df[train_mask][col_name], full_df[train_mask][config['target_column']])
                   full_df[col_name] = encoder.transform(full_df[col_name])
               else:
                   encoder = ce.TargetEncoder(cols=[col_name])
                   full_df = encoder.fit_transform(full_df, full_df[config['target_column']])
               transformations_applied.append(f"{col_name} → Target Encoding")
               
            elif method == 'standard':
                # 🔥 Calculer mean et std sur TOUTES les données via SQL
                with get_db_connection() as conn:
                    cur = conn.cursor()
                    cur.execute(f"""
                        SELECT 
                            AVG("{col_name}"::FLOAT) as mean,
                            STDDEV("{col_name}"::FLOAT) as std
                        FROM {source_table.lower()}
                        WHERE "{col_name}" IS NOT NULL 
                          AND "{col_name}"::TEXT != ''
                          AND "{col_name}"::TEXT != 'null'
                    """)
                    result = cur.fetchone()
                    mean_val = float(result[0]) if result[0] is not None else 0
                    std_val = float(result[1]) if result[1] is not None else 1
                
                fitted_on_train = False
                if has_split:
                    # Vérifier si on a des données train
                    with get_db_connection() as conn:
                        cur = conn.cursor()
                        cur.execute(f"""
                            SELECT COUNT(*) FROM {source_table.lower()}
                            WHERE split_type = 'train'
                              AND "{col_name}" IS NOT NULL
                        """)
                        train_count = cur.fetchone()[0]
                        if train_count > 0:
                            fitted_on_train = True
                            # Recalculer sur le train uniquement
                            cur.execute(f"""
                                SELECT 
                                    AVG("{col_name}"::FLOAT) as mean,
                                    STDDEV("{col_name}"::FLOAT) as std
                                FROM {source_table.lower()}
                                WHERE split_type = 'train'
                                  AND "{col_name}" IS NOT NULL
                            """)
                            result = cur.fetchone()
                            mean_val = float(result[0]) if result[0] is not None else 0
                            std_val = float(result[1]) if result[1] is not None else 1
                
                # Appliquer la transformation sur le DataFrame paginé
                if std_val > 0:
                    full_df[col_name] = (full_df[col_name].astype(float) - mean_val) / std_val
                else:
                    full_df[col_name] = 0
                
                # Stocker les paramètres pour sauvegarde ultérieure
                standard_params.append({
                    'bd_name': numerized_bd_name,
                    'action': f"standard:{col_name}",
                    'parameters': {
                        "mean": mean_val,
                        "std": std_val,
                        "fitted_on_train": fitted_on_train
                    },
                    'current_user_id': current_user_id
                })
                
                transformations_applied.append(
                    f"{col_name} → Standardization (mean: {mean_val:.3f}, std: {std_val:.3f})"
                )
                
            elif method == 'minmax':
                min_val = params.get('min', 0)
                max_val = params.get('max', 1)
                clip = params.get('clip', False)
                
                # 🔥 Calculer min et max sur TOUTES les données via SQL
                with get_db_connection() as conn:
                    cur = conn.cursor()
                    cur.execute(f"""
                        SELECT 
                            MIN("{col_name}"::FLOAT) as min,
                            MAX("{col_name}"::FLOAT) as max
                        FROM {source_table.lower()}
                        WHERE "{col_name}" IS NOT NULL 
                          AND "{col_name}"::TEXT != ''
                          AND "{col_name}"::TEXT != 'null'
                    """)
                    result = cur.fetchone()
                    data_min_val = float(result[0]) if result[0] is not None else 0
                    data_max_val = float(result[1]) if result[1] is not None else 1
                
                fitted_on_train = False
                if has_split:
                    # Vérifier si on a des données train
                    with get_db_connection() as conn:
                        cur = conn.cursor()
                        cur.execute(f"""
                            SELECT COUNT(*) FROM {source_table.lower()}
                            WHERE split_type = 'train'
                              AND "{col_name}" IS NOT NULL
                        """)
                        train_count = cur.fetchone()[0]
                        if train_count > 0:
                            fitted_on_train = True
                            cur.execute(f"""
                                SELECT 
                                    MIN("{col_name}"::FLOAT) as min,
                                    MAX("{col_name}"::FLOAT) as max
                                FROM {source_table.lower()}
                                WHERE split_type = 'train'
                                  AND "{col_name}" IS NOT NULL
                            """)
                            result = cur.fetchone()
                            data_min_val = float(result[0]) if result[0] is not None else 0
                            data_max_val = float(result[1]) if result[1] is not None else 1
                
                # Appliquer MinMax scaling sur le DataFrame paginé
                if data_max_val - data_min_val > 0:
                    scaled = (full_df[col_name].astype(float) - data_min_val) / (data_max_val - data_min_val)
                    full_df[col_name] = scaled * (max_val - min_val) + min_val
                    
                    if clip:
                        full_df[col_name] = full_df[col_name].clip(min_val, max_val)
                else:
                    full_df[col_name] = min_val
                
                # Stocker les paramètres pour sauvegarde ultérieure
                standard_params.append({
                    'bd_name': numerized_bd_name,
                    'action': f"minmax:{col_name}",
                    'parameters': {
                        "min": min_val,
                        "max": max_val,
                        "data_min": data_min_val,
                        "data_max": data_max_val,
                        "fitted_on_train": fitted_on_train,
                        "clip": clip
                    },
                    'current_user_id': current_user_id
                })
                
                transformations_applied.append(
                    f"{col_name} → MinMax normalization (range {min_val} to {max_val}, "
                    f"original data range: {data_min_val:.3f} to {data_max_val:.3f})"
                )
                
            elif method == 'log':
                base = params.get('base', 'natural')
                offset = params.get('offset', 1)
                
                # 🔥 Vérifier les valeurs négatives sur TOUTES les données via SQL
                with get_db_connection() as conn:
                    cur = conn.cursor()
                    cur.execute(f"""
                        SELECT MIN("{col_name}"::FLOAT)
                        FROM {source_table.lower()}
                        WHERE "{col_name}" IS NOT NULL 
                          AND "{col_name}"::TEXT != ''
                          AND "{col_name}"::TEXT != 'null'
                    """)
                    result = cur.fetchone()
                    col_min = float(result[0]) if result[0] is not None else 0
                
                # Vérification de l'offset
                if col_min + offset <= 0:
                    required_offset = abs(col_min) + 1.1
                    raise ValueError(
                        f"ERREUR TRANSFORMATION LOG: La colonne {col_name} contient des valeurs jusqu'à {col_min}. "
                        f"Offset minimum requis: {required_offset}"
                    )
                
                # Conversion forcée en float
                numeric_series = pd.to_numeric(full_df[col_name], errors='coerce').astype(float)
                
                # Application de la transformation
                total_offset_values = numeric_series + offset
                
                if base == 'natural':
                    full_df[col_name] = np.log(total_offset_values)
                elif base == '10':
                    full_df[col_name] = np.log10(total_offset_values)
                elif base == '2':
                    full_df[col_name] = np.log2(total_offset_values)
                else:
                    raise ValueError(f"Base logarithmique invalide: {base}")
                
                transformations_applied.append(
                    f"{col_name} → Log transformation (base {base}, offset: {offset})"
                )
                        
            elif method == 'extract':
                date_format = params.get('date_format', '')
                if not date_format:
                    raise ValueError("Le format de date est requis")
                
                if date_format.count('M') > 2 or date_format.count('m') > 2:
                    raise ValueError("Format invalide : utiliser 'M' pour mois et 'm' pour minutes")
                
                components_to_extract = []
                if params.get('extract_year', True):
                    components_to_extract.append('y')
                if params.get('extract_month', True):
                    components_to_extract.append('M')
                if params.get('extract_day', True):
                    components_to_extract.append('d')
                if params.get('extract_hour', False):
                    components_to_extract.append('h')
                if params.get('extract_minute', False):
                    components_to_extract.append('m')
                if params.get('extract_second', False):
                    components_to_extract.append('s')
                
                col_map = {
                    'd': 'day',
                    'M': 'month',
                    'y': 'year',
                    'h': 'hour',
                    'm': 'minute',
                    's': 'second'
                }
                
                for comp in components_to_extract:
                    full_df[f"{col_name}_{col_map[comp]}"] = None
                
                for idx, value in full_df[col_name].items():
                    extracted = extract_with_format(value, date_format)
                    for comp in components_to_extract:
                        col_suffix = col_map[comp]
                        if col_suffix in extracted:
                            full_df.at[idx, f"{col_name}_{col_suffix}"] = extracted[col_suffix]
                
                full_df.drop(columns=[col_name], inplace=True)
                
                transformations_applied.append(
                    f"{col_name} → Date extraction ({', '.join([col_map[c] for c in components_to_extract])})"
                )

        # 8. Save the numerized version
        with get_db_connection() as conn:
            cur = conn.cursor()
            cur.execute(f"DROP TABLE IF EXISTS {numerized_bd_name.lower()}")
            
            column_defs = ["id SERIAL PRIMARY KEY"]
            for col in full_df.columns:
                if pd.api.types.is_bool_dtype(full_df[col]):
                    pg_type = "BOOLEAN"
                elif pd.api.types.is_numeric_dtype(full_df[col]):
                    pg_type = "FLOAT8"
                else:
                    pg_type = "TEXT"
                
                column_defs.append(f'"{col}" {pg_type}')
        
            cur.execute(f"CREATE TABLE {numerized_bd_name.lower()} ({', '.join(column_defs)})")
            
            if not full_df.empty:
                cols = [f'"{col}"' for col in full_df.columns]
                placeholders = ", ".join(["%s"] * len(full_df.columns))
                
                insert_query = f"""
                    INSERT INTO {numerized_bd_name.lower()} ({", ".join(cols)})
                    VALUES ({placeholders})
                """
                
                values = []
                for _, row in full_df.iterrows():
                    row_values = []
                    for val in row:
                        if pd.isna(val) or val in ["", "NA", "NaN", "null"]:
                            row_values.append(None)
                        elif isinstance(val, (bool, np.bool_)):
                            row_values.append(bool(val))
                        elif isinstance(val, (np.int64, np.int32)):
                            row_values.append(int(val))
                        elif isinstance(val, (np.float64, np.float32)):
                            row_values.append(float(val))
                        elif isinstance(val, pd.Timestamp):
                            row_values.append(val.isoformat())
                        else:
                            row_values.append(val)
                    values.append(row_values)
                
                cur.executemany(insert_query, values)

            new_columns = [col for col in full_df.columns if col != 'split_type']

            cur.execute("""
                INSERT INTO user_tables_metadata 
                (table_name, owner_id, columns, created_at, target_column, model_type, updated_at, stage)
                SELECT %s, %s, %s, NOW(), target_column, model_type, NOW(), stage
                FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
                ON CONFLICT (table_name, owner_id) DO UPDATE
                SET 
                    columns = EXCLUDED.columns,
                    target_column = EXCLUDED.target_column,
                    model_type = EXCLUDED.model_type,
                    updated_at = EXCLUDED.updated_at,
                    stage = EXCLUDED.stage
            """, (numerized_bd_name.lower(), current_user_id, new_columns, original_bd_name.lower(), current_user_id))
            
            conn.commit()
        
        # Sauvegarder les actions standard et minmax
        for params in standard_params:
            try:
                await save_applied_action_directly(
                    bd_name=params['bd_name'],
                    action=params['action'],
                    parameters=params['parameters'],
                    current_user_id=params['current_user_id']
                )
            except Exception as e:
                print(f"Warning: Failed to save applied action: {str(e)}")
        
        # 🔥 Sauvegarder les actions label encoding
        for params in label_params:
            try:
                await save_applied_action_directly(
                    bd_name=params['bd_name'],
                    action=params['action'],
                    parameters=params['parameters'],
                    current_user_id=params['current_user_id']
                )
            except Exception as e:
                print(f"Warning: Failed to save label encoding action: {str(e)}")
        
        # 🔥 Sauvegarder les actions onehot encoding
        for params in onehot_params:
            try:
                await save_applied_action_directly(
                    bd_name=params['bd_name'],
                    action=params['action'],
                    parameters=params['parameters'],
                    current_user_id=params['current_user_id']
                )
            except Exception as e:
                print(f"Warning: Failed to save onehot encoding action: {str(e)}")

        return {
            "status": "success",
            "new_bd_name": numerized_bd_name,
            "transformations": transformations_applied,
            "new_columns": new_columns,
            "applied_configurations": request.configurations
        }
    except ValueError as ve:
        raise HTTPException(status_code=400, detail=str(ve))
    except Exception as e:
        raise HTTPException(
            status_code=500, detail=f"Transformation error: {str(e)}")




