def parse_date_with_format(value, date_format):
    """Parse une date selon le format spécifié par l'utilisateur"""
    if pd.isna(value) or not date_format:
        return None
    
    # Convertir le format utilisateur en format strftime
    format_mapping = {
        'd': '%d', 'dd': '%d',
        'm': '%m', 'mm': '%m',
        'y': '%y', 'yy': '%y', 'yyy': '%y', 'yyyy': '%Y',
        'h': '%H', 'hh': '%H',
        'M': '%M', 'MM': '%M',  # Minutes (Majuscule pour éviter conflit avec mois)
        's': '%S', 'ss': '%S'
    }
    
    # Convertir le format utilisateur en regex
    strftime_format = date_format
    for user_fmt, py_fmt in format_mapping.items():
        strftime_format = strftime_format.replace(user_fmt, py_fmt)
    
    try:
        return pd.to_datetime(value, format=strftime_format, exact=True)
    except:
        return None
def get_split_stats(cur, table_name: str, target_column: Optional[str]):
    """Get detailed split statistics - CORRECTED VERSION"""
    try:
        if target_column:
            # Verify target column exists first
            cur.execute("""
                SELECT 1 FROM information_schema.columns 
                WHERE table_name = %s AND column_name = %s
            """, (table_name, target_column))
            if not cur.fetchone():
                logger.warning(f"Target column {target_column} not found in table {table_name}")
                target_column = None

        if target_column:
            query = sql.SQL("""
                SELECT 
                    split_type,
                    {target},
                    COUNT(*) as count,
                    ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (PARTITION BY split_type), 2) as percentage
                FROM {table}
                WHERE split_type IS NOT NULL
                GROUP BY split_type, {target}
                ORDER BY split_type, {target}
            """).format(
                table=sql.Identifier(table_name),
                target=sql.Identifier(target_column)
            )
        else:
            query = sql.SQL("""
                SELECT 
                    split_type,
                    COUNT(*) as count,
                    ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 2) as percentage
                FROM {table}
                WHERE split_type IS NOT NULL
                GROUP BY split_type
                ORDER BY split_type
            """).format(
                table=sql.Identifier(table_name)
            )
        
        cur.execute(query)
        columns = [desc[0] for desc in cur.description]
        results = [dict(zip(columns, row)) for row in cur.fetchall()]
        
        # Debug: log the results
        logger.info(f"Split statistics: {results}")
        
        return results
        
    except Exception as e:
        logger.error(f"Error getting split stats: {str(e)}")
        return []

def fetch_ids_and_targets(cur, table_name: str, target_column: Optional[str] = None):
    """Récupère les IDs et les targets (si stratifié) depuis la base de données"""
    if target_column:
        query = sql.SQL("SELECT id, {target} FROM {table}").format(
            target=sql.Identifier(target_column),
            table=sql.Identifier(table_name)
        )
    else:
        query = sql.SQL("SELECT id FROM {table}").format(
            table=sql.Identifier(table_name)
        )
    
    cur.execute(query)
    return cur.fetchall()

def perform_split_in_python(rows, train_size: float, target_column: Optional[str] = None, 
                          use_seed: bool = False, seed_value: int = 42):
    """Effectue le split en Python avec gestion correcte du seed"""
    # Réinitialiser l'état aléatoire si useSeed=False
    if not use_seed:
        random.seed()  # Réinitialise avec une seed aléatoire
        np.random.seed()  # Idem pour numpy
        seed_value = None  # Pour scikit-learn
    else:
        random.seed(seed_value)
        np.random.seed(seed_value)
    
    ids = [row[0] for row in rows]
    
    if target_column and len(rows[0]) > 1:
        targets = [row[1] for row in rows]
        train_ids, test_ids = train_test_split(
            ids, 
            train_size=train_size, 
            stratify=targets,
            random_state=seed_value  # None si useSeed=False
        )
    else:
        train_ids, test_ids = train_test_split(
            ids, 
            train_size=train_size,
            random_state=seed_value  # None si useSeed=False
        )
    
    return {'train': train_ids, 'test': test_ids}

def update_database_split(cur, table_name: str, split_ids: dict):
    """Met à jour les splits dans la base de données"""
    # Réinitialiser les splits existants
    cur.execute(sql.SQL("UPDATE {} SET split_type = NULL").format(sql.Identifier(table_name)))
    
    # Mettre à jour les splits train
    if split_ids['train']:
        train_query = sql.SQL("""
            UPDATE {} SET split_type = 'train' 
            WHERE id = ANY(%s)
        """).format(sql.Identifier(table_name))
        cur.execute(train_query, (split_ids['train'],))
    
    # Mettre à jour les splits test
    if split_ids['test']:
        test_query = sql.SQL("""
            UPDATE {} SET split_type = 'test' 
            WHERE id = ANY(%s)
        """).format(sql.Identifier(table_name))
        cur.execute(test_query, (split_ids['test'],))
def apply_random_split(cur, table_name: str, train_size: float, use_seed: bool = False, seed_value: int = 42):
    """Apply random split with EXACT percentage matching"""
    try:
        # Reset all to null first
        cur.execute(sql.SQL("UPDATE {} SET split_type = NULL").format(sql.Identifier(table_name)))
        
        # Get total count
        cur.execute(sql.SQL("SELECT COUNT(*) FROM {}").format(sql.Identifier(table_name)))
        total_count = cur.fetchone()[0]
        
        if total_count == 0:
            logger.warning("No rows to split")
            return
        
        # Calculate exact numbers
        train_count = int(total_count * train_size)
        test_count = total_count - train_count
        
        logger.info(f"Exact split calculation: {train_count} train ({train_size*100}%), {test_count} test ({(1-train_size)*100}%)")
        
        if use_seed:
            # Use seed for reproducible ordering
            cur.execute(sql.SQL("""
                WITH numbered_rows AS (
                    SELECT id, 
                           row_number() OVER (ORDER BY md5(id::text || %s)) as rn
                    FROM {}
                ),
                split_assignment AS (
                    SELECT id,
                           CASE 
                               WHEN rn <= %s THEN 'train'
                               ELSE 'test'
                           END as split_cat
                    FROM numbered_rows
                )
                UPDATE {} 
                SET split_type = split_assignment.split_cat
                FROM split_assignment
                WHERE {}.id = split_assignment.id
            """).format(
                sql.Identifier(table_name),
                sql.Identifier(table_name),
                sql.Identifier(table_name)
            ), [str(seed_value), train_count])
        else:
            # Random order without seed
            cur.execute(sql.SQL("""
                WITH numbered_rows AS (
                    SELECT id, 
                           row_number() OVER (ORDER BY random()) as rn
                    FROM {}
                ),
                split_assignment AS (
                    SELECT id,
                           CASE 
                               WHEN rn <= %s THEN 'train'
                               ELSE 'test'
                           END as split_cat
                    FROM numbered_rows
                )
                UPDATE {} 
                SET split_type = split_assignment.split_cat
                FROM split_assignment
                WHERE {}.id = split_assignment.id
            """).format(
                sql.Identifier(table_name),
                sql.Identifier(table_name),
                sql.Identifier(table_name)
            ), [train_count])
        
        # Verify the split
        cur.execute(sql.SQL("""
            SELECT split_type, COUNT(*) 
            FROM {} 
            WHERE split_type IS NOT NULL
            GROUP BY split_type
        """).format(sql.Identifier(table_name)))
        
        result = cur.fetchall()
        actual_counts = {row[0]: row[1] for row in result}
        
        logger.info(f"Random split applied successfully. Actual counts: {actual_counts}")
        
    except Exception as e:
        logger.error(f"Error in random split: {str(e)}")
        raise
def apply_stratified_split(cur, table_name: str, train_size: float, target_column: str, use_seed: bool = False, seed_value: int = 42):
    """Apply stratified split with better distribution control"""
    try:
        # Reset all to null first
        cur.execute(sql.SQL("UPDATE {} SET split_type = NULL").format(sql.Identifier(table_name)))
        
        # Get unique classes
        cur.execute(sql.SQL("""
            SELECT DISTINCT {} FROM {} WHERE {} IS NOT NULL
        """).format(
            sql.Identifier(target_column),
            sql.Identifier(table_name),
            sql.Identifier(target_column)
        ))
        
        classes = [row[0] for row in cur.fetchall()]
        logger.info(f"Stratified split classes: {classes}")
        
        # Apply stratified split for each class
        for class_value in classes:
            if use_seed:
                # Use seed for reproducible ordering - CORRECTION ICI
                cur.execute(sql.SQL("""
                    WITH class_rows AS (
                        SELECT id, 
                               row_number() OVER (ORDER BY md5(id::text || %s)) as rn,
                               count(*) OVER () as total_count
                        FROM {} 
                        WHERE {} = %s
                    ),
                    ranked AS (
                        SELECT id,
                               CASE 
                                   WHEN rn <= ROUND(total_count * %s) THEN 'train'
                                   ELSE 'test'
                               END as split_cat
                        FROM class_rows
                    )
                    UPDATE {} 
                    SET split_type = ranked.split_cat
                    FROM ranked
                    WHERE {}.id = ranked.id
                """).format(
                    sql.Identifier(table_name),
                    sql.Identifier(target_column),
                    sql.Identifier(table_name),
                    sql.Identifier(table_name)
                ), [str(seed_value), class_value, train_size])
            else:
                # Random order without seed - CORRECTION ICI
                cur.execute(sql.SQL("""
                    WITH class_rows AS (
                        SELECT id, 
                               row_number() OVER (ORDER BY random()) as rn,
                               count(*) OVER () as total_count
                        FROM {} 
                        WHERE {} = %s
                    ),
                    ranked AS (
                        SELECT id,
                               CASE 
                                   WHEN rn <= ROUND(total_count * %s) THEN 'train'
                                   ELSE 'test'
                               END as split_cat
                        FROM class_rows
                    )
                    UPDATE {} 
                    SET split_type = ranked.split_cat
                    FROM ranked
                    WHERE {}.id = ranked.id
                """).format(
                    sql.Identifier(table_name),
                    sql.Identifier(target_column),
                    sql.Identifier(table_name),
                    sql.Identifier(table_name)
                ), [class_value, train_size])
        
        # Handle NULL values (if any) with random split
        cur.execute(sql.SQL("""
            UPDATE {} 
            SET split_type = 
                CASE 
                    WHEN random() < %s THEN 'train'
                    ELSE 'test'
                END
            WHERE split_type IS NULL
        """).format(sql.Identifier(table_name)), [train_size])
        
        logger.info(f"Applied stratified split on {target_column}")
        
    except Exception as e:
        logger.error(f"Error in stratified split: {str(e)}")
        raise
async def apply_oversampling(conn, cur, table_name: str, target_column: str):
    """Apply oversampling to balance classes — TRAIN SET ONLY (anti data-leakage).

    - Distribution computed on split_type='train' only
    - Source samples drawn from train only
    - Synthetic duplicates always inserted with split_type='train'
    - Test set remains strictly untouched
    """
    try:
        distribution = get_class_distribution(cur, table_name, target_column, split_type='train')
        if not distribution:
            logger.warning("No class distribution found for oversampling (train)")
            return

        max_count = max(distribution.values())
        logger.info(f"[TRAIN-ONLY] Class distribution: {distribution}, max_count: {max_count}")

        cur.execute(sql.SQL("SELECT COALESCE(MAX(id), 0) FROM {}").format(sql.Identifier(table_name)))
        max_id = cur.fetchone()[0]

        cur.execute("""
            SELECT column_name
            FROM information_schema.columns
            WHERE table_name = %s
            AND column_name != 'id'
            ORDER BY ordinal_position
        """, (table_name,))

        data_columns = [row[0] for row in cur.fetchall()]
        column_indices = {col: idx for idx, col in enumerate(data_columns)}
        split_type_idx = column_indices.get('split_type')

        new_samples_count = 0

        for class_value, count in distribution.items():
            if count >= max_count:
                continue
            samples_needed = max_count - count
            logger.info(f"[TRAIN-ONLY] Class {class_value}: needs {samples_needed} additional samples")

            cur.execute(sql.SQL("""
                SELECT {columns} FROM {table}
                WHERE {target} = %s AND split_type = 'train'
            """).format(
                columns=sql.SQL(', ').join(map(sql.Identifier, data_columns)),
                table=sql.Identifier(table_name),
                target=sql.Identifier(target_column)
            ), (class_value,))

            existing_samples = cur.fetchall()

            if not existing_samples:
                logger.warning(f"No train samples found for class {class_value}")
                continue

            for i in range(samples_needed):
                sample_data = list(random.choice(existing_samples))

                if split_type_idx is not None:
                    sample_data[split_type_idx] = 'train'

                max_id += 1
                new_samples_count += 1

                insert_query = sql.SQL("""
                    INSERT INTO {table} (id, {columns})
                    VALUES (%s, {values})
                """).format(
                    table=sql.Identifier(table_name),
                    columns=sql.SQL(', ').join(map(sql.Identifier, data_columns)),
                    values=sql.SQL(', ').join([sql.Placeholder()] * len(data_columns))
                )

                cur.execute(insert_query, [max_id] + sample_data)

        if new_samples_count > 0:
            cur.execute(sql.SQL("""
                SELECT setval(pg_get_serial_sequence(%s, 'id'),
                (SELECT COALESCE(MAX(id), 0) FROM {table}) + 1, false)
            """).format(table=sql.Identifier(table_name)), (table_name,))

        logger.info(f"[TRAIN-ONLY] Oversampling completed. Added {new_samples_count} train samples.")

    except Exception as e:
        logger.error(f"Oversampling error: {str(e)}", exc_info=True)
        raise Exception(f"Oversampling failed: {str(e)}")


async def apply_undersampling(conn, cur, table_name: str, target_column: str):
    """Apply undersampling to balance classes — TRAIN SET ONLY (anti data-leakage).

    - Distribution computed on split_type='train' only
    - Deletions only target split_type='train' rows
    - Test set remains strictly untouched / representative of reality
    """
    try:
        distribution = get_class_distribution(cur, table_name, target_column, split_type='train')
        if not distribution:
            logger.warning("No class distribution found for undersampling (train)")
            return

        min_count = min(distribution.values())
        logger.info(f"[TRAIN-ONLY] Class distribution: {distribution}, min_count: {min_count}")

        for class_value, count in distribution.items():
            if count <= min_count:
                continue
            samples_to_remove = count - min_count
            logger.info(f"[TRAIN-ONLY] Class {class_value}: needs to remove {samples_to_remove} train samples")

            cur.execute(sql.SQL("""
                SELECT id FROM {table}
                WHERE {target} = %s AND split_type = 'train'
                ORDER BY random()
                LIMIT %s
            """).format(
                table=sql.Identifier(table_name),
                target=sql.Identifier(target_column)
            ), (class_value, samples_to_remove))

            ids_to_remove = [row[0] for row in cur.fetchall()]

            if not ids_to_remove:
                logger.warning(f"No train samples found to remove for class {class_value}")
                continue

            cur.execute(sql.SQL("""
                DELETE FROM {table}
                WHERE id = ANY(%s)
            """).format(
                table=sql.Identifier(table_name)
            ), (ids_to_remove,))

            logger.info(f"[TRAIN-ONLY] Removed {len(ids_to_remove)} train samples from class {class_value}")

        logger.info("[TRAIN-ONLY] Undersampling completed successfully")

    except Exception as e:
        logger.error(f"Undersampling error: {str(e)}", exc_info=True)
        raise Exception(f"Undersampling failed: {str(e)}")




@router.post("/split-data2")
async def split_data2(
    request: SplitDataRequest,
    current_user_id: str = Depends(get_current_user2)
):
    """Endpoint for data splitting with robust handling of empty target columns"""
    logger.info(f"Starting split-data2 for user: {current_user_id}")
    
    try:
        # Validate train size
        if not 0.1 <= request.trainSize <= 0.9:
            raise HTTPException(
                status_code=422,
                detail="Train size must be between 10% and 90%"
            )

        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Verify table access and existence
                cur.execute("""
                    SELECT 1 FROM user_tables_metadata 
                    WHERE table_name = %s AND owner_id = %s
                """, (request.bdName.lower(), current_user_id))
                
                if not cur.fetchone():
                    raise HTTPException(
                        status_code=404,
                        detail="Table not found or access denied"
                    )

                # Add split_type column if not exists
                try:
                    cur.execute(sql.SQL("""
                        ALTER TABLE {} 
                        ADD COLUMN IF NOT EXISTS split_type VARCHAR(10)
                    """).format(sql.Identifier(request.bdName.lower())))
                except Exception as e:
                    logger.error(f"Error adding split_type column: {str(e)}")
                    raise HTTPException(
                        status_code=500,
                        detail="Failed to prepare table for splitting"
                    )

                # For stratified splits, validate target column exists
                if request.splitMethod == "stratified":
                    if not request.targetColumn:
                        raise HTTPException(
                            status_code=400,
                            detail="Target column required for stratified split"
                        )
    
                    # Vérifier que la colonne cible sauvegardée existe toujours dans la table
                    cur.execute("""
                        SELECT 1 FROM information_schema.columns 
                        WHERE table_name = %s AND column_name = %s
                    """, (request.bdName.lower(), request.targetColumn))
                    
                    column_result = cur.fetchone()
                    if not column_result:
                        # Si la colonne sauvegardée n'existe plus, chercher une alternative
                        logger.warning(f"Saved target column '{request.targetColumn}' not found, looking for alternative")
        
                        cur.execute("""
                            SELECT column_name 
                            FROM information_schema.columns 
                            WHERE table_name = %s 
                            AND column_name NOT IN ('id', 'split_type')
                            ORDER BY ordinal_position
                        """, (request.bdName.lower(),))
        
                        alternative_columns = [row[0] for row in cur.fetchall()]
                        if alternative_columns:
                            # Prendre la première colonne non technique
                            actual_column_name = alternative_columns[0]
                            logger.info(f"Using alternative target column: {actual_column_name}")
                        else:
                            raise HTTPException(
                                status_code=400,
                                detail="No suitable target column found for stratified split"
                            )
                    else:
                        actual_column_name = request.targetColumn
                    
                    # Vérifier que la colonne a des valeurs valides pour le split stratifié
                    cur.execute(sql.SQL("""
                        SELECT COUNT(DISTINCT {}) as unique_values
                        FROM {}
                        WHERE {} IS NOT NULL
                   """).format(
                        sql.Identifier(actual_column_name),
                        sql.Identifier(request.bdName.lower()),
                        sql.Identifier(actual_column_name)
                    ))
                    
                    unique_values_result = cur.fetchone()
                    if not unique_values_result or unique_values_result[0] < 2:
                        raise HTTPException(
                            status_code=400,
                            detail=f"Target column '{actual_column_name}' must have at least 2 distinct values for stratified split"
                        )
                    
                    logger.info(f"Performing stratified split on saved target column: {actual_column_name}")
                    
                    apply_stratified_split(
                        cur, 
                        request.bdName.lower(), 
                        request.trainSize, 
                        actual_column_name,
                        request.useSeed,
                        request.seedValue
                    )
                
                # For random splits
                else:
                    logger.info("Performing random split")
                    apply_random_split(
                        cur, 
                        request.bdName.lower(), 
                        request.trainSize,
                        request.useSeed,
                        request.seedValue
                    )

                # Handle class balancing if requested
                if request.balanceClasses:
                    if not request.targetColumn:
                        logger.warning("Class balancing skipped - no target column provided")
                    else:
                        # Trouver à nouveau le nom réel de la colonne pour le balancing
                        cur.execute("""
                            SELECT column_name 
                            FROM information_schema.columns 
                            WHERE table_name = %s 
                            AND LOWER(column_name) = LOWER(%s)
                        """, (request.bdName.lower(), request.targetColumn))
                        
                        balance_column_result = cur.fetchone()
                        if balance_column_result:
                            actual_balance_column = balance_column_result[0]
                            logger.info(f"Applying {request.balanceMethod} for class balancing on {actual_balance_column}")
                            
                            try:
                                # Get columns for oversampling if needed
                                cols = []
                                if request.balanceMethod == BalanceMethod.OVERSAMPLING:
                                    cur.execute("""
                                        SELECT columns FROM user_tables_metadata
                                        WHERE table_name = %s AND owner_id = %s
                                    """, (request.bdName.lower(), current_user_id))
                                    result = cur.fetchone()
                                    cols = result[0] if result else []

                                if request.balanceMethod == BalanceMethod.OVERSAMPLING:
                                    await apply_oversampling(
                                        conn,
                                        cur,
                                        request.bdName.lower(),
                                        actual_balance_column
                                    )
                                else:
                                    await apply_undersampling(
                                        conn,
                                        cur,
                                        request.bdName.lower(),
                                        actual_balance_column
    )
                            except Exception as e:
                                logger.error(f"Error during balancing: {str(e)}")
                                # Continue even if balancing fails - the split still happened
                        else:
                            logger.warning(f"Target column '{request.targetColumn}' not found for balancing")

                # Get split statistics - utiliser le nom réel de la colonne si disponible
                target_col_for_stats = None
                if request.targetColumn:
                    cur.execute("""
                        SELECT column_name 
                        FROM information_schema.columns 
                        WHERE table_name = %s 
                        AND LOWER(column_name) = LOWER(%s)
                    """, (request.bdName.lower(), request.targetColumn))
                    stats_column_result = cur.fetchone()
                    target_col_for_stats = stats_column_result[0] if stats_column_result else None

                stats = get_split_stats(cur, request.bdName.lower(), target_col_for_stats)

                # Compact summary for the UI — computed from the split just applied
                # (no extra full-table scan beyond get_split_stats / one GROUP BY).
                train_rows = 0
                test_rows = 0
                validation_rows = 0
                if isinstance(stats, list):
                    for row in stats:
                        st = (row.get("split_type") or "").lower()
                        n = int(row.get("count") or 0)
                        if st == "train":
                            train_rows += n
                        elif st == "test":
                            test_rows += n
                        elif st == "validation":
                            validation_rows += n
                else:
                    cur.execute(
                        sql.SQL("""
                            SELECT split_type, COUNT(*)::bigint
                            FROM {}
                            WHERE split_type IS NOT NULL
                            GROUP BY split_type
                        """).format(sql.Identifier(request.bdName.lower()))
                    )
                    for st, n in cur.fetchall():
                        st_l = (st or "").lower()
                        n = int(n or 0)
                        if st_l == "train":
                            train_rows = n
                        elif st_l == "test":
                            test_rows = n
                        elif st_l == "validation":
                            validation_rows = n

                total_split = train_rows + test_rows + validation_rows
                summary = {
                    "split_done": train_rows > 0 and test_rows > 0,
                    "train_rows": train_rows,
                    "test_rows": test_rows,
                    "validation_rows": validation_rows,
                    "total_rows": total_split,
                    "train_ratio": round(train_rows / total_split, 4) if total_split else 0,
                    "test_ratio": round(test_rows / total_split, 4) if total_split else 0,
                    "method": request.splitMethod,
                    "train_size_requested": request.trainSize,
                    "use_seed": request.useSeed,
                    "random_seed": request.seedValue if request.useSeed else None,
                    "target_column": target_col_for_stats or request.targetColumn,
                    "balance_classes": bool(request.balanceClasses),
                    "balance_method": request.balanceMethod if request.balanceClasses else None,
                }

                conn.commit()

                return {
                    "status": "success",
                    "split_method": request.splitMethod,
                    "target_column": request.targetColumn,
                    "actual_target_column": target_col_for_stats,
                    "train_size": request.trainSize,
                    "use_seed": request.useSeed,
                    "seed_value": request.seedValue,
                    "statistics": stats,
                    "summary": summary,
                }

    except psycopg2.Error as e:
        conn.rollback()
        logger.error(f"Database error: {e.pgerror}")
        raise HTTPException(
            status_code=500,
            detail=f"Database operation failed: {e.pgerror}"
        )
    except HTTPException:
        raise  # Re-raise HTTP exceptions
    except Exception as e:
        logger.error(f"Unexpected error: {str(e)}", exc_info=True)
        raise HTTPException(
            status_code=500,
            detail=f"Internal server error: {str(e)}"
        )

@router.post("/prepare-table-columns")
async def prepare_table_columns(
    request: dict,
    current_user_id: str = Depends(get_current_user2)
):
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            if "bdName" not in request:
                raise HTTPException(status_code=400, detail="bdName is required")
            table_name = assert_owns_table(
                cur, request["bdName"], current_user_id, label="table"
            )
            print(f"Preparing columns for table: {table_name}")  # Debug log
            
            # 1. Check and add ID column
            cur.execute("""
                SELECT 1 FROM information_schema.columns 
                WHERE table_name = %s AND column_name = 'id'
            """, (table_name,))
            
            if not cur.fetchone():
                print("Adding ID column")  # Debug log
                cur.execute(sql.SQL("ALTER TABLE {} ADD COLUMN id SERIAL PRIMARY KEY")
                          .format(sql.Identifier(table_name)))
            
            # 2. Check and add split_type column
            cur.execute("""
                SELECT 1 FROM information_schema.columns 
                WHERE table_name = %s AND column_name = 'split_type'
            """, (table_name,))
            
            if not cur.fetchone():
                print("Adding split_type column")  # Debug log
                cur.execute(sql.SQL("ALTER TABLE {} ADD COLUMN split_type VARCHAR(10) DEFAULT NULL")
                          .format(sql.Identifier(table_name)))
            
            conn.commit()
            return {"status": "success", "message": "Columns prepared successfully"}
            
        except HTTPException:
            if conn:
                conn.rollback()
            raise
        except Exception as e:
            print(f"Error preparing columns: {str(e)}")  # Debug log
            if conn:
                conn.rollback()
            raise HTTPException(
                status_code=500,
                detail=f"Error preparing table columns: {str(e)}"
            )


@router.get("/get-split-info")
async def get_split_info(
    bdName: str,
    current_user_id: str = Depends(get_current_user2)
):
    """Get information about available target columns for splitting - USE SAVED TARGET COLUMN"""
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()

            # Verify table access and get saved target column
            cur.execute("""
                SELECT target_column, columns 
                FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (bdName.lower(), current_user_id))
            
            table_info = cur.fetchone()
            if not table_info:
                raise HTTPException(404, "Table not found or access denied")

            # Use the saved target column from metadata
            saved_target_column = table_info[0]
            
            # Get all columns for information
            cur.execute("""
                SELECT column_name, data_type 
                FROM information_schema.columns 
                WHERE table_name = %s 
                ORDER BY ordinal_position
            """, (bdName.lower(),))
            
            columns_info = cur.fetchall()
            all_columns = [row[0] for row in columns_info]
            
            return {
                "target_column": saved_target_column,  # Use the saved target column
                "available_columns": all_columns,
                "all_columns_with_types": [{"name": row[0], "type": row[1]} for row in columns_info],
                "is_target_saved": saved_target_column is not None
            }

        except psycopg2.Error as e:
            raise HTTPException(500, f"PostgreSQL error: {e.pgerror}")
        except Exception as e:
            raise HTTPException(500, f"Server error: {str(e)}")
def get_class_distribution(cur, table_name: str, target_column: str, split_type: str = None):
    """Récupère la distribution des classes.
    Si split_type est fourni (ex. 'train'), ne compte que ces lignes —
    indispensable pour éviter le data leakage lors du balancing.
    """
    try:
        if split_type:
            query = sql.SQL("""
                SELECT {target}, COUNT(*) as count 
                FROM {table} 
                WHERE {target} IS NOT NULL AND split_type = %s
                GROUP BY {target}
                ORDER BY {target}
            """).format(
                table=sql.Identifier(table_name),
                target=sql.Identifier(target_column)
            )
            cur.execute(query, (split_type,))
        else:
            query = sql.SQL("""
                SELECT {target}, COUNT(*) as count 
                FROM {table} 
                WHERE {target} IS NOT NULL
                GROUP BY {target}
                ORDER BY {target}
            """).format(
                table=sql.Identifier(table_name),
                target=sql.Identifier(target_column)
            )
            cur.execute(query)
        results = cur.fetchall()
        
        if not results:
            logger.warning(f"No valid target values found in {target_column}")
            return {}
            
        return {str(row[0]): row[1] for row in results}
        
    except Exception as e:
        logger.error(f"Error getting class distribution: {str(e)}")
        return {}








'''@@@@@@@@@@@@@@@@@@@@@@@@@@stop-training@@@@@@@@@@@@@@@@@@@'''
import uuid
from concurrent.futures import ThreadPoolExecutor, Future
from datetime import datetime
from fastapi import BackgroundTasks

# Stockage global
active_trainings = {}
training_stop_flags = {}

# Server-side model bytes for save (Solution 1): never trust client pickle.
# Survives DELETE /training-status; expires after TTL.
PENDING_SAVE_TTL_SECONDS = 5 * 60  # 5 minutes
pending_save_models = {}  # training_id -> {user_id, model_object, created_at}


def _purge_expired_pending_saves():
    now = time.time()
    expired = [
        tid
        for tid, info in list(pending_save_models.items())
        if now - info.get("created_at", 0) > PENDING_SAVE_TTL_SECONDS
    ]
    for tid in expired:
        pending_save_models.pop(tid, None)


def register_pending_save_model(training_id: str, user_id: str, result) -> None:
    """Keep trained model bytes on the server for a short save window."""
    if not training_id or not user_id or not isinstance(result, dict):
        return
    model_object = result.get("model_object")
    if not model_object or not isinstance(model_object, str) or not model_object.strip():
        return
    _purge_expired_pending_saves()
    pending_save_models[training_id] = {
        "user_id": str(user_id),
        "model_object": model_object,
        "created_at": time.time(),
    }
    logger.info(
        f"📦 Pending save registered for training {training_id} "
        f"(TTL {PENDING_SAVE_TTL_SECONDS}s)"
    )


def get_pending_save_model(training_id: str, user_id: str):
    """Return pending entry or None if missing/expired/wrong user."""
    _purge_expired_pending_saves()
    if not training_id:
        return None
    info = pending_save_models.get(training_id)
    if not info:
        return None
    if info.get("user_id") != str(user_id):
        return None
    age = time.time() - info.get("created_at", 0)
    if age > PENDING_SAVE_TTL_SECONDS:
        pending_save_models.pop(training_id, None)
        return None
    return info


def consume_pending_save_model(training_id: str, user_id: str) -> None:
    info = pending_save_models.get(training_id)
    if info and info.get("user_id") == str(user_id):
        pending_save_models.pop(training_id, None)


def _safe_set_training_result(training_id, result):
    """Complete a training Future only if still pending (avoid CANCELLED InvalidStateError)."""
    info = active_trainings.get(training_id)
    if not info:
        return
    info["completed"] = True
    info["result"] = result
    info["error"] = None
    register_pending_save_model(training_id, info.get("user_id"), result)
    future = info.get("future")
    if future is not None and not future.done():
        try:
            future.set_result(result)
        except Exception as e:
            logger.warning(f"Could not set_result for {training_id}: {e}")


def _safe_set_training_error(training_id, error_msg, *, stopped=False):
    """Mark training failed/stopped without crashing if Future was already cancelled."""
    info = active_trainings.get(training_id)
    if not info:
        return
    info["completed"] = True
    info["error"] = error_msg
    info["result"] = None if stopped else {
        "status": "error",
        "error_message": error_msg,
    }
    future = info.get("future")
    if future is not None and not future.done():
        try:
            future.set_exception(HTTPException(400, error_msg))
        except Exception as e:
            logger.warning(f"Could not set_exception for {training_id}: {e}")


def pack_predictions_for_response(
    y_true,
    y_pred,
    y_proba=None,
    y_train_true=None,
    y_train_pred=None,
    max_points: int = 3000,
):
    """Downsample prediction arrays so large datasets don't blow up JSON / UI."""
    y_true = np.asarray(y_true)
    y_pred = np.asarray(y_pred)
    n = int(y_true.shape[0])
    sampled = False
    if n > max_points:
        idx = np.linspace(0, n - 1, max_points).astype(int)
        y_true = y_true[idx]
        y_pred = y_pred[idx]
        if y_proba is not None:
            y_proba = np.asarray(y_proba)[idx]
        sampled = True

    out = {
        "y_true": y_true.tolist(),
        "y_pred": y_pred.tolist(),
        "y_proba": np.asarray(y_proba).tolist() if y_proba is not None else None,
        "n_total": n,
        "n_plotted": int(y_true.shape[0]),
        "sampled": sampled,
    }
    if y_train_true is not None and y_train_pred is not None:
        yt = np.asarray(y_train_true)
        yp = np.asarray(y_train_pred)
        nt = int(yt.shape[0])
        if nt > max_points:
            idx_t = np.linspace(0, nt - 1, max_points).astype(int)
            yt = yt[idx_t]
            yp = yp[idx_t]
        out["y_train_true"] = yt.tolist()
        out["y_train_pred"] = yp.tolist()
    return out


@router.post("/stop-training")
async def stop_training(
    request: dict,
    current_user_id: str = Depends(get_current_user2)
):
    """Arrête un entraînement en cours - VERSION CORRIGÉE AVEC ARRÊT RÉEL"""
    training_id = request.get('training_id')
    
    if training_id in active_trainings:
        training_info = active_trainings[training_id]
        
        # Vérifier l'autorisation
        if training_info['user_id'] != current_user_id:
            raise HTTPException(403, "Not authorized")
        
        # ✅ CRITIQUE: Activer le flag d'arrêt pour TOUS les modèles
        if training_id in training_stop_flags:
            training_stop_flags[training_id] = True
            logger.info(f"🛑 Stop flag activated for training {training_id}")
        
        # Do NOT cancel the Future here — it is only a status holder.
        # Cancelling it causes InvalidStateError when the worker later calls set_exception.
        # Real stop is driven by training_stop_flags + check_stop() in the trainer.
        
        # Marquer comme complété (polling will see error)
        training_info['completed'] = True
        training_info['error'] = "Training stopped by user"
        training_info['result'] = None
        
        # ✅ Planifier le nettoyage
        async def delayed_cleanup():
            await asyncio.sleep(30)  # Donner le temps pour le polling
            if training_id in active_trainings:
                del active_trainings[training_id]
                logger.info(f"🧹 Cleaned up stopped training {training_id}")
            if training_id in training_stop_flags:
                del training_stop_flags[training_id]
        
        asyncio.create_task(delayed_cleanup())
        
        return {"status": "stopped", "training_id": training_id}
    
    return {"status": "not_found"}

@router.get("/training-status/{training_id}")
async def get_training_status(
    training_id: str,
    current_user_id: str = Depends(get_current_user2),
):
    """Vérifie le statut d'un entraînement asynchrone (owner only)."""
    
    if training_id not in active_trainings:
        raise HTTPException(status_code=404, detail="Training ID not found")
    
    training_info = active_trainings[training_id]

    if training_info.get("user_id") != current_user_id:
        raise HTTPException(status_code=403, detail="Not authorized")
    
    # ✅ VÉRIFIER SI L'ENTRAÎNEMENT EST TERMINÉ
    if training_info.get('completed', False):
        result = training_info.get('result')
        
        # ✅ CORRECTION #1: Marquer comme récupéré mais NE PAS SUPPRIMER
        training_info['retrieved'] = True
        
        # ✅ CORRECTION #2: Planifier la suppression APRÈS un délai
        async def delayed_cleanup():
            await asyncio.sleep(30)  # Donner 30 secondes au frontend
            if training_id in active_trainings:
                # Ne supprimer que si déjà marqué comme récupéré
                if active_trainings[training_id].get('retrieved', False):
                    del active_trainings[training_id]
                    logger.info(f"🧹 Cleaned up completed training {training_id}")
        
        asyncio.create_task(delayed_cleanup())
        
        return {
            "completed": True,
            "result": result,
            "error": training_info.get("error"),
        }
    
    # ✅ Toujours renvoyer completed: False si pas terminé
    out = {
        "completed": False,
        "message": "Training in progress",
    }
    # Random Search / mid-training progress (optional)
    if training_info.get("progress"):
        out["progress"] = training_info["progress"]
    return out

@router.delete("/training-status/{training_id}")
async def delete_training_status(
    training_id: str,
    current_user_id: str = Depends(get_current_user2)
):
    """Supprime un training du cache APRÈS que le frontend a fini de l'utiliser"""
    if training_id in active_trainings:
        training_info = active_trainings[training_id]
        if training_info['user_id'] == current_user_id:
            # ✅ CORRECTION: Ne supprimer que si déjà récupéré
            if training_info.get('retrieved', False):
                del active_trainings[training_id]
                logger.info(f"🧹 Manual cleanup of training {training_id}")
                return {"status": "deleted"}
            else:
                # Marquer comme à supprimer plus tard
                training_info['pending_deletion'] = True
                logger.info(f"⏳ Training {training_id} marked for pending deletion")
                return {"status": "marked_for_deletion"}
    return {"status": "not_found"}
'''@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@'''









'''+++++++++++++++++ridge +++++++++++++++++'''

logger = logging.getLogger(__name__)



def ridge_holdout_repeated_with_models(X, y, n_repetitions, test_size, fit_intercept, alpha_search_space, check_stop=None):
    """Hold-Out répété avec sauvegarde des modèles pour Ridge - CORRIGÉ"""
    holdout_scores = []
    holdout_models = []
    repetition_details = []
    
    for i in range(n_repetitions):
        if check_stop:
            check_stop()
        # Sous-découpage ALÉATOIRE
        X_ho_train, X_ho_val, y_ho_train, y_ho_val = train_test_split(
            X, y, 
            test_size=test_size, 
            random_state=i  # Différent à chaque fois mais reproductible
        )
        
        # Validation des données
        if len(X_ho_train) == 0 or len(X_ho_val) == 0:
            logger.warning(f"Répétition {i+1}: Données insuffisantes après split")
            continue
            
        # Vérifier la variance
        if np.std(y_ho_train) < 1e-10 or np.std(y_ho_val) < 1e-10:
            logger.warning(f"Répétition {i+1}: Variance trop faible dans les données")
            continue
        
        best_alpha = 1.0
        best_score = -np.inf
        alpha_scores = []
        
        for alpha in alpha_search_space:
            try:
                model = Ridge(alpha=alpha, fit_intercept=fit_intercept, random_state=None)
                model.fit(X_ho_train, y_ho_train)
                
                # Calcul R² robuste
                y_pred = model.predict(X_ho_val)
                ss_res = np.sum((y_ho_val - y_pred) ** 2)
                ss_tot = np.sum((y_ho_val - np.mean(y_ho_val)) ** 2)
                
                if ss_tot == 0:
                    score = 0.0
                else:
                    score = 1 - (ss_res / ss_tot)
                
                # Limiter les valeurs extrêmes
                if np.isnan(score) or np.isinf(score):
                    score = 0.0
                
                alpha_scores.append({
                    "alpha": alpha,
                    "score": float(score)
                })
                
                if score > best_score:
                    best_score = score
                    best_alpha = alpha
                    
            except Exception as e:
                logger.warning(f"Répétition {i+1}, alpha {alpha}: {e}")
                continue
        
        # Créer et entraîner le modèle avec l'alpha optimal
        model_ho = Ridge(alpha=best_alpha, fit_intercept=fit_intercept, random_state=None)
        model_ho.fit(X_ho_train, y_ho_train)
        
        # Calculer les scores FINAUX de manière robuste
        y_val_pred = model_ho.predict(X_ho_val)
        y_train_pred = model_ho.predict(X_ho_train)
        
        # R² pour validation
        ss_res_val = np.sum((y_ho_val - y_val_pred) ** 2)
        ss_tot_val = np.sum((y_ho_val - np.mean(y_ho_val)) ** 2)
        final_score = 1 - (ss_res_val / ss_tot_val) if ss_tot_val != 0 else 0.0
        
        # R² pour entraînement
        ss_res_train = np.sum((y_ho_train - y_train_pred) ** 2)
        ss_tot_train = np.sum((y_ho_train - np.mean(y_ho_train)) ** 2)
        train_score = 1 - (ss_res_train / ss_tot_train) if ss_tot_train != 0 else 0.0
        
        # Limiter les valeurs
        final_score = max(-1.0, min(1.0, final_score))
        train_score = max(-1.0, min(1.0, train_score))
        
        holdout_scores.append(final_score)
        holdout_models.append(model_ho)
        
        repetition_details.append({
            'repetition': i + 1,
            'score': float(final_score),
            'train_score': float(train_score),
            'best_alpha': float(best_alpha),
            'train_size': len(X_ho_train),
            'validation_size': len(X_ho_val),
            'test_size_percent': test_size * 100,
            'alpha_search_details': alpha_scores
        })
        
        logger.info(f"Répétition {i+1}: Alpha={best_alpha:.4f}, Val R²={final_score:.4f}, Train R²={train_score:.4f}")
    
    if not holdout_scores:
        raise ValueError("Aucune répétition Hold-Out n'a produit de résultats valides")
    
    # Trouver le meilleur modèle
    best_model_idx = np.argmax(holdout_scores)
    
    return holdout_scores, holdout_models, repetition_details, best_model_idx



def robust_nested_cv_optimization(X, y, outer_cv, inner_cv, alpha_search_space):
    """Nested CV robuste avec sauvegarde des modèles"""
    
    alpha_performance_all = {alpha: [] for alpha in alpha_search_space}
    fold_results = []
    local_alphas = []
    fold_models = []  # ✅ NOUVEAU : Sauvegarder les modèles
    
    for fold_idx, (train_idx, val_idx) in enumerate(outer_cv.split(X, y)):
        X_train_fold, X_val_fold = X[train_idx], X[val_idx]
        y_train_fold, y_val_fold = y[train_idx], y[val_idx]
        
        # Optimisation d'alpha sur le fold d'entraînement
        best_alpha_fold = 1.0
        best_inner_score = -np.inf
        inner_alpha_scores = []
        
        for alpha in alpha_search_space:
            try:
                model = Ridge(alpha=alpha, random_state=None)
                inner_scores = cross_val_score(
                    model, X_train_fold, y_train_fold,
                    cv=inner_cv, scoring='r2', n_jobs=-1
                )
                mean_score = np.mean(inner_scores)
                
                inner_alpha_scores.append({
                    "alpha": alpha,
                    "score": float(mean_score),
                    "std": float(np.std(inner_scores))
                })
                
                if mean_score > best_inner_score:
                    best_inner_score = mean_score
                    best_alpha_fold = alpha
                    
            except Exception as e:
                logger.warning(f"Fold {fold_idx+1}, alpha {alpha}: {e}")
                continue
        
        local_alphas.append(best_alpha_fold)
        
        # ✅ CORRECTION : Entraîner et sauvegarder le modèle pour ce fold
        fold_model = Ridge(alpha=best_alpha_fold, random_state=None)
        fold_model.fit(X_train_fold, y_train_fold)
        fold_models.append(fold_model)  # ← SAUVEGARDE
        
        val_score = fold_model.score(X_val_fold, y_val_fold)
        train_score = fold_model.score(X_train_fold, y_train_fold)
        
        # Stocker les performances de tous les alphas sur ce fold
        for alpha in alpha_search_space:
            try:
                alpha_model = Ridge(alpha=alpha, random_state=None)
                alpha_model.fit(X_train_fold, y_train_fold)
                alpha_score = alpha_model.score(X_val_fold, y_val_fold)
                alpha_performance_all[alpha].append(alpha_score)
            except Exception as e:
                logger.warning(f"Alpha {alpha} evaluation failed: {e}")
                alpha_performance_all[alpha].append(-np.inf)
        
        fold_results.append({
            "fold": fold_idx + 1,
            "best_alpha": best_alpha_fold,
            "inner_cv_score": float(best_inner_score),
            "outer_val_score": float(val_score),
            "train_r2": float(train_score),
            "alpha_search_details": inner_alpha_scores
        })
    
    # Trouver l'alpha le plus fréquent
    alpha_counts = {}
    for alpha in local_alphas:
        alpha_counts[alpha] = alpha_counts.get(alpha, 0) + 1
    
    best_alpha_global = max(alpha_counts.items(), key=lambda x: x[1])[0]
    frequency = alpha_counts[best_alpha_global]
    total_folds = len(local_alphas)
    
    logger.info(f"Alpha optimal GLOBAL (plus fréquent): {best_alpha_global}, Fréquence: {frequency}/{total_folds}")
    
    # ✅ CORRECTION : Retourner aussi les modèles des folds
    return best_alpha_global, fold_results, fold_models, alpha_performance_all


def bootstrap_alpha_optimization(X, y, n_bootstraps, test_size, alpha_search_space, sample_size=1.0):
    """Optimisation d'alpha avec bootstrap - COMPLÈTEMENT CORRIGÉE"""
    
    bootstrap_results = []
    local_alphas = []
    bootstrap_scores = []
    
    n_samples = len(X)
    
    for i in range(n_bootstraps):
        try:
            # 1. Échantillonnage bootstrap
            train_indices = np.random.choice(
                n_samples, 
                size=int(n_samples * sample_size), 
                replace=True
            )
            
            # 2. Indices OOB (out-of-bag)
            all_indices = np.arange(n_samples)
            val_indices = np.setdiff1d(all_indices, train_indices)
            
            # 3. S'assurer qu'on a suffisamment de données
            if len(val_indices) < 5:
                # Compléter avec quelques échantillons du training
                n_needed = max(5, len(train_indices) // 10)
                extra_indices = np.random.choice(
                    train_indices, 
                    size=min(n_needed, len(train_indices)), 
                    replace=False
                )
                val_indices = np.concatenate([val_indices, extra_indices])
                train_indices = np.setdiff1d(train_indices, extra_indices)
            
            if len(train_indices) < 10 or len(val_indices) < 5:
                continue
            
            X_train_bs = X[train_indices]
            y_train_bs = y[train_indices]
            X_val_bs = X[val_indices]
            y_val_bs = y[val_indices]
            
            # 4. Vérifier la variance
            if np.std(y_train_bs) < 1e-10 or np.std(y_val_bs) < 1e-10:
                continue
            
            # 5. Recherche d'alpha
            best_alpha_bs = 1.0
            best_score_bs = -np.inf
            alpha_scores_bs = []
            
            for alpha in alpha_search_space:
                try:
                    model = Ridge(alpha=alpha, random_state=None)
                    model.fit(X_train_bs, y_train_bs)
                    
                    # Calcul R² robuste
                    y_pred = model.predict(X_val_bs)
                    ss_res = np.sum((y_val_bs - y_pred) ** 2)
                    ss_tot = np.sum((y_val_bs - np.mean(y_val_bs)) ** 2)
                    
                    if ss_tot == 0:
                        score = 0.0
                    else:
                        score = 1 - (ss_res / ss_tot)
                    
                    # Limiter les valeurs
                    if np.isnan(score) or np.isinf(score):
                        score = 0.0
                    score = max(-1.0, min(1.0, score))
                    
                    alpha_scores_bs.append({
                        "alpha": alpha,
                        "score": float(score)
                    })
                    
                    if score > best_score_bs:
                        best_score_bs = score
                        best_alpha_bs = alpha
                        
                except Exception as e:
                    continue
            
            if best_score_bs == -np.inf:
                continue
            
            # 6. Entraîner le modèle final pour ce bootstrap
            final_model = Ridge(alpha=best_alpha_bs, random_state=None)
            final_model.fit(X_train_bs, y_train_bs)
            
            # Calcul des scores finaux
            y_val_pred = final_model.predict(X_val_bs)
            y_train_pred = final_model.predict(X_train_bs)
            
            # R² validation
            ss_res_val = np.sum((y_val_bs - y_val_pred) ** 2)
            ss_tot_val = np.sum((y_val_bs - np.mean(y_val_bs)) ** 2)
            val_score = 1 - (ss_res_val / ss_tot_val) if ss_tot_val != 0 else 0.0
            
            # R² entraînement
            ss_res_train = np.sum((y_train_bs - y_train_pred) ** 2)
            ss_tot_train = np.sum((y_train_bs - np.mean(y_train_bs)) ** 2)
            train_score = 1 - (ss_res_train / ss_tot_train) if ss_tot_train != 0 else 0.0
            
            # Limiter les valeurs
            val_score = max(-1.0, min(1.0, val_score))
            train_score = max(-1.0, min(1.0, train_score))
            
            local_alphas.append(best_alpha_bs)
            bootstrap_scores.append(val_score)
            
            bootstrap_results.append({
                "bootstrap": i + 1,
                "best_alpha": float(best_alpha_bs),
                "validation_score": float(val_score),
                "train_r2": float(train_score),
                "train_size": len(X_train_bs),
                "validation_size": len(X_val_bs),
                "sample_size_used": float(sample_size),
                "alpha_search_details": alpha_scores_bs
            })
            
        except Exception as e:
            logger.error(f"Erreur bootstrap {i+1}: {e}")
            continue
    
    if not bootstrap_results:
        # Fallback: utiliser alpha par défaut
        best_alpha = 1.0
        logger.warning("Aucun bootstrap valide, utilisation d'alpha=1.0")
    else:
        # Trouver l'alpha le plus fréquent
        from collections import Counter
        alpha_counts = Counter(local_alphas)
        best_alpha = alpha_counts.most_common(1)[0][0]
        
        # Calculer les statistiques
        validation_scores = [bs['validation_score'] for bs in bootstrap_results]
        train_scores = [bs['train_r2'] for bs in bootstrap_results]
        
        logger.info(f"Bootstrap terminé: {len(bootstrap_results)} échantillons valides")
        logger.info(f"Alpha optimal: {best_alpha}, Scores: {np.mean(validation_scores):.4f} ± {np.std(validation_scores):.4f}")
    
    return best_alpha, bootstrap_results, [], {}
class TrainModelRequest(BaseModel):
    numerized_dataset_name: str
    original_dataset_name: str
    model_type: str = "ridge"
    fit_intercept: bool = True
    validation_method: Optional[str] = "holdout"
    n_repetitions: int = Field(default=10, gt=0, le=50, description="Number of repetitions for Hold-Out")
    cv_params: Optional[Dict[str, Any]] = None
    bootstrap_params: Optional[Dict[str, Any]] = None
    time_series_params: Optional[Dict[str, Any]] = None  
    alpha_search_space: Optional[List[float]] = None
    training_id: Optional[str] = None
    # Used by background worker so Stop can be checked without re-entering async mode
    stop_check_training_id: Optional[str] = None
    sample_size: Optional[float] = Field(default=1.0, gt=0.1, le=1.0, description="Bootstrap sample size")
    date_column: Optional[str] = None
    # Random Search (optional). When True, disables multi-alpha internal grid.
    random_search: bool = False
    n_trials: Optional[int] = Field(default=20, ge=1, le=50)
    random_search_seed: Optional[int] = 42

def optimize_alpha_simple(X_train, y_train, X_val, y_val, alpha_search_space):
    """Optimisation simple d'alpha avec validation set"""
    best_alpha = 1.0
    best_score = -np.inf
    alpha_performance = []
    
    for alpha in alpha_search_space:
        try:
            model = Ridge(alpha=alpha, random_state=None)
            model.fit(X_train, y_train)
            score = model.score(X_val, y_val)
            
            alpha_performance.append({
                "alpha": alpha,
                "score": float(score)
            })
            
            if score > best_score:
                best_score = score
                best_alpha = alpha
                
        except Exception as e:
            logger.warning(f"Alpha {alpha} failed: {e}")
            continue
    
    return best_alpha, alpha_performance, best_score

def safe_preprocessing_for_split_data(df, target_column):
    """Preprocessing qui respecte les splits existants - SANS DATA LEAKAGE"""
    logger.info("🔧 Début du preprocessing SANS data leakage...")
    
    # 1. SÉPARER D'ABORD les données selon split_type
    train_mask = df['split_type'] == 'train'
    test_mask = df['split_type'] == 'test'
    
    df_train = df[train_mask].copy()
    df_test = df[test_mask].copy()
    
    logger.info(f"📊 Séparation: {len(df_train)} train, {len(df_test)} test")
    
    # 2. Fonction de preprocessing pour un split
    def preprocess_split(df_split, is_training=True, train_stats=None):
        
        df_processed = df_split.copy()
        
        for col in df_processed.columns:
            if col in ['split_type']: 
                continue
                
            # Conversion numérique
            original_dtype = df_processed[col].dtype
            df_processed[col] = pd.to_numeric(df_processed[col], errors='coerce')
            
            # Vérifier les NaN après conversion
            nan_count = df_processed[col].isna().sum()
            if nan_count > 0:
                logger.warning(f"Colonne {col}: {nan_count} NaN après conversion")
                
                if is_training:
                    # En training : calculer nos statistiques
                    if col == target_column:
                        if df_processed[col].notna().sum() > 0:
                            fill_val = df_processed[col].mode()[0] if not df_processed[col].mode().empty else 0
                        else:
                            fill_val = 0
                    else:
                        if df_processed[col].notna().sum() > 0:
                            fill_val = df_processed[col].median()
                        else:
                            fill_val = 0
                    
                    # Sauvegarder pour le test
                    if train_stats is not None:
                        train_stats[col] = fill_val
                        logger.info(f"📝 Statistique sauvegardée pour {col}: {fill_val}")
                else:
                    # En test : utiliser les statistiques du train
                    fill_val = train_stats.get(col, 0)
                    logger.info(f"🔧 Test: {col} rempli avec {fill_val} (statistique train)")
                
                df_processed[col] = df_processed[col].fillna(fill_val)
            
            # Log de conversion
            if original_dtype != df_processed[col].dtype:
                logger.info(f"🔄 {col}: {original_dtype} -> {df_processed[col].dtype}")
        
        return df_processed, train_stats
    
    # 3. APPLIQUER D'ABORD AU TRAIN (calcule les statistiques)
    train_stats = {}
    logger.info("🎯 Preprocessing des données TRAIN...")
    df_train_processed, train_stats = preprocess_split(df_train, is_training=True, train_stats=train_stats)
    
    # 4. PUIS AU TEST AVEC LES STATS DU TRAIN (pas de calcul)
    logger.info("🎯 Preprocessing des données TEST avec statistiques TRAIN...")
    df_test_processed, _ = preprocess_split(df_test, is_training=False, train_stats=train_stats)
    
    # 5. RECOMBINER
    df_final = pd.concat([df_train_processed, df_test_processed])
    
    logger.info("✅ Preprocessing terminé SANS data leakage")
    return df_final

def ensure_numeric_dataframe_split(df_split, name, train_stats=None):
    """Version sans leakage de ensure_numeric_dataframe"""
    non_numeric_cols = df_split.select_dtypes(exclude=[np.number]).columns.tolist()
    non_numeric_cols = [col for col in non_numeric_cols if col != 'split_type']
    
    if non_numeric_cols:
        logger.warning(f"{name} - Colonnes non numériques détectées: {non_numeric_cols}")
        for col in non_numeric_cols:
            logger.info(f"Conversion de {col}: {df_split[col].dtype} -> numérique")
            df_split[col] = pd.to_numeric(df_split[col], errors='coerce')
            
            # Remplir les NaN
            if df_split[col].isna().any():
                if train_stats and col in train_stats:
                    # Utiliser les statistiques du train
                    fill_val = train_stats[col]
                elif df_split[col].notna().sum() > 0:
                    # Calcul local (seulement si nécessaire)
                    fill_val = df_split[col].median()
                else:
                    fill_val = 0
                
                df_split[col] = df_split[col].fillna(fill_val)
                logger.info(f"Colonne {col} remplie avec {fill_val}")
    
    return df_split


def timeseries_alpha_optimization(X, y, date_series, n_splits, test_size, gap, 
                                   alpha_search_space, fit_intercept, feature_columns):
    """
    Optimisation d'alpha avec TimeSeriesSplit — tri chronologique avant split.
    date_series must be aligned with X/y (train rows only).
    """
    logger.info("=" * 80)
    logger.info("🕒 TIMESERIES SPLIT OPTIMIZATION STARTED")
    logger.info("=" * 80)
    
    logger.info(f"📊 Colonnes utilisées pour l'entraînement (features): {feature_columns}")
    logger.info(f"⚙️ Paramètres TimeSeries: n_splits={n_splits}, test_size={test_size}, gap={gap}")
    
    n_samples = len(X)
    logger.info(f"📊 Nombre total d'échantillons: {n_samples}")

    if date_series is None or len(date_series) != n_samples:
        logger.warning(
            f"⚠️ date_series length mismatch ({None if date_series is None else len(date_series)} vs {n_samples}) "
            "— falling back to row order"
        )
        date_values = list(range(n_samples))
    else:
        date_values = pd.to_datetime(date_series, errors="coerce")
    
    if isinstance(test_size, float) and test_size < 1:
        test_size_samples = int(n_samples * test_size)
        logger.info(f"   test_size={test_size} (proportion) → {test_size_samples} échantillons")
    else:
        test_size_samples = int(test_size)
        logger.info(f"   test_size={test_size_samples} échantillons")
    
    min_samples_needed = (n_splits + 1) * test_size_samples
    if min_samples_needed > n_samples:
        logger.warning(f"⚠️  test_size={test_size_samples} trop grand pour {n_samples} échantillons avec {n_splits} splits")
        logger.info(f"   Ajustement automatique de test_size...")
        
        max_test_size = n_samples // (n_splits + 1)
        if max_test_size < 1:
            logger.error(f"❌ Impossible: besoin d'au moins {n_splits + 1} échantillons")
            n_splits = max(2, n_samples // 3)
            max_test_size = n_samples // (n_splits + 1)
            logger.info(f"   Réduction de n_splits à {n_splits}, test_size={max_test_size}")
        
        test_size_samples = max(1, max_test_size)
    
    # Sort chronologically before TimeSeriesSplit
    if not isinstance(X, pd.DataFrame):
        X_df = pd.DataFrame(X, columns=feature_columns)
    else:
        X_df = X.copy()
    temp_df = X_df.copy()
    temp_df["__target__"] = y
    temp_df["__date__"] = date_values
    temp_df = temp_df.sort_values("__date__", kind="mergesort").reset_index(drop=True)
    X_sorted = temp_df[feature_columns]
    y_sorted = temp_df["__target__"].values

    tscv = TimeSeriesSplit(n_splits=n_splits, test_size=test_size_samples, gap=gap)
    
    fold_results = []
    local_alphas = []
    fold_models = []
    alpha_performance_all = {alpha: [] for alpha in alpha_search_space}
    
    total_folds = tscv.get_n_splits()
    logger.info(f"📊 Nombre de splits temporels effectifs: {total_folds}")
    
    fold_count = 0
    for fold_idx, (train_idx, val_idx) in enumerate(tscv.split(X_sorted)):
        fold_count += 1
        logger.info(f"🔍 Fold {fold_count}/{total_folds}")
        
        logger.info(f"   Train indices: {train_idx[0]} → {train_idx[-1]} (taille: {len(train_idx)})")
        logger.info(f"   Val indices:   {val_idx[0]} → {val_idx[-1]} (taille: {len(val_idx)})")
        
        X_train_fold = X_sorted.iloc[train_idx].values
        X_val_fold = X_sorted.iloc[val_idx].values
        y_train_fold = y_sorted[train_idx]
        y_val_fold = y_sorted[val_idx]
        
        logger.info(f"   X_train shape: {X_train_fold.shape}, y_train shape: {y_train_fold.shape}")
        logger.info(f"   X_val shape: {X_val_fold.shape}, y_val shape: {y_val_fold.shape}")
        
        # Vérifier qu'on a assez de données
        if len(X_train_fold) < 5 or len(X_val_fold) < 1:
            logger.warning(f"   ⚠️  Pas assez de données, skip ce fold")
            continue
        
        # Optimisation d'alpha sur ce fold
        best_alpha_fold = 1.0
        best_score_fold = -np.inf
        inner_alpha_scores = []
        
        for alpha in alpha_search_space:
            try:
                model = Ridge(alpha=alpha, fit_intercept=fit_intercept, random_state=None)
                model.fit(X_train_fold, y_train_fold)
                
                # Calcul du R²
                y_pred = model.predict(X_val_fold)
                score = r2_score(y_val_fold, y_pred)
                
                inner_alpha_scores.append({
                    "alpha": alpha,
                    "score": float(score)
                })
                
                if score > best_score_fold:
                    best_score_fold = score
                    best_alpha_fold = alpha
                    
            except Exception as e:
                logger.warning(f"   Alpha {alpha} failed: {e}")
                continue
        
        if best_score_fold == -np.inf:
            logger.warning(f"   ⚠️  Aucun alpha valide pour ce fold, skip")
            continue
        
        logger.info(f"   ✅ Meilleur alpha pour ce fold: {best_alpha_fold} (score: {best_score_fold:.4f})")
        
        local_alphas.append(best_alpha_fold)
        
        # Entraîner le modèle final pour ce fold avec le meilleur alpha
        fold_model = Ridge(alpha=best_alpha_fold, fit_intercept=fit_intercept, random_state=None)
        fold_model.fit(X_train_fold, y_train_fold)
        fold_models.append(fold_model)
        
        # Évaluer sur validation
        val_score = fold_model.score(X_val_fold, y_val_fold)
        train_score = fold_model.score(X_train_fold, y_train_fold)
        
        logger.info(f"   Train R²: {train_score:.4f}, Validation R²: {val_score:.4f}")
        
        # Stocker les performances de tous les alphas
        for alpha in alpha_search_space:
            try:
                alpha_model = Ridge(alpha=alpha, fit_intercept=fit_intercept, random_state=None)
                alpha_model.fit(X_train_fold, y_train_fold)
                alpha_score = alpha_model.score(X_val_fold, y_val_fold)
                alpha_performance_all[alpha].append(alpha_score)
            except Exception:
                alpha_performance_all[alpha].append(-np.inf)
        
        fold_results.append({
            "fold": fold_count,
            "best_alpha": float(best_alpha_fold),
            "train_r2": float(train_score),
            "validation_r2": float(val_score),
            "train_size": len(X_train_fold),
            "validation_size": len(X_val_fold),
            "train_indices": [int(train_idx[0]), int(train_idx[-1])],
            "val_indices": [int(val_idx[0]), int(val_idx[-1])],
            "alpha_search_details": inner_alpha_scores
        })
    
    if not fold_results:
        # Fallback: utiliser tous les échantillons pour l'entraînement final
        logger.error("❌ Aucun fold valide pour TimeSeriesSplit, fallback sur holdout simple")
        # Créer un modèle avec alpha=1.0
        dummy_model = Ridge(alpha=1.0, fit_intercept=fit_intercept, random_state=None)
        return 1.0, [], [dummy_model], {}
    
    # Trouver l'alpha le plus fréquent
    from collections import Counter
    alpha_counts = Counter(local_alphas)
    best_alpha_global = alpha_counts.most_common(1)[0][0]
    
    logger.info("=" * 80)
    logger.info(f"🏆 RÉSULTATS TIMESERIES SPLIT")
    logger.info(f"   Alphas par fold: {local_alphas}")
    logger.info(f"   Alpha le plus fréquent: {best_alpha_global}")
    logger.info(f"   Fréquence: {alpha_counts[best_alpha_global]}/{len(local_alphas)}")
    
    # Statistiques des scores
    val_scores = [fold['validation_r2'] for fold in fold_results]
    logger.info(f"   Validation R² moyen: {np.mean(val_scores):.4f} ± {np.std(val_scores):.4f}")
    logger.info("=" * 80)
    
    return best_alpha_global, fold_results, fold_models, alpha_performance_all





@router.post("/ridge")
async def train_model(
    request: TrainModelRequest,
    background_tasks: BackgroundTasks = None,
    current_user_id: str = Depends(get_current_user2)
):  
    # ========== 1. MODE ASYNCHRONE (BACKGROUND) ==========
    if hasattr(request, 'training_id') and request.training_id and background_tasks is not None:
        training_id = request.training_id
        
        def train_in_background():
            import asyncio
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)
            
            try:
                new_request = request.copy()
                # Clear training_id so sync path runs; keep stop id for check_stop()
                new_request.training_id = None
                new_request.stop_check_training_id = training_id
                
                result = loop.run_until_complete(
                    train_model(new_request, None, current_user_id)
                )
                
                if training_id in active_trainings:
                    active_trainings[training_id]['completed'] = True
                    active_trainings[training_id]['result'] = result
                    _safe_set_training_result(training_id, result)
                    
                    logger.info(f"✅ Training {training_id} marked as completed")
                
            except Exception as e:
                if training_id in active_trainings:
                    active_trainings[training_id]['completed'] = True
                    active_trainings[training_id]['error'] = str(e)
                    _safe_set_training_error(training_id, error_msg, stopped=False)
                    logger.error(f"❌ Training {training_id} failed: {e}")
            finally:
                loop.close()
        
        from concurrent.futures import Future
        future = Future()
        
        training_stop_flags[training_id] = False
        active_trainings[training_id] = {
            'future': future,
            'user_id': current_user_id,
            'start_time': datetime.now(),
            'model_type': 'ridge',
            'completed': False,
            'result': None,
            'error': None,
            'retrieved': False,
            'progress': None,
        }
        
        background_tasks.add_task(train_in_background)
        
        return {
            "status": "training_started",
            "training_id": training_id,
            "message": "Training started in background"
        }
    
    # ========== 2. MODE SYNCHRONE (EXÉCUTION NORMALE) ==========
    try:
        stop_id = getattr(request, "stop_check_training_id", None)

        def check_stop():
            if stop_id and training_stop_flags.get(stop_id, False):
                logger.info(f"🛑 Ridge training {stop_id} stopped by user")
                raise HTTPException(400, "Training stopped by user")

        check_stop()
        random_search_meta = None

        # Validation des entrées
        if not request.numerized_dataset_name or not request.original_dataset_name:
            raise HTTPException(400, "Dataset names missing")

        # Récupération de la colonne cible
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                cur.execute("""
                    SELECT target_column 
                    FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (request.original_dataset_name.lower(), current_user_id))
                
                target_info = cur.fetchone()
                if not target_info or not target_info[0]:
                    raise HTTPException(400, "Target column not defined in original dataset")
                
                target_column = target_info[0]

                # Vérification de la table numérisée
                cur.execute("""
                    SELECT 1 FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (request.numerized_dataset_name.lower(), current_user_id))
                
                if not cur.fetchone():
                    raise HTTPException(404, "Numerized dataset not found or access denied")

                # Vérification de la colonne cible
                cur.execute("""
                    SELECT 1 FROM information_schema.columns
                    WHERE table_name = %s AND column_name = %s
                """, (request.numerized_dataset_name.lower(), target_column))
                
                if not cur.fetchone():
                    raise HTTPException(400, f"Colonne cible '{target_column}' manquante dans la version numérisée")

                # Chargement des données
                cur.execute(sql.SQL("""
                    SELECT {}, split_type FROM {}
                    WHERE split_type IS NOT NULL
                """).format(
                    sql.SQL(',').join(
                        sql.Identifier(col) for col in 
                        get_table_columns(cur, request.numerized_dataset_name)
                        if col not in ['id', 'split_type']
                    ),
                    sql.Identifier(request.numerized_dataset_name.lower())
                ))
                
                rows = cur.fetchall()
                columns = [desc[0] for desc in cur.description if desc[0] != 'split_type']

        # Préparation des données
        df = pd.DataFrame(rows, columns=columns + ['split_type'])
        
        # Debug des types de données
        logger.info(f"Colonnes du dataset: {df.columns.tolist()}")
        logger.info(f"Types de données initiaux: {df.dtypes.to_dict()}")
        logger.info(f"Target column: {target_column}")
        
        # ✅ CORRECTION : PREPROCESSING SANS LEAKAGE
        logger.info("🛡️  Application du preprocessing SANS data leakage...")
        df = safe_preprocessing_for_split_data(df, target_column)
        logger.info(f"Types de données après conversion: {df.dtypes.to_dict()}")
        
        # Validation des splits
        if 'split_type' not in df.columns:
            raise HTTPException(400, "split_type column missing")
        
        # Variables pour stocker les résultats finaux
        final_model = None
        final_predictions = None
        validation_results = None
        test_metrics = None
        train_metrics = None
        X_for_features = None
        used_validation_model = False
        final_model_source = "standard_holdout"
        
        # Sélection de la méthode de validation
        validation_method = request.validation_method or "holdout"
        
        # SÉPARATION DES DONNÉES TRAIN/TEST
        train_mask = df['split_type'] == 'train'
        test_mask = df['split_type'] == 'test'
        
        if sum(train_mask) == 0:
            raise HTTPException(400, "Training data missing")
        if sum(test_mask) == 0:
            raise HTTPException(400, "Test data missing")

        # Date policy: always exclude date columns from features.
        # TimeSeries validation uses one date column only for chronological order.
        req_date = resolve_request_date_column(request)
        date_column = None
        if validation_method == "cv_timeseries":
            if req_date:
                date_column = req_date
                logger.info(f"📅 Colonne date reçue du frontend: {date_column}")
                if date_column not in df.columns:
                    raise HTTPException(400, f"Colonne date '{date_column}' non trouvée dans le dataset")
            else:
                date_column = detect_date_column_in_df(df)
                if date_column:
                    logger.info(f"📅 Colonne date détectée automatiquement: {date_column}")
                else:
                    raise HTTPException(400, "TimeSeriesSplit requires a date column, but none was detected")
        else:
            date_column = req_date or detect_date_column_in_df(df)

        # Identifier les colonnes à utiliser pour l'entraînement (toutes sauf target et split_type)
        feature_columns = [col for col in df.columns if col not in [target_column, 'split_type', 'id']]
        feature_columns = exclude_date_columns_from_list(
            df, feature_columns, date_column=date_column, target_column=target_column
        )
        
        logger.info(f"📊 Features utilisées pour l'entraînement: {feature_columns}")
        
        # Extraire les données
        X_train_full = df[train_mask][feature_columns]
        y_train_full = df[train_mask][target_column]
        X_test = df[test_mask][feature_columns]
        y_test = df[test_mask][target_column]

        # ✅ CORRECTION : PREPROCESSING FINAL SÉPARÉ
        logger.info("🔧 Preprocessing final séparé...")
        
        # Vérifier et convertir les features
        X_train_full = ensure_numeric_dataframe_split(X_train_full, "X_train_full")
        X_test = ensure_numeric_dataframe_split(X_test, "X_test")
        
        # Vérifier et convertir les targets
        y_train_full = pd.to_numeric(y_train_full, errors='coerce')
        y_test = pd.to_numeric(y_test, errors='coerce')
        
        # Remplir les NaN dans les targets avec statistiques LOCALES
        if y_train_full.isna().any():
            logger.warning(f"y_train_full: {y_train_full.isna().sum()} NaN détectés")
            if y_train_full.notna().sum() > 0:
                fill_val = y_train_full.mode()[0] if not y_train_full.mode().empty else y_train_full.median()
            else:
                fill_val = 0
            y_train_full = y_train_full.fillna(fill_val)
        
        if y_test.isna().any():
            logger.warning(f"y_test: {y_test.isna().sum()} NaN détectés")
            if y_test.notna().sum() > 0:
                fill_val = y_test.mode()[0] if not y_test.mode().empty else y_test.median()
            else:
                fill_val = 0
            y_test = y_test.fillna(fill_val)
        
        # Remplir les NaN dans les features
        X_train_full = X_train_full.fillna(X_train_full.median(numeric_only=True))
        for col in X_test.columns:
            if X_test[col].isna().any() and col in X_train_full.columns:
                if X_train_full[col].notna().sum() > 0:
                    fill_val = X_train_full[col].median()
                    X_test[col] = X_test[col].fillna(fill_val)
        
        logger.info(f"Forme X_train_full: {X_train_full.shape}, y_train_full: {y_train_full.shape}")
        logger.info(f"Forme X_test: {X_test.shape}, y_test: {y_test.shape}")

        # Conversion en numpy arrays
        check_stop()
        X_train_full_values = X_train_full.values.astype(float)
        X_test_values = X_test.values.astype(float)
        y_train_full_values = y_train_full.values.astype(float)
        y_test_values = y_test.values.astype(float)
        
        logger.info(f"Conversion numpy - X_train_full: {X_train_full_values.dtype}, y_train_full: {y_train_full_values.dtype}")
        
        # OPTIMISATION D'ALPHA AMÉLIORÉE
        best_alpha = 1.0
        # Random Search ON → find best alpha cheaply, then disable multi-alpha internal grid
        if getattr(request, "random_search", False):
            from backend.random_search_hp import run_hyperparam_random_search
            rs_best, random_search_meta = run_hyperparam_random_search(
                "ridge",
                X_train_full_values,
                y_train_full_values,
                n_trials=getattr(request, "n_trials", 20),
                is_classification=False,
                check_stop=check_stop,
                active_trainings=active_trainings,
                training_id=stop_id,
                fixed_params={"fit_intercept": request.fit_intercept},
                random_state=int(getattr(request, "random_search_seed", 42) or 42),
            )
            alpha_search_space = [float(rs_best["alpha"])]
            logger.info(f"🎲 Random Search best alpha={alpha_search_space[0]} (internal alpha grid disabled)")
        else:
            alpha_search_space = request.alpha_search_space or [0.001, 0.01, 0.1, 1, 10, 100, 1000]
        
        # Gestion de toutes les méthodes de validation
        if validation_method == "holdout":
            # HOLDOUT RÉPÉTÉ
            test_size = 0.2
            
            holdout_scores, holdout_models, repetition_details, best_model_idx = ridge_holdout_repeated_with_models(
                X_train_full_values, y_train_full_values, 
                request.n_repetitions, test_size,
                request.fit_intercept, alpha_search_space,
                check_stop=check_stop,
            )
            
            validation_model = holdout_models[best_model_idx]
            best_alpha = repetition_details[best_model_idx]['best_alpha']
            
            final_model = Ridge(alpha=best_alpha, fit_intercept=request.fit_intercept, random_state=None)
            check_stop()
            final_model.fit(X_train_full_values, y_train_full_values)
            used_validation_model = True
            final_model_source = f"best_holdout_repetition_{best_model_idx + 1}"
            
            logger.info(f"🎯 Utilisation du meilleur modèle Hold-Out (répétition {best_model_idx + 1}) avec alpha: {best_alpha}")
            
            validation_results = {
                "method": f"Hold-Out Repeated ({request.n_repetitions} repetitions)",
                "best_alpha": float(best_alpha),
                "scores": [float(score) for score in holdout_scores],
                "mean_score": float(np.mean(holdout_scores)),
                "std_score": float(np.std(holdout_scores)),
                "best_repetition": int(best_model_idx + 1),
                "best_score": float(holdout_scores[best_model_idx]),
                "repetition_details": repetition_details,
                "test_size": test_size,
                "n_repetitions": request.n_repetitions,
                "cv_validation_r2_mean": float(np.mean(holdout_scores)),
                "cv_validation_r2_std": float(np.std(holdout_scores)),
            }
        
        elif validation_method in ["cv_kfold", "cv_repeatedkfold", "cv_shufflesplit"]:
            # CONFIGURATION CV STANDARD
            cv_params = request.cv_params or {}
            shuffle = cv_params.get('shuffle', True)
            n_splits = cv_params.get('n_splits', 5)
            
            if validation_method == "cv_kfold":
                outer_cv = KFold(
                    n_splits=n_splits,
                    shuffle=shuffle,
                    random_state=None
                )
                method_name = "Nested Cross-Validation (KFold)"
            elif validation_method == "cv_repeatedkfold":
                n_repeats = cv_params.get('n_repeats', 3)
                outer_cv = RepeatedKFold(
                    n_splits=n_splits,
                    n_repeats=n_repeats,
                    random_state=None
                )
                method_name = "Nested Cross-Validation (Repeated KFold)"
            elif validation_method == "cv_shufflesplit":
                test_size = cv_params.get('test_size', 0.2)
                outer_cv = ShuffleSplit(
                    n_splits=n_splits,
                    test_size=test_size,
                    random_state=None
                )
                method_name = "Nested Cross-Validation (Shuffle Split)"
            
            inner_cv = KFold(n_splits=3, shuffle=True, random_state=None)
            
            best_alpha, nested_cv_results, fold_models, alpha_performance = robust_nested_cv_optimization(
                X_train_full_values, y_train_full_values, outer_cv, inner_cv, alpha_search_space
            )
            logger.info(f"Optimal alpha for {validation_method}: {best_alpha}")
            
            best_fold_idx = np.argmax([fold['outer_val_score'] for fold in nested_cv_results])
            final_model = fold_models[best_fold_idx]
            used_validation_model = True
            final_model_source = f"best_cv_fold_{best_fold_idx + 1}"
            
            logger.info(f"🎯 Utilisation du meilleur modèle CV (fold {best_fold_idx + 1}) avec score: {nested_cv_results[best_fold_idx]['outer_val_score']:.4f}")

            outer_scores = [fold['outer_val_score'] for fold in nested_cv_results]
            train_scores = [fold['train_r2'] for fold in nested_cv_results]

            validation_results = {
                "method": method_name,
                "best_alpha": best_alpha,
                "nested_cv_score": float(np.mean(outer_scores)),
                "alpha_selection_method": "nested_cv_most_frequent",
                "n_splits": len(nested_cv_results),
                "best_fold_used": int(best_fold_idx + 1),
                "best_fold_score": float(nested_cv_results[best_fold_idx]['outer_val_score']),
                "cv_validation_r2_mean": float(np.mean(outer_scores)),
                "cv_validation_r2_std": float(np.std(outer_scores)),
                "cv_train_r2_mean": float(np.mean(train_scores)),
                "cv_train_r2_std": float(np.std(train_scores)),
                "fold_details": [
                    {
                        "fold": fold["fold"],
                        "best_alpha": fold["best_alpha"],
                        "cv_train_r2": fold["train_r2"],
                        "cv_validation_r2": fold["outer_val_score"],
                    }
                    for fold in nested_cv_results
                ],
                "alpha_performance": [{"alpha": alpha, "score": np.mean(scores) if scores else 0} 
                                      for alpha, scores in alpha_performance.items() if scores]
            }

            if validation_method == "cv_repeatedkfold":
                validation_results["n_repeats"] = n_repeats
            elif validation_method == "cv_shufflesplit":
                validation_results["test_size"] = test_size

        elif validation_method == "bootstrap":
            # BOOTSTRAP
            n_bootstraps = request.bootstrap_params.get('n_bootstraps', 100)
            test_size = request.bootstrap_params.get('test_size', 0.2)
            sample_size = request.bootstrap_params.get('sample_size', 1.0)
            
            best_alpha, bootstrap_results, bootstrap_models, alpha_performance = bootstrap_alpha_optimization(
                X_train_full_values, y_train_full_values, 
                n_bootstraps, test_size, 
                alpha_search_space,
                sample_size=sample_size 
            )
            
            final_model = Ridge(alpha=best_alpha, fit_intercept=request.fit_intercept, random_state=None)
            final_model.fit(X_train_full_values, y_train_full_values)
            used_validation_model = False
            final_model_source = "bootstrap_optimized_alpha"
            
            logger.info(f"🎯 Utilisation de l'alpha optimal du bootstrap: {best_alpha}")
        
            bootstrap_scores = [bs['validation_score'] for bs in bootstrap_results]
            train_scores = [bs['train_r2'] for bs in bootstrap_results]
        
            validation_results = {
                "method": "True Bootstrap (with replacement)",
                "best_alpha": best_alpha,
                "bootstrap_mean_score": float(np.mean(bootstrap_scores)),
                "bootstrap_std_score": float(np.std(bootstrap_scores)),
                "alpha_selection_method": "bootstrap_most_frequent",
                "n_bootstraps": n_bootstraps,
                "test_size": test_size,
                "sample_size": sample_size,
                "cv_validation_r2_mean": float(np.mean(bootstrap_scores)),
                "cv_validation_r2_std": float(np.std(bootstrap_scores)),
                "cv_train_r2_mean": float(np.mean(train_scores)),
                "cv_train_r2_std": float(np.std(train_scores)),
                "bootstrap_details": bootstrap_results,
                "alpha_performance": [{"alpha": alpha, "score": np.mean(scores) if scores else 0} 
                                      for alpha, scores in alpha_performance.items() if scores]
            }
        
        
        elif validation_method == "cv_timeseries":
            # ✅ TIMESERIES SPLIT - CORRIGÉ
            logger.info("=" * 80)
            logger.info("⏰ TIMESERIES SPLIT SELECTED FOR RIDGE REGRESSION")
            logger.info("=" * 80)
    
            # Récupérer les paramètres TimeSeries
            time_series_params = getattr(request, 'time_series_params', {})
            n_splits = time_series_params.get('n_splits', 5)
            test_size = time_series_params.get('test_size', 0.2)
            gap = time_series_params.get('gap', 0)
            
            logger.info(f"📊 Paramètres TimeSeries reçus: n_splits={n_splits}, test_size={test_size}, gap={gap}")
            logger.info(f"📊 Nombre d'échantillons d'entraînement: {len(X_train_full)}")
            logger.info(f"🚫 Colonne date '{date_column}' exclue des features d'entraînement")

            date_series_train = train_aligned_date_series(df[train_mask], date_column)
            
            # ✅ CORRECTION: test_size peut être float ou int, on le passe directement
            # La fonction timeseries_alpha_optimization gérera la conversion
            best_alpha, timeseries_results, fold_models, alpha_performance = timeseries_alpha_optimization(
                X_train_full_values, y_train_full_values,
                date_series_train, n_splits, test_size, gap,
                alpha_search_space, request.fit_intercept,
                feature_columns
            )
            
            # Vérifier si on a des résultats valides
            if timeseries_results and fold_models:
                # Trouver le meilleur fold (meilleur score de validation)
                best_fold_idx = np.argmax([fold['validation_r2'] for fold in timeseries_results])
                final_model = fold_models[best_fold_idx]
                used_validation_model = True
                final_model_source = f"best_timeseries_fold_{best_fold_idx + 1}"
                
                logger.info(f"🎯 Utilisation du meilleur modèle TimeSeries (fold {best_fold_idx + 1})")
                logger.info(f"   Score validation: {timeseries_results[best_fold_idx]['validation_r2']:.4f}")
                
                # Calcul des statistiques
                val_scores = [fold['validation_r2'] for fold in timeseries_results]
                train_scores = [fold['train_r2'] for fold in timeseries_results]
            else:
                # Fallback: entraîner un modèle simple avec alpha=1.0
                logger.warning("⚠️  TimeSeriesSplit n'a pas produit de résultats valides, fallback sur alpha=1.0")
                final_model = Ridge(alpha=1.0, fit_intercept=request.fit_intercept, random_state=None)
                final_model.fit(X_train_full_values, y_train_full_values)
                used_validation_model = False
                final_model_source = "timeseries_fallback_alpha_1.0"
                val_scores = [0.0]
                train_scores = [final_model.score(X_train_full_values, y_train_full_values)]
                best_alpha = 1.0
            
            # Créer les résultats de validation
            validation_results = {
                "method": f"TimeSeries Split ({len(timeseries_results)} valid folds / {n_splits} total)",
                "best_alpha": float(best_alpha),
                "timeseries_mean_score": float(np.mean(val_scores)) if val_scores else 0.0,
                "timeseries_std_score": float(np.std(val_scores)) if val_scores else 0.0,
                "alpha_selection_method": "timeseries_most_frequent" if timeseries_results else "fallback",
                "n_splits": n_splits,
                "gap": gap,
                "test_size": test_size,
                "test_size_samples": int(len(X_train_full) * test_size) if isinstance(test_size, float) and test_size < 1 else int(test_size),
                "date_column": date_column,
                "best_fold_used": int(best_fold_idx + 1) if timeseries_results else None,
                "best_fold_score": float(timeseries_results[best_fold_idx]['validation_r2']) if timeseries_results else None,
                "cv_validation_r2_mean": float(np.mean(val_scores)) if val_scores else 0.0,
                "cv_validation_r2_std": float(np.std(val_scores)) if val_scores else 0.0,
                "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0.0,
                "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0.0,
                "fold_details": timeseries_results,
                "features_used": feature_columns,
                "date_column_excluded": True,
                "alpha_performance": [{"alpha": alpha, "score": float(np.mean(scores)) if scores else 0.0} 
                                      for alpha, scores in alpha_performance.items() if scores]
            }
            logger.info("=" * 80)
            logger.info("📊 RÉSUMÉ TIMESERIES SPLIT")
            logger.info(f"   Folds valides: {len(timeseries_results)}/{n_splits}")
            logger.info(f"   Alpha optimal: {best_alpha}")
            logger.info(f"   R² moyen validation: {validation_results['cv_validation_r2_mean']:.4f} ± {validation_results['cv_validation_r2_std']:.4f}")
            logger.info(f"   R² moyen train: {validation_results['cv_train_r2_mean']:.4f} ± {validation_results['cv_train_r2_std']:.4f}")
            logger.info(f"   Features utilisées: {feature_columns}")
            logger.info(f"   Colonne date exclue: OUI")
            logger.info("=" * 80)
        else:
            supported_methods = ["holdout", "cv_kfold", "cv_repeatedkfold", "cv_shufflesplit", "bootstrap", "cv_timeseries"]
            raise HTTPException(400, f"Validation method not supported: {validation_method}. Supported methods: {', '.join(supported_methods)}")

        # CALCUL DES MÉTRIQUES FINALES SUR LE VRAI TEST SET
        y_pred_test = final_model.predict(X_test_values)
        y_pred_train = final_model.predict(X_train_full_values)
        
        test_metrics = {
            "r2": float(r2_score(y_test_values, y_pred_test)),
            "mse": float(mean_squared_error(y_test_values, y_pred_test)),
            "mae": float(mean_absolute_error(y_test_values, y_pred_test))
        }
        
        train_metrics = {
            "r2": float(r2_score(y_train_full_values, y_pred_train)),
            "mse": float(mean_squared_error(y_train_full_values, y_pred_train)),
            "mae": float(mean_absolute_error(y_train_full_values, y_pred_train))
        }
        
        final_predictions = {
            "y_true": y_test_values.tolist(),
            "y_pred": y_pred_test.tolist(),
            "y_train_true": y_train_full_values.tolist(),
            "y_train_pred": y_pred_train.tolist()
        }
        
        X_for_features = X_train_full

        # Vérifications finales
        if final_model is None or X_for_features is None:
            raise HTTPException(500, "Error during model training")

        # Feature importances
        feature_importances = dict(zip(X_for_features.columns, final_model.coef_))
        
        # Erreurs de prédiction
        errors_data = {
            "absolute": (np.array(final_predictions["y_true"]) - np.array(final_predictions["y_pred"])).tolist(),
            "relative": ((np.array(final_predictions["y_true"]) - np.array(final_predictions["y_pred"])) / 
                        (np.array(final_predictions["y_true"]) + 1e-10)).tolist()
        }

        # Métriques finales structurées
        metrics = {
            # Métriques principales
            "r2": float(test_metrics["r2"]),
            "mse": float(test_metrics["mse"]),
            "mae": float(test_metrics["mae"]),
            
            # Métriques d'entraînement
            "train_r2": float(train_metrics["r2"]),
            "train_mse": float(train_metrics["mse"]),
            "train_mae": float(train_metrics["mae"]),
            
            # Structure détaillée
            "final_test": {
                "r2": float(test_metrics["r2"]),
                "mse": float(test_metrics["mse"]),
                "mae": float(test_metrics["mae"])
            },
            
            "final_train": {
                "r2": float(train_metrics["r2"]),
                "mse": float(train_metrics["mse"]),
                "mae": float(train_metrics["mae"])
            },
            
            # Feature importance
            "feature_importances": convert_numpy_types(feature_importances),
            "features_used": list(X_for_features.columns),
            "target_column": target_column,
            "validation_method": validation_method,
            
            # Alpha optimal
            "best_alpha_used": best_alpha,
            "alpha_search_space": alpha_search_space,
            "alpha_selection_method": (
                "random_search" if random_search_meta
                else validation_results.get("alpha_selection_method", "nested_cv_most_frequent")
            ),
            "random_search": random_search_meta,
            
            # Résultats de validation
            "validation_results": convert_numpy_types(validation_results),
            
            # Prédictions et erreurs
            "predictions": final_predictions,
            "errors": errors_data,
            
            # Métadonnées
            "metadata": {
                "model_type": "ridge_regression",
                "alpha_used": float(best_alpha),
                "alpha_selection_method": validation_results.get("alpha_selection_method", "nested_cv_most_frequent"),
                "fit_intercept": request.fit_intercept,
                "n_features": len(X_for_features.columns),
                "n_train_samples": len(X_train_full),
                "n_test_samples": len(X_test),
                "validation_method": validation_method,
                "used_validation_model": used_validation_model,
                "final_model_source": final_model_source,
                "data_separation": "Alpha optimization on training data, final test on unseen data",
                "leakage_prevention": "✅ Preprocessing applied separately on train/test",
                "date_column_excluded": validation_method == "cv_timeseries",
                "date_column": date_column if validation_method == "cv_timeseries" else None
            }
        }

        # Ajouter des informations spécifiques TimeSeries
        if validation_method == "cv_timeseries":
            metrics["metadata"]["time_series_params"] = {
                "n_splits": time_series_params.get('n_splits', 5),
                "test_size": time_series_params.get('test_size', 0.2),
                "gap": time_series_params.get('gap', 0)
            }
            metrics["metadata"]["features_excluding_date"] = feature_columns

        # Sérialisation
        model_bytes = io.BytesIO()
        joblib.dump(final_model, model_bytes)
        model_bytes.seek(0)
        model_base64 = base64.b64encode(model_bytes.read()).decode('utf-8')

        logger.info(f"🎉 Training completed! Method: {validation_method}, Model source: {final_model_source}")
        logger.info(f"📊 Final results - R²: {test_metrics['r2']:.4f}, MSE: {test_metrics['mse']:.4f}")
        
        return {
            "status": "success",
            "model_type": "ridge_regression",
            "model_object": model_base64,
            "dataset_used": request.numerized_dataset_name,
            "metrics": convert_numpy_types(metrics),
            "random_search": convert_numpy_types(random_search_meta) if random_search_meta else None,
            "timestamp": datetime.now().isoformat(),
            "training_info": {
                "model_trained_once": not used_validation_model,
                "used_cv_best_model": used_validation_model and validation_method.startswith('cv_'),
                "used_timeseries_model": used_validation_model and validation_method == "cv_timeseries",
                "used_bootstrap_model": used_validation_model and validation_method == "bootstrap",
                "final_model_source": final_model_source,
                "training_samples": len(X_train_full),
                "test_samples": len(X_test),
                "parameter_optimization": (
                    "Random Search (alpha) then fixed-alpha validation"
                    if random_search_meta
                    else f"Alpha optimization using {validation_method}"
                ),
                "date_column_excluded": validation_method == "cv_timeseries",
                "date_column": date_column if validation_method == "cv_timeseries" else None
            }
        }
        
    except HTTPException:
        raise
    except Exception as e:
        import traceback
        error_trace = traceback.format_exc()
        logger.error(f"Erreur complète: {error_trace}")
        raise HTTPException(
            status_code=500,
            detail={
                "error_message": str(e),
                "error_type": type(e).__name__,
                "traceback": error_trace
            }
        )


# ========== FONCTION UTILITAIRE POUR DÉTECTER LA COLONNE DATE ==========
def detect_date_column_in_df(df):
    """
    Détecte automatiquement une colonne date dans un DataFrame
    """
    date_formats = [
        '%Y-%m-%d %H:%M:%S',
        '%Y-%m-%d %H:%M',
        '%Y-%m-%d %H:%M:%S.%f',
        '%Y-%m-%dT%H:%M:%S',
        '%Y-%m-%dT%H:%M',
        '%Y-%m-%d',
        '%d-%m-%Y',
        '%Y/%m/%d',
        '%d/%m/%Y',
        '%Y.%m.%d',
        '%d.%m.%Y',
        '%Y%m%d',
        '%d-%m-%Y %H:%M',
        '%Y-%m-%dT%H:%M:%S.%fZ'
    ]
    
    for col in df.columns:
        if col in ['id', 'split_type', 'index']:
            continue
        
        # Prendre un échantillon de valeurs non nulles
        sample = df[col].dropna().head(20).astype(str)
        if len(sample) == 0:
            continue
        
        date_count = 0
        for val in sample:
            for fmt in date_formats:
                try:
                    datetime.strptime(val, fmt)
                    date_count += 1
                    break
                except:
                    continue
        
        if date_count / len(sample) > 0.8:
            logger.info(f"✅ Colonne date détectée: {col} ({date_count}/{len(sample)} valeurs valides)")
            return col
    
    return None


def resolve_request_date_column(request) -> Optional[str]:
    """Unify FE fields: date_column (preferred) or time_series_column."""
    col = getattr(request, "date_column", None) or getattr(request, "time_series_column", None)
    if isinstance(col, str):
        col = col.strip() or None
    return col


def exclude_date_columns_from_list(df, feature_columns, date_column=None, target_column=None):
    """
    Remove date-like columns from feature list.
    Policy: dates are never model features; optional clock for TimeSeries only.
    """
    feats = list(feature_columns)
    to_drop = set()
    if date_column:
        to_drop.add(date_column)
    try:
        for dc in detect_date_columns(df):
            to_drop.add(dc)
    except Exception as e:
        logger.warning(f"detect_date_columns during exclude skipped: {e}")
    if target_column:
        to_drop.discard(target_column)
    for dc in to_drop:
        if dc in feats:
            feats.remove(dc)
            logger.info(f"🚫 Date column '{dc}' excluded from model features")
    return feats


def train_aligned_date_series(df_train, date_column):
    """Date series aligned to X_train rows (same length / order)."""
    if not date_column or date_column not in df_train.columns:
        return None
    return df_train[date_column].reset_index(drop=True)

