import math
import traceback

def sanitize_for_json(obj):
    """
    Nettoie récursivement un objet pour la sérialisation JSON
    Remplace inf/-inf/NaN par des valeurs sérialisables
    """
    if obj is None:
        return None
    elif isinstance(obj, (dict,)):
        return {k: sanitize_for_json(v) for k, v in obj.items()}
    elif isinstance(obj, (list, tuple, np.ndarray)):
        return [sanitize_for_json(v) for v in obj]
    elif isinstance(obj, (np.integer, np.int_)):
        return int(obj)
    elif isinstance(obj, (np.floating, np.float64)):
        # Gère inf, -inf, NaN de manière robuste
        if np.isinf(obj):
            return 0.0 if obj > 0 else -1.0
        elif np.isnan(obj):
            return 0.0
        else:
            return float(obj)
    elif isinstance(obj, (np.bool_, bool)):
        return bool(obj)
    elif isinstance(obj, float):
        # Gère les float Python standards
        if math.isinf(obj) or math.isnan(obj):
            return 0.0
        return obj
    else:
        try:
            # Essayer de sérialiser directement
            json.dumps(obj)
            return obj
        except (TypeError, ValueError):
            # Fallback: convertir en string
            return str(obj)

def validate_logistic_params(penalty, solver, multi_class, class_weight, max_iter, l1_ratio=None, use_scaling=False):
    errors = []
    
    effective_penalty = None if penalty == 'none' else penalty
    
    # ✅ VALIDATION COMPLÈTE des combinaisons penalty/solver
    valid_combinations = {
        'liblinear': ['l1', 'l2'],
        'newton-cg': ['l2', None],
        'lbfgs': ['l2', None],
        'sag': ['l2', None],
        'saga': ['elasticnet', 'l1', 'l2', None]
    }
    
    if solver not in valid_combinations:
        errors.append(f"Solver {solver} not recognized. Choose from: {list(valid_combinations.keys())}")
    elif effective_penalty not in valid_combinations[solver]:
        errors.append(f"Penalty {penalty} not supported by solver {solver}. Valid penalties: {valid_combinations[solver]}")
    
    # ✅ VALIDATION MULTICLASS ÉTENDUE
    multiclass_restrictions = {
        'liblinear': {
            'allowed': ['ovr', 'auto'],
            'message': "Liblinear only supports 'ovr' or 'auto' for multiclass"
        },
        'newton-cg': {
            'allowed': ['multinomial', 'ovr', 'auto'],
            'message': "Newton-CG supports all multiclass strategies"
        },
        'lbfgs': {
            'allowed': ['multinomial', 'ovr', 'auto'],
            'message': "LBFGS supports all multiclass strategies"
        },
        'sag': {
            'allowed': ['multinomial', 'ovr', 'auto'],
            'message': "SAG supports all multiclass strategies"
        },
        'saga': {
            'allowed': ['multinomial', 'ovr', 'auto'],
            'message': "SAGA supports all multiclass strategies"
        }
    }
    
    if solver in multiclass_restrictions:
        if multi_class not in multiclass_restrictions[solver]['allowed']:
            errors.append(f"Solver {solver}: {multiclass_restrictions[solver]['message']}")
    
    # ✅ VALIDATION class_weight
    if class_weight not in [None, 'balanced']:
        errors.append("class_weight must be None or 'balanced'")
    
    # ✅ VALIDATION max_iter
    if max_iter < 100 or max_iter > 10000:
        errors.append("max_iter must be between 100 and 10000")
    
    # ✅ VALIDATION l1_ratio POUR ELASTICNET
    if effective_penalty == 'elasticnet':
        if l1_ratio is None:
            errors.append("l1_ratio must be specified when penalty is elasticnet")
        elif l1_ratio < 0 or l1_ratio > 1:
            errors.append("l1_ratio must be between 0 and 1")
        elif solver != 'saga':
            errors.append("ElasticNet penalty requires solver 'saga'")
    
    # ✅ NOUVELLE VALIDATION : Compatibilité solver/données
    if solver in ['sag', 'saga'] and not use_scaling:
        logger.warning(f"⚠️ Solver {solver} may require feature scaling for best performance")
    
    return errors

class TrainLogisticRequest(BaseModel):
    numerized_dataset_name: str
    original_dataset_name: str
    model_type: Literal["logistic"] = "logistic"
    penalty: str = "l2"
    solver: str = "lbfgs"
    max_iter: int = 100
    multi_class: str = "auto"
    class_weight: Optional[str] = None
    use_scaling: bool = False
    random_state: Optional[int] = None
    l1_ratio: Optional[float] = None 
    validation_method: Optional[str] = "holdout"
    cv_params: Optional[Dict[str, Any]] = None
    bootstrap_params: Optional[Dict[str, Any]] = None
    time_series_params: Optional[Dict[str, Any]] = None  
    n_repetitions: Optional[int] = Field(default=10, gt=0, le=50, description="Number of repetitions for Hold-Out")  
    date_column: Optional[str] = None  
    training_id: Optional[str] = None
    random_search: bool = False
    n_trials: Optional[int] = Field(default=20, ge=1, le=50)
    random_search_seed: Optional[int] = 42
    # When set (e.g. after Random Search), replaces the hardcoded C grid
    C_search_space: Optional[List[float]] = None

def logistic_nested_cv_optimization(X, y, outer_cv, inner_cv, C_search_space, penalty, solver, multi_class, class_weight, l1_ratio=None):
    """Nested CV - Version avec sauvegarde des modèles"""
    
    effective_penalty = None if penalty == 'none' else penalty
    C_performance_all = {C: [] for C in C_search_space}
    fold_results = []
    fold_models = []  # ✅ NOUVEAU : Sauvegarder les modèles
    
    for fold_idx, (train_idx, val_idx) in enumerate(outer_cv.split(X, y)):
        X_train_fold, X_val_fold = X[train_idx], X[val_idx]
        y_train_fold, y_val_fold = y[train_idx], y[val_idx]
        
        best_C_fold = 1.0
        best_inner_score = 0.0
        
        for C in C_search_space:
            try:
                model_params = {
                    'C': C,
                    'penalty': effective_penalty,
                    'solver': solver,
                    'multi_class': multi_class,
                    'class_weight': class_weight,
                    'max_iter': 1000
                    # ✅ SUPPRIMÉ: random_state pour aléatoire
                }
                
                if effective_penalty == 'elasticnet' and l1_ratio is not None:
                    model_params['l1_ratio'] = l1_ratio
                
                model = LogisticRegression(**model_params)
                inner_scores = cross_val_score(
                    model, X_train_fold, y_train_fold,
                    cv=inner_cv, scoring='accuracy', n_jobs=-1
                )
                mean_score = np.mean(inner_scores)
                
                if mean_score > best_inner_score:
                    best_inner_score = mean_score
                    best_C_fold = C
                    
            except Exception as e:
                logger.warning(f"Fold {fold_idx+1}, C {C}: {e}")
                continue
        
        # ✅ CORRECTION : Entraîner et sauvegarder le modèle pour ce fold
        try:
            model_params = {
                'C': best_C_fold,
                'penalty': effective_penalty,
                'solver': solver,
                'multi_class': multi_class,
                'class_weight': class_weight,
                'max_iter': 1000
            }
            
            if effective_penalty == 'elasticnet' and l1_ratio is not None:
                model_params['l1_ratio'] = l1_ratio
            
            fold_model = LogisticRegression(**model_params)
            fold_model.fit(X_train_fold, y_train_fold)
            fold_models.append(fold_model)  # ← SAUVEGARDE
            
            val_score = fold_model.score(X_val_fold, y_val_fold)
            train_score = fold_model.score(X_train_fold, y_train_fold)
            
            C_performance_all[best_C_fold].append(sanitize_for_json(val_score))
            
            fold_results.append({
                "fold": fold_idx + 1,
                "best_C": sanitize_for_json(best_C_fold),
                "inner_cv_score": sanitize_for_json(best_inner_score),
                "outer_val_score": sanitize_for_json(val_score),
                "train_accuracy": sanitize_for_json(train_score)
            })
            
        except Exception as e:
            logger.warning(f"Final training failed for fold {fold_idx+1}: {e}")
            continue
    
    # Gestion des cas où aucun fold ne réussit
    if not fold_results:
        logger.error("❌ NO fold succeeded in nested CV. Using default values.")
        best_C = 1.0
        nested_cv_score = 0.0
        C_performance = {}
    else:
        # Calcul du meilleur C (le plus fréquent)
        from collections import Counter
        c_values = [fold["best_C"] for fold in fold_results]
        best_C_counter = Counter(c_values)
        best_C = best_C_counter.most_common(1)[0][0]
        
        # Score moyen
        nested_cv_score = np.mean([fold["outer_val_score"] for fold in fold_results])
        
        # Performance par C
        C_performance = {}
        for C in C_search_space:
            scores = C_performance_all.get(C, [])
            if scores:
                C_performance[sanitize_for_json(C)] = sanitize_for_json(np.mean(scores))
    
    logger.info(f"✅ C optimal (nested CV): {best_C}, Score: {nested_cv_score:.4f}")
    
    # ✅ CORRECTION : Retourner aussi les modèles
    return (
        sanitize_for_json(best_C), 
        fold_results,
        sanitize_for_json(nested_cv_score), 
        C_performance,
        fold_models  # ← NOUVEAU
    )

def logistic_bootstrap_optimization(X, y, n_bootstraps, test_size, C_search_space, penalty, solver, multi_class, class_weight, l1_ratio=None):
    effective_penalty = None if penalty == 'none' else penalty
    C_performance_all = {C: [] for C in C_search_space}
    bootstrap_results = []
    bootstrap_models = []
    
    logger.info(f"Starting TRUE bootstrap optimization with {n_bootstraps} bootstraps")
    
    n_samples = len(X)
    
    for i in range(n_bootstraps):
        try:
            train_indices = np.random.choice(
                n_samples, 
                size=n_samples,
                replace=True
            )
            
            all_indices = np.arange(n_samples)
            val_indices = np.setdiff1d(all_indices, train_indices)
            
            if len(val_indices) < 5:
                n_needed = max(5, len(train_indices) // 10)
                extra_indices = np.random.choice(
                    train_indices, 
                    size=min(n_needed, len(train_indices)), 
                    replace=False
                )
                val_indices = np.concatenate([val_indices, extra_indices])
                train_indices = np.setdiff1d(train_indices, extra_indices)
            
            if len(train_indices) < 10 or len(val_indices) < 5:
                logger.warning(f"Bootstrap {i+1}: Pas assez de données (train: {len(train_indices)}, val: {len(val_indices)})")
                continue
            
            X_train_bs = X[train_indices]
            y_train_bs = y[train_indices]
            X_val_bs = X[val_indices]
            y_val_bs = y[val_indices]
            
            unique_train_samples = len(np.unique(train_indices))
            duplicate_rate = (len(train_indices) - unique_train_samples) / len(train_indices)
            logger.debug(f"Bootstrap {i+1}: {unique_train_samples} échantillons uniques, {duplicate_rate:.1%} de duplication")
            
            best_C_bs = 1.0
            best_score_bs = 0.0
            C_scores_bs = []
            
            for C in C_search_space:
                try:
                    model_params = {
                        'C': C,
                        'penalty': effective_penalty,
                        'solver': solver,
                        'multi_class': multi_class,
                        'class_weight': class_weight,
                        'max_iter': 1000
                    }
                    
                    if effective_penalty == 'elasticnet' and l1_ratio is not None:
                        model_params['l1_ratio'] = l1_ratio
                    
                    model = LogisticRegression(**model_params)
                    model.fit(X_train_bs, y_train_bs)
                    score = model.score(X_val_bs, y_val_bs)
                    
                    score_clean = sanitize_for_json(score)
                    
                    C_scores_bs.append({
                        "C": sanitize_for_json(C),
                        "score": score_clean
                    })
                    
                    if score_clean > best_score_bs:
                        best_score_bs = score_clean
                        best_C_bs = C
                        
                except Exception as e:
                    logger.warning(f"Bootstrap {i+1}, C {C}: {e}")
                    continue
            
            final_model_params = {
                'C': best_C_bs,
                'penalty': effective_penalty,
                'solver': solver,
                'multi_class': multi_class,
                'class_weight': class_weight,
                'max_iter': 1000
            }
            
            if effective_penalty == 'elasticnet' and l1_ratio is not None:
                final_model_params['l1_ratio'] = l1_ratio
            
            bootstrap_model = LogisticRegression(**final_model_params)
            bootstrap_model.fit(X_train_bs, y_train_bs)
            bootstrap_models.append(bootstrap_model)
            
            train_score = bootstrap_model.score(X_train_bs, y_train_bs)
            val_score = bootstrap_model.score(X_val_bs, y_val_bs)
            
            train_score_clean = sanitize_for_json(train_score)
            val_score_clean = sanitize_for_json(val_score)
            
            C_performance_all[best_C_bs].append(val_score_clean)
            
            bootstrap_results.append({
                "bootstrap": i + 1,
                "best_C": sanitize_for_json(best_C_bs),
                "validation_score": val_score_clean,
                "train_accuracy": train_score_clean,
                "train_size": len(X_train_bs),
                "validation_size": len(X_val_bs),
                "unique_samples": int(unique_train_samples),
                "duplicate_rate": float(duplicate_rate),
                "C_search_details": C_scores_bs
            })
            
        except Exception as e:
            logger.warning(f"Erreur bootstrap {i+1}: {e}")
            continue
    
    if not bootstrap_results:
        logger.error("❌ Aucun bootstrap réussi")
        best_C = 1.0
        mean_bootstrap_score = 0.0
        C_performance_formatted = []
        bootstrap_scores = []
    else:
        from collections import Counter
        c_values = [bs['best_C'] for bs in bootstrap_results]
        best_C_counter = Counter(c_values)
        best_C = best_C_counter.most_common(1)[0][0]
        
        bootstrap_scores = [bs['validation_score'] for bs in bootstrap_results]
        mean_bootstrap_score = np.mean(bootstrap_scores)
        
        C_mean_scores = {}
        for C in C_search_space:
            scores = C_performance_all.get(C, [])
            if scores:
                valid_scores = [s for s in scores if s is not None and not math.isinf(s) and not math.isnan(s)]
                if valid_scores:
                    C_mean_scores[sanitize_for_json(C)] = sanitize_for_json(np.mean(valid_scores))
        
        C_performance_formatted = [
            {"C": C, "score": score} 
            for C, score in C_mean_scores.items()
        ]
        C_performance_formatted.sort(key=lambda x: x["C"])
        
        logger.info(f"✅ C optimal (bootstrap): {best_C}, Score moyen: {mean_bootstrap_score:.4f} sur {len(bootstrap_results)} échantillons")
    
    return (
        sanitize_for_json(best_C), 
        bootstrap_results, 
        sanitize_for_json(mean_bootstrap_score), 
        C_performance_formatted,
        bootstrap_models,
        sanitize_for_json(np.mean(bootstrap_scores) if bootstrap_scores else 0.0),
        sanitize_for_json(np.std(bootstrap_scores) if bootstrap_scores else 0.0)
    )

def optimize_C_simple_with_repetitions(X, y, n_repetitions, test_size, C_search_space, penalty, solver, multi_class, class_weight, l1_ratio=None):
    """Hold-Out répété avec sauvegarde des modèles pour Logistic - AMÉLIORÉ"""
    holdout_scores = []
    holdout_models = []
    repetition_details = []
    
    # ✅ NOUVEAU : Collecter les performances par C pour toutes les répétitions
    C_performance_all = {C: [] for C in C_search_space}
    
    for i in range(n_repetitions):
        # Split ALÉATOIRE avec une seed différente pour chaque répétition
        X_temp, X_val, y_temp, y_val = train_test_split(
            X, y, test_size=test_size, random_state=i
        )
        
        best_C_rep = 1.0
        best_score_rep = 0.0
        C_scores_rep = []
        
        # ✅ NOUVEAU : Collecter les scores pour chaque C
        C_scores_dict = {}
        
        for C in C_search_space:
            try:
                effective_penalty = None if penalty == 'none' else penalty
                model_params = {
                    'C': C,
                    'penalty': effective_penalty,
                    'solver': solver,
                    'multi_class': multi_class,
                    'class_weight': class_weight,
                    'max_iter': 1000
                }
                
                if effective_penalty == 'elasticnet' and l1_ratio is not None:
                    model_params['l1_ratio'] = l1_ratio
                
                model = LogisticRegression(**model_params)
                model.fit(X_temp, y_temp)
                score = model.score(X_val, y_val)
                
                # ✅ NOUVEAU : Collecter pour C_performance
                C_performance_all[C].append(float(score))
                C_scores_dict[C] = float(score)
                
                C_scores_rep.append({
                    "C": C,
                    "score": float(score)
                })
                
                if score > best_score_rep:
                    best_score_rep = score
                    best_C_rep = C
                    
            except Exception as e:
                logger.warning(f"Répétition {i+1}, C {C}: {e}")
                continue
        
        # Créer et entraîner le modèle avec le C optimal pour cette répétition
        effective_penalty = None if penalty == 'none' else penalty
        model_params = {
            'C': best_C_rep,
            'penalty': effective_penalty,
            'solver': solver,
            'multi_class': multi_class,
            'class_weight': class_weight,
            'max_iter': 1000
        }
        
        if effective_penalty == 'elasticnet' and l1_ratio is not None:
            model_params['l1_ratio'] = l1_ratio
        
        model_rep = LogisticRegression(**model_params)
        model_rep.fit(X_temp, y_temp)
        
        # Calculer les scores finaux
        train_score = model_rep.score(X_temp, y_temp)
        val_score = model_rep.score(X_val, y_val)
        
        holdout_scores.append(val_score)
        holdout_models.append(model_rep)
        
        # ✅ NOUVEAU : Inclure les scores par C dans les détails
        repetition_details.append({
            'repetition': i + 1,
            'score': float(val_score),
            'train_score': float(train_score),
            'best_C': float(best_C_rep),
            'train_size': len(X_temp),
            'validation_size': len(X_val),
            'test_size_percent': test_size * 100,
            'C_search_details': C_scores_rep,  # ✅ Détails des scores par C
            'C_scores_dict': C_scores_dict     # ✅ Pour calculer la performance moyenne par C
        })
        
        logger.info(f"Répétition {i+1}: C={best_C_rep:.4f}, Val Acc={val_score:.4f}, Train Acc={train_score:.4f}")
    
    if not holdout_scores:
        raise ValueError("Aucune répétition Hold-Out n'a produit de résultats valides")
    
    # Trouver le meilleur modèle
    best_model_idx = np.argmax(holdout_scores)
    
    # ✅ NOUVEAU : Calculer les performances moyennes par C
    C_performance_formatted = []
    for C in C_search_space:
        scores = C_performance_all.get(C, [])
        if scores:
            valid_scores = [s for s in scores if s is not None and not math.isinf(s) and not math.isnan(s)]
            if valid_scores:
                C_performance_formatted.append({
                    "C": float(C),
                    "score": float(np.mean(valid_scores))
                })
    
    # Trier par C
    C_performance_formatted.sort(key=lambda x: x["C"])
    
    return holdout_scores, holdout_models, repetition_details, best_model_idx, C_performance_formatted

def logistic_timeseries_optimization(
    X, y, date_series, n_splits, test_size, gap,
    C_search_space, penalty, solver, multi_class, 
    class_weight, l1_ratio=None, feature_columns=None
):
    """
    Version CORRIGÉE de l'optimisation TimeSeriesSplit
    - X ne contient PAS la colonne date
    - date_series est utilisé UNIQUEMENT pour l'ordre chronologique
    """
    logger.info("=" * 80)
    logger.info("🕒 TIMESERIES SPLIT OPTIMIZATION FOR LOGISTIC REGRESSION (CORRECTED)")
    logger.info("=" * 80)
    
    logger.info(f"📊 Features utilisées: {feature_columns}")
    logger.info(f"⚙️ Paramètres: n_splits={n_splits}, test_size={test_size}, gap={gap}")
    
    n_samples = len(X)
    logger.info(f"📊 Nombre total d'échantillons: {n_samples}")
    
    # ✅ CORRECTION: S'assurer que date_series a la même longueur que X
    if len(date_series) != n_samples:
        logger.warning(f"⚠️ Longueur de date_series ({len(date_series)}) != n_samples ({n_samples})")
        # Prendre les n_samples premiers éléments
        date_series = date_series.iloc[:n_samples] if hasattr(date_series, 'iloc') else date_series[:n_samples]
        logger.info(f"✅ Ajusté: date_series maintenant {len(date_series)} éléments")
    
    # Convertir X en DataFrame si nécessaire
    if not isinstance(X, pd.DataFrame):
        X_df = pd.DataFrame(X, columns=feature_columns) if feature_columns else pd.DataFrame(X)
    else:
        X_df = X.copy()
    
    # ✅ CRITIQUE: Trier par date pour garantir l'ordre chronologique
    if date_series is not None:
        # Convertir en datetime si possible
        try:
            date_series = pd.to_datetime(date_series)
            logger.info("✅ Dates converties en datetime avec succès")
        except:
            logger.warning("⚠️ Conversion datetime échouée, utilisation de l'ordre original")
        
        # ✅ CORRECTION: Créer un DataFrame temporaire avec les dates pour le tri
        temp_df = X_df.copy()
        temp_df['_temp_date'] = date_series.values
        
        # Trier par date
        temp_df_sorted = temp_df.sort_values('_temp_date')
        
        # Extraire les valeurs triées sans la colonne temporaire
        X_sorted = temp_df_sorted.drop('_temp_date', axis=1).values
        y_sorted = y[temp_df_sorted.index]
        
        logger.info(f"✅ Données triées chronologiquement")
    else:
        X_sorted = X_df.values
        y_sorted = y
        logger.warning("⚠️ Pas de colonne date, utilisation de l'ordre original")
    
    # Calculer test_size en nombre d'échantillons
    if isinstance(test_size, float) and test_size < 1:
        test_size_samples = int(n_samples * test_size)
    else:
        test_size_samples = int(test_size)
    
    test_size_samples = max(1, min(test_size_samples, n_samples // (n_splits + 1)))
    logger.info(f"📊 test_size final: {test_size_samples} échantillons")
    
    # Créer TimeSeriesSplit
    tscv = TimeSeriesSplit(n_splits=n_splits, test_size=test_size_samples, gap=gap)
    
    fold_results = []
    local_Cs = []
    fold_models = []
    C_performance_all = {C: [] for C in C_search_space}
    effective_penalty = None if penalty == 'none' else penalty
    
    fold_count = 0
    for fold_idx, (train_idx, val_idx) in enumerate(tscv.split(X_sorted)):
        fold_count += 1
        logger.info(f"🔍 Fold {fold_count}/{tscv.get_n_splits()}")
        
        X_train_fold = X_sorted[train_idx]
        X_val_fold = X_sorted[val_idx]
        y_train_fold = y_sorted[train_idx]
        y_val_fold = y_sorted[val_idx]
        
        # ✅ Vérification de NaN
        if np.isnan(X_train_fold).any():
            logger.warning(f"   ⚠️ NaN dans X_train_fold, remplacement par 0")
            X_train_fold = np.nan_to_num(X_train_fold, nan=0.0)
        if np.isnan(X_val_fold).any():
            X_val_fold = np.nan_to_num(X_val_fold, nan=0.0)
        
        logger.info(f"   X_train shape: {X_train_fold.shape}, y_train shape: {y_train_fold.shape}")
        logger.info(f"   X_val shape: {X_val_fold.shape}, y_val shape: {y_val_fold.shape}")
        
        # Vérifier classes dans y_train_fold
        unique_classes = np.unique(y_train_fold)
        logger.info(f"   Classes dans train: {unique_classes}")
        
        if len(unique_classes) < 2:
            logger.warning(f"   ⚠️ Moins de 2 classes dans train, skip ce fold")
            continue
        
        # Optimisation de C
        best_C_fold = 1.0
        best_score_fold = 0.0
        inner_C_scores = []
        
        for C in C_search_space:
            try:
                model_params = {
                    'C': C,
                    'penalty': effective_penalty,
                    'solver': solver,
                    'multi_class': multi_class,
                    'class_weight': class_weight,
                    'max_iter': 1000
                }
                if effective_penalty == 'elasticnet' and l1_ratio is not None:
                    model_params['l1_ratio'] = l1_ratio
                
                model = LogisticRegression(**model_params)
                model.fit(X_train_fold, y_train_fold)
                
                score = model.score(X_val_fold, y_val_fold)
                
                inner_C_scores.append({"C": float(C), "score": float(score)})
                
                if score > best_score_fold:
                    best_score_fold = score
                    best_C_fold = C
                    
            except Exception as e:
                logger.warning(f"   C {C} failed: {e}")
                continue
        
        if best_score_fold == 0.0:
            logger.warning(f"   ⚠️ Aucun C valide, skip ce fold")
            continue
        
        logger.info(f"   ✅ Meilleur C: {best_C_fold} (score: {best_score_fold:.4f})")
        local_Cs.append(best_C_fold)
        
        # Entraîner modèle final pour ce fold
        model_params = {
            'C': best_C_fold,
            'penalty': effective_penalty,
            'solver': solver,
            'multi_class': multi_class,
            'class_weight': class_weight,
            'max_iter': 1000
        }
        if effective_penalty == 'elasticnet' and l1_ratio is not None:
            model_params['l1_ratio'] = l1_ratio
        
        fold_model = LogisticRegression(**model_params)
        fold_model.fit(X_train_fold, y_train_fold)
        fold_models.append(fold_model)
        
        val_score = fold_model.score(X_val_fold, y_val_fold)
        train_score = fold_model.score(X_train_fold, y_train_fold)
        
        logger.info(f"   Train Acc: {train_score:.4f}, Val Acc: {val_score:.4f}")
        
        # Stocker performances pour ce C
        C_performance_all[best_C_fold].append(float(val_score))
        
        fold_results.append({
            "fold": fold_count,
            "best_C": float(best_C_fold),
            "train_accuracy": float(train_score),
            "validation_accuracy": float(val_score),
            "train_size": len(X_train_fold),
            "validation_size": len(X_val_fold),
            "C_search_details": inner_C_scores
        })
    
    if not fold_results:
        logger.error("❌ Aucun fold valide pour TimeSeriesSplit")
        return 1.0, [], [], {}
    
    # Trouver C le plus fréquent
    from collections import Counter
    C_counts = Counter(local_Cs)
    best_C_global = C_counts.most_common(1)[0][0]
    
    val_scores = [fold['validation_accuracy'] for fold in fold_results]
    logger.info(f"🏆 C optimal: {best_C_global}, Fréquence: {C_counts[best_C_global]}/{len(local_Cs)}")
    logger.info(f"📊 Validation Acc moyenne: {np.mean(val_scores):.4f} ± {np.std(val_scores):.4f}")
    
    return best_C_global, fold_results, fold_models, C_performance_all

def prepare_data_for_logistic(df, target_column, date_column=None, validation_method=None):
    
    logger.info("🔧 PREPARATION DES DONNEES POUR LOGISTIC REGRESSION")
    
    # Créer une copie pour éviter de modifier l'original
    df_processed = df.copy()
    
    # Identifier les colonnes à exclure de l'entraînement
    exclude_columns = [target_column, 'split_type']
    
    if date_column:
        exclude_columns.append(date_column)
        if validation_method == "cv_timeseries":
            logger.info(f"📅 Colonne date '{date_column}' utilisée UNIQUEMENT pour split temporel -> EXCLUE des features")
        else:
            logger.info(f"🚫 Colonne date '{date_column}' -> EXCLUE des features (non TimeSeries)")
    
    # Colonnes features (tout sauf les exclues) + auto-exclude other date-like cols
    feature_columns = [col for col in df_processed.columns if col not in exclude_columns]
    feature_columns = exclude_date_columns_from_list(
        df_processed, feature_columns, date_column=date_column, target_column=target_column
    )
    logger.info(f"📊 Features utilisées pour l'entraînement: {feature_columns}")
    logger.info(f"🚫 Colonnes exclues: {exclude_columns}")
    
    # Séparer les données selon split_type
    train_mask = df_processed['split_type'] == 'train'
    test_mask = df_processed['split_type'] == 'test'
    
    df_train = df_processed[train_mask].copy()  # ✅ Utiliser .copy() pour éviter les warnings
    df_test = df_processed[test_mask].copy()    # ✅ Utiliser .copy() pour éviter les warnings
    
    logger.info(f"📊 Train: {len(df_train)} samples, Test: {len(df_test)} samples")
    
    # Extraire X et y pour train/test
    X_train_raw = df_train[feature_columns].copy()  # ✅ .copy() explicite
    y_train_raw = df_train[target_column].copy()    # ✅ .copy() explicite
    X_test_raw = df_test[feature_columns].copy()    # ✅ .copy() explicite
    y_test_raw = df_test[target_column].copy()      # ✅ .copy() explicite
    
    # ✅ Conversion numérique ROBUSTE avec gestion des erreurs
    for df_part, name in [(X_train_raw, "X_train"), (X_test_raw, "X_test")]:
        for col in df_part.columns:
            try:
                # Convertir en numérique, les erreurs deviennent NaN
                df_part.loc[:, col] = pd.to_numeric(df_part[col], errors='coerce')  # ✅ Utiliser .loc
                
                # Log des problèmes potentiels
                nan_count = df_part[col].isna().sum()
                if nan_count > 0:
                    logger.warning(f"⚠️ {name}: {nan_count} NaN dans {col} après conversion")
            except Exception as e:
                logger.error(f"❌ Erreur conversion {col}: {e}")
                df_part.loc[:, col] = 0.0  # ✅ Utiliser .loc
    
    # ✅ Remplir les NaN avec la médiane (calculée SUR LE TRAIN UNIQUEMENT)
    train_medians = X_train_raw.median(numeric_only=True)
    
    # Remplacer les NaN dans les deux datasets avec les stats du train
    X_train = X_train_raw.fillna(train_medians)
    X_test = X_test_raw.fillna(train_medians)
    
    # ✅ Vérification finale des NaN
    if X_train.isna().any().any():
        nan_cols = X_train.columns[X_train.isna().any()].tolist()
        logger.warning(f"⚠️ NaN persistants dans X_train colonnes: {nan_cols} - remplissage avec 0")
        X_train = X_train.fillna(0)
    
    if X_test.isna().any().any():
        X_test = X_test.fillna(0)
    
    # ✅ Traitement de la target
    y_train = pd.to_numeric(y_train_raw, errors='coerce').fillna(0).values
    y_test = pd.to_numeric(y_test_raw, errors='coerce').fillna(0).values
    
    # ✅ Récupérer la colonne date pour TimeSeriesSplit si nécessaire
    date_series = None
    if date_column and validation_method == "cv_timeseries":
        # Align date series to TRAIN rows only (same length/order as X_train)
        date_series = train_aligned_date_series(df_train, date_column)
        logger.info(f"📅 Colonne date récupérée pour TimeSeriesSplit: {date_column}")
    
    logger.info(f"✅ Préparation terminée: X_train shape {X_train.shape}, X_test shape {X_test.shape}")
    
    return X_train, X_test, y_train, y_test, feature_columns, date_series
# ========== NOUVELLE FONCTION AVEC VÉRIFICATION D'ARRÊT ==========
async def train_logistic_with_stop_check(
    request: TrainLogisticRequest,
    background_tasks: BackgroundTasks = None,
    current_user_id: str = None,
    training_id: str = None
):
    """Version de train_logistic_regression avec vérification d'arrêt à chaque étape"""
    
    # ✅ Fonction de vérification d'arrêt
    def check_stop():
        if training_id and training_stop_flags.get(training_id, False):
            logger.info(f"🛑 Logistic training {training_id} stopped by user (check_stop triggered)")
            raise HTTPException(400, "Training stopped by user")
    
    try:
        logger.info("=== LOGISTIC REGRESSION TRAINING STARTED ===")
        if training_id:
            logger.info(f"🎫 Training ID: {training_id}")
        
        # ==================== VÉRIFICATION D'ARRÊT ====================
        check_stop()

        # ==================== VALIDATION DES PARAMÈTRES ====================
        validation_errors = validate_logistic_params(
            request.penalty,
            request.solver, 
            request.multi_class,
            request.class_weight,
            request.max_iter,
            request.l1_ratio,
            request.use_scaling
        )
        
        if validation_errors:
            raise HTTPException(400, detail={
                "message": "Invalid model parameters",
                "errors": validation_errors
            })
        
        check_stop()

        # ==================== VALIDATION INITIALE ====================
        if not request.numerized_dataset_name or not request.original_dataset_name:
            raise HTTPException(400, "Dataset names are required")
        
        check_stop()

        # ==================== CHARGEMENT DES DONNEES ====================
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Vérification des permissions et récupération de la target
                cur.execute("""
                    SELECT target_column FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (request.original_dataset_name.lower(), current_user_id))
                
                target_info = cur.fetchone()
                if not target_info or not target_info[0]:
                    raise HTTPException(400, "Target column not defined")
                target_column = target_info[0]
                check_stop()

                # Récupération des colonnes disponibles
                cur.execute("""
                    SELECT column_name FROM information_schema.columns
                    WHERE table_name = %s
                """, (request.numerized_dataset_name.lower(),))
                
                all_columns = [row[0] for row in cur.fetchall()]
                if not all_columns:
                    raise HTTPException(404, "No columns found")
                check_stop()

                if target_column not in all_columns:
                    raise HTTPException(400, f"Target column '{target_column}' not found")

                # Construction de la liste des colonnes à sélectionner
                select_columns = [
                    sql.Identifier(col) 
                    for col in all_columns 
                    if col not in ['id', 'split_type']
                ]

                # Construction de la requête SQL
                query = sql.SQL("""
                    SELECT {columns}, split_type FROM {table}
                    WHERE split_type IS NOT NULL
                """).format(
                    columns=sql.SQL(',').join(select_columns),
                    table=sql.Identifier(request.numerized_dataset_name.lower())
                )

                cur.execute(query)
                rows = cur.fetchall()
                check_stop()

        # ==================== PREPARATION DES DONNEES ====================
        df_columns = [col for col in all_columns if col not in ['id', 'split_type']] + ['split_type']
        df = pd.DataFrame(rows, columns=df_columns)
        check_stop()

        # Nettoyage de la colonne split_type
        df['split_type'] = df['split_type'].astype(str).str.lower().str.strip()
        check_stop()
        
        # Validation des valeurs de split_type
        valid_splits = {'train', 'test'}
        invalid_splits = set(df['split_type'].unique()) - valid_splits
        if invalid_splits:
            raise HTTPException(
                400, 
                f"Invalid values in split_type: {invalid_splits}. Expected: 'train' or 'test'"
            )

        check_stop()

        # ✅ CRITIQUE: Utiliser la nouvelle fonction de préparation des données
        # qui exclut correctement la colonne date des features
        date_column = resolve_request_date_column(request)
        validation_method = request.validation_method or "holdout"
        
        X_train, X_test, y_train, y_test, feature_columns, date_series = prepare_data_for_logistic(
            df, 
            target_column, 
            date_column=date_column,
            validation_method=validation_method
        )

        check_stop()

        # ==================== TARGET PROCESSING ====================
        # Récupération des classes uniques
        class_names = sorted(np.unique(np.concatenate([y_train, y_test])))
        num_to_class = {i: str(cls) for i, cls in enumerate(class_names)}

        # Log des informations
        logger.info(f"X_train shape: {X_train.shape}, y_train unique: {np.unique(y_train)}")
        logger.info(f"Classes détectées: {class_names}")
        logger.info(f"Nombre de classes: {len(class_names)}")
        check_stop()
        
        # ==================== FEATURE SCALING ====================
        if request.use_scaling:
            scaler = StandardScaler()
            X_train_scaled = scaler.fit_transform(X_train)
            X_test_scaled = scaler.transform(X_test)
        else:
            scaler = None
            X_train_scaled = X_train.values if isinstance(X_train, pd.DataFrame) else X_train
            X_test_scaled = X_test.values if isinstance(X_test, pd.DataFrame) else X_test

        # ✅ Vérification finale des NaN
        if np.isnan(X_train_scaled).any():
            logger.warning("⚠️ NaN dans X_train_scaled - remplacement par 0")
            X_train_scaled = np.nan_to_num(X_train_scaled, nan=0.0)
        if np.isnan(X_test_scaled).any():
            X_test_scaled = np.nan_to_num(X_test_scaled, nan=0.0)

        check_stop()

        # ==================== VALIDATION METHOD SELECTION ====================
        best_C = 1.0
        validation_results = None
        final_model = None
        used_validation_model = False
        final_model_source = "standard_holdout"
        
        # Espace de recherche pour C
        # Random Search ON → cheap C search, then single-value grid (disables internal multi-C search)
        random_search_meta = None
        if getattr(request, "random_search", False):
            from backend.random_search_hp import run_hyperparam_random_search
            rs_best, random_search_meta = run_hyperparam_random_search(
                "logistic",
                X_train_scaled,
                y_train,
                n_trials=getattr(request, "n_trials", 20),
                is_classification=True,
                check_stop=check_stop,
                active_trainings=active_trainings,
                training_id=training_id,
                fixed_params={
                    "penalty": request.penalty,
                    "solver": request.solver,
                    "max_iter": request.max_iter,
                    "multi_class": request.multi_class,
                    "class_weight": request.class_weight,
                    "l1_ratio": request.l1_ratio,
                },
                random_state=int(getattr(request, "random_search_seed", 42) or 42),
            )
            C_search_space = [float(rs_best["C"])]
            if request.penalty == "elasticnet" and "l1_ratio" in rs_best:
                request.l1_ratio = float(rs_best["l1_ratio"])
            logger.info(f"🎲 Random Search best C={C_search_space[0]} (internal C grid disabled)")
        elif getattr(request, "C_search_space", None):
            C_search_space = list(request.C_search_space)
        else:
            C_search_space = [0.001, 0.01, 0.1, 1, 10, 100, 1000]

        if validation_method == "holdout":
            n_repetitions = getattr(request, 'n_repetitions', 10)
            test_size = 0.2
            
            # ✅ VÉRIFICATION D'ARRÊT AVANT VALIDATION
            check_stop()
            
            # ✅ RÉIMPLÉMENTATION AVEC VÉRIFICATION D'ARRÊT DANS LA BOUCLE
            holdout_scores = []
            holdout_models = []
            repetition_details = []
            C_performance_all = {C: [] for C in C_search_space}
            
            for i in range(n_repetitions):
                check_stop()  # ✅ Vérifier l'arrêt à CHAQUE répétition
                
                X_temp, X_val, y_temp, y_val = train_test_split(
                    X_train_scaled, y_train, test_size=test_size, random_state=i
                )
                
                best_C_rep = 1.0
                best_score_rep = 0.0
                C_scores_rep = []
                
                for C in C_search_space:
                    try:
                        effective_penalty = None if request.penalty == 'none' else request.penalty
                        model_params = {
                            'C': C,
                            'penalty': effective_penalty,
                            'solver': request.solver,
                            'multi_class': request.multi_class,
                            'class_weight': request.class_weight,
                            'max_iter': 1000
                        }
                        
                        if effective_penalty == 'elasticnet' and request.l1_ratio is not None:
                            model_params['l1_ratio'] = request.l1_ratio
                        
                        model = LogisticRegression(**model_params)
                        model.fit(X_temp, y_temp)
                        score = model.score(X_val, y_val)
                        
                        C_performance_all[C].append(float(score))
                        C_scores_rep.append({"C": C, "score": float(score)})
                        
                        if score > best_score_rep:
                            best_score_rep = score
                            best_C_rep = C
                            
                    except Exception as e:
                        logger.warning(f"Répétition {i+1}, C {C}: {e}")
                        continue
                
                effective_penalty = None if request.penalty == 'none' else request.penalty
                model_params = {
                    'C': best_C_rep,
                    'penalty': effective_penalty,
                    'solver': request.solver,
                    'multi_class': request.multi_class,
                    'class_weight': request.class_weight,
                    'max_iter': 1000
                }
                
                if effective_penalty == 'elasticnet' and request.l1_ratio is not None:
                    model_params['l1_ratio'] = request.l1_ratio
                
                model_rep = LogisticRegression(**model_params)
                model_rep.fit(X_temp, y_temp)
                
                train_score = model_rep.score(X_temp, y_temp)
                val_score = model_rep.score(X_val, y_val)
                
                holdout_scores.append(val_score)
                holdout_models.append(model_rep)
                
                repetition_details.append({
                    'repetition': i + 1,
                    'score': float(val_score),
                    'train_score': float(train_score),
                    'best_C': float(best_C_rep),
                    'train_size': len(X_temp),
                    'validation_size': len(X_val),
                    'C_search_details': C_scores_rep
                })
                
                logger.info(f"Répétition {i+1}: C={best_C_rep:.4f}, Val Acc={val_score:.4f}")
            
            if not holdout_scores:
                raise ValueError("Aucune répétition Hold-Out n'a produit de résultats valides")
            
            best_model_idx = np.argmax(holdout_scores)
            final_model = holdout_models[best_model_idx]
            best_C = repetition_details[best_model_idx]['best_C']
            used_validation_model = True
            final_model_source = f"best_holdout_repetition_{best_model_idx + 1}"
            
            # Calcul des performances par C
            C_performance_formatted = []
            for C in C_search_space:
                scores = C_performance_all.get(C, [])
                if scores:
                    valid_scores = [s for s in scores if s is not None]
                    if valid_scores:
                        C_performance_formatted.append({
                            "C": float(C),
                            "score": float(np.mean(valid_scores))
                        })
            C_performance_formatted.sort(key=lambda x: x["C"])
            
            validation_results = {
                "method": f"Hold-Out Repeated ({n_repetitions} repetitions)",
                "best_C": float(best_C),
                "scores": [float(score) for score in holdout_scores],
                "mean_score": float(np.mean(holdout_scores)),
                "std_score": float(np.std(holdout_scores)),
                "best_repetition": int(best_model_idx + 1),
                "best_score": float(holdout_scores[best_model_idx]),
                "repetition_details": repetition_details,
                "test_size": test_size,
                "n_repetitions": n_repetitions,
                "cv_validation_accuracy_mean": float(np.mean(holdout_scores)),
                "cv_validation_accuracy_std": float(np.std(holdout_scores)),
                "cv_train_accuracy_mean": float(np.mean([rd['train_score'] for rd in repetition_details])),
                "cv_train_accuracy_std": float(np.std([rd['train_score'] for rd in repetition_details])),
                "C_performance": C_performance_formatted,
                "holdout_details": repetition_details
            }
            
        elif validation_method == "bootstrap":
            # ✅ VÉRIFICATION D'ARRÊT AVANT BOOTSTRAP
            check_stop()
            
            bootstrap_params = request.bootstrap_params or {}
            n_bootstraps = bootstrap_params.get('n_bootstraps', 100)
            test_size = bootstrap_params.get('test_size', 0.2)
            sample_size = bootstrap_params.get('sample_size', 1.0)
            
            logger.info(f"🔄 TRUE Bootstrap: {n_bootstraps} échantillons (avec remise)")
            
            # ✅ RÉIMPLÉMENTATION AVEC VÉRIFICATION D'ARRÊT
            bootstrap_results = []
            bootstrap_models = []
            C_performance_all = {C: [] for C in C_search_space}
            n_samples = len(X_train_scaled)
            
            for i in range(n_bootstraps):
                check_stop()  # ✅ Vérifier l'arrêt à CHAQUE bootstrap
                
                try:
                    train_indices = np.random.choice(n_samples, size=n_samples, replace=True)
                    all_indices = np.arange(n_samples)
                    val_indices = np.setdiff1d(all_indices, train_indices)
                    
                    if len(val_indices) < 5:
                        n_needed = max(5, len(train_indices) // 10)
                        extra_indices = np.random.choice(
                            train_indices, 
                            size=min(n_needed, len(train_indices)), 
                            replace=False
                        )
                        val_indices = np.concatenate([val_indices, extra_indices])
                        train_indices = np.setdiff1d(train_indices, extra_indices)
                    
                    if len(train_indices) < 10 or len(val_indices) < 5:
                        continue
                    
                    X_train_bs = X_train_scaled[train_indices]
                    y_train_bs = y_train[train_indices]
                    X_val_bs = X_train_scaled[val_indices]
                    y_val_bs = y_train[val_indices]
                    
                    unique_train_samples = len(np.unique(train_indices))
                    
                    best_C_bs = 1.0
                    best_score_bs = 0.0
                    
                    for C in C_search_space:
                        try:
                            effective_penalty = None if request.penalty == 'none' else request.penalty
                            model_params = {
                                'C': C,
                                'penalty': effective_penalty,
                                'solver': request.solver,
                                'multi_class': request.multi_class,
                                'class_weight': request.class_weight,
                                'max_iter': 1000
                            }
                            
                            if effective_penalty == 'elasticnet' and request.l1_ratio is not None:
                                model_params['l1_ratio'] = request.l1_ratio
                            
                            model = LogisticRegression(**model_params)
                            model.fit(X_train_bs, y_train_bs)
                            score = model.score(X_val_bs, y_val_bs)
                            
                            if score > best_score_bs:
                                best_score_bs = score
                                best_C_bs = C
                                
                        except Exception as e:
                            continue
                    
                    final_model_params = {
                        'C': best_C_bs,
                        'penalty': effective_penalty,
                        'solver': request.solver,
                        'multi_class': request.multi_class,
                        'class_weight': request.class_weight,
                        'max_iter': 1000
                    }
                    
                    if effective_penalty == 'elasticnet' and request.l1_ratio is not None:
                        final_model_params['l1_ratio'] = request.l1_ratio
                    
                    bootstrap_model = LogisticRegression(**final_model_params)
                    bootstrap_model.fit(X_train_bs, y_train_bs)
                    bootstrap_models.append(bootstrap_model)
                    
                    val_score = bootstrap_model.score(X_val_bs, y_val_bs)
                    C_performance_all[best_C_bs].append(float(val_score))
                    
                    bootstrap_results.append({
                        "bootstrap": i + 1,
                        "best_C": float(best_C_bs),
                        "validation_score": float(val_score),
                        "train_size": len(X_train_bs),
                        "validation_size": len(X_val_bs),
                        "unique_samples": int(unique_train_samples)
                    })
                    
                except Exception as e:
                    logger.warning(f"Erreur bootstrap {i+1}: {e}")
                    continue
            
            if not bootstrap_results:
                raise HTTPException(500, "Aucun bootstrap réussi")
            
            from collections import Counter
            c_values = [bs['best_C'] for bs in bootstrap_results]
            best_C_counter = Counter(c_values)
            best_C = best_C_counter.most_common(1)[0][0]
            
            bootstrap_scores = [bs['validation_score'] for bs in bootstrap_results]
            mean_bootstrap_score = np.mean(bootstrap_scores)
            
            # Utiliser le modèle médian
            median_idx = np.argsort(bootstrap_scores)[len(bootstrap_scores) // 2]
            final_model = bootstrap_models[median_idx]
            used_validation_model = True
            final_model_source = f"median_bootstrap_{median_idx + 1}"
            
            # Format C_performance
            C_performance_formatted = []
            for C in C_search_space:
                scores = C_performance_all.get(C, [])
                if scores:
                    valid_scores = [s for s in scores if s is not None]
                    if valid_scores:
                        C_performance_formatted.append({
                            "C": float(C),
                            "score": float(np.mean(valid_scores))
                        })
            C_performance_formatted.sort(key=lambda x: x["C"])
            
            validation_results = {
                "method": "True Bootstrap (with replacement)",
                "best_C": float(best_C),
                "mean_score": float(mean_bootstrap_score),
                "std_score": float(np.std(bootstrap_scores)),
                "best_score": float(np.max(bootstrap_scores)),
                "bootstrap_mean_score": float(mean_bootstrap_score),
                "bootstrap_std_score": float(np.std(bootstrap_scores)),
                "n_bootstraps": n_bootstraps,
                "test_size": test_size,
                "median_bootstrap_index": int(median_idx + 1),
                "median_bootstrap_score": float(bootstrap_scores[median_idx]),
                "cv_validation_accuracy_mean": float(np.mean(bootstrap_scores)),
                "cv_validation_accuracy_std": float(np.std(bootstrap_scores)),
                "bootstrap_details": bootstrap_results,
                "C_performance": C_performance_formatted
            }
            
            logger.info(f"✅ C optimal (bootstrap): {best_C}, Score moyen: {mean_bootstrap_score:.4f}")
            
        elif validation_method in ["cv_kfold", "cv_repeatedkfold", "cv_shufflesplit"]:
            # ✅ VÉRIFICATION D'ARRÊT AVANT CV
            check_stop()
            
            cv_params = request.cv_params or {}
            shuffle = cv_params.get('shuffle', True)
            n_splits = cv_params.get('n_splits', 5)
            
            if validation_method == "cv_kfold":
                outer_cv = KFold(n_splits=n_splits, shuffle=shuffle, random_state=None)
                method_name = "Nested Cross-Validation (KFold)"
            elif validation_method == "cv_repeatedkfold":
                n_repeats = cv_params.get('n_repeats', 3)
                outer_cv = RepeatedKFold(n_splits=n_splits, n_repeats=n_repeats, random_state=None)
                method_name = "Nested Cross-Validation (Repeated KFold)"
            elif validation_method == "cv_shufflesplit":
                test_size = cv_params.get('test_size', 0.2)
                outer_cv = ShuffleSplit(n_splits=n_splits, test_size=test_size, random_state=None)
                method_name = "Nested Cross-Validation (Shuffle Split)"
            
            inner_cv = KFold(n_splits=3, shuffle=True, random_state=None)
            
            # ✅ RÉIMPLÉMENTATION AVEC VÉRIFICATION D'ARRÊT
            effective_penalty = None if request.penalty == 'none' else request.penalty
            C_performance_all = {C: [] for C in C_search_space}
            fold_results = []
            fold_models = []
            
            for fold_idx, (train_idx, val_idx) in enumerate(outer_cv.split(X_train_scaled, y_train)):
                check_stop()  # ✅ Vérifier l'arrêt à CHAQUE fold
                
                X_train_fold, X_val_fold = X_train_scaled[train_idx], X_train_scaled[val_idx]
                y_train_fold, y_val_fold = y_train[train_idx], y_train[val_idx]
                
                best_C_fold = 1.0
                best_inner_score = 0.0
                
                for C in C_search_space:
                    try:
                        model_params = {
                            'C': C,
                            'penalty': effective_penalty,
                            'solver': request.solver,
                            'multi_class': request.multi_class,
                            'class_weight': request.class_weight,
                            'max_iter': 1000
                        }
                        
                        if effective_penalty == 'elasticnet' and request.l1_ratio is not None:
                            model_params['l1_ratio'] = request.l1_ratio
                        
                        model = LogisticRegression(**model_params)
                        inner_scores = cross_val_score(
                            model, X_train_fold, y_train_fold,
                            cv=inner_cv, scoring='accuracy', n_jobs=-1
                        )
                        mean_score = np.mean(inner_scores)
                        
                        if mean_score > best_inner_score:
                            best_inner_score = mean_score
                            best_C_fold = C
                            
                    except Exception as e:
                        continue
                
                try:
                    model_params = {
                        'C': best_C_fold,
                        'penalty': effective_penalty,
                        'solver': request.solver,
                        'multi_class': request.multi_class,
                        'class_weight': request.class_weight,
                        'max_iter': 1000
                    }
                    
                    if effective_penalty == 'elasticnet' and request.l1_ratio is not None:
                        model_params['l1_ratio'] = request.l1_ratio
                    
                    fold_model = LogisticRegression(**model_params)
                    fold_model.fit(X_train_fold, y_train_fold)
                    fold_models.append(fold_model)
                    
                    val_score = fold_model.score(X_val_fold, y_val_fold)
                    train_score = fold_model.score(X_train_fold, y_train_fold)
                    
                    C_performance_all[best_C_fold].append(float(val_score))
                    
                    fold_results.append({
                        "fold": fold_idx + 1,
                        "best_C": float(best_C_fold),
                        "inner_cv_score": float(best_inner_score),
                        "outer_val_score": float(val_score),
                        "train_accuracy": float(train_score)
                    })
                    
                except Exception as e:
                    continue
            
            if not fold_results:
                raise HTTPException(500, "Aucun fold de CV n'a réussi")
            
            from collections import Counter
            c_values = [fold["best_C"] for fold in fold_results]
            best_C_counter = Counter(c_values)
            best_C = best_C_counter.most_common(1)[0][0]
            
            outer_scores = [fold['outer_val_score'] for fold in fold_results]
            nested_cv_score = np.mean(outer_scores)
            
            best_fold_idx = np.argmax(outer_scores)
            final_model = fold_models[best_fold_idx]
            used_validation_model = True
            final_model_source = f"best_cv_fold_{best_fold_idx + 1}"
            
            # Format C_performance
            C_performance_formatted = {}
            for C in C_search_space:
                scores = C_performance_all.get(C, [])
                if scores:
                    valid_scores = [s for s in scores if s is not None]
                    if valid_scores:
                        C_performance_formatted[float(C)] = float(np.mean(valid_scores))
            
            validation_results = {
                "method": method_name,
                "best_C": float(best_C),
                "nested_cv_score": float(nested_cv_score),
                "mean_score": float(np.mean(outer_scores)),
                "std_score": float(np.std(outer_scores)),
                "best_score": float(np.max(outer_scores)),
                "n_splits": len(fold_results),
                "best_fold_used": int(best_fold_idx + 1),
                "best_fold_score": float(outer_scores[best_fold_idx]),
                "cv_validation_accuracy_mean": float(np.mean(outer_scores)),
                "cv_validation_accuracy_std": float(np.std(outer_scores)),
                "fold_details": fold_results,
                "C_performance": [{"C": C, "score": score} for C, score in C_performance_formatted.items()]
            }

        elif validation_method == "cv_timeseries":
            # ✅ TIMESERIES SPLIT POUR LOGISTIC REGRESSION
            logger.info("=" * 80)
            logger.info("⏰ TIMESERIES SPLIT SELECTED FOR LOGISTIC REGRESSION")
            logger.info("=" * 80)
            
            check_stop()
            
            # Récupérer les paramètres TimeSeries
            time_series_params = getattr(request, 'time_series_params', {})
            n_splits = time_series_params.get('n_splits', 5)
            test_size = time_series_params.get('test_size', 0.2)
            gap = time_series_params.get('gap', 0)
            
            logger.info(f"📊 Paramètres: n_splits={n_splits}, test_size={test_size}, gap={gap}")
            logger.info(f"📅 Colonne date: {date_column if date_column else 'Aucune'}")
            
            if date_series is None:
                raise HTTPException(400, "TimeSeriesSplit requires a date column")
            
            logger.info(f"📊 Features utilisées (SANS date): {feature_columns}")
            
            # ✅ Utiliser la version corrigée avec date_series
            best_C, timeseries_results, fold_models, C_performance_dict = logistic_timeseries_optimization(
                X_train_scaled, y_train, date_series,
                n_splits, test_size, gap,
                C_search_space, request.penalty, request.solver,
                request.multi_class, request.class_weight,
                request.l1_ratio, feature_columns
            )
            
            # Sélection du meilleur modèle
            if timeseries_results and fold_models:
                val_scores = [fold['validation_accuracy'] for fold in timeseries_results]
                best_fold_idx = np.argmax(val_scores)
                final_model = fold_models[best_fold_idx]
                used_validation_model = True
                final_model_source = f"best_timeseries_fold_{best_fold_idx + 1}"
                
                # Formater C_performance pour l'affichage
                C_performance_formatted = []
                for C in C_search_space:
                    scores = C_performance_dict.get(C, [])
                    if scores:
                        C_performance_formatted.append({
                            "C": float(C),
                            "score": float(np.mean(scores))
                        })
                C_performance_formatted.sort(key=lambda x: x["C"])
                
                validation_results = {
                    "method": f"TimeSeries Split ({len(timeseries_results)} folds)",
                    "best_C": float(best_C),
                    "mean_score": float(np.mean(val_scores)),
                    "std_score": float(np.std(val_scores)),
                    "best_fold": int(best_fold_idx + 1),
                    "best_score": float(val_scores[best_fold_idx]),
                    "fold_details": timeseries_results,
                    "C_performance": C_performance_formatted,
                    "features_used": feature_columns,
                    "date_column_excluded": True
                }
                
                logger.info(f"🎯 Meilleur fold: {best_fold_idx + 1}, Score: {val_scores[best_fold_idx]:.4f}")
            else:
                logger.error("❌ Aucun résultat valide pour TimeSeriesSplit")
                raise HTTPException(500, "TimeSeriesSplit failed to produce valid results")
        
        # ==================== VÉRIFICATION QUE L'ENTRAÎNEMENT N'A PAS ÉTÉ ARRÊTÉ ====================
        if final_model is None:
            if training_id and training_stop_flags.get(training_id, False):
                raise HTTPException(400, "Training stopped by user")
            else:
                raise HTTPException(500, "Failed to train model: no model produced")

        check_stop()

        # ==================== MODEL EVALUATION ====================
        y_pred = final_model.predict(X_test_scaled)
        y_proba = final_model.predict_proba(X_test_scaled) if hasattr(final_model, "predict_proba") else None

        # Basic metrics
        accuracy = accuracy_score(y_test, y_pred)
        precision = precision_score(y_test, y_pred, average='weighted', zero_division=0)
        recall = recall_score(y_test, y_pred, average='weighted', zero_division=0)
        f1 = f1_score(y_test, y_pred, average='weighted', zero_division=0)

        # Training metrics
        y_pred_train = final_model.predict(X_train_scaled)
        train_accuracy = accuracy_score(y_train, y_pred_train)

        # Confusion matrix
        conf_matrix = confusion_matrix(y_test, y_pred)

        if len(class_names) == 2:
            tn, fp, fn, tp = conf_matrix.ravel()
            confusion_matrix_dict = {
                'true_negative': int(tn),
                'false_positive': int(fp),
                'false_negative': int(fn),
                'true_positive': int(tp),
                'labels': [str(c) for c in class_names]
            }
        else:
            confusion_matrix_dict = {
                'matrix': conf_matrix.tolist(),
                'labels': [str(c) for c in class_names]
            }

        # Classification report
        classification_rep = classification_report(
            y_test, y_pred, 
            target_names=[str(c) for c in class_names],
            output_dict=True,
            zero_division=0
        )

        # ==================== FEATURE IMPORTANCE ====================
        feature_importance = {}

        try:
            if hasattr(final_model, 'coef_') and final_model.coef_ is not None and len(final_model.coef_) > 0:
                if len(class_names) == 2:
                    if final_model.coef_.ndim == 2:
                        if final_model.coef_.shape[0] == 1:
                            coef_values = final_model.coef_[0]
                        else:
                            coef_values = final_model.coef_.ravel()
                    else:
                        coef_values = final_model.coef_
                    
                    min_len = min(len(coef_values), len(X_train.columns) if isinstance(X_train, pd.DataFrame) else len(feature_columns))
                    feature_names = X_train.columns.tolist() if isinstance(X_train, pd.DataFrame) else feature_columns
                    feature_importance = dict(zip(feature_names[:min_len], coef_values[:min_len]))
                else:
                    mean_importance = np.mean(np.abs(final_model.coef_), axis=0)
                    min_len = min(len(mean_importance), len(X_train.columns) if isinstance(X_train, pd.DataFrame) else len(feature_columns))
                    feature_names = X_train.columns.tolist() if isinstance(X_train, pd.DataFrame) else feature_columns
                    feature_importance = dict(zip(feature_names[:min_len], mean_importance[:min_len]))
            else:
                feature_names = X_train.columns.tolist() if isinstance(X_train, pd.DataFrame) else feature_columns
                feature_importance = {col: 1.0 for col in feature_names}
        except Exception as e:
            logger.error(f"Error computing feature importance: {str(e)}")
            feature_names = X_train.columns.tolist() if isinstance(X_train, pd.DataFrame) else feature_columns
            feature_importance = {col: 1.0 for col in feature_names}

        # ROC AUC (for binary classification)
        roc_auc = None
        if len(class_names) == 2 and y_proba is not None:
            roc_auc = roc_auc_score(y_test, y_proba[:, 1])

        check_stop()

        # ==================== METRICS STRUCTURE ====================
        metrics = {
            "accuracy": float(accuracy),
            "precision": float(precision),
            "recall": float(recall),
            "f1": float(f1),
            "roc_auc": float(roc_auc) if roc_auc is not None else None,
            "log_loss": float(log_loss(y_test, y_proba)) if y_proba is not None else None,
            "train_accuracy": float(train_accuracy),
            "final_test": {
                "accuracy": float(accuracy),
                "precision": float(precision),
                "recall": float(recall),
                "f1": float(f1)
            },
            "final_train": {
                "accuracy": float(train_accuracy)
            },
            "confusion_matrix": confusion_matrix_dict,
            "classification_report": classification_rep,
            "feature_importance": convert_numpy_types(feature_importance),
            "features_used": feature_columns,
            "target_column": target_column,
            "validation_method": validation_method,
            "best_C_used": best_C,
            "C_search_space": C_search_space,
            "C_selection_method": (
                "random_search" if random_search_meta
                else (validation_results.get("C_selection_method", "validation_split") if validation_results else "default")
            ),
            "random_search": random_search_meta,
            "validation_results": convert_numpy_types(validation_results) if validation_results else None,
            "predictions": {
                "y_true": y_test.tolist(),
                "y_pred": y_pred.tolist(),
                "y_proba": y_proba.tolist() if y_proba is not None else None,
                "y_train_true": y_train.tolist(),
                "y_train_pred": y_pred_train.tolist()
            },
            "classes": [str(c) for c in class_names],
            "n_classes": len(class_names),
            "is_classification": True,
            "metadata": {
                "model_type": "logistic_regression",
                "C_used": float(best_C),
                "C_selection_method": validation_results.get("C_selection_method", "validation_split") if validation_results else "default",
                "penalty": request.penalty,
                "solver": request.solver,
                "multi_class": request.multi_class,
                "n_features": len(feature_columns),
                "n_train_samples": len(X_train),
                "n_test_samples": len(X_test),
                "validation_method": validation_method,
                "class_names": [str(c) for c in class_names],
                "used_validation_model": used_validation_model,
                "final_model_source": final_model_source,
                "date_column_excluded": validation_method == "cv_timeseries" or date_column is not None
            }
        }

        # ==================== SERIALIZATION ====================
        try:
            model_bytes = io.BytesIO()
            model_data = {
                'model': final_model,
                'scaler': scaler,
                'feature_names': feature_columns,
                'class_names': class_names,
                'final_parameters': {
                    'C': best_C,
                    'penalty': request.penalty,
                    'solver': request.solver,
                    'multi_class': request.multi_class,
                    'class_weight': request.class_weight,
                    'max_iter': request.max_iter,
                    'l1_ratio': request.l1_ratio,
                    'use_scaling': request.use_scaling
                },
                'validation_method': validation_method,
                'used_validation_model': used_validation_model
            }
            joblib.dump(model_data, model_bytes)
            model_bytes.seek(0)
            model_base64 = base64.b64encode(model_bytes.read()).decode('utf-8')
            logger.info("💾 Model serialized successfully")
        except Exception as e:
            logger.error(f"❌ Error during model serialization: {str(e)}")
            model_base64 = None

        check_stop()

        # ==================== RESPONSE ====================
        response_data = {
            "status": "success",
            "model_type": "logistic_regression",
            "model_object": model_base64,
            "dataset_used": request.numerized_dataset_name,
            "metrics": convert_numpy_types(metrics),
            "random_search": convert_numpy_types(random_search_meta) if random_search_meta else None,
            "timestamp": datetime.now().isoformat(),
            "training_info": {
                "model_trained_once": not used_validation_model,
                "used_cv_best_model": used_validation_model and validation_method.startswith('cv_'),
                "used_bootstrap_model": used_validation_model and validation_method == "bootstrap",
                "used_holdout_model": used_validation_model and validation_method == "holdout",
                "used_timeseries_model": used_validation_model and validation_method == "cv_timeseries",
                "final_model_source": final_model_source,
                "training_samples": len(X_train),
                "test_samples": len(X_test),
                "parameter_optimization": (
                    "Random Search (C) then fixed-C validation"
                    if random_search_meta
                    else f"C optimization using {validation_method}"
                ),
                "n_repetitions": request.n_repetitions if validation_method == "holdout" else None,
                "validation_method": validation_method,
                "date_column_excluded": validation_method == "cv_timeseries" or date_column is not None,
                "date_column": date_column if date_column else None
            }
        }

        logger.info("=== LOGISTIC REGRESSION TRAINING COMPLETED SUCCESSFULLY ===")
        logger.info(f"📊 FINAL RESULTS - Accuracy: {accuracy:.4f}, Best C: {best_C}")
        
        return response_data

    except HTTPException as he:
        if he.detail == "Training stopped by user":
            logger.info(f"🛑 Logistic training {training_id} stopped by user")
        raise
    except Exception as e:
        logger.error(f"Complete error: {traceback.format_exc()}")
        raise HTTPException(500, f"Server error: {str(e)}")

@router.post("/train-logistic-regression")
async def train_logistic_regression(
    request: TrainLogisticRequest,
    background_tasks: BackgroundTasks = None, 
    current_user_id: str = Depends(get_current_user2)
):  
    # ========== 1. MODE ASYNCHRONE (BACKGROUND) - AVEC ARRÊT RÉEL ==========
    if hasattr(request, 'training_id') and request.training_id and background_tasks is not None:
        training_id = request.training_id
        
        # ✅ CRITIQUE: Initialiser le flag d'arrêt
        training_stop_flags[training_id] = False
        
        def train_in_background():
            import asyncio
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)
            
            try:
                new_request = request.copy()
                new_request.training_id = None
                
                # ✅ CRITIQUE: Exécuter l'entraînement avec vérification d'arrêt
                result = loop.run_until_complete(
                    train_logistic_with_stop_check(new_request, None, current_user_id, training_id)
                )
                
                # ✅ Marquer comme complété SEULEMENT si pas arrêté par l'utilisateur
                if training_id in active_trainings and not training_stop_flags.get(training_id, False):
                    training_info = active_trainings[training_id]
                    future = training_info.get('future')
                    
                    if future and not future.done():
                        training_info['completed'] = True
                        training_info['result'] = result
                        _safe_set_training_result(training_id, result)
                        logger.info(f"✅ Logistic training {training_id} completed successfully")
                    else:
                        logger.warning(f"⚠️ Training {training_id} future already done/cancelled")
                
            except Exception as e:
                # ✅ Gestion spéciale pour l'arrêt utilisateur
                error_msg = str(e)
                if "Training stopped by user" in error_msg:
                    logger.info(f"🛑 Logistic training {training_id} was stopped by user")
                    if training_id in active_trainings:
                        training_info = active_trainings[training_id]
                        future = training_info.get('future')
                        if future and not future.done():
                            training_info['completed'] = True
                            training_info['error'] = "Training stopped by user"
                            training_info['result'] = None
                            _safe_set_training_error(training_id, 'Training stopped by user', stopped=True)
                else:
                    logger.error(f"❌ Erreur dans train_logistic background: {error_msg}")
                    if training_id in active_trainings:
                        training_info = active_trainings[training_id]
                        future = training_info.get('future')
                        if future and not future.done():
                            training_info['completed'] = True
                            training_info['error'] = error_msg
                            _safe_set_training_error(training_id, error_msg, stopped=False)
            finally:
                # ✅ Nettoyer le flag d'arrêt
                if training_id in training_stop_flags:
                    del training_stop_flags[training_id]
                loop.close()
        
        from concurrent.futures import Future
        future = Future()
        
        active_trainings[training_id] = {
            'future': future,
            'user_id': current_user_id,
            'start_time': datetime.now(),
            'model_type': 'logistic',
            'completed': False,
            'result': None,
            'error': None,
            'retrieved': False
        }
        
        background_tasks.add_task(train_in_background)
        
        return {
            "status": "training_started",
            "training_id": training_id,
            "message": "Logistic regression training started in background"
        }
    
    # ========== 2. MODE SYNCHRONE (EXÉCUTION NORMALE) ==========
    return await train_logistic_with_stop_check(request, background_tasks, current_user_id, None)

