logger = logging.getLogger(__name__)

def convert_numpy_types(data):
    """Convertit récursivement les types numpy en types natifs Python"""
    if isinstance(data, (np.integer, np.int64)):
        return int(data)
    elif isinstance(data, (np.floating, np.float64)):
        return float(data)
    elif isinstance(data, np.ndarray):
        return data.tolist()
    elif isinstance(data, dict):
        return {k: convert_numpy_types(v) for k, v in data.items()}
    elif isinstance(data, (list, tuple)):
        return [convert_numpy_types(item) for item in data]
    return data

class TrainRandomForestRequest(BaseModel):
    numerized_dataset_name: str
    original_dataset_name: str
    model_type: Literal["random_forest"] = "random_forest"
    n_estimators: int = Field(100, gt=0)
    max_depth: Optional[int] = Field(None, gt=0)
    min_samples_split: int = Field(2, gt=1)
    min_samples_leaf: int = Field(1, gt=0)
    max_features: Optional[Union[str, float]] = Field(
        None,
        description="For classification: 'sqrt', 'log2' or None. For regression: float between 0 and 1"
    )
    bootstrap: bool = True
    oob_score: bool = False
    n_jobs: int = Field(-1, description="Number of CPU cores to use")
    criterion: Optional[str] = Field(
        default=None,
        description="Split quality: 'gini'/'entropy'/'log_loss' (clf) or 'squared_error'/'absolute_error'/'friedman_mse'/'poisson' (reg)"
    )
    
    # ✅ Validation method
    validation_method: Optional[str] = "holdout"
    n_repetitions: int = Field(
        default=10, 
        gt=0, 
        le=50, 
        description="Number of repetitions for Hold-Out validation"
    )
    final_training_on_all_data: bool = Field(
        default=False,
        description="If True, retrain final model on train+test combined (not for objective evaluation)"
    )
    cv_params: Optional[Dict[str, Any]] = None
    bootstrap_params: Optional[Dict[str, Any]] = Field(
        default=None,
        description="Parameters for bootstrap validation: n_bootstraps, test_size, sample_size"
    )
    
    # ✅ TimeSeries parameters
    time_series_column: Optional[str] = Field(
        default=None,
        description="Column name containing dates for time series split"
    )
    time_series_params: Optional[Dict[str, Any]] = Field(
        default=None,
        description="Parameters for time series split: n_splits, test_size, gap"
    )
    
    training_id: Optional[str] = None
    random_search: bool = False
    n_trials: Optional[int] = Field(default=20, ge=1, le=50)
    random_search_seed: Optional[int] = 42

@router.get("/get-target-type")
async def get_target_type(bdName: str, current_user_id: str = Depends(get_current_user2)):
    try:
        print(f"[DEBUG] 🔍 Starting target type detection for {bdName}")
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                print(f"[DEBUG] Début de get-target-type pour la table: {bdName}")
                
                # Récupérer la colonne cible
                cur.execute("""
                    SELECT target_column 
                    FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (bdName.lower(), current_user_id))
                
                target_info = cur.fetchone()
                if not target_info or not target_info[0]:
                    print("[ERROR] Target column not defined")
                    raise HTTPException(400, "Target column not defined")
                
                target_column = target_info[0]
                print(f"[DEBUG] Colonne cible trouvée: {target_column}")

                # Récupérer les valeurs de la colonne cible
                cur.execute(f"""
                    SELECT {target_column} 
                    FROM {bdName.lower()}
                    WHERE {target_column} IS NOT NULL
                    LIMIT 1000
                """)
                target_values = [row[0] for row in cur.fetchall()]
                
                if not target_values:
                    print("[ERROR] Aucune donnée dans la colonne cible")
                    raise HTTPException(400, "No data available in target column")

                print(f"[DEBUG] Exemple de valeurs cibles (5 premières): {target_values[:5]}")

                # Vérification numérique
                try:
                    pd.Series(target_values).apply(pd.to_numeric, errors='raise')
                    target_is_numeric = True
                    print("[DEBUG] Conversion numérique réussie")
                except (ValueError, TypeError) as e:
                    target_is_numeric = False
                    print(f"[DEBUG] Échec conversion numérique. Erreur: {str(e)}")

                # Calcul du taux d'unicité
                unique_values = len(set(target_values))
                total_values = len(target_values)
                unicity_rate = unique_values / total_values
                print(f"[DEBUG] Unicité: {unique_values}/{total_values} = {unicity_rate:.2f}")

                # Décision
                is_classification = unicity_rate < 0.05

                if not target_is_numeric:
                    is_classification = True
                elif unicity_rate < 0.05:
                    is_classification = True
                elif unique_values <= 10:
                    is_classification = True
                else:
                    is_classification = False

                if unique_values == 2:
                    is_classification = True
                    
                decision = "CLASSIFICATION" if is_classification else "REGRESSION"
                print(f"[DEBUG] Décision finale: {decision} (Numérique: {target_is_numeric})")

                result = {
                    "is_classification": is_classification,
                    "unicity_rate": unicity_rate,
                    "unique_values": unique_values,
                    "total_values": total_values,
                    "target_is_numeric": target_is_numeric,
                    "decision": decision
                }
                
                print(f"[DEBUG] Résultat à renvoyer: {result}")
                return result
        print(f"[DEBUG] Target values sample: {target_values[:10]}")
        print(f"[DEBUG] Unique values: {unique_values}")
        print(f"[DEBUG] Total values: {total_values}")
        print(f"[DEBUG] Unicity rate: {unicity_rate:.4f}")
        print(f"[DEBUG] Target is numeric: {target_is_numeric}")
        
        # Force regression for purely numeric datasets with high uniqueness
        if target_is_numeric and unicity_rate > 0.1:
            is_classification = False
            print("[DEBUG] 🔄 Forcing regression due to high uniqueness")
        
        print(f"[DEBUG] Final decision: {'CLASSIFICATION' if is_classification else 'REGRESSION'}")
        
        return result
    except Exception as e:
        print(f"[ERROR] Erreur dans get-target-type: {str(e)}")
        raise HTTPException(500, f"Error getting target type: {str(e)}")

def get_table_columns(cursor, table_name):
    """Récupère toutes les colonnes d'une table"""
    cursor.execute("""
        SELECT column_name 
        FROM information_schema.columns 
        WHERE table_name = %s 
        ORDER BY ordinal_position
    """, (table_name.lower(),))
    return [row[0] for row in cursor.fetchall()]

def random_forest_timeseries_optimization(
    X, y, date_series, n_splits, test_size, gap,
    base_params, is_classification, feature_columns,
    training_id=None, training_stop_flags=None
):
    """
    Optimisation Random Forest avec TimeSeriesSplit
    Retourne: (fold_results, fold_models, val_scores)
    """
    logger.info("=" * 80)
    logger.info("🕒 TIMESERIES SPLIT OPTIMIZATION FOR RANDOM FOREST")
    logger.info("=" * 80)
    
    n_samples = len(X)
    logger.info(f"📊 Nombre total d'échantillons: {n_samples}")
    
    # Vérifier la longueur de date_series
    if len(date_series) != n_samples:
        logger.warning(f"⚠️ Longueur de date_series ({len(date_series)}) != n_samples ({n_samples})")
        if len(date_series) > n_samples:
            date_series = date_series.iloc[:n_samples]
        else:
            date_series = pd.Series(range(n_samples), index=range(n_samples))
    
    # Créer DataFrame avec index
    temp_df = pd.DataFrame(X, columns=feature_columns)
    temp_df['target'] = y
    temp_df['date'] = date_series.values if hasattr(date_series, 'values') else date_series
    temp_df['original_index'] = range(n_samples)
    
    # Trier par date
    temp_df_sorted = temp_df.sort_values('date').reset_index(drop=True)
    
    # Extraire les données triées
    X_sorted = temp_df_sorted[feature_columns].values
    y_sorted = temp_df_sorted['target'].values
    
    logger.info(f"✅ X_sorted shape: {X_sorted.shape}, y_sorted shape: {y_sorted.shape}")
    
    # Calculer test_size en échantillons
    if isinstance(test_size, float) and test_size < 1:
        test_size_samples = max(1, int(n_samples * test_size))
    else:
        test_size_samples = max(1, int(test_size))
    
    logger.info(f"📊 test_size: {test_size} → {test_size_samples} échantillons")
    
    # Ajuster si nécessaire
    min_samples_needed = (n_splits + 1) * test_size_samples
    if min_samples_needed > n_samples:
        max_possible_splits = max(2, n_samples // test_size_samples - 1)
        n_splits = min(n_splits, max_possible_splits)
        logger.info(f"✅ n_splits ajusté à {n_splits}")
    
    # Créer le splitter
    tscv = TimeSeriesSplit(n_splits=n_splits, test_size=test_size_samples, gap=gap)
    
    fold_results = []
    fold_models = []
    val_scores = []
    
    fold_count = 0
    for fold_idx, (train_idx, val_idx) in enumerate(tscv.split(X_sorted)):
        fold_count += 1
        
        # Vérifier stop flag
        if training_id and training_stop_flags and training_stop_flags.get(training_id, False):
            logger.info(f"🛑 Stop signal détecté, arrêt après {fold_count} folds")
            break
        
        # Vérifier les index
        if max(train_idx) >= n_samples or max(val_idx) >= n_samples:
            logger.error(f"❌ Index hors limites: train max={max(train_idx)}, val max={max(val_idx)}")
            continue
        
        logger.info(f"🔍 Fold {fold_count}/{n_splits}")
        logger.info(f"   Train indices: {train_idx[0]} → {train_idx[-1]} (taille: {len(train_idx)})")
        logger.info(f"   Val indices:   {val_idx[0]} → {val_idx[-1]} (taille: {len(val_idx)})")
        
        # Extraire les données
        X_train_fold = X_sorted[train_idx]
        X_val_fold = X_sorted[val_idx]
        y_train_fold = y_sorted[train_idx]
        y_val_fold = y_sorted[val_idx]
        
        if len(X_train_fold) < 5 or len(X_val_fold) < 1:
            logger.warning(f"   ⚠️ Pas assez de données, skip")
            continue
        
        try:
            # Créer et entraîner le modèle
            if is_classification:
                model = RandomForestClassifier(**base_params)
            else:
                model = RandomForestRegressor(**base_params)
            
            model.fit(X_train_fold, y_train_fold)
            
            # Évaluer
            train_score = model.score(X_train_fold, y_train_fold)
            val_score = model.score(X_val_fold, y_val_fold)
            
            logger.info(f"   ✅ Train score: {train_score:.4f}, Val score: {val_score:.4f}")
            
            fold_models.append(model)
            val_scores.append(val_score)
            
            fold_results.append({
                'fold': fold_count,
                'train_size': len(X_train_fold),
                'val_size': len(X_val_fold),
                'train_score': float(train_score),
                'val_score': float(val_score),
                'train_indices': [int(train_idx[0]), int(train_idx[-1])],
                'val_indices': [int(val_idx[0]), int(val_idx[-1])],
                'best_params': base_params  # Ajouter les paramètres utilisés
            })
            
        except Exception as e:
            logger.error(f"❌ Erreur sur fold {fold_count}: {e}")
            continue
    
    if not fold_results:
        logger.error("❌ Aucun fold valide")
        return [], [], []
    
    logger.info("=" * 80)
    logger.info("📊 RÉSULTATS TIMESERIES SPLIT")
    logger.info(f"   Folds valides: {len(fold_results)}/{n_splits}")
    logger.info(f"   Score moyen validation: {np.mean(val_scores):.4f} ± {np.std(val_scores):.4f}")
    logger.info("=" * 80)
    
    return fold_results, fold_models, val_scores

def random_forest_cv_with_models(X, y, cv, model_params, is_classification):
    """Validation croisée qui sauvegarde les modèles"""
    cv_scores = []
    cv_models = []
    fold_details = []
    
    for fold_idx, (train_idx, val_idx) in enumerate(cv.split(X, y)):
        X_cv_train, X_cv_val = X[train_idx], X[val_idx]
        y_cv_train, y_cv_val = y[train_idx], y[val_idx]
        
        # Créer et entraîner un modèle pour ce fold
        if is_classification:
            fold_model = RandomForestClassifier(**model_params)
        else:
            fold_model = RandomForestRegressor(**model_params)
            
        fold_model.fit(X_cv_train, y_cv_train)
        
        # Calculer le score pour ce fold
        if is_classification:
            score = accuracy_score(y_cv_val, fold_model.predict(X_cv_val))
            train_score = accuracy_score(y_cv_train, fold_model.predict(X_cv_train))
        else:
            score = r2_score(y_cv_val, fold_model.predict(X_cv_val))
            train_score = r2_score(y_cv_train, fold_model.predict(X_cv_train))
        
        cv_scores.append(score)
        cv_models.append(fold_model)
        
        fold_details.append({
            'fold': fold_idx + 1,
            'train_score': float(train_score),
            'validation_score': float(score),
            'train_size': len(X_cv_train),
            'validation_size': len(X_cv_val)
        })
    
    return cv_scores, cv_models, fold_details

# ✅ NOUVELLE FONCTION : Bootstrap avec sauvegarde des modèles
def random_forest_bootstrap_with_models(X, y, n_bootstraps, test_size, base_params, is_classification):
    """
    Bootstrap avec sauvegarde des modèles et des scores d'entraînement
    """
    bootstrap_scores = []
    bootstrap_models = []
    bootstrap_details = []
    
    n_samples = len(X)
    
    for i in range(n_bootstraps):
        try:
            # Échantillonnage bootstrap avec remise
            train_indices = np.random.choice(n_samples, size=n_samples, replace=True)
            
            # Indices OOB (out-of-bag)
            all_indices = np.arange(n_samples)
            val_indices = np.setdiff1d(all_indices, train_indices)
            
            # Si pas assez d'OOB, prendre un échantillon aléatoire
            if len(val_indices) < 5:
                val_indices = np.random.choice(train_indices, size=max(5, n_samples // 10), replace=False)
                train_indices = np.setdiff1d(train_indices, val_indices)
            
            X_train_bs = X[train_indices]
            y_train_bs = y[train_indices]
            X_val_bs = X[val_indices]
            y_val_bs = y[val_indices]
            
            # Vérifier qu'on a assez de données
            if len(X_train_bs) < 5 or len(X_val_bs) < 1:
                continue
            
            # Créer et entraîner le modèle
            if is_classification:
                model = RandomForestClassifier(**base_params)
            else:
                model = RandomForestRegressor(**base_params)
            
            model.fit(X_train_bs, y_train_bs)
            
            # Calculer les scores
            val_score = model.score(X_val_bs, y_val_bs)
            train_score = model.score(X_train_bs, y_train_bs)
            
            bootstrap_scores.append(val_score)
            bootstrap_models.append(model)
            
            bootstrap_details.append({
                'bootstrap': i + 1,
                'score': float(val_score),
                'train_score': float(train_score),  # ✅ AJOUT : score d'entraînement
                'train_size': len(X_train_bs),
                'validation_size': len(X_val_bs),
                'unique_samples_in_bootstrap': len(np.unique(train_indices)),
                'test_size_percent': (len(val_indices) / n_samples) * 100
            })
            
        except Exception as e:
            logger.warning(f"Bootstrap {i+1} failed: {e}")
            continue
    
    if not bootstrap_scores:
        # Fallback: un seul modèle sur toutes les données
        if is_classification:
            model = RandomForestClassifier(**base_params)
        else:
            model = RandomForestRegressor(**base_params)
        
        model.fit(X, y)
        train_score = model.score(X, y)
        
        bootstrap_scores = [train_score]
        bootstrap_models = [model]
        bootstrap_details = [{
            'bootstrap': 1,
            'score': float(train_score),
            'train_score': float(train_score),
            'train_size': len(X),
            'validation_size': 0,
            'unique_samples_in_bootstrap': len(X),
            'test_size_percent': 0,
            'note': 'Fallback - trained on all data'
        }]
    
    return bootstrap_scores, bootstrap_models, bootstrap_details
def random_forest_holdout_repeated_with_models(X, y, n_repetitions, test_size, base_params, is_classification):
    """
    Hold-Out répété avec sauvegarde des modèles et des scores d'entraînement
    """
    holdout_scores = []
    holdout_models = []
    repetition_details = []
    
    for i in range(n_repetitions):
        # Split aléatoire
        X_train, X_val, y_train, y_val = train_test_split(
            X, y, 
            test_size=test_size, 
            random_state=i,
            stratify=y if is_classification else None
        )
        
        # Créer et entraîner le modèle
        if is_classification:
            model = RandomForestClassifier(**base_params)
        else:
            model = RandomForestRegressor(**base_params)
        
        model.fit(X_train, y_train)
        
        # Calculer les scores
        val_score = model.score(X_val, y_val)
        train_score = model.score(X_train, y_train)
        
        holdout_scores.append(val_score)
        holdout_models.append(model)
        
        repetition_details.append({
            'repetition': i + 1,
            'score': float(val_score),
            'train_score': float(train_score),  # ✅ AJOUT : score d'entraînement
            'train_size': len(X_train),
            'validation_size': len(X_val),
            'test_size_percent': test_size * 100,
            'random_state': i
        })
        
        logger.info(f"Répétition {i+1}: Val Score={val_score:.4f}, Train Score={train_score:.4f}")
    
    return holdout_scores, holdout_models, repetition_details
def prepare_data_for_random_forest(df, target_column, date_column=None, validation_method=None):
    """
    Prépare les données pour Random Forest en excluant correctement la colonne date
    des features si elle n'est pas utilisée pour TimeSeriesSplit
    """
    logger.info("🔧 PREPARATION DES DONNEES POUR RANDOM FOREST")
    
    # Créer une copie pour éviter de modifier l'original
    df_processed = df.copy()
    
    # Identifier les colonnes à exclure de l'entraînement
    exclude_columns = [target_column, 'split_type']
    
    if date_column:
        exclude_columns.append(date_column)
        if validation_method == "cv_timeseries":
            logger.info(f"📅 Colonne date '{date_column}' utilisée UNIQUEMENT pour split temporel -> EXCLUE des features")
        else:
            logger.info(f"🚫 Colonne date '{date_column}' -> EXCLUE des features (non TimeSeries)")
    
    # Colonnes features (tout sauf les exclues) + auto-exclude other date-like cols
    feature_columns = [col for col in df_processed.columns if col not in exclude_columns]
    feature_columns = exclude_date_columns_from_list(
        df_processed, feature_columns, date_column=date_column, target_column=target_column
    )
    logger.info(f"📊 Features utilisées pour l'entraînement: {feature_columns}")
    logger.info(f"🚫 Colonnes exclues: {exclude_columns}")
    
    # Séparer les données selon split_type
    train_mask = df_processed['split_type'] == 'train'
    test_mask = df_processed['split_type'] == 'test'
    
    df_train = df_processed[train_mask].copy()
    df_test = df_processed[test_mask].copy()
    
    logger.info(f"📊 Train: {len(df_train)} samples, Test: {len(df_test)} samples")
    
    # Extraire X et y pour train/test
    X_train_raw = df_train[feature_columns].copy()
    y_train_raw = df_train[target_column].copy()
    X_test_raw = df_test[feature_columns].copy()
    y_test_raw = df_test[target_column].copy()
    
    # ✅ Conversion numérique ROBUSTE avec gestion des erreurs
    for df_part, name in [(X_train_raw, "X_train"), (X_test_raw, "X_test")]:
        for col in df_part.columns:
            try:
                # Convertir en numérique, les erreurs deviennent NaN
                df_part.loc[:, col] = pd.to_numeric(df_part[col], errors='coerce')
                
                # Log des problèmes potentiels
                nan_count = df_part[col].isna().sum()
                if nan_count > 0:
                    logger.warning(f"⚠️ {name}: {nan_count} NaN dans {col} après conversion")
            except Exception as e:
                logger.error(f"❌ Erreur conversion {col}: {e}")
                df_part.loc[:, col] = 0.0
    
    # ✅ Remplir les NaN avec la médiane (calculée SUR LE TRAIN UNIQUEMENT)
    train_medians = X_train_raw.median(numeric_only=True)
    
    # Remplacer les NaN dans les deux datasets avec les stats du train
    X_train = X_train_raw.fillna(train_medians)
    X_test = X_test_raw.fillna(train_medians)
    
    # ✅ Vérification finale des NaN
    if X_train.isna().any().any():
        nan_cols = X_train.columns[X_train.isna().any()].tolist()
        logger.warning(f"⚠️ NaN persistants dans X_train colonnes: {nan_cols} - remplissage avec 0")
        X_train = X_train.fillna(0)
    
    if X_test.isna().any().any():
        X_test = X_test.fillna(0)
    
    # ✅ Traitement de la target
    y_train = pd.to_numeric(y_train_raw, errors='coerce').fillna(0).values
    y_test = pd.to_numeric(y_test_raw, errors='coerce').fillna(0).values
    
    # ✅ Récupérer la colonne date pour TimeSeriesSplit si nécessaire
    date_series = None
    if date_column and validation_method == "cv_timeseries":
        # Align date series to TRAIN rows only (same length/order as X_train)
        date_series = train_aligned_date_series(df_train, date_column)
        logger.info(f"📅 Colonne date récupérée pour TimeSeriesSplit: {date_column}")
    
    logger.info(f"✅ Préparation terminée: X_train shape {X_train.shape}, X_test shape {X_test.shape}")
    
    return X_train, X_test, y_train, y_test, feature_columns, date_series

# ========== NOUVELLE FONCTION AVEC VÉRIFICATION D'ARRÊT ==========
async def train_random_forest_with_stop_check(
    request: TrainRandomForestRequest,
    background_tasks: BackgroundTasks = None,
    current_user_id: str = None,
    training_id: str = None
):
    """Version de train_random_forest avec vérification d'arrêt à chaque étape"""
    
    # ✅ Fonction de vérification d'arrêt
    def check_stop():
        if training_id and training_stop_flags.get(training_id, False):
            logger.info(f"🛑 Random Forest training {training_id} stopped by user (check_stop triggered)")
            raise HTTPException(400, "Training stopped by user")
    
    try:
        # ==================== VALIDATION INITIALE ====================
        logger.info("🎯 Random Forest training started")
        if training_id:
            logger.info(f"🎫 Training ID: {training_id}")
        
        check_stop()
        
        if not request.numerized_dataset_name or not request.original_dataset_name:
            raise HTTPException(400, "Dataset names are required")
        
        check_stop()

        # ==================== CHARGEMENT DES DONNEES ====================
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Vérification des permissions et récupération de la colonne cible
                cur.execute("""
                    SELECT target_column 
                    FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (request.original_dataset_name.lower(), current_user_id))
                
                target_info = cur.fetchone()
                if not target_info or not target_info[0]:
                    raise HTTPException(400, "Target column not defined in original dataset")
                
                target_column = target_info[0]
                check_stop()

                # Vérification de la table numérisée
                cur.execute("""
                    SELECT 1 FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (request.numerized_dataset_name.lower(), current_user_id))
                
                if not cur.fetchone():
                    raise HTTPException(404, "Numerized dataset not found or access denied")
                
                check_stop()

                # Vérification de la colonne cible
                cur.execute("""
                    SELECT 1 FROM information_schema.columns
                    WHERE table_name = %s AND column_name = %s
                """, (request.numerized_dataset_name.lower(), target_column))
                
                if not cur.fetchone():
                    raise HTTPException(400, 
                        f"Colonne cible '{target_column}' manquante dans la version numérisée")
                
                check_stop()

                # Récupération des colonnes disponibles
                all_columns = get_table_columns(cur, request.numerized_dataset_name)
                if not all_columns:
                    raise HTTPException(404, "No columns found")
                
                check_stop()

                # Construction de la liste des colonnes à sélectionner
                select_columns = [
                    sql.Identifier(col) 
                    for col in all_columns 
                    if col not in ['id', 'split_type']
                ]

                # Construction de la requête SQL
                query = sql.SQL("""
                    SELECT {columns}, split_type FROM {table}
                    WHERE split_type IS NOT NULL
                """).format(
                    columns=sql.SQL(',').join(select_columns),
                    table=sql.Identifier(request.numerized_dataset_name.lower())
                )

                cur.execute(query)
                rows = cur.fetchall()
                check_stop()

        # ==================== PREPARATION DES DONNEES ====================
        df_columns = [col for col in all_columns if col not in ['id', 'split_type']] + ['split_type']
        df = pd.DataFrame(rows, columns=df_columns)
        check_stop()

        # Nettoyage de la colonne split_type
        df['split_type'] = df['split_type'].astype(str).str.lower().str.strip()
        check_stop()
        
        # Validation des valeurs de split_type
        valid_splits = {'train', 'test'}
        invalid_splits = set(df['split_type'].unique()) - valid_splits
        if invalid_splits:
            raise HTTPException(
                400, 
                f"Invalid values in split_type: {invalid_splits}. Expected: 'train' or 'test'"
            )

        # ✅ Utiliser la nouvelle fonction de préparation des données
        # qui exclut correctement la colonne date des features
        date_column = resolve_request_date_column(request)
        validation_method = request.validation_method or "holdout"
        
        X_train, X_test, y_train, y_test, feature_columns, date_series = prepare_data_for_random_forest(
            df, 
            target_column, 
            date_column=date_column,
            validation_method=validation_method
        )

        check_stop()

        # ==================== TARGET PROCESSING ====================
        try:
            pd.to_numeric(y_train, errors='raise')
            target_is_numeric = True
        except (ValueError, TypeError):
            target_is_numeric = False

        unique_values = len(np.unique(y_train))
        total_samples = len(y_train)
        unique_ratio = (unique_values / total_samples) * 100

        # Seuil adaptatif
        if total_samples <= 30:
            threshold = 25.0
        elif total_samples <= 100:
            threshold = 15.0
        else:
            threshold = 5.0

        # Détection du type de problème
        is_classification = unique_ratio <= threshold
        decision_reason = f"{unique_values} unique values ({unique_ratio:.1f}% of data) - {'classification' if is_classification else 'regression'} (threshold: {threshold}%)"
        check_stop()

        # Encodage des cibles
        if is_classification:
            y_train_encoded = y_train
            y_test_encoded = y_test
            class_names = sorted(np.unique(y_train_encoded))
        elif not is_classification and not target_is_numeric:
            try:
                y_train_encoded = pd.to_numeric(y_train, errors='raise')
                y_test_encoded = pd.to_numeric(y_test, errors='raise')
                target_is_numeric = True
                class_names = sorted(np.unique(y_train_encoded))
            except ValueError as e:
                raise HTTPException(400, f"Column '{target_column}' cannot be used for regression: {str(e)}")
        else:
            y_train_encoded = y_train
            y_test_encoded = y_test
            class_names = sorted(np.unique(y_train_encoded))
        
        check_stop()

        target_analysis = {
            "target_column": target_column,
            "unique_values": int(unique_values),
            "total_samples": total_samples,
            "unique_ratio": float(unique_ratio),
            "is_numeric": target_is_numeric,
            "is_classification": is_classification,
            "decision_reason": decision_reason,
            "threshold_used": threshold,
            "class_names": [str(c) for c in class_names]
        }

        # ==================== VALIDATION DES PARAMETRES UTILISATEUR ====================
        if request.max_features is not None:
            if is_classification:
                # Pour la classification: 'sqrt', 'log2', None, ou int
                if request.max_features not in ['sqrt', 'log2', None] and not isinstance(request.max_features, int):
                    raise HTTPException(400, "For classification, max_features must be 'sqrt', 'log2', None, or integer")
            else:
                # Pour la Regression: 'sqrt', 'log2', None, int, ou float entre 0 et 1
                if request.max_features in ['sqrt', 'log2', None]:
                    # Ces valeurs sont valides pour la Regression aussi
                    pass
                elif isinstance(request.max_features, int):
                    # Entier valide
                    pass
                elif isinstance(request.max_features, float):
                    # Float doit être entre 0 et 1
                    if not (0 < request.max_features <= 1):
                        raise HTTPException(400, "For regression float max_features, must be between 0 and 1")
                else:
                    raise HTTPException(400, "For regression, max_features must be 'sqrt', 'log2', None, integer, or float between 0 and 1")
        
        check_stop()

        # ==================== RANDOM SEARCH (optional) ====================
        random_search_meta = None
        if getattr(request, "random_search", False):
            from backend.random_search_hp import run_hyperparam_random_search
            X_rs = X_train.values if hasattr(X_train, "values") else np.asarray(X_train)
            y_rs = np.asarray(y_train_encoded).ravel()
            rs_best, random_search_meta = run_hyperparam_random_search(
                "random_forest",
                X_rs,
                y_rs,
                n_trials=getattr(request, "n_trials", 20),
                is_classification=is_classification,
                check_stop=check_stop,
                active_trainings=active_trainings,
                training_id=training_id,
                fixed_params={
                    "bootstrap": request.bootstrap,
                    "criterion": getattr(request, "criterion", None),
                },
                random_state=int(getattr(request, "random_search_seed", 42) or 42),
            )
            request.n_estimators = int(rs_best["n_estimators"])
            request.max_depth = rs_best.get("max_depth")
            request.min_samples_split = int(rs_best["min_samples_split"])
            request.min_samples_leaf = int(rs_best["min_samples_leaf"])
            request.max_features = rs_best.get("max_features")
            logger.info(f"🎲 Random Search best RF params: {rs_best}")

        # ==================== CONFIGURATION DES PARAMÈTRES DU MODÈLE ====================
        final_params = {
            'n_estimators': request.n_estimators,
            'max_depth': request.max_depth,
            'min_samples_split': request.min_samples_split,
            'min_samples_leaf': request.min_samples_leaf,
            'max_features': request.max_features,
            'bootstrap': request.bootstrap,
            'oob_score': request.oob_score,
            'n_jobs': request.n_jobs,
            'random_state': None
        }
        if getattr(request, "criterion", None):
            final_params['criterion'] = request.criterion

        # ==================== PHASE 1 : VALIDATION SUR TRAIN UNIQUEMENT ====================
        validation_results = None
        validation_scores = []
        validation_models = []
        best_validation_model_idx = None
        
        logger.info(f"🎯 Début de la validation avec méthode: {request.validation_method}")
        
        # ✅ TIMESERIES SPLIT POUR RANDOM FOREST
        if request.validation_method == "cv_timeseries":
            logger.info("=" * 80)
            logger.info("⏰ TIMESERIES SPLIT SELECTED FOR RANDOM FOREST")
            logger.info("=" * 80)
            
            check_stop()
            
            # Récupérer les paramètres TimeSeries
            time_series_params = getattr(request, 'time_series_params', {})
            n_splits = time_series_params.get('n_splits', 5)
            test_size = time_series_params.get('test_size', 0.2)
            gap = time_series_params.get('gap', 0)
            
            logger.info(f"📊 Paramètres: n_splits={n_splits}, test_size={test_size}, gap={gap}")
            logger.info(f"📅 Colonne date: {date_column if date_column else 'Aucune'}")
            
            if date_series is None:
                raise HTTPException(400, "TimeSeriesSplit requires a date column")
            
            logger.info(f"📊 Features utilisées (SANS date): {feature_columns}")
            
            # ✅ Utiliser la version corrigée pour Random Forest avec paramètres d'arrêt
            timeseries_results, fold_models, val_scores = random_forest_timeseries_optimization(
                X_train, y_train_encoded, date_series,
                n_splits, test_size, gap,
                final_params, is_classification, feature_columns,
                training_id, training_stop_flags
            )
            
            if timeseries_results and fold_models:
                validation_models = fold_models
                validation_scores = val_scores
                
                # Trouver le meilleur fold
                best_validation_model_idx = np.argmax(val_scores)
                
                # ✅ Extraire les scores d'entraînement
                train_scores = [fold.get('train_score', 0) for fold in timeseries_results]
                
                # ✅ Formater fold_details avec les bons noms de champs
                formatted_fold_details = []
                for i, fold in enumerate(timeseries_results):
                    formatted_fold_details.append({
                        'fold': fold.get('fold', i + 1),
                        'train_size': fold.get('train_size', 0),
                        'val_size': fold.get('val_size', 0),
                        'train_score': float(fold.get('train_score', 0)),
                        'val_score': float(fold.get('val_score', 0)),
                        'best_params': fold.get('best_params', None),
                        'train_indices': fold.get('train_indices', []),
                        'val_indices': fold.get('val_indices', [])
                    })
                
                validation_results = {
                    "method": f"TimeSeries Split ({len(timeseries_results)} valid folds / {n_splits} total)",
                    "fold_details": formatted_fold_details,
                    
                    # ✅ Scores moyens (multiples formats pour compatibilité)
                    "mean_score": float(np.mean(val_scores)),
                    "std_score": float(np.std(val_scores)),
                    "cv_validation_r2_mean": float(np.mean(val_scores)),
                    "cv_validation_r2_std": float(np.std(val_scores)),
                    "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0,
                    "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0,
                    
                    # ✅ Meilleur fold
                    "best_fold": int(best_validation_model_idx + 1),
                    "best_score": float(val_scores[best_validation_model_idx]),
                    "best_fold_score": float(val_scores[best_validation_model_idx]),
                    
                    # ✅ Paramètres TimeSeries
                    "date_column": date_column,
                    "date_column_excluded": True,
                    "features_used": feature_columns,
                    "n_splits": n_splits,
                    "test_size": test_size,
                    "gap": gap
                }
                
                logger.info(f"🎯 Meilleur fold: {best_validation_model_idx + 1}, Score: {val_scores[best_validation_model_idx]:.4f}")
                logger.info(f"📊 Scores validation: moyenne={np.mean(val_scores):.4f}, écart-type={np.std(val_scores):.4f}")
            else:
                logger.error("❌ Aucun résultat valide pour TimeSeriesSplit")
                raise HTTPException(500, "TimeSeriesSplit failed to produce valid results")
        
        elif request.validation_method == "holdout":
            # ✅ HOLD-OUT RÉPÉTÉ
            test_size = 0.2
            logger.info(f"🔁 Hold-Out répété: {request.n_repetitions} répétitions sur train set")
            
            holdout_scores, holdout_models, repetition_details = random_forest_holdout_repeated_with_models(
                X_train.values, y_train_encoded, request.n_repetitions, test_size, 
                final_params, is_classification
            )
            
            if len(holdout_scores) > 0:
                best_validation_model_idx = np.argmax(holdout_scores)
                validation_models = holdout_models
                validation_scores = holdout_scores
                
                # ✅ Extraire les scores d'entraînement des répétitions
                train_scores = [rep.get('train_score', 0) for rep in repetition_details]
                
                validation_results = {
                    "method": f"Hold-Out Repeated ({request.n_repetitions} repetitions)",
                    "repetition_details": repetition_details,
                    "mean_score": float(np.mean(holdout_scores)),
                    "std_score": float(np.std(holdout_scores)),
                    "cv_validation_r2_mean": float(np.mean(holdout_scores)),  # ✅ Pour compatibilité
                    "cv_validation_r2_std": float(np.std(holdout_scores)),    # ✅ Pour compatibilité
                    "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0,  # ✅ AJOUT
                    "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0,   # ✅ AJOUT
                    "best_repetition": int(best_validation_model_idx + 1),
                    "best_score": float(holdout_scores[best_validation_model_idx]),
                    "test_size": test_size,
                    "n_repetitions": request.n_repetitions
                }
        
        elif request.validation_method and request.validation_method.startswith('cv_'):
            # ✅ CROSS-VALIDATION
            cv_params = request.cv_params or {}
            n_splits = cv_params.get('n_splits', 5)
            shuffle = cv_params.get('shuffle', True)
            
            if request.validation_method == "cv_kfold":
                cv = KFold(n_splits=n_splits, shuffle=shuffle, random_state=None)
                method_name = "Cross-Validation (KFold)"
            elif request.validation_method == "cv_repeatedkfold":
                n_repeats = cv_params.get('n_repeats', 3)
                cv = RepeatedKFold(n_splits=n_splits, n_repeats=n_repeats, random_state=None)
                method_name = "Cross-Validation (Repeated KFold)"
            elif request.validation_method == "cv_shufflesplit":
                test_size = cv_params.get('test_size', 0.2)
                cv = ShuffleSplit(n_splits=n_splits, test_size=test_size, random_state=None)
                method_name = "Cross-Validation (Shuffle Split)"
            
            logger.info(f"🔁 Cross-Validation: {method_name} sur train set")
            
            cv_scores, cv_models, fold_details = random_forest_cv_with_models(
                X_train.values, y_train_encoded, cv, final_params, is_classification
            )
            
            if len(cv_scores) > 0:
                best_validation_model_idx = np.argmax(cv_scores)
                validation_models = cv_models
                validation_scores = cv_scores
                
                # ✅ Extraire les scores d'entraînement des folds
                train_scores = [fold.get('train_score', 0) for fold in fold_details]
                
                validation_results = {
                    "method": method_name,
                    "fold_details": fold_details,
                    "cv_scores": [float(score) for score in cv_scores],
                    "cv_mean": float(np.mean(cv_scores)),
                    "cv_std": float(np.std(cv_scores)),
                    "cv_validation_r2_mean": float(np.mean(cv_scores)),  # ✅ Pour compatibilité
                    "cv_validation_r2_std": float(np.std(cv_scores)),    # ✅ Pour compatibilité
                    "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0,  # ✅ AJOUT
                    "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0,   # ✅ AJOUT
                    "n_splits": n_splits,
                    "best_fold": int(best_validation_model_idx + 1),
                    "best_score": float(cv_scores[best_validation_model_idx])
                }
                
                if request.validation_method == "cv_repeatedkfold":
                    validation_results["n_repeats"] = n_repeats
                elif request.validation_method == "cv_shufflesplit":
                    validation_results["test_size"] = test_size
        
        elif request.validation_method == "bootstrap":
            # ✅ BOOTSTRAP
            bootstrap_params = request.bootstrap_params or {}
            n_bootstraps = bootstrap_params.get('n_bootstraps', 100)
            test_size = bootstrap_params.get('test_size', 0.2)
            
            logger.info(f"🔁 Bootstrap: {n_bootstraps} échantillons sur train set")
            
            bootstrap_scores, bootstrap_models, bootstrap_details = random_forest_bootstrap_with_models(
                X_train.values, y_train_encoded, n_bootstraps, test_size, 
                final_params, is_classification
            )
            
            if len(bootstrap_scores) > 0:
                best_validation_model_idx = np.argsort(bootstrap_scores)[len(bootstrap_scores) // 2]
                validation_models = bootstrap_models
                validation_scores = bootstrap_scores
                
                # ✅ Extraire les scores d'entraînement des bootstrap
                train_scores = [bs.get('train_score', 0) for bs in bootstrap_details]
                
                validation_results = {
                    "method": "Bootstrap Validation",
                    "bootstrap_details": bootstrap_details,
                    "bootstrap_scores": [float(score) for score in bootstrap_scores],
                    "bootstrap_mean": float(np.mean(bootstrap_scores)),
                    "bootstrap_std": float(np.std(bootstrap_scores)),
                    "cv_validation_r2_mean": float(np.mean(bootstrap_scores)),  # ✅ Pour compatibilité
                    "cv_validation_r2_std": float(np.std(bootstrap_scores)),    # ✅ Pour compatibilité
                    "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0,  # ✅ AJOUT
                    "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0,   # ✅ AJOUT
                    "n_bootstraps": n_bootstraps,
                    "test_size": test_size,
                    "median_bootstrap_index": int(best_validation_model_idx + 1),
                    "median_bootstrap_score": float(bootstrap_scores[best_validation_model_idx])
                }
        else:
            # ✅ HOLD-OUT SIMPLE (fallback)
            check_stop()
            logger.info("🔁 Hold-Out simple (1 entraînement) sur train set")
            
            if is_classification:
                validation_model = RandomForestClassifier(**final_params)
            else:
                validation_model = RandomForestRegressor(**final_params)
            
            validation_model.fit(X_train.values, y_train_encoded)
            validation_score = validation_model.score(X_train.values, y_train_encoded)
            validation_models = [validation_model]
            validation_scores = [validation_score]
            best_validation_model_idx = 0
            
            validation_results = {
                "method": "Hold-Out Simple",
                "score": float(validation_score),
                "mean_score": float(validation_score),
                "std_score": 0,
                "cv_validation_r2_mean": float(validation_score),
                "cv_validation_r2_std": 0,
                "best_score": float(validation_score)
            }
        
        check_stop()
        
        # ✅ Sélectionner le meilleur modèle de validation
        if best_validation_model_idx is not None and validation_models:
            best_validation_model = validation_models[best_validation_model_idx]
        else:
            best_validation_model = validation_models[0] if validation_models else None
            
        # ==================== PHASE 2 : ENTRAÎNEMENT SUR TOUT LE TRAIN ====================
        logger.info("🏋️ Phase 2: Entraînement sur tout le train set")
        check_stop()
        
        # Créer un NOUVEAU modèle avec les mêmes paramètres
        if is_classification:
            model_on_full_train = RandomForestClassifier(**final_params)
        else:
            model_on_full_train = RandomForestRegressor(**final_params)

        # Entraîner sur TOUT le train set
        model_on_full_train.fit(X_train.values, y_train_encoded)
        check_stop()
        
        # Évaluer sur test set (pour le rapport seulement)
        y_pred_test = model_on_full_train.predict(X_test.values)
        
        # Calculer les métriques sur test
        if is_classification:
            test_accuracy = accuracy_score(y_test_encoded, y_pred_test)
            test_precision = precision_score(y_test_encoded, y_pred_test, average='weighted', zero_division=0)
            test_recall = recall_score(y_test_encoded, y_pred_test, average='weighted', zero_division=0)
            test_f1 = f1_score(y_test_encoded, y_pred_test, average='weighted', zero_division=0)
            
            y_pred_train = model_on_full_train.predict(X_train.values)
            train_accuracy = accuracy_score(y_train_encoded, y_pred_train)
            
            conf_matrix = confusion_matrix(y_test_encoded, y_pred_test)
            
            if len(class_names) == 2:
                tn, fp, fn, tp = conf_matrix.ravel()
                confusion_matrix_dict = {
                    'true_negative': int(tn),
                    'false_positive': int(fp),
                    'false_negative': int(fn),
                    'true_positive': int(tp),
                    'labels': [str(c) for c in class_names]
                }
            else:
                confusion_matrix_dict = {
                    'matrix': conf_matrix.tolist(),
                    'labels': [str(c) for c in class_names]
                }

            classification_rep = classification_report(
                y_test_encoded, y_pred_test, 
                target_names=[str(c) for c in class_names],
                output_dict=True,
                zero_division=0
            )
            
            test_metrics = {
                "accuracy": float(test_accuracy),
                "precision": float(test_precision),
                "recall": float(test_recall),
                "f1": float(test_f1)
            }
            
            train_metrics = {
                "accuracy": float(train_accuracy)
            }
            
        else:
            y_test_numeric = y_test_encoded.astype(float)
            y_pred_test_numeric = y_pred_test.astype(float)
    
            test_r2 = r2_score(y_test_numeric, y_pred_test_numeric)
            test_mse = mean_squared_error(y_test_numeric, y_pred_test_numeric)
            test_mae = mean_absolute_error(y_test_numeric, y_pred_test_numeric)
    
            y_pred_train = model_on_full_train.predict(X_train.values)
            y_train_numeric = y_train_encoded.astype(float)
            y_pred_train_numeric = y_pred_train.astype(float)
    
            train_r2 = r2_score(y_train_numeric, y_pred_train_numeric)
            train_mse = mean_squared_error(y_train_numeric, y_pred_train_numeric)
            train_mae = mean_absolute_error(y_train_numeric, y_pred_train_numeric)
            
            test_metrics = {
                "r2": float(test_r2),
                "mse": float(test_mse),
                "mae": float(test_mae)
            }
            
            train_metrics = {
                "r2": float(train_r2),
                "mse": float(train_mse),
                "mae": float(train_mae)
            }
        
        check_stop()

        # ==================== PHASE 3 : MODÈLE FINAL SUR TOUTES LES DONNÉES ====================
        logger.info(f"🚀 Phase 3: Préparation du modèle final (final_training_on_all_data={request.final_training_on_all_data})")
        check_stop()
        
        if request.final_training_on_all_data:
            # ✅ RÉUNIR train + test
            X_all = np.vstack([X_train.values, X_test.values])
            y_all = np.concatenate([y_train_encoded, y_test_encoded])
            
            logger.info(f"✅ Fusion train+test: {len(X_train)} + {len(X_test)} = {len(X_all)} échantillons")
            
            # ✅ CRÉER UN NOUVEAU MODÈLE
            if is_classification:
                final_model = RandomForestClassifier(**final_params)
            else:
                final_model = RandomForestRegressor(**final_params)
            
            # ✅ RÉENTRAÎNER SUR TOUTES LES DONNÉES
            final_model.fit(X_all, y_all)
            check_stop()
            
            logger.info(f"✅ Modèle final entraîné sur {len(X_all)} échantillons (train+test)")
            
            training_info = {
                "final_training_data": "train_and_test_combined",
                "all_data_samples": len(X_all),
                "train_samples_used": len(X_train),
                "test_samples_used": len(X_test),
                "final_model_trained_on": "all_available_data",
                "n_repetitions": request.n_repetitions if request.validation_method == "holdout" else None,
                "validation_method": request.validation_method,
                "date_column_excluded": validation_method == "cv_timeseries" or date_column is not None
            }
        else:
            # Garder le modèle entraîné sur train seulement
            final_model = model_on_full_train
            
            logger.info("ℹ️ Modèle final entraîné sur train seulement (option désactivée)")
            
            training_info = {
                "final_training_data": "train_only",
                "all_data_samples": len(X_train),
                "train_samples_used": len(X_train),
                "test_samples_used": 0,
                "final_model_trained_on": "train_data_only",
                "n_repetitions": request.n_repetitions if request.validation_method == "holdout" else None,
                "validation_method": request.validation_method,
                "date_column_excluded": validation_method == "cv_timeseries" or date_column is not None
            }

        # ==================== CALCUL OOB SCORE ====================
        oob_score_value = None
        if request.oob_score and request.bootstrap:
            try:
                if hasattr(final_model, 'oob_score_'):
                    oob_score_value = float(final_model.oob_score_)
            except Exception as e:
                logger.warning(f"Could not calculate OOB score: {str(e)}")
                oob_score_value = None
        
        check_stop()

        # ==================== CALCUL DES MÉTRIQUES FINALES ====================
        # Charts/metrics use Phase-2 train-only model (honest test predictions).
        # final_model is only for saving (may be train+test if Phase 3 enabled).
        y_final_pred_test = y_pred_test
        y_final_pred_train = y_pred_train
        y_final_proba_test = None
        if is_classification and hasattr(model_on_full_train, "predict_proba"):
            try:
                y_final_proba_test = model_on_full_train.predict_proba(X_test.values)
            except Exception as e:
                logger.warning(f"RF predict_proba failed: {e}")
                y_final_proba_test = None
        
        # Feature importance from saved final_model (production model)
        feature_names = X_train.columns.tolist() if hasattr(X_train, 'columns') else feature_columns
        feature_importance = dict(zip(
            feature_names,
            final_model.feature_importances_
        ))

        # ==================== STRUCTURE DES MÉTRIQUES ====================
        metrics = {
            "model_type": "random_forest",
            "is_classification": is_classification,
            "target_analysis": target_analysis,
            
            "feature_importance": convert_numpy_types(feature_importance),
            "features_used": feature_names,
            
            "tree_metadata": {
                "n_trees": len(final_model.estimators_),
                "avg_depth": float(np.mean([tree.tree_.max_depth for tree in final_model.estimators_])),
                "avg_leaves": float(np.mean([tree.tree_.n_leaves for tree in final_model.estimators_])),
                "oob_score": oob_score_value,
                "max_features_used": str(final_params['max_features']),
                "bootstrap_used": request.bootstrap,
                "oob_score_requested": request.oob_score,
            },
            
            "final_params_used": convert_numpy_types(final_params),
            "validation_results": convert_numpy_types(validation_results),
            "user_parameters_used": True,
            "random_search": convert_numpy_types(random_search_meta) if random_search_meta else None,
            
            "predictions": pack_predictions_for_response(
                y_test_encoded,
                y_final_pred_test,
                y_proba=y_final_proba_test,
                y_train_true=y_train_encoded,
                y_train_pred=y_final_pred_train,
            ),
            
            # Informations sur le processus
            "training_process": {
                "phase_1_validation": {
                    "method": request.validation_method,
                    "n_repetitions": request.n_repetitions if request.validation_method == "holdout" else None,
                    "mean_score": validation_results.get('mean_score') if validation_results else None,
                    "best_score": validation_results.get('best_score') if validation_results else None,
                    "date_column_excluded": validation_method == "cv_timeseries" or date_column is not None
                },
                "phase_2_train_evaluation": {
                    "train_metrics": train_metrics,
                    "test_metrics": test_metrics
                },
                "phase_3_final_model": {
                    "trained_on_all_data": request.final_training_on_all_data,
                    "total_samples": len(X_all) if request.final_training_on_all_data else len(X_train)
                }
            }
        }

        # Ajout des métriques spécifiques
        if is_classification:
            metrics.update({
                "accuracy": float(test_accuracy),
                "precision": float(test_precision),
                "recall": float(test_recall),
                "f1": float(test_f1),
                "train_accuracy": float(train_accuracy),
                "confusion_matrix": confusion_matrix_dict,
                "classification_report": classification_rep,
                "classes": [str(c) for c in class_names],
                "n_classes": len(class_names),
                
                "final_test": {
                    "accuracy": float(test_accuracy),
                    "precision": float(test_precision),
                    "recall": float(test_recall),
                    "f1": float(test_f1)
                },
                "final_train": {
                    "accuracy": float(train_accuracy)
                }
            })
        else:
            metrics.update({
                "r2": float(test_r2),
                "mse": float(test_mse),
                "mae": float(test_mae),
                "train_r2": float(train_r2),
                "train_mse": float(train_mse), 
                "train_mae": float(train_mae),
                
                "final_test": {
                    "r2": float(test_r2),
                    "mse": float(test_mse),
                    "mae": float(test_mae)
                },
                "final_train": {
                    "r2": float(train_r2),
                    "mse": float(train_mse),
                    "mae": float(train_mae),
                },
                "errors": {
                    "absolute": (y_test_numeric - y_pred_test_numeric).tolist(),
                    "relative": ((y_test_numeric - y_pred_test_numeric) / (y_test_numeric + 1e-10)).tolist()
                }
            })

        check_stop()

        # ==================== SÉRIALISATION DU MODÈLE FINAL ====================
        try:
            model_bytes = io.BytesIO()
            joblib.dump(final_model, model_bytes)
            model_bytes.seek(0)
            model_base64 = base64.b64encode(model_bytes.read()).decode('utf-8')
            logger.info("✅ Modèle final sérialisé avec succès")
        except Exception as e:
            logger.error(f"Erreur lors de la sérialisation du modèle: {str(e)}")
            model_base64 = None

        check_stop()

        # ==================== RÉPONSE ====================
        response_data = {
            "status": "success",
            "model_type": "random_forest",
            "model_object": model_base64,
            "dataset_used": request.numerized_dataset_name,
            "metrics": convert_numpy_types(metrics),
            "random_search": convert_numpy_types(random_search_meta) if random_search_meta else None,
            "timestamp": datetime.now().isoformat(),
            "validation_method": request.validation_method,
            "user_parameters_used": True,
            "training_info": {
                **training_info,
                "n_repetitions": request.n_repetitions if request.validation_method == "holdout" else None,
                "final_training_on_all_data": request.final_training_on_all_data,
                "training_samples": len(X_train),
                "test_samples": len(X_test),
                "final_model_samples": len(X_all) if request.final_training_on_all_data else len(X_train)
            }
        }

        logger.info("🎉 Entraînement terminé avec succès!")
        return response_data
        
    except HTTPException as he:
        # ✅ Propager l'exception d'arrêt utilisateur
        if he.detail == "Training stopped by user":
            logger.info(f"🛑 Random Forest training {training_id} stopped by user")
        raise
    except Exception as e:
        logger.error(f"Erreur dans train_random_forest: {str(e)}", exc_info=True)
        raise HTTPException(
            status_code=500,
            detail={
                "error_message": str(e),
                "error_type": type(e).__name__,
            }
        )
@router.post("/train-random-forest")
async def train_random_forest(
    request: TrainRandomForestRequest,
    background_tasks: BackgroundTasks = None,
    current_user_id: str = Depends(get_current_user2)
):  
    # ========== 1. MODE ASYNCHRONE (BACKGROUND) - AVEC ARRÊT RÉEL ==========
    if hasattr(request, 'training_id') and request.training_id and background_tasks is not None:
        training_id = request.training_id
        
        # ✅ CRITIQUE: Initialiser le flag d'arrêt
        training_stop_flags[training_id] = False
        
        def train_in_background():
            import asyncio
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)
            
            try:
                # Créer une nouvelle requête SANS training_id pour éviter la boucle
                new_request = request.copy()
                new_request.training_id = None
        
                # ✅ CRITIQUE: Exécuter l'entraînement avec vérification d'arrêt
                result = loop.run_until_complete(
                    train_random_forest_with_stop_check(new_request, None, current_user_id, training_id)
                )
        
                # ✅ Marquer comme complété SEULEMENT si pas arrêté par l'utilisateur
                if training_id in active_trainings and not training_stop_flags.get(training_id, False):
                    active_trainings[training_id]['completed'] = True
                    active_trainings[training_id]['result'] = result
                    _safe_set_training_result(training_id, result)
                    logger.info(f"✅ Random Forest training {training_id} completed successfully")
                
            except Exception as e:
                # ✅ Gestion spéciale pour l'arrêt utilisateur
                error_msg = str(e)
                if "Training stopped by user" in error_msg:
                    logger.info(f"🛑 Random Forest training {training_id} was stopped by user")
                    if training_id in active_trainings:
                        active_trainings[training_id]['completed'] = True
                        active_trainings[training_id]['error'] = "Training stopped by user"
                        active_trainings[training_id]['result'] = None
                        _safe_set_training_error(training_id, 'Training stopped by user', stopped=True)
                else:
                    logger.error(f"❌ Erreur dans train_random_forest background: {error_msg}")
                    if training_id in active_trainings:
                        error_result = {
                            "status": "error",
                            "error_message": error_msg,
                            "error_type": type(e).__name__
                        }
                        active_trainings[training_id]['completed'] = True
                        active_trainings[training_id]['result'] = error_result
                        active_trainings[training_id]['error'] = error_msg
                        _safe_set_training_error(training_id, error_msg, stopped=False)
            finally:
                # ✅ Nettoyer le flag d'arrêt
                if training_id in training_stop_flags:
                    del training_stop_flags[training_id]
                loop.close()
        
        # Créer un Future pour suivre l'exécution
        from concurrent.futures import Future
        future = Future()
        
        # ✅ Initialiser avec completed=False et tous les champs
        active_trainings[training_id] = {
            'future': future,
            'user_id': current_user_id,
            'start_time': datetime.now(),
            'model_type': 'random_forest',
            'completed': False,
            'result': None,
            'error': None,
            'retrieved': False
        }
        
        # Lancer en arrière-plan
        background_tasks.add_task(train_in_background)
        
        # ✅ RETOURNER IMMÉDIATEMENT
        return {
            "status": "training_started",
            "training_id": training_id,
            "message": "Random Forest training started in background"
        }
    
    # ========== 2. MODE SYNCHRONE (EXÉCUTION NORMALE) ==========
    return await train_random_forest_with_stop_check(request, background_tasks, current_user_id, None)

