"""@@@@@@@@@@@@@@@@@@@@LightGBM@@@@@@@@@@@@@@@@@@@@@@@@"""


logger = logging.getLogger(__name__)

# ========== CLASSE DE REQUÊTE ==========
class TrainLightGBMRequest(BaseModel):
    numerized_dataset_name: str
    original_dataset_name: str
    model_type: Literal["lightgbm"] = "lightgbm"
    objective: Optional[str] = Field(None)
    boosting_type: str = Field("gbdt", pattern="^(gbdt|dart|goss)$")
    num_leaves: int = Field(31, gt=1)
    learning_rate: float = Field(0.1, gt=0)
    n_estimators: int = Field(100, gt=0)
    max_depth: int = Field(-1)
    min_child_samples: int = Field(20, ge=0)
    subsample: float = Field(1.0, gt=0, le=1)
    colsample_bytree: float = Field(1.0, gt=0, le=1)
    reg_alpha: float = Field(0.0, ge=0)
    reg_lambda: float = Field(0.0, ge=0)
    random_state: Optional[int] = 42
    n_jobs: int = Field(-1, description="Number of CPU cores to use")
    early_stopping_rounds: Optional[int] = Field(10, gt=0)
    verbose: int = Field(-1)
    validation_method: Optional[str] = "holdout"
    n_repetitions: int = Field(
        default=10, 
        gt=0, 
        le=50, 
        description="Number of repetitions for Hold-Out validation"
    )
    
    # ✅ AJOUT : Paramètre manquant
    final_training_on_all_data: bool = Field(
        default=False,
        description="If True, retrain final model on train+test combined (not for objective evaluation)"
    )
    
    cv_params: Optional[Dict[str, Any]] = None
    bootstrap_params: Optional[Dict[str, Any]] = None
    
    # ✅ PARAMÈTRES TIMESERIES
    time_series_column: Optional[str] = Field(
        default=None,
        description="Column name containing dates for time series split"
    )
    time_series_params: Optional[Dict[str, Any]] = Field(
        default=None,
        description="Parameters for time series split: n_splits, test_size, gap"
    )
    
    training_id: Optional[str] = None
    random_search: bool = False
    n_trials: Optional[int] = Field(default=20, ge=1, le=50)
    random_search_seed: Optional[int] = 42

# ========== FONCTIONS UTILITAIRES ==========
def convert_numpy_types(obj):
    """Convertit les types numpy en types Python natifs"""
    if isinstance(obj, (np.integer, np.int32, np.int64)):
        return int(obj)
    elif isinstance(obj, (np.floating, np.float32, np.float64)):
        return float(obj)
    elif isinstance(obj, np.ndarray):
        return obj.tolist()
    elif isinstance(obj, np.bool_):
        return bool(obj)
    elif isinstance(obj, dict):
        return {key: convert_numpy_types(value) for key, value in obj.items()}
    elif isinstance(obj, list):
        return [convert_numpy_types(item) for item in obj]
    elif isinstance(obj, tuple):
        return tuple(convert_numpy_types(item) for item in obj)
    else:
        return obj

def get_table_columns(cursor, table_name):
    """Récupère toutes les colonnes d'une table"""
    cursor.execute("""
        SELECT column_name 
        FROM information_schema.columns 
        WHERE table_name = %s 
        ORDER BY ordinal_position
    """, (table_name.lower(),))
    return [row[0] for row in cursor.fetchall()]

def calculate_lightgbm_feature_importance(model, feature_names):
    """Calcule l'importance des features pour LightGBM"""
    try:
        importance = model.feature_importances_
        feature_importance = dict(zip(feature_names, importance))
        
        # Normalisation
        total_importance = sum(feature_importance.values())
        if total_importance > 0:
            for feature_name in feature_importance:
                feature_importance[feature_name] = feature_importance[feature_name] / total_importance
        
        return feature_importance
    except Exception as e:
        logger.error(f"Error calculating LightGBM feature importance: {str(e)}")
        return {name: 0.0 for name in feature_names}

# ========== FONCTION DE PRÉPARATION DES DONNÉES ==========
def prepare_data_for_lightgbm(df, target_column, date_column=None, validation_method=None):
    """
    Prépare les données pour LightGBM en excluant correctement la colonne date
    des features si elle n'est pas utilisée pour TimeSeriesSplit
    """
    logger.info("🔧 PREPARATION DES DONNEES POUR LIGHTGBM")
    
    # Créer une copie pour éviter de modifier l'original
    df_processed = df.copy()
    
    # Identifier les colonnes à exclure de l'entraînement
    exclude_columns = [target_column, 'split_type']
    
    if date_column:
        exclude_columns.append(date_column)
        if validation_method == "cv_timeseries":
            logger.info(f"📅 Colonne date '{date_column}' utilisée UNIQUEMENT pour split temporel -> EXCLUE des features")
        else:
            logger.info(f"🚫 Colonne date '{date_column}' -> EXCLUE des features (non TimeSeries)")
    
    # Colonnes features (tout sauf les exclues) + auto-exclude other date-like cols
    feature_columns = [col for col in df_processed.columns if col not in exclude_columns]
    feature_columns = exclude_date_columns_from_list(
        df_processed, feature_columns, date_column=date_column, target_column=target_column
    )
    logger.info(f"📊 Features utilisées pour l'entraînement: {feature_columns}")
    logger.info(f"🚫 Colonnes exclues: {exclude_columns}")
    
    # Séparer les données selon split_type
    train_mask = df_processed['split_type'] == 'train'
    test_mask = df_processed['split_type'] == 'test'
    
    df_train = df_processed[train_mask].copy()
    df_test = df_processed[test_mask].copy()
    
    logger.info(f"📊 Train: {len(df_train)} samples, Test: {len(df_test)} samples")
    
    # Extraire X et y pour train/test
    X_train_raw = df_train[feature_columns].copy()
    y_train_raw = df_train[target_column].copy()
    X_test_raw = df_test[feature_columns].copy()
    y_test_raw = df_test[target_column].copy()
    
    # ✅ Conversion numérique ROBUSTE avec gestion des erreurs
    for df_part, name in [(X_train_raw, "X_train"), (X_test_raw, "X_test")]:
        for col in df_part.columns:
            try:
                df_part.loc[:, col] = pd.to_numeric(df_part[col], errors='coerce')
                nan_count = df_part[col].isna().sum()
                if nan_count > 0:
                    logger.warning(f"⚠️ {name}: {nan_count} NaN dans {col} après conversion")
            except Exception as e:
                logger.error(f"❌ Erreur conversion {col}: {e}")
                df_part.loc[:, col] = 0.0
    
    # ✅ Remplir les NaN avec la médiane (calculée SUR LE TRAIN UNIQUEMENT)
    train_medians = X_train_raw.median(numeric_only=True)
    
    X_train = X_train_raw.fillna(train_medians)
    X_test = X_test_raw.fillna(train_medians)
    
    # ✅ Vérification finale des NaN
    if X_train.isna().any().any():
        X_train = X_train.fillna(0)
    if X_test.isna().any().any():
        X_test = X_test.fillna(0)
    
    # ✅ Traitement de la target
    y_train = pd.to_numeric(y_train_raw, errors='coerce').fillna(0).values
    y_test = pd.to_numeric(y_test_raw, errors='coerce').fillna(0).values
    
    # ✅ Récupérer la colonne date pour TimeSeriesSplit si nécessaire
    date_series = None
    if date_column and validation_method == "cv_timeseries":
        date_series = train_aligned_date_series(df_train, date_column)
        logger.info(f"📅 Colonne date récupérée pour TimeSeriesSplit: {date_column}")
    
    logger.info(f"✅ Préparation terminée: X_train shape {X_train.shape}, X_test shape {X_test.shape}")
    
    return X_train, X_test, y_train, y_test, feature_columns, date_series

def lightgbm_holdout_repeated_with_models(X, y, n_repetitions, test_size, model_params, is_classification):
    """Hold-Out répété avec sauvegarde des modèles"""
    holdout_scores = []
    holdout_models = []
    repetition_details = []

    def _ctor(params):
        clean = {k: v for k, v in params.items() if v is not None and k != 'early_stopping_rounds'}
        clean['n_estimators'] = max(1, int(clean.get('n_estimators') or 100))
        return clean
    
    for i in range(n_repetitions):
        X_ho_train, X_ho_val, y_ho_train, y_ho_val = train_test_split(
            X, y, 
            test_size=test_size, 
            random_state=None,
            stratify=y if is_classification else None
        )
        
        if is_classification:
            model_ho = lgb.LGBMClassifier(**_ctor(model_params))
        else:
            model_ho = lgb.LGBMRegressor(**_ctor(model_params))
        
        early_stopping = model_params.get('early_stopping_rounds', 10)
        if early_stopping and early_stopping > 0:
            eval_set = [(X_ho_val, y_ho_val)]
            objective = model_params.get('objective', 'auto')
            
            if objective == 'binary':
                eval_metric = 'binary_logloss'
            elif objective == 'multiclass':
                eval_metric = 'multi_logloss'
            else:
                eval_metric = 'l2'
            
            model_ho.fit(
                X_ho_train, y_ho_train,
                eval_set=eval_set,
                eval_metric=eval_metric,
                callbacks=[lgb.early_stopping(early_stopping)]
            )
        else:
            model_ho.fit(X_ho_train, y_ho_train)
        
        score = model_ho.score(X_ho_val, y_ho_val)
        train_score = model_ho.score(X_ho_train, y_ho_train)
        
        holdout_scores.append(score)
        holdout_models.append(model_ho)
        
        repetition_details.append({
            'repetition': i + 1,
            'score': float(score),
            'train_score': float(train_score),
            'train_size': len(X_ho_train),
            'validation_size': len(X_ho_val),
            'test_size_percent': test_size * 100,
            'best_iteration': model_ho.best_iteration_ if hasattr(model_ho, 'best_iteration_') else model_params.get('n_estimators', 100)
        })
    
    return holdout_scores, holdout_models, repetition_details

def lightgbm_cv_with_models(X, y, cv, model_params, is_classification):
    """Validation croisée qui sauvegarde les modèles"""
    cv_scores = []
    cv_models = []
    fold_details = []

    def _ctor(params):
        clean = {k: v for k, v in params.items() if v is not None and k != 'early_stopping_rounds'}
        clean['n_estimators'] = max(1, int(clean.get('n_estimators') or 100))
        return clean
    
    for fold_idx, (train_idx, val_idx) in enumerate(cv.split(X, y)):
        X_cv_train, X_cv_val = X[train_idx], X[val_idx]
        y_cv_train, y_cv_val = y[train_idx], y[val_idx]
        
        if is_classification:
            fold_model = lgb.LGBMClassifier(**_ctor(model_params))
        else:
            fold_model = lgb.LGBMRegressor(**_ctor(model_params))
        
        early_stopping = model_params.get('early_stopping_rounds', 10)
        if early_stopping and early_stopping > 0:
            eval_set = [(X_cv_val, y_cv_val)]
            objective = model_params.get('objective', 'auto')
            
            if objective == 'binary':
                eval_metric = 'binary_logloss'
            elif objective == 'multiclass':
                eval_metric = 'multi_logloss'
            else:
                eval_metric = 'l2'
            
            fold_model.fit(
                X_cv_train, y_cv_train,
                eval_set=eval_set,
                eval_metric=eval_metric,
                callbacks=[lgb.early_stopping(early_stopping)]
            )
        else:
            fold_model.fit(X_cv_train, y_cv_train)
        
        train_score = fold_model.score(X_cv_train, y_cv_train)
        val_score = fold_model.score(X_cv_val, y_cv_val)
        
        cv_scores.append(val_score)
        cv_models.append(fold_model)
        
        fold_details.append({
            'fold': fold_idx + 1,
            'train_score': float(train_score),
            'validation_score': float(val_score),
            'train_size': len(X_cv_train),
            'validation_size': len(X_cv_val),
            'best_iteration': fold_model.best_iteration_ if hasattr(fold_model, 'best_iteration_') else model_params.get('n_estimators', 100)
        })
    
    return cv_scores, cv_models, fold_details

def lightgbm_bootstrap_with_models(X, y, n_bootstraps, test_size, model_params, is_classification):
    """VRAI Bootstrap (avec remise) qui sauvegarde les modèles"""
    bootstrap_scores = []
    bootstrap_models = []
    bootstrap_details = []

    def _ctor(params):
        clean = {k: v for k, v in params.items() if v is not None and k != 'early_stopping_rounds'}
        clean['n_estimators'] = max(1, int(clean.get('n_estimators') or 100))
        return clean
    
    n_samples = len(X)
    test_n_samples = int(n_samples * test_size)
    
    for i in range(n_bootstraps):
        bootstrap_indices = np.random.choice(n_samples, size=n_samples, replace=True)
        
        all_indices = set(range(n_samples))
        bootstrap_set = set(bootstrap_indices)
        val_indices = list(all_indices - bootstrap_set)
        
        if len(val_indices) < test_n_samples:
            val_indices = np.random.choice(n_samples, size=test_n_samples, replace=False)
        
        X_train_bs = X[bootstrap_indices]
        y_train_bs = y[bootstrap_indices]
        X_val_bs = X[val_indices]
        y_val_bs = y[val_indices]
        
        if is_classification:
            model_bs = lgb.LGBMClassifier(**_ctor(model_params))
        else:
            model_bs = lgb.LGBMRegressor(**_ctor(model_params))
        
        early_stopping = model_params.get('early_stopping_rounds', 10)
        if early_stopping and early_stopping > 0:
            eval_set = [(X_val_bs, y_val_bs)]
            objective = model_params.get('objective', 'auto')
            
            if objective == 'binary':
                eval_metric = 'binary_logloss'
            elif objective == 'multiclass':
                eval_metric = 'multi_logloss'
            else:
                eval_metric = 'l2'
            
            model_bs.fit(
                X_train_bs, y_train_bs,
                eval_set=eval_set,
                eval_metric=eval_metric,
                callbacks=[lgb.early_stopping(early_stopping)]
            )
        else:
            model_bs.fit(X_train_bs, y_train_bs)
        
        val_score = model_bs.score(X_val_bs, y_val_bs)
        train_score = model_bs.score(X_train_bs, y_train_bs)
        
        bootstrap_scores.append(val_score)
        bootstrap_models.append(model_bs)
        
        unique_samples = len(set(bootstrap_indices))
        duplicate_count = n_samples - unique_samples
        
        bootstrap_details.append({
            'bootstrap': i + 1,
            'score': float(val_score),
            'train_score': float(train_score),
            'train_size': len(X_train_bs),
            'validation_size': len(X_val_bs),
            'unique_samples_in_bootstrap': unique_samples,
            'duplicate_samples': duplicate_count,
            'best_iteration': model_bs.best_iteration_ if hasattr(model_bs, 'best_iteration_') else model_params.get('n_estimators', 100)
        })
    
    if not bootstrap_scores:
        if is_classification:
            model_bs = lgb.LGBMClassifier(**_ctor(model_params))
        else:
            model_bs = lgb.LGBMRegressor(**_ctor(model_params))
        
        model_bs.fit(X, y)
        train_score = model_bs.score(X, y)
        
        bootstrap_scores = [train_score]
        bootstrap_models = [model_bs]
        bootstrap_details = [{
            'bootstrap': 1,
            'score': float(train_score),
            'train_score': float(train_score),
            'train_size': len(X),
            'validation_size': 0,
            'unique_samples_in_bootstrap': len(X),
            'duplicate_samples': 0,
            'note': 'Fallback - trained on all data'
        }]
    
    return bootstrap_scores, bootstrap_models, bootstrap_details

def lightgbm_timeseries_optimization(
    X, y, date_series, n_splits, test_size, gap,
    base_params, is_classification, feature_columns,
    training_id=None, training_stop_flags=None
):
    """
    Optimisation LightGBM avec TimeSeriesSplit
    La colonne date est utilisée UNIQUEMENT pour l'ordre chronologique
    Retourne: (fold_results, fold_models, val_scores)
    """
    logger.info("=" * 80)
    logger.info("🕒 TIMESERIES SPLIT OPTIMIZATION FOR LIGHTGBM")
    logger.info("=" * 80)
    
    n_samples = len(X)
    logger.info(f"📊 Nombre total d'échantillons: {n_samples}")
    
    # Vérifier la longueur de date_series
    if len(date_series) != n_samples:
        logger.warning(f"⚠️ Longueur de date_series ({len(date_series)}) != n_samples ({n_samples})")
        if len(date_series) > n_samples:
            date_series = date_series.iloc[:n_samples]
        else:
            date_series = pd.Series(range(n_samples), index=range(n_samples))
    
    # ✅ CRITIQUE: Créer DataFrame avec les features et la date pour le tri chronologique
    if isinstance(X, pd.DataFrame):
        temp_df = X.copy()
        X_values = X.values
    else:
        temp_df = pd.DataFrame(X, columns=feature_columns)
        X_values = X
    
    temp_df['target'] = y
    temp_df['date'] = date_series.values if hasattr(date_series, 'values') else date_series
    temp_df['original_index'] = range(n_samples)
    
    # ✅ Trier par date pour garantir l'ordre chronologique
    temp_df_sorted = temp_df.sort_values('date').reset_index(drop=True)
    
    # Extraire les données triées
    X_sorted = temp_df_sorted[feature_columns].values
    y_sorted = temp_df_sorted['target'].values
    
    logger.info(f"✅ X_sorted shape: {X_sorted.shape}, y_sorted shape: {y_sorted.shape}")
    
    # Calculer test_size en échantillons
    if isinstance(test_size, float) and test_size < 1:
        test_size_samples = max(1, int(n_samples * test_size))
    else:
        test_size_samples = max(1, int(test_size))
    
    logger.info(f"📊 test_size: {test_size} → {test_size_samples} échantillons")
    
    # Ajuster n_splits si nécessaire
    min_samples_needed = (n_splits + 1) * test_size_samples
    if min_samples_needed > n_samples:
        max_possible_splits = max(2, n_samples // test_size_samples - 1)
        n_splits = min(n_splits, max_possible_splits)
        logger.info(f"✅ n_splits ajusté à {n_splits}")
    
    # Créer le splitter
    tscv = TimeSeriesSplit(n_splits=n_splits, test_size=test_size_samples, gap=gap)
    
    fold_results = []
    fold_models = []
    val_scores = []
    
    fold_count = 0
    for fold_idx, (train_idx, val_idx) in enumerate(tscv.split(X_sorted)):
        fold_count += 1
        
        # Vérifier stop flag
        if training_id and training_stop_flags and training_stop_flags.get(training_id, False):
            logger.info(f"🛑 Stop signal détecté, arrêt après {fold_count} folds")
            break
        
        # Vérifier les index
        if max(train_idx) >= n_samples or max(val_idx) >= n_samples:
            logger.error(f"❌ Index hors limites: train max={max(train_idx)}, val max={max(val_idx)}")
            continue
        
        logger.info(f"🔍 Fold {fold_count}/{n_splits}")
        logger.info(f"   Train indices: {train_idx[0]} → {train_idx[-1]} (taille: {len(train_idx)})")
        logger.info(f"   Val indices:   {val_idx[0]} → {val_idx[-1]} (taille: {len(val_idx)})")
        
        # Extraire les données
        X_train_fold = X_sorted[train_idx]
        X_val_fold = X_sorted[val_idx]
        y_train_fold = y_sorted[train_idx]
        y_val_fold = y_sorted[val_idx]
        
        if len(X_train_fold) < 5 or len(X_val_fold) < 1:
            logger.warning(f"   ⚠️ Pas assez de données, skip")
            continue
        
        try:
            # Créer et entraîner le modèle LightGBM
            clean_params = {
                k: v for k, v in base_params.items()
                if v is not None and k != 'early_stopping_rounds'
            }
            clean_params['n_estimators'] = max(1, int(clean_params.get('n_estimators') or 100))
            if is_classification:
                model = lgb.LGBMClassifier(**clean_params)
            else:
                model = lgb.LGBMRegressor(**clean_params)
            
            # Early stopping pour chaque fold
            early_stopping = base_params.get('early_stopping_rounds', 10)
            if early_stopping and early_stopping > 0:
                eval_set = [(X_val_fold, y_val_fold)]
                objective = base_params.get('objective', 'auto')
                
                if objective == 'binary':
                    eval_metric = 'binary_logloss'
                elif objective == 'multiclass':
                    eval_metric = 'multi_logloss'
                else:
                    eval_metric = 'l2'
                
                model.fit(
                    X_train_fold, y_train_fold,
                    eval_set=eval_set,
                    eval_metric=eval_metric,
                    callbacks=[lgb.early_stopping(early_stopping)]
                )
            else:
                model.fit(X_train_fold, y_train_fold)
            
            # Évaluer
            train_score = model.score(X_train_fold, y_train_fold)
            val_score = model.score(X_val_fold, y_val_fold)
            
            logger.info(f"   ✅ Train score: {train_score:.4f}, Val score: {val_score:.4f}")
            
            fold_models.append(model)
            val_scores.append(val_score)
            
            fold_results.append({
                'fold': fold_count,
                'train_size': len(X_train_fold),
                'val_size': len(X_val_fold),
                'train_score': float(train_score),
                'val_score': float(val_score),
                'best_iteration': model.best_iteration_ if hasattr(model, 'best_iteration_') else base_params.get('n_estimators', 100),
                'train_indices': [int(train_idx[0]), int(train_idx[-1])],
                'val_indices': [int(val_idx[0]), int(val_idx[-1])]
            })
            
        except Exception as e:
            logger.error(f"❌ Erreur sur fold {fold_count}: {e}")
            continue
    
    if not fold_results:
        logger.error("❌ Aucun fold valide pour TimeSeriesSplit")
        return [], [], []
    
    logger.info("=" * 80)
    logger.info("📊 RÉSULTATS TIMESERIES SPLIT")
    logger.info(f"   Folds valides: {len(fold_results)}/{n_splits}")
    logger.info(f"   Score moyen validation: {np.mean(val_scores):.4f} ± {np.std(val_scores):.4f}")
    logger.info("=" * 80)
    
    return fold_results, fold_models, val_scores

async def train_lightgbm_with_stop_check(
    request: TrainLightGBMRequest,
    background_tasks: BackgroundTasks = None,
    current_user_id: str = None,
    training_id: str = None
):
    """Version de train_lightgbm avec vérification d'arrêt à chaque étape"""
    
    # ✅ Fonction de vérification d'arrêt
    def check_stop():
        if training_id and training_stop_flags.get(training_id, False):
            logger.info(f"🛑 LightGBM training {training_id} stopped by user (check_stop triggered)")
            raise HTTPException(400, "Training stopped by user")
    
    try:
        logger.info("=== LIGHTGBM TRAINING STARTED ===")
        if training_id:
            logger.info(f"🎫 Training ID: {training_id}")
        logger.info(f"📋 Request validation method: {request.validation_method}")
        logger.info(f"📊 Number of repetitions: {request.n_repetitions}")
        logger.info(f"⚙️ Parameters: boosting={request.boosting_type}, n_estimators={request.n_estimators}, learning_rate={request.learning_rate}")

        # ==================== VÉRIFICATION D'ARRÊT ====================
        check_stop()

        # ==================== INITIAL VALIDATION ====================
        if not request.numerized_dataset_name or not request.original_dataset_name:
            raise HTTPException(400, "Dataset names are required")
        
        check_stop()

        # ==================== DATA LOADING ====================
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Check permissions and get target column
                cur.execute("""
                    SELECT target_column 
                    FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (request.original_dataset_name.lower(), current_user_id))
                
                target_info = cur.fetchone()
                if not target_info or not target_info[0]:
                    raise HTTPException(400, "Target column not defined in original dataset")
                
                target_column = target_info[0]
                check_stop()

                # Verify numerized table exists
                cur.execute("""
                    SELECT 1 FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (request.numerized_dataset_name.lower(), current_user_id))
                
                if not cur.fetchone():
                    raise HTTPException(404, "Numerized dataset not found or access denied")
                
                check_stop()

                # Get available columns
                all_columns = get_table_columns(cur, request.numerized_dataset_name)
                if not all_columns:
                    raise HTTPException(404, "No columns found")
                
                check_stop()

                # Build SQL query
                select_columns = [
                    sql.Identifier(col) 
                    for col in all_columns 
                    if col not in ['id', 'split_type']
                ]

                query = sql.SQL("""
                    SELECT {columns}, split_type FROM {table}
                    WHERE split_type IS NOT NULL
                """).format(
                    columns=sql.SQL(',').join(select_columns),
                    table=sql.Identifier(request.numerized_dataset_name.lower())
                )

                cur.execute(query)
                rows = cur.fetchall()
                check_stop()

        # ==================== DATA PREPARATION ====================
        df_columns = [col for col in all_columns if col not in ['id', 'split_type']] + ['split_type']
        df = pd.DataFrame(rows, columns=df_columns)
        check_stop()

        df['split_type'] = df['split_type'].astype(str).str.lower().str.strip()
        check_stop()

        valid_splits = {'train', 'test'}
        invalid_splits = set(df['split_type'].unique()) - valid_splits
        if invalid_splits:
            raise HTTPException(
                400, 
                f"Invalid values in split_type: {invalid_splits}. Expected: 'train' or 'test'"
            )

        # ✅ Utiliser la fonction de préparation qui exclut correctement la colonne date
        date_column = resolve_request_date_column(request)
        validation_method = request.validation_method or "holdout"
        
        X_train, X_test, y_train, y_test, feature_columns, date_series = prepare_data_for_lightgbm(
            df, 
            target_column, 
            date_column=date_column,
            validation_method=validation_method
        )

        check_stop()

        # Conversion en arrays numpy
        X_train_np = X_train.values if isinstance(X_train, pd.DataFrame) else X_train
        X_test_np = X_test.values if isinstance(X_test, pd.DataFrame) else X_test
        check_stop()

        # ==================== TARGET PROCESSING ====================
        try:
            pd.to_numeric(y_train, errors='raise')
            target_is_numeric = True
        except (ValueError, TypeError):
            target_is_numeric = False

        unique_values = len(np.unique(y_train))
        total_samples = len(y_train)
        unique_ratio = (unique_values / total_samples) * 100

        # Seuil adaptatif
        if total_samples <= 30:
            threshold = 25.0
        elif total_samples <= 100:
            threshold = 15.0
        else:
            threshold = 5.0

        # Détection du type de problème
        is_classification = unique_ratio <= threshold
        logger.info(f"🎯 Target analysis: {unique_values} unique values ({unique_ratio:.1f}% of {total_samples} samples), treated as {'classification' if is_classification else 'regression'} (threshold: {threshold}%)")
        check_stop()

        # Conversion des cibles
        if is_classification:
            y_train_encoded = y_train.astype(str)
            y_test_encoded = y_test.astype(str)
            
            all_classes = sorted(list(set(y_train_encoded) | set(y_test_encoded)))
            class_to_num = {cls: i for i, cls in enumerate(all_classes)}
            num_to_class = {i: cls for i, cls in enumerate(all_classes)}
            
            y_train_encoded = np.array([class_to_num[cls] for cls in y_train_encoded])
            y_test_encoded = np.array([class_to_num[cls] for cls in y_test_encoded])
            class_names = all_classes
            
            logger.info(f"🏷️ Classification: {len(class_names)} classes")
        else:
            if not target_is_numeric:
                try:
                    y_train_encoded = pd.to_numeric(y_train, errors='raise')
                    y_test_encoded = pd.to_numeric(y_test, errors='raise')
                    target_is_numeric = True
                except ValueError as e:
                    raise HTTPException(400, f"Target column '{target_column}' contains non-numeric values for regression: {str(e)}")

            y_train_encoded = pd.to_numeric(y_train, errors='coerce')
            y_test_encoded = pd.to_numeric(y_test, errors='coerce')
            
            if pd.isna(y_train_encoded).any() or pd.isna(y_test_encoded).any():
                train_median = np.nanmedian(y_train_encoded)
                y_train_encoded = np.nan_to_num(y_train_encoded, nan=train_median)
                y_test_encoded = np.nan_to_num(y_test_encoded, nan=train_median)
            
            class_names = None
            logger.info("📈 Regression problem detected")
        
        check_stop()

        target_analysis = {
            "target_column": target_column,
            "unique_values": int(unique_values),
            "total_samples": total_samples,
            "unique_ratio": float(unique_ratio),
            "is_numeric": target_is_numeric,
            "is_classification": is_classification,
            "threshold_used": threshold,
            "class_names": [str(c) for c in class_names] if class_names else None
        }

        # ==================== RANDOM SEARCH (optional) ====================
        random_search_meta = None
        if getattr(request, "random_search", False):
            from backend.random_search_hp import run_hyperparam_random_search
            X_rs = X_train.values if hasattr(X_train, "values") else np.asarray(X_train)
            y_rs = np.asarray(y_train_encoded).ravel()
            rs_best, random_search_meta = run_hyperparam_random_search(
                "lightgbm",
                X_rs,
                y_rs,
                n_trials=getattr(request, "n_trials", 20),
                is_classification=is_classification,
                check_stop=check_stop,
                active_trainings=active_trainings,
                training_id=training_id,
                fixed_params={"boosting_type": request.boosting_type},
                random_state=int(getattr(request, "random_search_seed", 42) or 42),
            )
            request.num_leaves = int(rs_best["num_leaves"])
            request.learning_rate = float(rs_best["learning_rate"])
            request.n_estimators = int(rs_best["n_estimators"])
            request.max_depth = int(rs_best["max_depth"])
            request.min_child_samples = int(rs_best["min_child_samples"])
            request.subsample = float(rs_best["subsample"])
            request.colsample_bytree = float(rs_best["colsample_bytree"])
            request.reg_alpha = float(rs_best["reg_alpha"])
            request.reg_lambda = float(rs_best["reg_lambda"])
            logger.info(f"🎲 Random Search best LightGBM params: {rs_best}")

        # ==================== CONFIGURATION DU MODÈLE LIGHTGBM ====================
        model_params = {
            'boosting_type': request.boosting_type,
            'num_leaves': request.num_leaves,
            'learning_rate': request.learning_rate,
            'n_estimators': request.n_estimators,
            'max_depth': request.max_depth if request.max_depth > 0 else -1,
            'min_child_samples': request.min_child_samples,
            'subsample': request.subsample,
            'colsample_bytree': request.colsample_bytree,
            'reg_alpha': request.reg_alpha,
            'reg_lambda': request.reg_lambda,
            'random_state': request.random_state,
            'n_jobs': request.n_jobs,
            'verbose': request.verbose
        }

        # Gestion robuste de l'objective
        if is_classification:
            if len(class_names) == 2:
                final_objective = "binary"
            else:
                final_objective = "multiclass"
        else:
            final_objective = "regression"

        if request.objective and request.objective in ["binary", "multiclass", "regression"]:
            final_objective = request.objective
            logger.info(f"🎯 Using user-specified objective: {final_objective}")
        else:
            logger.info(f"🎯 Auto-detected objective: {final_objective}")

        model_params['objective'] = final_objective

        if final_objective == 'multiclass' and class_names:
            model_params['num_class'] = len(class_names)
            logger.info(f"🔢 Setting num_class to {len(class_names)} for multiclass classification")

        if request.early_stopping_rounds and request.early_stopping_rounds > 0:
            model_params['early_stopping_rounds'] = request.early_stopping_rounds
            logger.info(f"🛑 Early stopping after {request.early_stopping_rounds} rounds")
        else:
            model_params.pop('early_stopping_rounds', None)

        # Ensure n_estimators always valid before any fit
        model_params['n_estimators'] = max(1, int(request.n_estimators or 100))

        # Sélection du modèle LightGBM approprié
        if is_classification:
            model_class = lgb.LGBMClassifier
            logger.info(f"🤖 Using LGBMClassifier with objective: {final_objective}")
        else:
            model_class = lgb.LGBMRegressor
            logger.info(f"🤖 Using LGBMRegressor with objective: {final_objective}")
        
        def _lgbm_ctor_params(params):
            """Constructor params: never pass early_stopping_rounds / None values."""
            clean = {
                k: v for k, v in params.items()
                if v is not None and k != 'early_stopping_rounds'
            }
            clean['n_estimators'] = max(1, int(clean.get('n_estimators') or 100))
            return clean
        
        check_stop()

        # ==================== PHASE 1 : VALIDATION ====================
        validation_results = None
        validation_scores = []
        validation_models = []
        best_validation_model_idx = None
        
        logger.info(f"🔍 Starting validation with method: {request.validation_method}")
        
        # ✅ TIMESERIES SPLIT POUR LIGHTGBM
        if request.validation_method == "cv_timeseries":
            logger.info("=" * 80)
            logger.info("⏰ TIMESERIES SPLIT SELECTED FOR LIGHTGBM")
            logger.info("=" * 80)
            
            check_stop()
            
            # Récupérer les paramètres TimeSeries
            time_series_params = getattr(request, 'time_series_params', {})
            n_splits = time_series_params.get('n_splits', 5)
            test_size = time_series_params.get('test_size', 0.2)
            gap = time_series_params.get('gap', 0)
            
            logger.info(f"📊 Paramètres: n_splits={n_splits}, test_size={test_size}, gap={gap}")
            logger.info(f"📅 Colonne date: {date_column if date_column else 'Aucune'}")
            
            if date_series is None:
                raise HTTPException(400, "TimeSeriesSplit requires a date column")
            
            logger.info(f"📊 Features utilisées (SANS date): {feature_columns}")
            logger.info(f"✅ La colonne date est utilisée UNIQUEMENT pour l'ordre chronologique")
            
            # ✅ Utiliser la fonction TimeSeriesSplit pour LightGBM
            timeseries_results, fold_models, val_scores = lightgbm_timeseries_optimization(
                X_train_np, y_train_encoded, date_series,
                n_splits, test_size, gap,
                model_params, is_classification, feature_columns,
                training_id, training_stop_flags
            )
            
            if timeseries_results and fold_models:
                validation_models = fold_models
                validation_scores = val_scores
                
                # Trouver le meilleur fold
                best_validation_model_idx = np.argmax(val_scores)
                
                # Extraire les scores d'entraînement
                train_scores = [fold.get('train_score', 0) for fold in timeseries_results]
                
                # Formater fold_details
                formatted_fold_details = []
                for i, fold in enumerate(timeseries_results):
                    formatted_fold_details.append({
                        'fold': fold.get('fold', i + 1),
                        'train_size': fold.get('train_size', 0),
                        'val_size': fold.get('val_size', 0),
                        'train_score': float(fold.get('train_score', 0)),
                        'val_score': float(fold.get('val_score', 0)),
                        'best_iteration': fold.get('best_iteration', None),
                        'train_indices': fold.get('train_indices', []),
                        'val_indices': fold.get('val_indices', [])
                    })
                
                validation_results = {
                    "method": f"TimeSeries Split ({len(timeseries_results)} valid folds / {n_splits} total)",
                    "fold_details": formatted_fold_details,
                    
                    # Scores moyens (multiples formats pour compatibilité)
                    "mean_score": float(np.mean(val_scores)),
                    "std_score": float(np.std(val_scores)),
                    "cv_validation_r2_mean": float(np.mean(val_scores)),
                    "cv_validation_r2_std": float(np.std(val_scores)),
                    "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0,
                    "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0,
                    
                    # Meilleur fold
                    "best_fold": int(best_validation_model_idx + 1),
                    "best_score": float(val_scores[best_validation_model_idx]),
                    "best_fold_score": float(val_scores[best_validation_model_idx]),
                    "best_iteration_global": validation_scores[best_validation_model_idx],
                    
                    # Paramètres TimeSeries
                    "date_column": date_column,
                    "date_column_excluded": True,
                    "features_used": feature_columns,
                    "n_splits": n_splits,
                    "test_size": test_size,
                    "gap": gap
                }
                
                logger.info(f"🎯 Meilleur fold: {best_validation_model_idx + 1}, Score: {val_scores[best_validation_model_idx]:.4f}")
                logger.info(f"📊 Scores validation: moyenne={np.mean(val_scores):.4f}, écart-type={np.std(val_scores):.4f}")
            else:
                logger.error("❌ Aucun résultat valide pour TimeSeriesSplit")
                raise HTTPException(500, "TimeSeriesSplit failed to produce valid results")
        
        elif request.validation_method == "holdout":
            # ✅ HOLD-OUT RÉPÉTÉ
            test_size = 0.2
            logger.info(f"🔁 Hold-Out répété: {request.n_repetitions} répétitions sur train set")
            
            holdout_scores, holdout_models, repetition_details = lightgbm_holdout_repeated_with_models(
                X_train_np, y_train_encoded, request.n_repetitions, test_size, 
                model_params, is_classification
            )
            
            if len(holdout_scores) > 0:
                best_validation_model_idx = np.argmax(holdout_scores)
                validation_models = holdout_models
                validation_scores = holdout_scores
                
                train_scores = [rep.get('train_score', 0) for rep in repetition_details]
                
                validation_results = {
                    "method": f"Hold-Out Repeated ({request.n_repetitions} repetitions)",
                    "repetition_details": repetition_details,
                    "mean_score": float(np.mean(holdout_scores)),
                    "std_score": float(np.std(holdout_scores)),
                    "cv_validation_r2_mean": float(np.mean(holdout_scores)),
                    "cv_validation_r2_std": float(np.std(holdout_scores)),
                    "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0,
                    "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0,
                    "best_repetition": int(best_validation_model_idx + 1),
                    "best_score": float(holdout_scores[best_validation_model_idx]),
                    "test_size": test_size,
                    "n_repetitions": request.n_repetitions
                }
            
        elif request.validation_method and request.validation_method.startswith('cv_'):
            # ✅ CROSS-VALIDATION
            cv_params = request.cv_params or {}
            n_splits = cv_params.get('n_splits', 5)
            shuffle = cv_params.get('shuffle', True)
            
            if request.validation_method == "cv_kfold":
                cv = KFold(n_splits=n_splits, shuffle=shuffle, random_state=None)
                method_name = "Cross-Validation (KFold)"
            elif request.validation_method == "cv_repeatedkfold":
                n_repeats = cv_params.get('n_repeats', 3)
                cv = RepeatedKFold(n_splits=n_splits, n_repeats=n_repeats, random_state=None)
                method_name = "Cross-Validation (Repeated KFold)"
            elif request.validation_method == "cv_shufflesplit":
                test_size = cv_params.get('test_size', 0.2)
                cv = ShuffleSplit(n_splits=n_splits, test_size=test_size, random_state=None)
                method_name = "Cross-Validation (Shuffle Split)"
            
            logger.info(f"🔁 Cross-Validation: {method_name} sur train set")
            
            cv_scores, cv_models, fold_details = lightgbm_cv_with_models(
                X_train_np, y_train_encoded, cv, model_params, is_classification
            )
            
            if len(cv_scores) > 0:
                best_validation_model_idx = np.argmax(cv_scores)
                validation_models = cv_models
                validation_scores = cv_scores
                
                train_scores = [fold.get('train_score', 0) for fold in fold_details]
                
                validation_results = {
                    "method": method_name,
                    "fold_details": fold_details,
                    "cv_scores": [float(score) for score in cv_scores],
                    "cv_mean": float(np.mean(cv_scores)),
                    "cv_std": float(np.std(cv_scores)),
                    "cv_validation_r2_mean": float(np.mean(cv_scores)),
                    "cv_validation_r2_std": float(np.std(cv_scores)),
                    "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0,
                    "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0,
                    "n_splits": n_splits,
                    "best_fold": int(best_validation_model_idx + 1),
                    "best_score": float(cv_scores[best_validation_model_idx])
                }
                
                if request.validation_method == "cv_repeatedkfold":
                    validation_results["n_repeats"] = n_repeats
                elif request.validation_method == "cv_shufflesplit":
                    validation_results["test_size"] = test_size
        
        elif request.validation_method == "bootstrap":
            # ✅ BOOTSTRAP
            bootstrap_params = request.bootstrap_params or {}
            n_bootstraps = bootstrap_params.get('n_bootstraps', 100)
            test_size = bootstrap_params.get('test_size', 0.2)
            
            logger.info(f"🔁 TRUE Bootstrap: {n_bootstraps} échantillons (avec remise)")
            
            bootstrap_scores, bootstrap_models, bootstrap_details = lightgbm_bootstrap_with_models(
                X_train_np, y_train_encoded, n_bootstraps, test_size, 
                model_params, is_classification
            )
            
            if len(bootstrap_scores) > 0:
                best_validation_model_idx = np.argsort(bootstrap_scores)[len(bootstrap_scores) // 2]
                validation_models = bootstrap_models
                validation_scores = bootstrap_scores
                
                train_scores = [bs.get('train_score', 0) for bs in bootstrap_details]
                
                validation_results = {
                    "method": "Bootstrap Validation",
                    "bootstrap_details": bootstrap_details,
                    "bootstrap_scores": [float(score) for score in bootstrap_scores],
                    "bootstrap_mean": float(np.mean(bootstrap_scores)),
                    "bootstrap_std": float(np.std(bootstrap_scores)),
                    "cv_validation_r2_mean": float(np.mean(bootstrap_scores)),
                    "cv_validation_r2_std": float(np.std(bootstrap_scores)),
                    "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0,
                    "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0,
                    "n_bootstraps": n_bootstraps,
                    "test_size": test_size,
                    "median_bootstrap_index": int(best_validation_model_idx + 1),
                    "median_bootstrap_score": float(bootstrap_scores[best_validation_model_idx])
                }
        
        else:
            # ✅ HOLD-OUT SIMPLE (fallback)
            logger.info("🔁 Hold-Out simple sur train set")
            check_stop()
            
            validation_model = model_class(**model_params)
            
            if request.early_stopping_rounds and request.early_stopping_rounds > 0:
                # Anti-leakage: early-stop on a train-internal holdout, never on global test
                try:
                    stratify = y_train_encoded if is_classification and len(np.unique(y_train_encoded)) > 1 else None
                    X_es_fit, X_es_val, y_es_fit, y_es_val = train_test_split(
                        X_train_np, y_train_encoded, test_size=0.2, random_state=42, stratify=stratify
                    )
                except ValueError:
                    X_es_fit, y_es_fit = X_train_np, y_train_encoded
                    X_es_val, y_es_val = None, None

                if X_es_val is not None:
                    if final_objective == 'binary':
                        eval_metric = 'binary_logloss'
                    elif final_objective == 'multiclass':
                        eval_metric = 'multi_logloss'
                    else:
                        eval_metric = 'l2'
                    
                    validation_model.fit(
                        X_es_fit, y_es_fit,
                        eval_set=[(X_es_val, y_es_val)],
                        eval_metric=eval_metric,
                        callbacks=[lgb.early_stopping(request.early_stopping_rounds)]
                    )
                else:
                    validation_model.fit(X_train_np, y_train_encoded)
            else:
                validation_model.fit(X_train_np, y_train_encoded)
            
            validation_score = validation_model.score(X_train_np, y_train_encoded)
            validation_models = [validation_model]
            validation_scores = [validation_score]
            best_validation_model_idx = 0
            
            validation_results = {
                "method": "Hold-Out Simple",
                "score": float(validation_score),
                "mean_score": float(validation_score),
                "std_score": 0,
                "cv_validation_r2_mean": float(validation_score),
                "cv_validation_r2_std": 0,
                "best_score": float(validation_score),
                "best_iteration": validation_model.best_iteration_ if hasattr(validation_model, 'best_iteration_') else request.n_estimators
            }

        # ==================== VÉRIFICATION QUE LA VALIDATION A RÉUSSI ====================
        if validation_results is None:
            raise HTTPException(500, "Validation failed: no results produced")
        
        check_stop()
        
        # ✅ Sélectionner le meilleur modèle de validation
        if best_validation_model_idx is not None and validation_models:
            best_validation_model = validation_models[best_validation_model_idx]
        else:
            best_validation_model = validation_models[0] if validation_models else None

        # ==================== PHASE 2 : ENTRAÎNEMENT SUR TOUT LE TRAIN ====================
        logger.info("🏋️ Phase 2: Entraînement sur tout le train set")
        
        model_on_full_train = model_class(**_lgbm_ctor_params(model_params))
        
        if request.early_stopping_rounds and request.early_stopping_rounds > 0:
            # Anti-leakage: find best_iteration on train-internal holdout, then refit on full train
            try:
                stratify = y_train_encoded if is_classification and len(np.unique(y_train_encoded)) > 1 else None
                X_es_fit, X_es_val, y_es_fit, y_es_val = train_test_split(
                    X_train_np, y_train_encoded, test_size=0.2, random_state=42, stratify=stratify
                )
            except ValueError:
                X_es_fit, y_es_fit = X_train_np, y_train_encoded
                X_es_val, y_es_val = None, None

            if X_es_val is not None:
                if final_objective == 'binary':
                    eval_metric = 'binary_logloss'
                elif final_objective == 'multiclass':
                    eval_metric = 'multi_logloss'
                else:
                    eval_metric = 'l2'
                
                es_model = model_class(**_lgbm_ctor_params(model_params))
                es_model.fit(
                    X_es_fit, y_es_fit,
                    eval_set=[(X_es_val, y_es_val)],
                    eval_metric=eval_metric,
                    callbacks=[lgb.early_stopping(request.early_stopping_rounds)]
                )
                best_iter = getattr(es_model, "best_iteration_", None)
                # LightGBM can report 0 in edge cases — never allow 0 boosting rounds
                try:
                    best_iter = int(best_iter) if best_iter is not None else int(request.n_estimators)
                except (TypeError, ValueError):
                    best_iter = int(request.n_estimators)
                best_iter = max(1, best_iter)
                refit_params = _lgbm_ctor_params(model_params)
                refit_params["n_estimators"] = best_iter
                model_on_full_train = model_class(**refit_params)
                model_on_full_train.fit(X_train_np, y_train_encoded)
                # Preserve best_iteration_ for Phase 3 / reporting
                try:
                    model_on_full_train.best_iteration_ = best_iter
                except Exception:
                    pass
            else:
                model_on_full_train.fit(X_train_np, y_train_encoded)
        else:
            model_on_full_train.fit(X_train_np, y_train_encoded)
        
        check_stop()
        
        y_pred_test = model_on_full_train.predict(X_test_np)
        check_stop()
        
        # Calculer les métriques sur test
        if is_classification:
            test_accuracy = accuracy_score(y_test_encoded, y_pred_test)
            test_precision = precision_score(y_test_encoded, y_pred_test, average='weighted', zero_division=0)
            test_recall = recall_score(y_test_encoded, y_pred_test, average='weighted', zero_division=0)
            test_f1 = f1_score(y_test_encoded, y_pred_test, average='weighted', zero_division=0)
            
            y_pred_train = model_on_full_train.predict(X_train_np)
            train_accuracy = accuracy_score(y_train_encoded, y_pred_train)
            
            conf_matrix = confusion_matrix(y_test_encoded, y_pred_test)
            
            if len(class_names) == 2:
                tn, fp, fn, tp = conf_matrix.ravel()
                confusion_matrix_dict = {
                    'true_negative': int(tn),
                    'false_positive': int(fp),
                    'false_negative': int(fn),
                    'true_positive': int(tp),
                    'labels': [str(c) for c in class_names]
                }
            else:
                confusion_matrix_dict = {
                    'matrix': conf_matrix.tolist(),
                    'labels': [str(c) for c in class_names]
                }

            classification_rep = classification_report(
                y_test_encoded, y_pred_test, 
                target_names=[str(c) for c in class_names],
                output_dict=True,
                zero_division=0
            )

            roc_auc = None
            if len(class_names) == 2 and hasattr(model_on_full_train, "predict_proba"):
                try:
                    y_proba = model_on_full_train.predict_proba(X_test_np)
                    roc_auc = roc_auc_score(y_test_encoded, y_proba[:, 1])
                except Exception as e:
                    logger.warning(f"Could not compute ROC AUC: {str(e)}")
            
            test_metrics = {
                "accuracy": float(test_accuracy),
                "precision": float(test_precision),
                "recall": float(test_recall),
                "f1": float(test_f1),
                "roc_auc": float(roc_auc) if roc_auc is not None else None
            }
            
            train_metrics = {
                "accuracy": float(train_accuracy)
            }
            
        else:
            y_test_numeric = y_test_encoded.astype(float)
            y_pred_test_numeric = y_pred_test.astype(float)
    
            test_r2 = r2_score(y_test_numeric, y_pred_test_numeric)
            test_mse = mean_squared_error(y_test_numeric, y_pred_test_numeric)
            test_mae = mean_absolute_error(y_test_numeric, y_pred_test_numeric)
    
            y_pred_train = model_on_full_train.predict(X_train_np)
            y_train_numeric = y_train_encoded.astype(float)
            y_pred_train_numeric = y_pred_train.astype(float)
    
            train_r2 = r2_score(y_train_numeric, y_pred_train_numeric)
            train_mse = mean_squared_error(y_train_numeric, y_pred_train_numeric)
            train_mae = mean_absolute_error(y_train_numeric, y_pred_train_numeric)
            
            test_metrics = {
                "r2": float(test_r2),
                "mse": float(test_mse),
                "mae": float(test_mae)
            }
            
            train_metrics = {
                "r2": float(train_r2),
                "mse": float(train_mse),
                "mae": float(train_mae)
            }
        
        check_stop()

        # ==================== PHASE 3 : MODÈLE FINAL ====================
        logger.info(f"🚀 Phase 3: Préparation du modèle final (final_training_on_all_data={request.final_training_on_all_data})")

        if request.final_training_on_all_data:
            X_all = np.vstack([X_train_np, X_test_np])
            y_all = np.concatenate([y_train_encoded, y_test_encoded])
            
            logger.info(f"✅ Fusion train+test: {len(X_train_np)} + {len(X_test_np)} = {len(X_all)} échantillons")
            
            # ✅ CORRECTION : Créer une copie des paramètres sans early_stopping_rounds
            final_model_params = _lgbm_ctor_params(model_params)
            
            if request.early_stopping_rounds and request.early_stopping_rounds > 0:
                logger.info("🛑 Early stopping désactivé pour le modèle final (entraînement sur toutes les données)")
                best_iter = getattr(model_on_full_train, 'best_iteration_', None)
                try:
                    best_iter = int(best_iter) if best_iter is not None else int(request.n_estimators)
                except (TypeError, ValueError):
                    best_iter = int(request.n_estimators)
                best_iter = max(1, best_iter)
                final_model_params['n_estimators'] = best_iter
                logger.info(f"📊 Utilisation de {best_iter} itérations (optimal trouvé)")

            if int(final_model_params.get('n_estimators') or 0) < 1:
                final_model_params['n_estimators'] = max(1, int(request.n_estimators or 100))
            
            final_model = model_class(**final_model_params)
            final_model.fit(X_all, y_all)
            
            logger.info(f"✅ Modèle final entraîné sur {len(X_all)} échantillons (train+test)")
            
            training_info = {
                "final_training_data": "train_and_test_combined",
                "all_data_samples": len(X_all),
                "train_samples_used": len(X_train_np),
                "test_samples_used": len(X_test_np),
                "final_model_trained_on": "all_available_data",
                "n_repetitions": request.n_repetitions if request.validation_method == "holdout" else None,
                "validation_method": request.validation_method,
                "date_column_excluded": validation_method == "cv_timeseries" or date_column is not None,
                "early_stopping_used": request.early_stopping_rounds is not None and request.early_stopping_rounds > 0,
                "best_iteration": final_model.best_iteration_ if hasattr(final_model, 'best_iteration_') else 
                                (model_on_full_train.best_iteration_ if hasattr(model_on_full_train, 'best_iteration_') else request.n_estimators)
            }
        else:
            final_model = model_on_full_train
            
            logger.info("ℹ️ Modèle final entraîné sur train seulement (option désactivée)")
            
            training_info = {
                "final_training_data": "train_only",
                "all_data_samples": len(X_train_np),
                "train_samples_used": len(X_train_np),
                "test_samples_used": 0,
                "final_model_trained_on": "train_data_only",
                "n_repetitions": request.n_repetitions if request.validation_method == "holdout" else None,
                "validation_method": request.validation_method,
                "date_column_excluded": validation_method == "cv_timeseries" or date_column is not None,
                "early_stopping_used": request.early_stopping_rounds is not None and request.early_stopping_rounds > 0,
                "best_iteration": final_model.best_iteration_ if hasattr(final_model, 'best_iteration_') else request.n_estimators
            }
        
        check_stop()

        # ==================== CALCUL DES MÉTRIQUES LIGHTGBM SPÉCIFIQUES ====================
        feature_importance = calculate_lightgbm_feature_importance(final_model, feature_columns)

        # ==================== STRUCTURE DES MÉTRIQUES ====================
        metrics = {
            "model_type": "lightgbm",
            "is_classification": is_classification,
            "model_class": "LGBMClassifier" if is_classification else "LGBMRegressor",
            "target_analysis": target_analysis,
            
            # PARAMÈTRES UTILISÉS
            "objective_used": final_objective,
            "boosting_type_used": request.boosting_type,
            "n_estimators_used": request.n_estimators,
            "learning_rate_used": request.learning_rate,
            "best_iteration": final_model.best_iteration_ if hasattr(final_model, 'best_iteration_') else request.n_estimators,
            "parameters_source": "user",
            
            # IMPORTANCE DES FEATURES
            "feature_importance": convert_numpy_types(feature_importance),
            "features_used": feature_columns,
            
            # Paramètres complets utilisés
            "final_params_used": model_params.copy(),
            
            # Résultats de validation
            "validation_results": convert_numpy_types(validation_results),
            "random_search": convert_numpy_types(random_search_meta) if random_search_meta else None,
            
            # Prédictions (Phase-2 train-only; subsampled for large datasets)
            "predictions": pack_predictions_for_response(
                y_test_encoded,
                y_pred_test,
                y_proba=(
                    model_on_full_train.predict_proba(X_test_np)
                    if is_classification and hasattr(model_on_full_train, "predict_proba")
                    else None
                ),
                y_train_true=y_train_encoded,
                y_train_pred=y_pred_train,
            ),
            
            # Informations sur le processus
            "training_process": {
                "phase_1_validation": {
                    "method": request.validation_method,
                    "n_repetitions": request.n_repetitions if request.validation_method == "holdout" else None,
                    "mean_score": validation_results.get('mean_score') if validation_results else None,
                    "best_score": validation_results.get('best_score') if validation_results else None,
                    "best_iteration": validation_results.get('best_iteration_global') if validation_results else None,
                    "date_column_excluded": validation_method == "cv_timeseries" or date_column is not None
                },
                "phase_2_train_evaluation": {
                    "train_metrics": train_metrics,
                    "test_metrics": test_metrics
                },
                "phase_3_final_model": {
                    "trained_on_all_data": request.final_training_on_all_data,
                    "total_samples": len(X_all) if request.final_training_on_all_data else len(X_train_np),
                    "best_iteration": final_model.best_iteration_ if hasattr(final_model, 'best_iteration_') else request.n_estimators
                }
            }
        }

        # AJOUT DES MÉTRIQUES SPÉCIFIQUES
        if is_classification:
            metrics.update({
                "accuracy": float(test_accuracy),
                "precision": float(test_precision),
                "recall": float(test_recall),
                "f1": float(test_f1),
                "roc_auc": float(roc_auc) if roc_auc is not None else None,
                "train_accuracy": float(train_accuracy),
                "confusion_matrix": confusion_matrix_dict,
                "classification_report": classification_rep,
                "classes": [str(c) for c in class_names],
                "n_classes": len(class_names),
                
                "final_test": test_metrics,
                "final_train": train_metrics
            })
        else:
            metrics.update({
                "r2": float(test_r2),
                "mse": float(test_mse),
                "mae": float(test_mae),
                "train_r2": float(train_r2),
                "train_mse": float(train_mse),
                "train_mae": float(train_mae),
                
                "final_test": test_metrics,
                "final_train": train_metrics,
                
                "errors": {
                    "absolute": (y_test_numeric - y_pred_test_numeric).tolist(),
                    "relative": ((y_test_numeric - y_pred_test_numeric) / (np.abs(y_test_numeric) + 1e-10)).tolist()
                }
            })

        if hasattr(final_model, 'evals_result_') and final_model.evals_result_:
            metrics["learning_curve"] = {
                "train": final_model.evals_result_.get('training', {}),
                "valid": final_model.evals_result_.get('valid_0', {})
            }

        check_stop()

        # ==================== SÉRIALISATION ====================
        try:
            model_bytes = io.BytesIO()
            model_data = {
                'model': final_model,
                'feature_names': feature_columns,
                'is_classification': is_classification,
                'class_names': class_names if is_classification else None,
                'final_parameters': model_params.copy(),
                'validation_method': request.validation_method,
                'used_validation_model': best_validation_model_idx is not None
            }
            joblib.dump(model_data, model_bytes)
            model_bytes.seek(0)
            model_base64 = base64.b64encode(model_bytes.read()).decode('utf-8')
            logger.info("💾 Model serialized successfully")
        except Exception as e:
            logger.error(f"❌ Error during model serialization: {str(e)}")
            model_base64 = None

        check_stop()

        # ==================== RÉPONSE FINALE ====================
        response_data = {
            "status": "success",
            "model_type": "lightgbm",
            "model_object": model_base64,
            "dataset_used": request.numerized_dataset_name,
            "metrics": convert_numpy_types(metrics),
            "random_search": convert_numpy_types(random_search_meta) if random_search_meta else None,
            "timestamp": datetime.now().isoformat(),
            "validation_method": request.validation_method,
            "parameters_optimized": bool(random_search_meta),
            "training_info": {
                **training_info,
                "model_trained_once": best_validation_model_idx is None,
                "used_cv_best_model": best_validation_model_idx is not None and request.validation_method.startswith('cv_'),
                "used_bootstrap_model": best_validation_model_idx is not None and request.validation_method == "bootstrap",
                "used_holdout_repeated_model": best_validation_model_idx is not None and request.validation_method == "holdout",
                "used_timeseries_model": best_validation_model_idx is not None and request.validation_method == "cv_timeseries",
                "final_model_source": f"best_{request.validation_method}_fold_{best_validation_model_idx + 1}" if best_validation_model_idx is not None else "standard_training",
                "training_samples": len(X_train_np),
                "test_samples": len(X_test_np),
                "parameter_optimization": (
                    "Random Search then fixed-param validation"
                    if random_search_meta else "User parameters used - no optimization"
                ),
                "early_stopping_used": request.early_stopping_rounds is not None and request.early_stopping_rounds > 0,
                "best_iteration": final_model.best_iteration_ if hasattr(final_model, 'best_iteration_') else request.n_estimators,
                "n_repetitions": request.n_repetitions if request.validation_method == "holdout" else None,
                "validation_method": request.validation_method,
                "date_column_excluded": validation_method == "cv_timeseries" or date_column is not None
            }
        }

        logger.info("=== LIGHTGBM TRAINING COMPLETED SUCCESSFULLY ===")
        
        if is_classification:
            logger.info(f"📊 FINAL RESULTS - Accuracy: {test_accuracy:.4f}")
        else:
            logger.info(f"📊 FINAL RESULTS - R²: {test_r2:.4f}")
        
        return response_data
        
    except HTTPException as he:
        if he.detail == "Training stopped by user":
            logger.info(f"🛑 LightGBM training {training_id} stopped by user")
        raise
    except Exception as e:
        logger.error(f"❌ Error in train_lightgbm: {str(e)}", exc_info=True)
        raise HTTPException(
            status_code=500,
            detail={
                "error_message": str(e),
                "error_type": type(e).__name__,
            }
        )

@router.post("/train-lightgbm")
async def train_lightgbm(
    request: TrainLightGBMRequest,
    background_tasks: BackgroundTasks = None,
    current_user_id: str = Depends(get_current_user2)
):
    # ========== 1. MODE ASYNCHRONE (BACKGROUND) - AVEC ARRÊT RÉEL ==========
    if hasattr(request, 'training_id') and request.training_id and background_tasks is not None:
        training_id = request.training_id
        
        training_stop_flags[training_id] = False
        
        def train_in_background():
            import asyncio
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)
            
            try:
                new_request = request.copy()
                new_request.training_id = None
        
                result = loop.run_until_complete(
                    train_lightgbm_with_stop_check(new_request, None, current_user_id, training_id)
                )
        
                if training_id in active_trainings and not training_stop_flags.get(training_id, False):
                    _safe_set_training_result(training_id, result)
                    logger.info(f"✅ LightGBM training {training_id} completed successfully")
                
            except Exception as e:
                error_msg = str(e)
                if "Training stopped by user" in error_msg:
                    logger.info(f"🛑 LightGBM training {training_id} was stopped by user")
                    _safe_set_training_error(training_id, "Training stopped by user", stopped=True)
                else:
                    logger.error(f"❌ Erreur dans train_lightgbm background: {error_msg}")
                    _safe_set_training_error(training_id, error_msg, stopped=False)
            finally:
                if training_id in training_stop_flags:
                    del training_stop_flags[training_id]
                loop.close()
        
        from concurrent.futures import Future
        future = Future()
        
        active_trainings[training_id] = {
            'future': future,
            'user_id': current_user_id,
            'start_time': datetime.now(),
            'model_type': 'lightgbm',
            'completed': False,
            'result': None,
            'error': None,
            'retrieved': False
        }
        
        background_tasks.add_task(train_in_background)
        
        return {
            "status": "training_started",
            "training_id": training_id,
            "message": "LightGBM training started in background"
        }
    
    # ========== 2. MODE SYNCHRONE (EXÉCUTION NORMALE) ==========
    return await train_lightgbm_with_stop_check(request, background_tasks, current_user_id, None)
