"""@@@@@@@@@@@@@@@@@@@mlp@@@@@@@@@@@@@@@@@@@@2222"""

logger = logging.getLogger(__name__)

class MLPModel(nn.Module):
    def __init__(self, input_size: int, layers: List[int], output_size: int, 
                 activation: str = 'relu', problem_type: str = 'auto',
                 dropout_rate: float = 0.0):
        super(MLPModel, self).__init__()
        self.layers = nn.ModuleList()
        self.activation = activation
        self.problem_type = problem_type
        self.dropout = nn.Dropout(dropout_rate) if dropout_rate > 0 else None
        
        # Input layer
        prev_size = input_size
        
        # Hidden layers
        for size in layers:
            self.layers.append(nn.Linear(prev_size, size))
            prev_size = size
            
        # Output layer
        self.output_layer = nn.Linear(prev_size, output_size)
        
        # Store architecture info
        self.architecture = []
        self.architecture.append({
            'type': 'input',
            'input_size': input_size,
            'output_size': input_size,
            'parameters': 0
        })
        
        for i, layer in enumerate(self.layers):
            self.architecture.append({
                'type': 'dense',
                'input_size': layer.in_features,
                'output_size': layer.out_features,
                'parameters': layer.weight.numel() + layer.bias.numel()
            })
            
        self.architecture.append({
            'type': 'output',
            'input_size': self.output_layer.in_features,
            'output_size': self.output_layer.out_features,
            'parameters': self.output_layer.weight.numel() + self.output_layer.bias.numel()
        })
    
    def forward(self, x):
        for layer in self.layers:
            x = layer(x)
            
            if self.activation == 'relu':
                x = torch.relu(x)
            elif self.activation == 'sigmoid':
                x = torch.sigmoid(x)
            elif self.activation == 'tanh':
                x = torch.tanh(x)
            elif self.activation == 'leaky_relu':
                x = nn.functional.leaky_relu(x)
            elif self.activation == 'elu':
                x = nn.functional.elu(x)
            elif self.activation == 'selu':
                x = nn.functional.selu(x)
                
            if self.dropout:
                x = self.dropout(x)
                
        x = self.output_layer(x)
        
        # Automatic output activation based on problem type
        if self.problem_type == 'binary_classification':
            x = torch.sigmoid(x)
        elif self.problem_type == 'multiclass_classification':
            x = torch.softmax(x, dim=1)
        # For regression, no activation (linear)
            
        return x

# Ajouter cette ligne pour la sérialisation sécurisée
torch.serialization.add_safe_globals([MLPModel])

# ==================== REQUÊTE MLP ====================
class TrainMLPRequest(BaseModel):
    numerized_dataset_name: str
    original_dataset_name: str
    model_type: Literal["mlp"] = "mlp"
    layers: List[int] = Field([64, 32], description="List of hidden layer sizes")
    activation: str = Field("relu", pattern="^(relu|sigmoid|tanh|leaky_relu|elu|selu)$")
    problem_type: str = Field("auto", pattern="^(auto|regression|binary_classification|multiclass_classification)$")
    dropout_rate: float = Field(0.2, ge=0, le=0.9, description="Dropout rate (0-0.9)")
    learning_rate: float = Field(0.001, gt=0, description="Learning rate")
    batch_size: int = Field(32, gt=0)
    epochs: int = Field(100, gt=0)
    patience: int = Field(10, gt=0, description="Early stopping patience")
    validation_split: float = Field(0.2, gt=0, lt=1, description="Validation split ratio")
    use_scaling: bool = Field(True, description="Whether to scale input features")
    validation_method: Optional[str] = "holdout"
    n_repetitions: int = Field(
        default=10, 
        gt=0, 
        le=50, 
        description="Number of repetitions for Hold-Out validation"
    )
    cv_params: Optional[Dict[str, Any]] = None
    bootstrap_params: Optional[Dict[str, Any]] = None
    
    # ✅ PARAMÈTRES TIMESERIES
    time_series_column: Optional[str] = Field(
        default=None,
        description="Column name containing dates for time series split"
    )
    time_series_params: Optional[Dict[str, Any]] = Field(
        default=None,
        description="Parameters for time series split: n_splits, test_size, gap"
    )
    
    # ✅ CRITIQUE: training_id POUR LE MODE ASYNCHRONE
    training_id: Optional[str] = None

    @field_validator('layers')
    def validate_layers(cls, v):
        if len(v) < 1:
            raise ValueError("At least one layer must be specified")
        if any(not isinstance(x, int) or x <= 0 for x in v):
            raise ValueError("All layer sizes must be positive integers")
        return v

# ==================== DICTIONNAIRES GLOBAUX POUR SUIVI ====================
active_trainings = {}
training_stop_flags = {}

# ==================== FONCTIONS UTILITAIRES ====================
def convert_numpy_types(obj):
    """Convertit les types numpy en types Python natifs"""
    if isinstance(obj, (np.integer, np.int32, np.int64)):
        return int(obj)
    elif isinstance(obj, (np.floating, np.float32, np.float64)):
        return float(obj)
    elif isinstance(obj, np.ndarray):
        return obj.tolist()
    elif isinstance(obj, np.bool_):
        return bool(obj)
    elif isinstance(obj, dict):
        return {key: convert_numpy_types(value) for key, value in obj.items()}
    elif isinstance(obj, list):
        return [convert_numpy_types(item) for item in obj]
    elif isinstance(obj, tuple):
        return tuple(convert_numpy_types(item) for item in obj)
    else:
        return obj

def get_table_columns(cursor, table_name):
    """Récupère toutes les colonnes d'une table"""
    cursor.execute("""
        SELECT column_name 
        FROM information_schema.columns 
        WHERE table_name = %s 
        ORDER BY ordinal_position
    """, (table_name.lower(),))
    return [row[0] for row in cursor.fetchall()]

# ==================== FONCTION DE PRÉPARATION DES DONNÉES ====================
def prepare_data_for_mlp(df, target_column, date_column=None, validation_method=None):
    """
    Prépare les données pour MLP en excluant correctement la colonne date
    des features si elle n'est pas utilisée pour TimeSeriesSplit
    """
    logger.info("🔧 PREPARATION DES DONNEES POUR MLP")
    
    # Créer une copie pour éviter de modifier l'original
    df_processed = df.copy()
    
    # Identifier les colonnes à exclure de l'entraînement
    exclude_columns = [target_column, 'split_type']
    
    if date_column:
        exclude_columns.append(date_column)
        if validation_method == "cv_timeseries":
            logger.info(f"📅 Colonne date '{date_column}' utilisée UNIQUEMENT pour split temporel -> EXCLUE des features")
        else:
            logger.info(f"🚫 Colonne date '{date_column}' -> EXCLUE des features (non TimeSeries)")
    
    # Colonnes features (tout sauf les exclues) + auto-exclude other date-like cols
    feature_columns = [col for col in df_processed.columns if col not in exclude_columns]
    feature_columns = exclude_date_columns_from_list(
        df_processed, feature_columns, date_column=date_column, target_column=target_column
    )
    logger.info(f"📊 Features utilisées pour l'entraînement: {feature_columns}")
    logger.info(f"🚫 Colonnes exclues: {exclude_columns}")
    
    # Séparer les données selon split_type
    train_mask = df_processed['split_type'] == 'train'
    test_mask = df_processed['split_type'] == 'test'
    
    df_train = df_processed[train_mask].copy()
    df_test = df_processed[test_mask].copy()
    
    logger.info(f"📊 Train: {len(df_train)} samples, Test: {len(df_test)} samples")
    
    # Extraire X et y pour train/test
    X_train_raw = df_train[feature_columns].copy()
    y_train_raw = df_train[target_column].copy()
    X_test_raw = df_test[feature_columns].copy()
    y_test_raw = df_test[target_column].copy()
    
    # ✅ Conversion numérique ROBUSTE avec gestion des erreurs
    for df_part, name in [(X_train_raw, "X_train"), (X_test_raw, "X_test")]:
        for col in df_part.columns:
            try:
                df_part.loc[:, col] = pd.to_numeric(df_part[col], errors='coerce')
                nan_count = df_part[col].isna().sum()
                if nan_count > 0:
                    logger.warning(f"⚠️ {name}: {nan_count} NaN dans {col} après conversion")
            except Exception as e:
                logger.error(f"❌ Erreur conversion {col}: {e}")
                df_part.loc[:, col] = 0.0
    
    # ✅ Remplir les NaN avec la médiane (calculée SUR LE TRAIN UNIQUEMENT)
    train_medians = X_train_raw.median(numeric_only=True)
    
    X_train = X_train_raw.fillna(train_medians)
    X_test = X_test_raw.fillna(train_medians)
    
    # ✅ Vérification finale des NaN
    if X_train.isna().any().any():
        X_train = X_train.fillna(0)
    if X_test.isna().any().any():
        X_test = X_test.fillna(0)
    
    # ✅ Traitement de la target
    y_train = pd.to_numeric(y_train_raw, errors='coerce').fillna(0).values
    y_test = pd.to_numeric(y_test_raw, errors='coerce').fillna(0).values
    
    # ✅ Récupérer la colonne date pour TimeSeriesSplit si nécessaire
    date_series = None
    if date_column and validation_method == "cv_timeseries":
        date_series = train_aligned_date_series(df_train, date_column)
        logger.info(f"📅 Colonne date récupérée pour TimeSeriesSplit: {date_column}")
    
    logger.info(f"✅ Préparation terminée: X_train shape {X_train.shape}, X_test shape {X_test.shape}")
    
    return X_train, X_test, y_train, y_test, feature_columns, date_series

# ==================== FONCTION D'ENTRAÎNEMENT D'UN SEUL MODÈLE MLP ====================
def train_mlp_model_single_with_stop(
    X_train: np.ndarray, y_train: np.ndarray, 
    X_val: np.ndarray, y_val: np.ndarray,
    input_size: int, output_size: int,
    params: Dict[str, Any],
    problem_type: str,
    training_id: str = None,
    training_stop_flags: Dict = None,
    fold_or_rep_info: str = ""
) -> Dict[str, Any]:
    """Train a single MLP model avec vérification d'arrêt pendant l'entraînement"""
    
    # ✅ Fonction de vérification d'arrêt interne
    def check_stop():
        if training_id and training_stop_flags and training_stop_flags.get(training_id, False):
            logger.info(f"🛑 Training stopped by user during {fold_or_rep_info}")
            raise HTTPException(400, "Training stopped by user")
    
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    
    is_classification = problem_type in ['binary_classification', 'multiclass_classification']
    
    # Convert data to PyTorch tensors
    X_train_tensor = torch.FloatTensor(X_train).to(device)
    X_val_tensor = torch.FloatTensor(X_val).to(device)
    
    # Traitement des targets selon le type de problème
    if problem_type == 'multiclass_classification':
        if y_train.ndim > 1 and y_train.shape[1] > 1:  # One-hot encoded
            y_train_labels = y_train.argmax(axis=1)
            y_val_labels = y_val.argmax(axis=1) if y_val.ndim > 1 else y_val
        else:  # Already class indices
            y_train_labels = y_train
            y_val_labels = y_val
        
        # S'assurer que les labels commencent à 0 et sont continus
        unique_train = np.unique(y_train_labels)
        unique_val = np.unique(y_val_labels)
        all_unique = np.unique(np.concatenate([y_train_labels, y_val_labels]))
        
        # Remapper les labels pour qu'ils commencent à 0
        label_mapping = {old: new for new, old in enumerate(sorted(all_unique))}
        
        y_train_labels = np.vectorize(label_mapping.get)(y_train_labels)
        y_val_labels = np.vectorize(label_mapping.get)(y_val_labels)
        
        # Mettre à jour output_size
        actual_n_classes = len(all_unique)
        if actual_n_classes != output_size:
            logger.info(f"⚠️ Adjusting output_size from {output_size} to {actual_n_classes}")
            output_size = actual_n_classes
        
        # Convertir en tensors (labels pour CrossEntropyLoss)
        y_train_tensor = torch.LongTensor(y_train_labels).to(device)
        y_val_tensor = torch.LongTensor(y_val_labels).to(device)
        
    elif problem_type == 'binary_classification':
        y_train = y_train.astype(np.float32).reshape(-1, 1)
        y_val = y_val.astype(np.float32).reshape(-1, 1)
        y_train_tensor = torch.FloatTensor(y_train).to(device)
        y_val_tensor = torch.FloatTensor(y_val).to(device)
        output_size = 1
    else:
        # For regression
        y_train_tensor = torch.FloatTensor(y_train.reshape(-1, output_size)).to(device)
        y_val_tensor = torch.FloatTensor(y_val.reshape(-1, output_size)).to(device)
    
    # Vérification de sécurité pour classification
    if problem_type == 'multiclass_classification':
        max_label = max(y_train_tensor.max().item(), y_val_tensor.max().item())
        if max_label >= output_size:
            logger.error(f"❌ Error: Label {max_label} exceeds output_size {output_size}")
            raise ValueError(f"Label {max_label} out of bounds for {output_size} classes")
    
    # Create datasets and loaders
    train_dataset = TensorDataset(X_train_tensor, y_train_tensor)
    val_dataset = TensorDataset(X_val_tensor, y_val_tensor)
    
    train_loader = DataLoader(train_dataset, batch_size=params['batch_size'], shuffle=True)
    val_loader = DataLoader(val_dataset, batch_size=params['batch_size'])
    
    # Initialize model
    model = MLPModel(
        input_size=input_size,
        layers=params['layers'],
        output_size=output_size,
        activation=params['activation'],
        problem_type=problem_type,
        dropout_rate=params['dropout_rate']
    ).to(device)
    
    # Define loss function based on problem type
    if problem_type == 'multiclass_classification':
        criterion = nn.CrossEntropyLoss()
    elif problem_type == 'binary_classification':
        criterion = nn.BCELoss()
    else:  # regression
        criterion = nn.MSELoss()
        
    optimizer = optim.Adam(model.parameters(), lr=params['learning_rate'])
    
    # Training loop with early stopping
    best_val_loss = float('inf')
    epochs_no_improve = 0
    best_epoch = 0
    best_model_state = None
    
    history = {
        'epoch': [],
        'loss': [],
        'val_loss': [],
        'accuracy': [],
        'val_accuracy': [],
        'mse': [],
        'val_mse': []
    }
    
    for epoch in range(params['epochs']):
        # ✅ Vérifier l'arrêt à CHAQUE epoch
        check_stop()
        
        # Training phase
        model.train()
        train_loss = 0.0
        train_correct = 0
        train_total = 0
        
        for inputs, targets in train_loader:
            optimizer.zero_grad()
            outputs = model(inputs)
            
            if problem_type == 'multiclass_classification':
                loss = criterion(outputs, targets)
                _, predicted = torch.max(outputs.data, 1)
                train_correct += (predicted == targets).sum().item()
            elif problem_type == 'binary_classification':
                loss = criterion(outputs, targets)
                predicted = (outputs > 0.5).float()
                train_correct += (predicted == targets).sum().item()
            else:
                loss = criterion(outputs, targets)
            
            train_total += targets.size(0)
            loss.backward()
            optimizer.step()
            train_loss += loss.item() * inputs.size(0)
        
        # Validation phase
        model.eval()
        val_loss = 0.0
        val_correct = 0
        val_total = 0
        
        with torch.no_grad():
            for inputs, targets in val_loader:
                outputs = model(inputs)
                
                if problem_type == 'multiclass_classification':
                    loss = criterion(outputs, targets)
                    _, predicted = torch.max(outputs.data, 1)
                    val_correct += (predicted == targets).sum().item()
                    val_total += targets.size(0)
                elif problem_type == 'binary_classification':
                    loss = criterion(outputs, targets)
                    predicted = (outputs > 0.5).float()
                    val_correct += (predicted == targets).sum().item()
                    val_total += targets.size(0)
                else:
                    loss = criterion(outputs, targets)
                
                val_loss += loss.item() * inputs.size(0)
        
        # Calculate metrics
        train_loss = train_loss / len(train_loader.dataset)
        val_loss = val_loss / len(val_loader.dataset)
        
        # Store history
        history['epoch'].append(epoch + 1)
        history['loss'].append(train_loss)
        history['val_loss'].append(val_loss)
        
        if is_classification:
            train_accuracy = train_correct / train_total if train_total > 0 else 0
            val_accuracy = val_correct / val_total if val_total > 0 else 0
            history['accuracy'].append(train_accuracy)
            history['val_accuracy'].append(val_accuracy)
        else:
            history['mse'].append(train_loss)
            history['val_mse'].append(val_loss)
        
        # Early stopping check
        if val_loss < best_val_loss:
            best_val_loss = val_loss
            epochs_no_improve = 0
            best_epoch = epoch
            best_model_state = model.state_dict().copy()
        else:
            epochs_no_improve += 1
            if epochs_no_improve >= params['patience']:
                logger.info(f"Early stopping triggered after {epoch + 1} epochs")
                break
    
    # Load best model weights
    if best_model_state:
        model.load_state_dict(best_model_state)
    
    return {
        'model': model,
        'history': history,
        'best_epoch': best_epoch + 1,
        'is_classification': is_classification,
        'problem_type': problem_type,
        'best_val_loss': float(best_val_loss),
        'best_val_accuracy': history['val_accuracy'][best_epoch] if is_classification else None,
        'n_classes': output_size if problem_type == 'multiclass_classification' else None
    }

# ==================== FONCTION PRINCIPALE: MLP TIMESERIES SPLIT (CORRIGÉE) ====================
def mlp_timeseries_split_with_stop(
    X, y, date_series, n_splits, test_size, gap,
    model_params, problem_type, input_size, output_size,
    training_id=None, training_stop_flags=None
):
    """
    Optimisation MLP avec TimeSeriesSplit
    La colonne date est utilisée UNIQUEMENT pour l'ordre chronologique
    Retourne: (fold_results, fold_models, val_scores)
    """
    logger.info("=" * 80)
    logger.info("🕒 TIMESERIES SPLIT OPTIMIZATION FOR MLP")
    logger.info("=" * 80)
    
    n_samples = len(X)
    logger.info(f"📊 Nombre total d'échantillons: {n_samples}")
    
    # Vérifier la longueur de date_series
    if len(date_series) != n_samples:
        logger.warning(f"⚠️ Longueur de date_series ({len(date_series)}) != n_samples ({n_samples})")
        if len(date_series) > n_samples:
            date_series = date_series.iloc[:n_samples]
        else:
            date_series = pd.Series(range(n_samples), index=range(n_samples))
    
    # ✅ CORRECTION: Gérer le cas où y est one-hot (multiclasse)
    if problem_type == 'multiclass_classification' and y.ndim > 1 and y.shape[1] > 1:
        # Sauvegarder les labels one-hot pour l'évaluation
        y_onehot = y.copy()
        # Utiliser les indices de classe pour le DataFrame
        y_labels = y.argmax(axis=1)
        logger.info(f"📊 y_labels shape: {y_labels.shape}")
    else:
        y_labels = y
        y_onehot = y
    
    # ✅ CRITIQUE: Créer DataFrame avec les features et la date pour le tri chronologique
    if isinstance(X, pd.DataFrame):
        temp_df = X.copy()
        X_values = X.values
    else:
        temp_df = pd.DataFrame(X)
        X_values = X
    
    # Ajouter les colonnes au DataFrame (en gérant les dimensions)
    temp_df['target'] = y_labels  # Utiliser les labels (1D)
    temp_df['date'] = date_series.values if hasattr(date_series, 'values') else date_series
    temp_df['original_index'] = range(n_samples)
    
    # ✅ Trier par date pour garantir l'ordre chronologique
    temp_df_sorted = temp_df.sort_values('date').reset_index(drop=True)
    
    # Extraire les données triées
    X_sorted = temp_df_sorted.drop(columns=['target', 'date', 'original_index']).values
    
    # ✅ Récupérer les targets triées selon le type
    if problem_type == 'multiclass_classification' and y_onehot is not None:
        # Reconstruire les one-hot dans l'ordre trié
        sorted_indices = temp_df_sorted['original_index'].values
        y_sorted = y_onehot[sorted_indices]
        y_labels_sorted = temp_df_sorted['target'].values
    else:
        y_sorted = temp_df_sorted['target'].values
        y_labels_sorted = y_sorted
    
    logger.info(f"✅ X_sorted shape: {X_sorted.shape}, y_sorted shape: {y_sorted.shape}")
    
    # Calculer test_size en échantillons
    if isinstance(test_size, float) and test_size < 1:
        test_size_samples = max(1, int(n_samples * test_size))
    else:
        test_size_samples = max(1, int(test_size))
    
    logger.info(f"📊 test_size: {test_size} → {test_size_samples} échantillons")
    
    # Ajuster n_splits si nécessaire
    min_samples_needed = (n_splits + 1) * test_size_samples
    if min_samples_needed > n_samples:
        max_possible_splits = max(2, n_samples // test_size_samples - 1)
        n_splits = min(n_splits, max_possible_splits)
        logger.info(f"✅ n_splits ajusté à {n_splits}")
    
    # Créer le splitter
    tscv = TimeSeriesSplit(n_splits=n_splits, test_size=test_size_samples, gap=gap)
    
    fold_results = []
    fold_models = []
    val_scores = []
    
    fold_count = 0
    for fold_idx, (train_idx, val_idx) in enumerate(tscv.split(X_sorted)):
        fold_count += 1
        
        # Vérifier stop flag
        if training_id and training_stop_flags and training_stop_flags.get(training_id, False):
            logger.info(f"🛑 Stop signal détecté, arrêt après {fold_count} folds")
            break
        
        # Vérifier les index
        if max(train_idx) >= n_samples or max(val_idx) >= n_samples:
            logger.error(f"❌ Index hors limites: train max={max(train_idx)}, val max={max(val_idx)}")
            continue
        
        logger.info(f"🔍 Fold {fold_count}/{n_splits}")
        logger.info(f"   Train indices: {train_idx[0]} → {train_idx[-1]} (taille: {len(train_idx)})")
        logger.info(f"   Val indices:   {val_idx[0]} → {val_idx[-1]} (taille: {len(val_idx)})")
        
        # Extraire les données
        X_train_fold = X_sorted[train_idx]
        X_val_fold = X_sorted[val_idx]
        
        # ✅ Extraire les targets selon le type
        if problem_type == 'multiclass_classification' and y_sorted.ndim > 1 and y_sorted.shape[1] > 1:
            y_train_fold = y_sorted[train_idx]  # One-hot
            y_val_fold = y_sorted[val_idx]      # One-hot
        else:
            y_train_fold = y_sorted[train_idx]  # 1D
            y_val_fold = y_sorted[val_idx]      # 1D
        
        if len(X_train_fold) < 5 or len(X_val_fold) < 1:
            logger.warning(f"   ⚠️ Pas assez de données, skip")
            continue
        
        try:
            # Calculer output_size pour ce fold
            current_output_size = output_size
            if problem_type == 'multiclass_classification':
                # Pour classification, déterminer le nombre de classes dans ce fold
                if y_train_fold.ndim > 1 and y_train_fold.shape[1] > 1:
                    train_classes = y_train_fold.argmax(axis=1)
                else:
                    train_classes = y_train_fold
                
                unique_train_classes = len(np.unique(train_classes))
                if unique_train_classes < current_output_size:
                    logger.warning(f"⚠️ Fold {fold_count}: Only {unique_train_classes} classes, adjusting output_size")
                    current_output_size = unique_train_classes
            
            # Entraîner le modèle MLP pour ce fold
            fold_result = train_mlp_model_single_with_stop(
                X_train=X_train_fold,
                y_train=y_train_fold,
                X_val=X_val_fold,
                y_val=y_val_fold,
                input_size=X_train_fold.shape[1],
                output_size=current_output_size,
                params=model_params,
                problem_type=problem_type,
                training_id=training_id,
                training_stop_flags=training_stop_flags,
                fold_or_rep_info=f"fold_{fold_count}"
            )
            
            # Évaluer sur validation
            device = next(fold_result['model'].parameters()).device
            X_val_tensor = torch.FloatTensor(X_val_fold).to(device)
            
            fold_result['model'].eval()
            with torch.no_grad():
                val_outputs = fold_result['model'](X_val_tensor)
                
                if problem_type == 'multiclass_classification':
                    y_pred = torch.argmax(val_outputs, dim=1).cpu().numpy()
                    if y_val_fold.ndim > 1 and y_val_fold.shape[1] > 1:
                        y_true = y_val_fold.argmax(axis=1)
                    else:
                        y_true = y_val_fold
                    val_score = accuracy_score(y_true, y_pred)
                elif problem_type == 'binary_classification':
                    y_pred = (val_outputs > 0.5).float().cpu().numpy().flatten()
                    val_score = accuracy_score(y_val_fold.flatten(), y_pred)
                else:  # regression
                    y_pred = val_outputs.cpu().numpy().flatten()
                    val_score = r2_score(y_val_fold.flatten(), y_pred)
            
            # Évaluer sur train
            X_train_tensor = torch.FloatTensor(X_train_fold).to(device)
            with torch.no_grad():
                train_outputs = fold_result['model'](X_train_tensor)
                
                if problem_type == 'multiclass_classification':
                    y_pred_train = torch.argmax(train_outputs, dim=1).cpu().numpy()
                    if y_train_fold.ndim > 1 and y_train_fold.shape[1] > 1:
                        y_true_train = y_train_fold.argmax(axis=1)
                    else:
                        y_true_train = y_train_fold
                    train_score = accuracy_score(y_true_train, y_pred_train)
                elif problem_type == 'binary_classification':
                    y_pred_train = (train_outputs > 0.5).float().cpu().numpy().flatten()
                    train_score = accuracy_score(y_train_fold.flatten(), y_pred_train)
                else:  # regression
                    y_pred_train = train_outputs.cpu().numpy().flatten()
                    train_score = r2_score(y_train_fold.flatten(), y_pred_train)
            
            logger.info(f"   ✅ Train score: {train_score:.4f}, Val score: {val_score:.4f}")
            
            fold_models.append(fold_result['model'])
            val_scores.append(val_score)
            
            fold_results.append({
                'fold': fold_count,
                'train_size': len(X_train_fold),
                'val_size': len(X_val_fold),
                'train_score': float(train_score),
                'val_score': float(val_score),
                'best_val_loss': float(fold_result['best_val_loss']),
                'training_history': fold_result['history'],
                'train_indices': [int(train_idx[0]), int(train_idx[-1])],
                'val_indices': [int(val_idx[0]), int(val_idx[-1])],
                'n_classes': current_output_size
            })
            
        except Exception as e:
            if "Training stopped by user" in str(e):
                raise  # Propager l'arrêt
            logger.error(f"❌ Erreur sur fold {fold_count}: {e}")
            continue
    
    if not fold_results:
        logger.error("❌ Aucun fold valide pour TimeSeriesSplit")
        return [], [], []
    
    logger.info("=" * 80)
    logger.info("📊 RÉSULTATS TIMESERIES SPLIT")
    logger.info(f"   Folds valides: {len(fold_results)}/{n_splits}")
    logger.info(f"   Score moyen validation: {np.mean(val_scores):.4f} ± {np.std(val_scores):.4f}")
    logger.info("=" * 80)
    
    return fold_results, fold_models, val_scores

# ==================== AUTRES FONCTIONS DE VALIDATION ====================
def mlp_holdout_repeated_with_stop(X, y, n_repetitions, test_size, params, problem_type, 
                                    training_id=None, training_stop_flags=None):
    """Hold-Out répété avec sauvegarde des modèles et vérification d'arrêt"""
    
    def check_stop():
        if training_id and training_stop_flags and training_stop_flags.get(training_id, False):
            raise HTTPException(400, "Training stopped by user")
    
    holdout_scores = []
    holdout_models = []
    repetition_details = []
    
    if problem_type == 'multiclass_classification':
        if y.ndim > 1 and y.shape[1] > 1:
            output_size = y.shape[1]
        else:
            output_size = len(np.unique(y))
    elif problem_type == 'binary_classification':
        output_size = 1
    else:
        output_size = 1
    
    logger.info(f"🔢 Calculated output_size for MLP: {output_size}")
    
    for i in range(n_repetitions):
        # ✅ Vérifier l'arrêt à CHAQUE répétition
        check_stop()
        
        # Sous-découpage ALÉATOIRE du train set
        if problem_type in ['binary_classification', 'multiclass_classification']:
            # Pour classification, stratifier si possible
            if y.ndim > 1 and y.shape[1] > 1:
                y_for_stratify = y.argmax(axis=1)
            else:
                y_for_stratify = y
                
            X_ho_train, X_ho_val, y_ho_train, y_ho_val = train_test_split(
                X, y, 
                test_size=test_size, 
                random_state=None,
                stratify=y_for_stratify
            )
        else:
            X_ho_train, X_ho_val, y_ho_train, y_ho_val = train_test_split(
                X, y, 
                test_size=test_size, 
                random_state=None
            )
        
        # Ajuster output_size pour cette répétition
        current_output_size = output_size
        if problem_type == 'multiclass_classification':
            if y_ho_train.ndim > 1 and y_ho_train.shape[1] > 1:
                train_classes = y_ho_train.argmax(axis=1)
            else:
                train_classes = y_ho_train
            
            unique_train_classes = len(np.unique(train_classes))
            if unique_train_classes < current_output_size:
                logger.warning(f"⚠️ Repetition {i+1}: Only {unique_train_classes} classes, adjusting output_size")
                current_output_size = unique_train_classes
        
        # Entraînement du modèle MLP pour cette répétition
        try:
            holdout_result = train_mlp_model_single_with_stop(
                X_train=X_ho_train,
                y_train=y_ho_train,
                X_val=X_ho_val,
                y_val=y_ho_val,
                input_size=X_ho_train.shape[1],
                output_size=current_output_size,
                params=params,
                problem_type=problem_type,
                training_id=training_id,
                training_stop_flags=training_stop_flags,
                fold_or_rep_info=f"repetition_{i+1}"
            )
        except Exception as e:
            if "Training stopped by user" in str(e):
                raise  # Propager l'arrêt
            logger.error(f"❌ Error in repetition {i+1}: {str(e)}")
            continue
        
        # Évaluation sur les données de validation
        device = next(holdout_result['model'].parameters()).device
        X_val_tensor = torch.FloatTensor(X_ho_val).to(device)
        
        holdout_result['model'].eval()
        with torch.no_grad():
            val_outputs = holdout_result['model'](X_val_tensor)
            
            if problem_type == 'multiclass_classification':
                y_pred = torch.argmax(val_outputs, dim=1).cpu().numpy()
                if y_ho_val.ndim > 1 and y_ho_val.shape[1] > 1:
                    y_true = y_ho_val.argmax(axis=1)
                else:
                    y_true = y_ho_val
                score = accuracy_score(y_true, y_pred)
            elif problem_type == 'binary_classification':
                y_pred = (val_outputs > 0.5).float().cpu().numpy().flatten()
                score = accuracy_score(y_ho_val.flatten(), y_pred)
            else:
                y_pred = val_outputs.cpu().numpy().flatten()
                score = r2_score(y_ho_val.flatten(), y_pred)
        
        holdout_scores.append(score)
        holdout_models.append(holdout_result['model'])
        
        repetition_details.append({
            'repetition': i + 1,
            'score': float(score),
            'train_size': len(X_ho_train),
            'validation_size': len(X_ho_val),
            'test_size_percent': test_size * 100,
            'best_val_loss': float(holdout_result['best_val_loss']),
            'parameters_used': params.copy(),
            'training_history': holdout_result['history'],
            'n_classes': current_output_size,
            'output_size_used': current_output_size
        })
    
    if not holdout_scores:
        raise ValueError("All repetitions failed. Check your data and parameters.")
    
    return holdout_scores, holdout_models, repetition_details

def mlp_cv_with_stop(X, y, cv, params, problem_type, training_id=None, training_stop_flags=None):
    """Validation croisée avec vérification d'arrêt"""
    
    def check_stop():
        if training_id and training_stop_flags and training_stop_flags.get(training_id, False):
            raise HTTPException(400, "Training stopped by user")
    
    cv_scores = []
    cv_models = []
    fold_details = []
    
    if problem_type == 'multiclass_classification':
        if y.ndim > 1 and y.shape[1] > 1:
            output_size = y.shape[1]
        else:
            output_size = len(np.unique(y))
    elif problem_type == 'binary_classification':
        output_size = 1
    else:
        output_size = 1
    
    logger.info(f"🔢 Calculated output_size for CV: {output_size}")
    
    for fold_idx, (train_idx, val_idx) in enumerate(cv.split(X, y)):
        # ✅ Vérifier l'arrêt à CHAQUE fold
        check_stop()
        
        logger.info(f"📐 Fold {fold_idx + 1}: {len(train_idx)} train, {len(val_idx)} validation samples")
        
        X_fold_train = X[train_idx]
        X_fold_val = X[val_idx]
        y_fold_train = y[train_idx]
        y_fold_val = y[val_idx]
        
        # Ajuster output_size pour ce fold
        current_output_size = output_size
        if problem_type == 'multiclass_classification':
            if y_fold_train.ndim > 1 and y_fold_train.shape[1] > 1:
                train_classes = y_fold_train.argmax(axis=1)
            else:
                train_classes = y_fold_train
            
            unique_train_classes = len(np.unique(train_classes))
            if unique_train_classes < current_output_size:
                logger.warning(f"⚠️ Fold {fold_idx + 1}: Only {unique_train_classes} classes, adjusting output_size")
                current_output_size = unique_train_classes
        
        try:
            fold_result = train_mlp_model_single_with_stop(
                X_train=X_fold_train,
                y_train=y_fold_train,
                X_val=X_fold_val,
                y_val=y_fold_val,
                input_size=X_fold_train.shape[1],
                output_size=current_output_size,
                params=params,
                problem_type=problem_type,
                training_id=training_id,
                training_stop_flags=training_stop_flags,
                fold_or_rep_info=f"fold_{fold_idx+1}"
            )
        except Exception as e:
            if "Training stopped by user" in str(e):
                raise
            logger.error(f"❌ Error in fold {fold_idx + 1}: {str(e)}")
            continue
        
        device = next(fold_result['model'].parameters()).device
        X_val_tensor = torch.FloatTensor(X_fold_val).to(device)
        
        fold_result['model'].eval()
        with torch.no_grad():
            val_outputs = fold_result['model'](X_val_tensor)
            
            if problem_type == 'multiclass_classification':
                y_pred = torch.argmax(val_outputs, dim=1).cpu().numpy()
                y_true = y_fold_val.argmax(axis=1) if y_fold_val.ndim > 1 else y_fold_val
                score = accuracy_score(y_true, y_pred)
            elif problem_type == 'binary_classification':
                y_pred = (val_outputs > 0.5).float().cpu().numpy().flatten()
                score = accuracy_score(y_fold_val.flatten(), y_pred)
            else:
                y_pred = val_outputs.cpu().numpy().flatten()
                score = r2_score(y_fold_val.flatten(), y_pred)
        
        cv_scores.append(score)
        cv_models.append(fold_result['model'])
        
        fold_details.append({
            'fold': fold_idx + 1,
            'train_size': len(X_fold_train),
            'validation_size': len(X_fold_val),
            'score': float(score),
            'train_score': float(fold_result['history']['loss'][-1]),
            'best_val_loss': float(fold_result['best_val_loss']),
            'parameters_used': params.copy(),
            'training_history': fold_result['history'],
            'n_classes': current_output_size,
            'output_size_used': current_output_size
        })
        
        logger.info(f"   Fold {fold_idx + 1} validation score: {score:.4f}")
    
    if not cv_scores:
        raise ValueError("All folds failed. Check your data and parameters.")
    
    return cv_scores, cv_models, fold_details

def mlp_bootstrap_with_stop(X, y, n_bootstraps, test_size, params, problem_type, 
                            training_id=None, training_stop_flags=None):
    """VRAI Bootstrap avec vérification d'arrêt"""
    
    def check_stop():
        if training_id and training_stop_flags and training_stop_flags.get(training_id, False):
            raise HTTPException(400, "Training stopped by user")
    
    bootstrap_scores = []
    bootstrap_models = []
    bootstrap_details = []
    
    n_samples = len(X)
    
    if problem_type == 'multiclass_classification':
        if y.ndim > 1 and y.shape[1] > 1:
            output_size = y.shape[1]
        else:
            output_size = len(np.unique(y))
    elif problem_type == 'binary_classification':
        output_size = 1
    else:
        output_size = 1
    
    logger.info(f"🔢 Calculated output_size for Bootstrap: {output_size}")
    
    for i in range(n_bootstraps):
        # ✅ Vérifier l'arrêt à CHAQUE bootstrap
        check_stop()
        
        # VRAI BOOTSTRAP : Échantillonnage avec remise
        bootstrap_indices = np.random.choice(n_samples, size=n_samples, replace=True)
        
        X_bs = X[bootstrap_indices]
        y_bs = y[bootstrap_indices]
        
        # Échantillon de test: points NON sélectionnés dans le bootstrap
        all_indices = set(range(n_samples))
        bootstrap_set = set(bootstrap_indices)
        test_indices = list(all_indices - bootstrap_set)
        
        if len(test_indices) == 0:
            test_indices = np.random.choice(n_samples, size=int(n_samples * test_size), replace=False)
        
        X_bs_val = X[test_indices]
        y_bs_val = y[test_indices]
        
        # Ajuster output_size pour ce bootstrap
        current_output_size = output_size
        if problem_type == 'multiclass_classification':
            if y_bs.ndim > 1 and y_bs.shape[1] > 1:
                train_classes = y_bs.argmax(axis=1)
            else:
                train_classes = y_bs
            
            unique_train_classes = len(np.unique(train_classes))
            if unique_train_classes < current_output_size:
                logger.warning(f"⚠️ Bootstrap {i+1}: Only {unique_train_classes} classes, adjusting output_size")
                current_output_size = unique_train_classes
        
        try:
            bootstrap_result = train_mlp_model_single_with_stop(
                X_train=X_bs,
                y_train=y_bs,
                X_val=X_bs_val,
                y_val=y_bs_val,
                input_size=X_bs.shape[1],
                output_size=current_output_size,
                params=params,
                problem_type=problem_type,
                training_id=training_id,
                training_stop_flags=training_stop_flags,
                fold_or_rep_info=f"bootstrap_{i+1}"
            )
        except Exception as e:
            if "Training stopped by user" in str(e):
                raise
            logger.error(f"❌ Error in bootstrap {i+1}: {str(e)}")
            continue
        
        device = next(bootstrap_result['model'].parameters()).device
        X_val_tensor = torch.FloatTensor(X_bs_val).to(device)
        
        bootstrap_result['model'].eval()
        with torch.no_grad():
            val_outputs = bootstrap_result['model'](X_val_tensor)
            
            if problem_type == 'multiclass_classification':
                y_pred = torch.argmax(val_outputs, dim=1).cpu().numpy()
                y_true = y_bs_val.argmax(axis=1) if y_bs_val.ndim > 1 else y_bs_val
                score = accuracy_score(y_true, y_pred)
            elif problem_type == 'binary_classification':
                y_pred = (val_outputs > 0.5).float().cpu().numpy().flatten()
                score = accuracy_score(y_bs_val.flatten(), y_pred)
            else:
                y_pred = val_outputs.cpu().numpy().flatten()
                score = r2_score(y_bs_val.flatten(), y_pred)
        
        bootstrap_scores.append(score)
        bootstrap_models.append(bootstrap_result['model'])
        
        unique_samples = len(set(bootstrap_indices))
        duplicate_count = n_samples - unique_samples
        
        bootstrap_details.append({
            'bootstrap': i + 1,
            'score': float(score),
            'train_size': len(X_bs),
            'validation_size': len(X_bs_val),
            'unique_samples_in_bootstrap': unique_samples,
            'duplicate_samples': duplicate_count,
            'best_val_loss': float(bootstrap_result['best_val_loss']),
            'parameters_used': params.copy(),
            'training_history': bootstrap_result['history'],
            'n_classes': current_output_size,
            'output_size_used': current_output_size
        })
    
    if not bootstrap_scores:
        raise ValueError("All bootstraps failed. Check your data and parameters.")
    
    return bootstrap_scores, bootstrap_models, bootstrap_details

# ==================== FONCTION PRINCIPALE AVEC VÉRIFICATION D'ARRÊT ====================
async def train_mlp_pytorch_with_stop_check(
    request: TrainMLPRequest,
    background_tasks: BackgroundTasks = None,
    current_user_id: str = None,
    training_id: str = None
):
    """Version de train_mlp_pytorch avec vérification d'arrêt à chaque étape"""
    
    # ✅ Fonction de vérification d'arrêt
    def check_stop():
        if training_id and training_stop_flags.get(training_id, False):
            logger.info(f"🛑 MLP training {training_id} stopped by user (check_stop triggered)")
            raise HTTPException(400, "Training stopped by user")
    
    try:
        logger.info("=== MLP PYTORCH TRAINING STARTED ===")
        if training_id:
            logger.info(f"🎫 Training ID: {training_id}")
        logger.info(f"📋 Request validation method: {request.validation_method}")
        logger.info(f"⚙️ Parameters: layers={request.layers}, activation={request.activation}, problem_type={request.problem_type}")

        # ==================== VÉRIFICATION D'ARRÊT ====================
        check_stop()

        # ==================== INITIAL VALIDATION ====================
        if not request.numerized_dataset_name or not request.original_dataset_name:
            raise HTTPException(400, "Dataset names are required")
        
        check_stop()

        # ==================== DATA LOADING ====================
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Check permissions and get target column
                cur.execute("""
                    SELECT target_column 
                    FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (request.original_dataset_name.lower(), current_user_id))
                
                target_info = cur.fetchone()
                if not target_info or not target_info[0]:
                    raise HTTPException(400, "Target column not defined in original dataset")
                
                target_column = target_info[0]
                check_stop()

                # Check if numerized table exists
                cur.execute("""
                    SELECT 1 FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (request.numerized_dataset_name.lower(), current_user_id))
                
                if not cur.fetchone():
                    raise HTTPException(404, "Numerized dataset not found or access denied")
                
                check_stop()

                # Get all columns
                all_columns = get_table_columns(cur, request.numerized_dataset_name)
                if not all_columns:
                    raise HTTPException(404, "No columns found")
                
                check_stop()

                # Build SQL query
                select_columns = [
                    sql.Identifier(col) 
                    for col in all_columns 
                    if col not in ['id', 'split_type']
                ]

                query = sql.SQL("""
                    SELECT {columns}, split_type FROM {table}
                    WHERE split_type IS NOT NULL
                """).format(
                    columns=sql.SQL(',').join(select_columns),
                    table=sql.Identifier(request.numerized_dataset_name.lower())
                )

                cur.execute(query)
                rows = cur.fetchall()
                check_stop()

        # ==================== DATA PREPARATION ====================
        df_columns = [col for col in all_columns if col not in ['id', 'split_type']] + ['split_type']
        df = pd.DataFrame(rows, columns=df_columns)
        check_stop()

        # Clean data
        df['split_type'] = df['split_type'].astype(str).str.lower().str.strip()
        check_stop()
        
        # Validate splits
        valid_splits = {'train', 'test'}
        invalid_splits = set(df['split_type'].unique()) - valid_splits
        if invalid_splits:
            raise HTTPException(
                400, 
                f"Invalid values in split_type: {invalid_splits}. Expected: 'train' or 'test'"
            )

        # ✅ Utiliser la fonction de préparation qui exclut correctement la colonne date
        date_column = resolve_request_date_column(request)
        validation_method = request.validation_method or "holdout"
        
        X_train, X_test, y_train, y_test, feature_columns, date_series = prepare_data_for_mlp(
            df, 
            target_column, 
            date_column=date_column,
            validation_method=validation_method
        )

        check_stop()

        # ==================== STANDARDIZATION ====================
        if request.use_scaling:
            scaler = StandardScaler()
            X_train_scaled = scaler.fit_transform(X_train)
            X_test_scaled = scaler.transform(X_test)
        else:
            scaler = None
            X_train_scaled = X_train.values if hasattr(X_train, 'values') else X_train
            X_test_scaled = X_test.values if hasattr(X_test, 'values') else X_test
        
        check_stop()

        # ==================== TARGET PROCESSING ====================
        try:
            pd.to_numeric(y_train, errors='raise')
            target_is_numeric = True
        except (ValueError, TypeError):
            target_is_numeric = False

        # Calculate values for auto-detection
        unique_values = len(np.unique(y_train))
        total_samples = len(y_train)
        unique_ratio = (unique_values / total_samples) * 100

        if total_samples <= 30:
            threshold = 25.0
        elif total_samples <= 100:
            threshold = 15.0
        else:
            threshold = 5.0

        # Determine problem type
        if request.problem_type == 'auto':
            if unique_ratio <= threshold:
                if unique_values == 2:
                    problem_type = 'binary_classification'
                else:
                    problem_type = 'multiclass_classification'
            else:
                problem_type = 'regression'
        else:
            problem_type = request.problem_type
            
        is_classification = problem_type in ['binary_classification', 'multiclass_classification']
        check_stop()
        
        # Target analysis info
        target_analysis = {
            "target_column": target_column,
            "unique_values": int(unique_values),
            "total_samples": total_samples,
            "unique_ratio": float(unique_ratio),
            "is_numeric": target_is_numeric,
            "is_classification": is_classification,
            "threshold_used": threshold,
            "problem_type_detected": problem_type
        }

        # Process targets selon le type de problème
        if is_classification:
            # Pour classification, convertir en strings puis encoder
            if y_train.dtype == 'object' or y_train.dtype == 'O':
                y_train_str = y_train.astype(str)
                y_test_str = y_test.astype(str)
            else:
                y_train_str = y_train.astype(str)
                y_test_str = y_test.astype(str)
            
            # Nettoyer les strings
            y_train_str = np.array([str(x).strip() for x in y_train_str])
            y_test_str = np.array([str(x).strip() for x in y_test_str])
            
            # Trouver toutes les classes uniques
            all_classes = sorted(list(set(y_train_str) | set(y_test_str)))
            class_to_num = {cls: i for i, cls in enumerate(all_classes)}
            num_to_class = {i: cls for i, cls in enumerate(all_classes)}
            
            logger.info(f"🎯 Classes mapping: {class_to_num}")
            logger.info(f"🎯 Number of classes: {len(all_classes)}")
            
            # Convertir en indices numériques
            y_train_indices = np.array([class_to_num[cls] for cls in y_train_str])
            y_test_indices = np.array([class_to_num[cls] for cls in y_test_str])
            class_names = all_classes
            
            if problem_type == 'binary_classification':
                # Pour binaire, garder comme float32 pour BCE loss
                y_train_encoded_np = y_train_indices.astype(np.float32).reshape(-1, 1)
                y_test_encoded_np = y_test_indices.astype(np.float32).reshape(-1, 1)
                
                # Garder aussi les labels 1D pour l'évaluation
                y_train_labels = y_train_indices
                y_test_labels = y_test_indices
            else:  # multiclass classification
                # Convertir en one-hot pour l'entraînement
                y_train_onehot = np.zeros((len(y_train_indices), len(all_classes)), dtype=np.float32)
                y_train_onehot[np.arange(len(y_train_indices)), y_train_indices] = 1
                y_train_encoded_np = y_train_onehot
                
                y_test_onehot = np.zeros((len(y_test_indices), len(all_classes)), dtype=np.float32)
                y_test_onehot[np.arange(len(y_test_indices)), y_test_indices] = 1
                y_test_encoded_np = y_test_onehot
                
                # Garder les labels 1D pour l'évaluation
                y_train_labels = y_train_indices
                y_test_labels = y_test_indices
                
                logger.info(f"🎯 One-hot shape: {y_train_onehot.shape}")
        else:
            # Pour regression, s'assurer que c'est numérique
            try:
                y_train_encoded_np = np.array(y_train, dtype=np.float32).reshape(-1, 1)
                y_test_encoded_np = np.array(y_test, dtype=np.float32).reshape(-1, 1)
                y_train_labels = y_train_encoded_np.flatten()
                y_test_labels = y_test_encoded_np.flatten()
            except (ValueError, TypeError):
                # Fallback avec median
                train_median = np.nanmedian(y_train.astype(np.float32))
                y_train_encoded_np = np.nan_to_num(y_train.astype(np.float32), nan=train_median).reshape(-1, 1)
                y_test_encoded_np = np.nan_to_num(y_test.astype(np.float32), nan=train_median).reshape(-1, 1)
                y_train_labels = y_train_encoded_np.flatten()
                y_test_labels = y_test_encoded_np.flatten()
            class_names = None
        
        check_stop()

        # ==================== MODEL PARAMETERS ====================
        model_params = {
            'layers': request.layers,
            'activation': request.activation,
            'dropout_rate': request.dropout_rate,
            'learning_rate': request.learning_rate,
            'batch_size': request.batch_size,
            'epochs': request.epochs,
            'patience': request.patience
        }

        # Calculer output_size correctement
        if problem_type == 'multiclass_classification':
            output_size = len(all_classes)
            logger.info(f"🎯 Final output_size for MLP: {output_size}")
        elif problem_type == 'binary_classification':
            output_size = 1
        else:
            output_size = 1  # regression

        # ==================== VALIDATION STRATEGY ====================
        validation_results = None
        final_model = None
        used_validation_model = False
        training_result = None

        logger.info(f"🔍 Starting MLP validation with method: {request.validation_method}")

        # ==================== EXÉCUTION DE LA VALIDATION ====================
        
        # ✅ TIMESERIES SPLIT POUR MLP
        if request.validation_method == "cv_timeseries":
            logger.info("=" * 80)
            logger.info("⏰ TIMESERIES SPLIT SELECTED FOR MLP")
            logger.info("=" * 80)
            
            check_stop()
            
            # Récupérer les paramètres TimeSeries
            time_series_params = getattr(request, 'time_series_params', {})
            n_splits = time_series_params.get('n_splits', 5)
            test_size = time_series_params.get('test_size', 0.2)
            gap = time_series_params.get('gap', 0)
            
            logger.info(f"📊 Paramètres: n_splits={n_splits}, test_size={test_size}, gap={gap}")
            logger.info(f"📅 Colonne date: {date_column if date_column else 'Aucune'}")
            
            if date_series is None:
                raise HTTPException(400, "TimeSeriesSplit requires a date column")
            
            logger.info(f"📊 Features utilisées (SANS date): {feature_columns}")
            logger.info(f"✅ La colonne date est utilisée UNIQUEMENT pour l'ordre chronologique")
            
            # ✅ Utiliser la fonction TimeSeriesSplit pour MLP (corrigée)
            timeseries_results, fold_models, val_scores = mlp_timeseries_split_with_stop(
                X=X_train_scaled,
                y=y_train_encoded_np,  # Passer les one-hot pour multiclasse
                date_series=date_series,
                n_splits=n_splits,
                test_size=test_size,
                gap=gap,
                model_params=model_params,
                problem_type=problem_type,
                input_size=X_train_scaled.shape[1],
                output_size=output_size,
                training_id=training_id,
                training_stop_flags=training_stop_flags
            )
            
            if timeseries_results and fold_models:
                # ✅ Sélectionner le meilleur fold
                best_fold_idx = np.argmax(val_scores)
                final_model = fold_models[best_fold_idx]
                used_validation_model = True
                
                # Extraire les scores d'entraînement
                train_scores = [fold.get('train_score', 0) for fold in timeseries_results]
                
                validation_results = {
                    "method": f"TimeSeries Split ({len(timeseries_results)} valid folds / {n_splits} total)",
                    "fold_details": timeseries_results,
                    
                    # Scores moyens
                    "mean_score": float(np.mean(val_scores)),
                    "std_score": float(np.std(val_scores)),
                    "cv_validation_r2_mean": float(np.mean(val_scores)),
                    "cv_validation_r2_std": float(np.std(val_scores)),
                    "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0,
                    "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0,
                    
                    # Meilleur fold
                    "best_fold": int(best_fold_idx + 1),
                    "best_score": float(val_scores[best_fold_idx]),
                    "best_fold_score": float(val_scores[best_fold_idx]),
                    
                    # Paramètres TimeSeries
                    "date_column": date_column,
                    "date_column_excluded": True,
                    "features_used": feature_columns,
                    "n_splits": n_splits,
                    "test_size": test_size,
                    "gap": gap
                }
                
                logger.info(f"🎯 Meilleur fold: {best_fold_idx + 1}, Score: {val_scores[best_fold_idx]:.4f}")
                logger.info(f"📊 Scores validation: moyenne={np.mean(val_scores):.4f}, écart-type={np.std(val_scores):.4f}")
            else:
                logger.error("❌ Aucun résultat valide pour TimeSeriesSplit")
                raise HTTPException(500, "TimeSeriesSplit failed to produce valid results")
        
        elif request.validation_method == "holdout":
            # ✅ HOLD-OUT RÉPÉTÉ
            test_size = 0.2
            logger.info(f"🔁 Hold-Out répété: {request.n_repetitions} répétitions sur train set")
            
            holdout_scores, holdout_models, repetition_details = mlp_holdout_repeated_with_stop(
                X_train_scaled, y_train_encoded_np, 
                request.n_repetitions, test_size,
                model_params, problem_type,
                training_id, training_stop_flags
            ) 
            
            if holdout_scores:
                best_validation_model_idx = np.argmax(holdout_scores)
                final_model = holdout_models[best_validation_model_idx]
                used_validation_model = True
                
                train_scores = [rep.get('score', 0) for rep in repetition_details]
                
                validation_results = {
                    "method": f"Hold-Out Repeated ({request.n_repetitions} repetitions)",
                    "scores": [float(score) for score in holdout_scores],
                    "mean_score": float(np.mean(holdout_scores)),
                    "std_score": float(np.std(holdout_scores)),
                    "cv_validation_r2_mean": float(np.mean(holdout_scores)),
                    "cv_validation_r2_std": float(np.std(holdout_scores)),
                    "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0,
                    "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0,
                    "best_repetition": int(best_validation_model_idx + 1),
                    "best_score": float(holdout_scores[best_validation_model_idx]),
                    "repetition_details": repetition_details,
                    "test_size": test_size,
                    "n_repetitions": request.n_repetitions
                }
                
                logger.info(f"🎯 Using best hold-out model from repetition {best_validation_model_idx + 1} with score: {holdout_scores[best_validation_model_idx]:.4f}")
            else:
                raise HTTPException(500, "Hold-Out validation failed to produce results")

        elif request.validation_method and request.validation_method.startswith('cv_'):
            cv_params = request.cv_params or {}
            n_splits = cv_params.get('n_splits', 5)
            shuffle = cv_params.get('shuffle', True)
            
            if request.validation_method == "cv_kfold":
                cv = KFold(n_splits=n_splits, shuffle=shuffle, random_state=None)
                method_name = "Cross-Validation (KFold)"
            elif request.validation_method == "cv_repeatedkfold":
                n_repeats = cv_params.get('n_repeats', 3)
                cv = RepeatedKFold(n_splits=n_splits, n_repeats=n_repeats, random_state=None)
                method_name = "Cross-Validation (Repeated KFold)"
            elif request.validation_method == "cv_shufflesplit":
                test_size = cv_params.get('test_size', 0.2)
                cv = ShuffleSplit(n_splits=n_splits, test_size=test_size, random_state=None)
                method_name = "Cross-Validation (Shuffle Split)"
            
            logger.info(f"🔍 MLP CROSS-VALIDATION STARTED - Method: {method_name}")
            
            cv_scores, cv_models, fold_details = mlp_cv_with_stop(
                X_train_scaled, y_train_encoded_np, cv, model_params, problem_type,
                training_id, training_stop_flags
            )
            
            if cv_scores:
                best_fold_idx = np.argmax(cv_scores)
                final_model = cv_models[best_fold_idx]
                used_validation_model = True
                
                train_scores = [fold.get('train_score', 0) for fold in fold_details]
                
                validation_results = {
                    "method": method_name,
                    "cv_scores": [float(score) for score in cv_scores],
                    "cv_mean": float(np.mean(cv_scores)),
                    "cv_std": float(np.std(cv_scores)),
                    "cv_validation_r2_mean": float(np.mean(cv_scores)),
                    "cv_validation_r2_std": float(np.std(cv_scores)),
                    "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0,
                    "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0,
                    "n_splits": n_splits,
                    "fold_details": fold_details,
                    "best_fold": int(best_fold_idx + 1),
                    "best_fold_score": float(cv_scores[best_fold_idx])
                }
                
                if request.validation_method == "cv_repeatedkfold":
                    validation_results["n_repeats"] = n_repeats
                elif request.validation_method == "cv_shufflesplit":
                    validation_results["test_size"] = test_size
                
                logger.info(f"🎯 Using best CV model from fold {best_fold_idx + 1} with score: {cv_scores[best_fold_idx]:.4f}")
            else:
                raise HTTPException(500, "Cross-Validation failed to produce results")

        elif request.validation_method == "bootstrap":
            bootstrap_params = request.bootstrap_params or {}
            n_bootstraps = bootstrap_params.get('n_bootstraps', 100)
            test_size = bootstrap_params.get('test_size', 0.2)
            
            logger.info(f"🔄 TRUE Bootstrap: {n_bootstraps} échantillons (avec remise)")
            
            bootstrap_scores, bootstrap_models, bootstrap_details = mlp_bootstrap_with_stop(
                X_train_scaled, y_train_encoded_np, n_bootstraps, test_size, model_params, problem_type,
                training_id, training_stop_flags
            )
            
            if bootstrap_scores:
                median_idx = np.argsort(bootstrap_scores)[len(bootstrap_scores) // 2]
                final_model = bootstrap_models[median_idx]
                used_validation_model = True
                
                train_scores = [bs.get('train_score', 0) for bs in bootstrap_details]
                
                validation_results = {
                    "method": "True Bootstrap (with replacement)",
                    "bootstrap_scores": [float(score) for score in bootstrap_scores],
                    "bootstrap_mean": float(np.mean(bootstrap_scores)),
                    "bootstrap_std": float(np.std(bootstrap_scores)),
                    "cv_validation_r2_mean": float(np.mean(bootstrap_scores)),
                    "cv_validation_r2_std": float(np.std(bootstrap_scores)),
                    "cv_train_r2_mean": float(np.mean(train_scores)) if train_scores else 0,
                    "cv_train_r2_std": float(np.std(train_scores)) if train_scores else 0,
                    "n_bootstraps": n_bootstraps,
                    "test_size": test_size,
                    "median_bootstrap_index": int(median_idx + 1),
                    "median_bootstrap_score": float(bootstrap_scores[median_idx]),
                    "bootstrap_details": bootstrap_details
                }
                
                logger.info(f"🎯 Using median bootstrap model (index {median_idx}) with score: {bootstrap_scores[median_idx]:.4f}")
            else:
                raise HTTPException(500, "Bootstrap validation failed to produce results")

        else:
            # HOLDOUT SIMPLE
            logger.info("🔧 Using standard hold-out validation")
            
            check_stop()
            
            # Split validation set from training
            X_train_split, X_val_split, y_train_split, y_val_split = train_test_split(
                X_train_scaled, y_train_encoded_np, 
                test_size=request.validation_split,
                random_state=42,
                stratify=y_train_labels if is_classification else None
            )
            
            # Entraînement du modèle
            training_result = train_mlp_model_single_with_stop(
                X_train=X_train_split,
                y_train=y_train_split,
                X_val=X_val_split,
                y_val=y_val_split,
                input_size=X_train_split.shape[1],
                output_size=output_size,
                params=model_params,
                problem_type=problem_type,
                training_id=training_id,
                training_stop_flags=training_stop_flags,
                fold_or_rep_info="final_model"
            )
            
            final_model = training_result['model']
            used_validation_model = False
            
            validation_results = {
                "method": "Hold-out Validation",
                "parameters_optimized": False,
                "model_class": "MLPClassifier" if is_classification else "MLPRegressor",
                "user_parameters": model_params,
                "validation_split_used": request.validation_split,
                "optimization_note": "No parameter optimization - using user-provided parameters",
                "training_history": training_result['history'],
                "best_val_loss": float(training_result['best_val_loss'])
            }

        # Vérification que final_model n'est pas None
        if final_model is None:
            if training_id and training_stop_flags.get(training_id, False):
                raise HTTPException(400, "Training stopped by user")
            else:
                raise HTTPException(500, "Model training failed. No valid model was created.")

        check_stop()

        # ==================== ÉVALUATION FINALE SUR LE TEST SET ====================
        logger.info("🧪 Starting final evaluation on test set")
        
        device = next(final_model.parameters()).device
        
        # Convert test data to tensor
        X_test_tensor = torch.FloatTensor(X_test_scaled).to(device)
        
        # Get predictions
        final_model.eval()
        with torch.no_grad():
            test_outputs = final_model(X_test_tensor)
            
            if is_classification:
                if problem_type == 'multiclass_classification':
                    y_pred = torch.argmax(test_outputs, dim=1).cpu().numpy()
                    y_proba = torch.softmax(test_outputs, dim=1).cpu().numpy()
                else:  # binary classification
                    y_pred = (test_outputs > 0.5).float().cpu().numpy().flatten()
                    y_proba = test_outputs.cpu().numpy()
            else:  # regression
                y_pred = test_outputs.cpu().numpy().flatten()
                y_proba = None

        check_stop()

        # ==================== CALCUL DES MÉTRIQUES ====================
        logger.info("📊 Calculating performance metrics...")

        if is_classification:
            accuracy = accuracy_score(y_test_labels, y_pred)
            precision = precision_score(y_test_labels, y_pred, average='weighted', zero_division=0)
            recall = recall_score(y_test_labels, y_pred, average='weighted', zero_division=0)
            f1 = f1_score(y_test_labels, y_pred, average='weighted', zero_division=0)
            
            X_train_tensor_for_eval = torch.FloatTensor(X_train_scaled).to(device)
            final_model.eval()
            with torch.no_grad():
                train_outputs = final_model(X_train_tensor_for_eval)
                if problem_type == 'multiclass_classification':
                    y_pred_train = torch.argmax(train_outputs, dim=1).cpu().numpy()
                else:
                    y_pred_train = (train_outputs > 0.5).float().cpu().numpy().flatten()
            
            train_accuracy = accuracy_score(y_train_labels, y_pred_train)
            
            conf_matrix = confusion_matrix(y_test_labels, y_pred)
            
            if len(class_names) == 2:
                tn, fp, fn, tp = conf_matrix.ravel()
                confusion_matrix_dict = {
                    'true_negative': int(tn),
                    'false_positive': int(fp),
                    'false_negative': int(fn),
                    'true_positive': int(tp),
                    'labels': [str(c) for c in class_names]
                }
            else:
                confusion_matrix_dict = {
                    'matrix': conf_matrix.tolist(),
                    'labels': [str(c) for c in class_names]
                }

            classification_rep = classification_report(
                y_test_labels, y_pred, 
                target_names=[str(c) for c in class_names],
                output_dict=True,
                zero_division=0
            )

            roc_auc = None
            if y_proba is not None:
                if problem_type == 'multiclass_classification' and len(class_names) == 2:
                    roc_auc = roc_auc_score(y_test_labels, y_proba[:, 1])
                elif problem_type == 'binary_classification':
                    roc_auc = roc_auc_score(y_test_labels, y_proba.flatten())

            logger.info(f"✅ Classification results - Accuracy: {accuracy:.4f}, F1: {f1:.4f}")

        else:
            # Regression
            r2 = r2_score(y_test_labels, y_pred)
            mse = mean_squared_error(y_test_labels, y_pred)
            mae = mean_absolute_error(y_test_labels, y_pred)
            
            X_train_tensor_for_eval = torch.FloatTensor(X_train_scaled).to(device)
            final_model.eval()
            with torch.no_grad():
                train_outputs = final_model(X_train_tensor_for_eval)
                y_pred_train = train_outputs.cpu().numpy().flatten()
            
            train_r2 = r2_score(y_train_labels, y_pred_train)
            train_mse = mean_squared_error(y_train_labels, y_pred_train)
            train_mae = mean_absolute_error(y_train_labels, y_pred_train)

            logger.info(f"✅ Regression results - R²: {r2:.4f}, MSE: {mse:.4f}")

        check_stop()

        # ==================== CONSTRUCTION DES MÉTRIQUES COMPLÈTES ====================

        # Récupérer le training history
        training_history_value = None
        if used_validation_model:
            if request.validation_method == "cv_timeseries" and validation_results.get('fold_details'):
                best_fold_index = validation_results.get('best_fold', 1) - 1
                if 0 <= best_fold_index < len(validation_results['fold_details']):
                    training_history_value = validation_results['fold_details'][best_fold_index].get('training_history')
            elif request.validation_method.startswith('cv_') and validation_results.get('fold_details'):
                best_fold_index = validation_results.get('best_fold', 1) - 1
                if 0 <= best_fold_index < len(validation_results['fold_details']):
                    training_history_value = validation_results['fold_details'][best_fold_index].get('training_history')
            elif request.validation_method == "bootstrap" and validation_results.get('bootstrap_details'):
                median_index = validation_results.get('median_bootstrap_index', 1) - 1
                if 0 <= median_index < len(validation_results['bootstrap_details']):
                    training_history_value = validation_results['bootstrap_details'][median_index].get('training_history')
            elif request.validation_method == "holdout" and validation_results.get('repetition_details'):
                best_rep_index = validation_results.get('best_repetition', 1) - 1
                if 0 <= best_rep_index < len(validation_results['repetition_details']):
                    training_history_value = validation_results['repetition_details'][best_rep_index].get('training_history')
        else:
            training_history_value = training_result['history'] if training_result else None

        metrics = {
            "model_type": "mlp",
            "is_classification": is_classification,
            "problem_type": problem_type,
            "model_class": "MLPClassifier" if is_classification else "MLPRegressor",
            "target_analysis": target_analysis,
            
            "layers_used": request.layers,
            "activation_used": request.activation,
            "dropout_rate_used": request.dropout_rate,
            "learning_rate_used": request.learning_rate,
            "batch_size_used": request.batch_size,
            "parameters_source": "user",
            
            "model_architecture": final_model.architecture if hasattr(final_model, 'architecture') else [],
            
            "training_history": training_history_value,
            
            "validation_results": convert_numpy_types(validation_results) if validation_results else None,
            
            "predictions": {
                "y_true": y_test_labels.tolist(),
                "y_pred": y_pred.tolist(),
                "y_proba": y_proba.tolist() if y_proba is not None else None,
            }
        }

        if is_classification:
            metrics.update({
                "accuracy": float(accuracy),
                "precision": float(precision),
                "recall": float(recall),
                "f1": float(f1),
                "roc_auc": float(roc_auc) if roc_auc is not None else None,
                "train_accuracy": float(train_accuracy),
                "confusion_matrix": confusion_matrix_dict,
                "classification_report": classification_rep,
                "classes": [str(c) for c in class_names] if class_names else [],
                "n_classes": len(class_names) if class_names else 0,
            })
        else:
            metrics.update({
                "r2": float(r2),
                "mse": float(mse),
                "mae": float(mae),
                "train_r2": float(train_r2),
                "train_mse": float(train_mse),
                "train_mae": float(train_mae),
                "errors": {
                    "absolute": (y_test_labels - y_pred).tolist(),
                    "relative": ((y_test_labels - y_pred) / (np.abs(y_test_labels) + 1e-10)).tolist()
                }
            })

        check_stop()

        # ==================== SERIALISATION DU MODÈLE ====================
        try:
            model_bytes = io.BytesIO()
            model_data = {
                'model': final_model,
                'feature_names': feature_columns,
                'is_classification': is_classification,
                'problem_type': problem_type,
                'class_names': class_names if is_classification else None,
                'scaler': scaler if request.use_scaling else None,
                'final_parameters': model_params.copy(),
                'validation_method': request.validation_method,
                'used_validation_model': used_validation_model
            }
            torch.save(model_data, model_bytes)
            model_bytes.seek(0)
            model_base64 = base64.b64encode(model_bytes.read()).decode('utf-8')
            logger.info("💾 MLP model serialized successfully")
        except Exception as e:
            logger.error(f"❌ Error during MLP model serialization: {str(e)}")
            model_base64 = None

        check_stop()

        # ==================== RÉPONSE FINALE ====================
        response_data = {
            "status": "success",
            "model_type": "mlp",
            "model_object": model_base64,
            "framework": "pytorch",
            "dataset_used": request.numerized_dataset_name,
            "metrics": convert_numpy_types(metrics),
            "timestamp": datetime.now().isoformat(),
            "validation_method": request.validation_method,
            "parameters_optimized": False,
            "training_info": {
                "model_trained_once": not used_validation_model,
                "used_cv_best_model": used_validation_model and request.validation_method.startswith('cv_'),
                "used_bootstrap_model": used_validation_model and request.validation_method == "bootstrap",
                "used_holdout_model": used_validation_model and request.validation_method == "holdout",
                "used_timeseries_model": used_validation_model and request.validation_method == "cv_timeseries",
                "training_samples": len(X_train_scaled),
                "test_samples": len(X_test_scaled),
                "parameter_optimization": "User parameters used - no optimization",
                "final_model_source": f"best_{request.validation_method}_fold_{validation_results.get('best_fold', 1)}" 
                                    if used_validation_model and request.validation_method == "cv_timeseries" 
                                    else "best_cv_fold" if used_validation_model and request.validation_method.startswith('cv_') 
                                    else "median_bootstrap" if used_validation_model and request.validation_method == "bootstrap" 
                                    else "best_holdout_repetition" if used_validation_model and request.validation_method == "holdout"
                                    else "standard_holdout",
                "early_stopping_used": request.patience > 0,
                "training_id": training_id,
                "date_column_excluded": validation_method == "cv_timeseries" or date_column is not None
            }
        }

        logger.info("=== MLP PYTORCH TRAINING COMPLETED SUCCESSFULLY ===")
        
        if is_classification:
            logger.info(f"📊 FINAL RESULTS - Accuracy: {accuracy:.4f}, Precision: {precision:.4f}, Recall: {recall:.4f}, F1: {f1:.4f}")
        else:
            logger.info(f"📊 FINAL RESULTS - R²: {r2:.4f}, MSE: {mse:.4f}, MAE: {mae:.4f}")
        
        return response_data
        
    except HTTPException as he:
        if he.detail == "Training stopped by user":
            logger.info(f"🛑 MLP training {training_id} stopped by user")
        raise
    except Exception as e:
        logger.error(f"❌ Error in train_mlp_pytorch: {str(e)}", exc_info=True)
        error_detail = {
            "error_message": str(e),
            "error_type": type(e).__name__,
        }
        raise HTTPException(status_code=500, detail=error_detail)

# ==================== ROUTE PRINCIPALE ====================
@router.post("/train-mlp-pytorch")
async def train_mlp_pytorch(
    request: TrainMLPRequest,
    background_tasks: BackgroundTasks = None,
    current_user_id: str = Depends(get_current_user2)
):
    # ========== 1. MODE ASYNCHRONE (BACKGROUND) - AVEC ARRÊT RÉEL ==========
    if hasattr(request, 'training_id') and request.training_id and background_tasks is not None:
        training_id = request.training_id
        
        # ✅ CRITIQUE: Initialiser le flag d'arrêt
        training_stop_flags[training_id] = False
        
        def train_in_background():
            import asyncio
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)
            
            try:
                # Créer une nouvelle requête SANS training_id pour éviter la boucle
                new_request = request.copy()
                new_request.training_id = None
        
                # ✅ CRITIQUE: Exécuter l'entraînement avec vérification d'arrêt
                result = loop.run_until_complete(
                    train_mlp_pytorch_with_stop_check(new_request, None, current_user_id, training_id)
                )
        
                # ✅ Marquer comme complété SEULEMENT si pas arrêté par l'utilisateur
                if training_id in active_trainings and not training_stop_flags.get(training_id, False):
                    active_trainings[training_id]['completed'] = True
                    active_trainings[training_id]['result'] = result
                    _safe_set_training_result(training_id, result)
                    logger.info(f"✅ MLP training {training_id} completed successfully")
                
            except Exception as e:
                # ✅ Gestion spéciale pour l'arrêt utilisateur
                error_msg = str(e)
                if "Training stopped by user" in error_msg:
                    logger.info(f"🛑 MLP training {training_id} was stopped by user")
                    if training_id in active_trainings:
                        active_trainings[training_id]['completed'] = True
                        active_trainings[training_id]['error'] = "Training stopped by user"
                        active_trainings[training_id]['result'] = None
                        _safe_set_training_error(training_id, 'Training stopped by user', stopped=True)
                else:
                    logger.error(f"❌ Erreur dans train_mlp_pytorch background: {error_msg}")
                    if training_id in active_trainings:
                        error_result = {
                            "status": "error",
                            "error_message": error_msg,
                            "error_type": type(e).__name__
                        }
                        active_trainings[training_id]['completed'] = True
                        active_trainings[training_id]['result'] = error_result
                        active_trainings[training_id]['error'] = error_msg
                        _safe_set_training_error(training_id, error_msg, stopped=False)
            finally:
                # ✅ Nettoyer le flag d'arrêt
                if training_id in training_stop_flags:
                    del training_stop_flags[training_id]
                loop.close()
        
        from concurrent.futures import Future
        future = Future()
        
        active_trainings[training_id] = {
            'future': future,
            'user_id': current_user_id,
            'start_time': datetime.now(),
            'model_type': 'mlp',
            'completed': False,
            'result': None,
            'error': None,
            'retrieved': False
        }
        
        background_tasks.add_task(train_in_background)
        
        # ✅ RETOURNER IMMÉDIATEMENT
        return {
            "status": "training_started",
            "training_id": training_id,
            "message": "MLP training started in background"
        }
    
    # ========== 2. MODE SYNCHRONE (EXÉCUTION NORMALE) ==========
    return await train_mlp_pytorch_with_stop_check(request, background_tasks, current_user_id, None)
"""@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@"""
'''+++++++++++++++++ KMeans Model +++++++++++++++++'''

logger = logging.getLogger(__name__)

# ==================== DICTIONNAIRES GLOBAUX POUR SUIVI ====================
active_trainings = {}
training_stop_flags = {}

# ==================== FONCTIONS UTILITAIRES ====================
def convert_numpy_types(obj):
    """Convertit les types numpy en types Python natifs"""
    if isinstance(obj, (np.integer, np.int32, np.int64)):
        return int(obj)
    elif isinstance(obj, (np.floating, np.float32, np.float64)):
        return float(obj)
    elif isinstance(obj, np.ndarray):
        return obj.tolist()
    elif isinstance(obj, np.bool_):
        return bool(obj)
    elif isinstance(obj, dict):
        return {key: convert_numpy_types(value) for key, value in obj.items()}
    elif isinstance(obj, list):
        return [convert_numpy_types(item) for item in obj]
    elif isinstance(obj, tuple):
        return tuple(convert_numpy_types(item) for item in obj)
    else:
        return obj

def get_table_columns(cursor, table_name):
    """Récupère toutes les colonnes d'une table"""
    cursor.execute("""
        SELECT column_name 
        FROM information_schema.columns 
        WHERE table_name = %s 
        ORDER BY ordinal_position
    """, (table_name.lower(),))
    return [row[0] for row in cursor.fetchall()]

def detect_date_columns(df, sample_size=20):
    """
    Détecte les colonnes qui contiennent des dates
    Retourne une liste des noms de colonnes qui sont des dates
    """
    date_columns = []
    
    # Formats de date à vérifier
    date_formats = [
        '%Y-%m-%d %H:%M:%S',
        '%Y-%m-%d %H:%M',
        '%Y-%m-%d %H:%M:%S.%f',
        '%Y-%m-%dT%H:%M:%S',
        '%Y-%m-%dT%H:%M',
        '%Y-%m-%d %H:%M:%S%z',
        '%d-%m-%Y',
        '%Y/%m/%d',
        '%Y-%m-%d',
        '%d/%m/%Y',
        '%Y.%m.%d',
        '%d.%m.%Y',
        '%Y%m%d',
        '%d-%m-%Y %H:%M',
        '%Y-%m-%dT%H:%M:%S%z'
    ]
    
    for col in df.columns:
        if col == 'split_type':
            continue
            
        # Prendre un échantillon de valeurs non nulles
        sample_values = df[col].dropna().head(sample_size).astype(str)
        if len(sample_values) == 0:
            continue
        
        # Compter combien de valeurs sont des dates
        date_count = 0
        for val in sample_values:
            val = val.strip()
            for fmt in date_formats:
                try:
                    pd.to_datetime(val, format=fmt, errors='raise')
                    date_count += 1
                    break
                except:
                    continue
        
        # Si plus de 80% des valeurs sont des dates, c'est une colonne date
        if date_count / len(sample_values) > 0.8:
            logger.info(f"📅 Colonne date détectée: {col} ({date_count}/{len(sample_values)} valeurs)")
            date_columns.append(col)
    
    return date_columns

# ==================== CLASSE DE REQUÊTE ====================
class TrainKMeansRequest(BaseModel):
    numerized_dataset_name: str
    original_dataset_name: str
    model_type: Literal["kmeans"] = "kmeans"
    n_clusters: int = Field(8, gt=1, le=20, description="Number of clusters to form")
    init: str = Field("k-means++", pattern=r"^(k-means\+\+|random)$")
    n_init: int = Field(10, gt=0, description="Number of time the k-means algorithm will be run")
    max_iter: int = Field(300, gt=0, description="Maximum number of iterations")
    tol: float = Field(1e-4, gt=0, description="Relative tolerance to declare convergence")
    random_state: Optional[int] = Field(42, description="Random seed for reproducibility")
    algorithm: str = Field("lloyd", pattern="^(lloyd|elkan)$")
    use_scaling: bool = Field(True, description="Whether to scale features before clustering")
    
    # ✅ Colonne date pour exclusion
    date_column: Optional[str] = Field(
        default=None,
        description="Date column to exclude from features"
    )
    
    # ✅ training_id POUR LE MODE ASYNCHRONE
    training_id: Optional[str] = None

# ==================== FONCTION DE PRÉPARATION DES DONNÉES ====================
def prepare_data_for_kmeans(df, date_column=None):
    """
    Prépare les données pour KMeans en excluant les colonnes de date
    """
    logger.info("🔧 PREPARATION DES DONNEES POUR KMEANS")
    
    # Créer une copie pour éviter de modifier l'original
    df_processed = df.copy()
    
    # Identifier les colonnes à exclure
    exclude_columns = ['id', 'split_type']
    
    # ✅ Exclure la colonne date si elle est spécifiée
    if date_column:
        logger.info(f"🚫 Exclusion de la colonne date: {date_column}")
        exclude_columns.append(date_column)
    
    # Détecter automatiquement les autres colonnes de date
    auto_detected_dates = detect_date_columns(df_processed)
    for date_col in auto_detected_dates:
        if date_col not in exclude_columns:
            logger.info(f"🚫 Exclusion automatique de la colonne date: {date_col}")
            exclude_columns.append(date_col)
    
    # Colonnes features (tout sauf les exclues)
    feature_columns = [col for col in df_processed.columns if col not in exclude_columns]
    logger.info(f"📊 Features utilisées pour le clustering: {feature_columns}")
    logger.info(f"🚫 Colonnes exclues: {exclude_columns}")
    
    # Extraire les données
    X_raw = df_processed[feature_columns].copy()
    
    # Conversion numérique ROBUSTE avec gestion des erreurs
    for col in X_raw.columns:
        try:
            X_raw.loc[:, col] = pd.to_numeric(X_raw[col], errors='coerce')
            nan_count = X_raw[col].isna().sum()
            if nan_count > 0:
                logger.warning(f"⚠️ {nan_count} NaN dans {col} après conversion")
        except Exception as e:
            logger.error(f"❌ Erreur conversion {col}: {e}")
            X_raw.loc[:, col] = 0.0
    
    # ✅ Remplir les NaN avec la médiane
    medians = X_raw.median(numeric_only=True)
    X = X_raw.fillna(medians)
    
    # ✅ Vérification finale des NaN
    if X.isna().any().any():
        X = X.fillna(0)
    
    logger.info(f"✅ Préparation terminée: X shape {X.shape}")
    
    return X, feature_columns

# ==================== FONCTION PRINCIPALE AVEC VÉRIFICATION D'ARRÊT ====================
async def train_kmeans_with_stop_check(
    request: TrainKMeansRequest,
    background_tasks: BackgroundTasks = None,
    current_user_id: str = None,
    training_id: str = None
):
    """Version de train_kmeans avec vérification d'arrêt à chaque étape"""
    
    # ✅ Fonction de vérification d'arrêt
    def check_stop():
        if training_id and training_stop_flags.get(training_id, False):
            logger.info(f"🛑 KMeans training {training_id} stopped by user (check_stop triggered)")
            raise HTTPException(400, "Training stopped by user")
    
    try:
        # ==================== VÉRIFICATION D'ARRÊT ====================
        check_stop()
        
        logger.info("=== KMEANS TRAINING STARTED ===")
        if training_id:
            logger.info(f"🎫 Training ID: {training_id}")
        logger.info(f"📊 Parameters: n_clusters={request.n_clusters}, use_scaling={request.use_scaling}")

        # ==================== INITIAL VALIDATION ====================
        if not request.numerized_dataset_name or not request.original_dataset_name:
            raise HTTPException(400, "Dataset names are required")
        
        check_stop()

        # ==================== DATA LOADING ====================
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Verify dataset access
                cur.execute("""
                    SELECT 1 FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (request.numerized_dataset_name.lower(), current_user_id))
                
                if not cur.fetchone():
                    raise HTTPException(404, "Numerized dataset not found or access denied")
                
                check_stop()

                # Get all columns
                all_columns = get_table_columns(cur, request.numerized_dataset_name)
                if not all_columns:
                    raise HTTPException(404, "No columns found")
                
                check_stop()

                # Build SQL query (exclude id and split_type if present)
                select_columns = [
                    sql.Identifier(col) 
                    for col in all_columns 
                    if col not in ['id', 'split_type']
                ]

                query = sql.SQL("""
                    SELECT {columns} FROM {table}
                """).format(
                    columns=sql.SQL(',').join(select_columns),
                    table=sql.Identifier(request.numerized_dataset_name.lower())
                )

                cur.execute(query)
                rows = cur.fetchall()
                check_stop()

        # ==================== DATA PREPARATION ====================
        df_columns = [col for col in all_columns if col not in ['id', 'split_type']]
        df = pd.DataFrame(rows, columns=df_columns)
        check_stop()

        # ✅ Utiliser la fonction de préparation qui exclut les colonnes date
        X, feature_columns = prepare_data_for_kmeans(df, request.date_column)
        
        check_stop()

        # Convertir en numpy array
        X_np = X.values
        
        # Scale data if requested
        if request.use_scaling:
            scaler = StandardScaler()
            X_scaled = scaler.fit_transform(X_np)
        else:
            scaler = None
            X_scaled = X_np
        
        check_stop()

        # ==================== MODEL TRAINING ====================
        logger.info(f"🏋️ Training KMeans with {request.n_clusters} clusters on {len(X_scaled)} samples")
        
        model = KMeans(
            n_clusters=request.n_clusters,
            init=request.init,
            n_init=request.n_init,
            max_iter=request.max_iter,
            tol=request.tol,
            random_state=request.random_state,
            algorithm=request.algorithm
        )
        
        check_stop()
        
        # Fit the model
        labels = model.fit_predict(X_scaled)
        
        check_stop()
        
        # Calculate metrics
        silhouette = silhouette_score(X_scaled, labels)
        check_stop()
        
        calinski = calinski_harabasz_score(X_scaled, labels)
        check_stop()
        
        davies = davies_bouldin_score(X_scaled, labels)
        check_stop()

        # Get cluster centers (original scale if scaling was applied)
        if request.use_scaling:
            cluster_centers = scaler.inverse_transform(model.cluster_centers_)
        else:
            cluster_centers = model.cluster_centers_

        check_stop()

        # Prepare cluster info
        cluster_info = []
        for i, center in enumerate(cluster_centers):
            check_stop()
            cluster_info.append({
                "cluster_id": i,
                "center": center.tolist(),
                "size": int(np.sum(labels == i)),
                "features": dict(zip(feature_columns, center))
            })

        check_stop()

        # Prepare PCA components for visualization (2D and 3D)
        pca_2d = PCA(n_components=2)
        pca_3d = PCA(n_components=3)
        
        X_pca_2d = pca_2d.fit_transform(X_scaled)
        check_stop()
        
        X_pca_3d = pca_3d.fit_transform(X_scaled)
        check_stop()
        
        # Prepare data points with cluster assignments
        points_2d = []
        points_3d = []
        
        for idx, (point_2d, point_3d) in enumerate(zip(X_pca_2d, X_pca_3d)):
            check_stop()  # Vérification périodique
            points_2d.append({
                "x": float(point_2d[0]),
                "y": float(point_2d[1]),
                "cluster": int(labels[idx]),
                "original_index": idx
            })
            
            points_3d.append({
                "x": float(point_3d[0]),
                "y": float(point_3d[1]),
                "z": float(point_3d[2]),
                "cluster": int(labels[idx]),
                "original_index": idx
            })

        check_stop()

        # Prepare cluster centers in PCA space
        centers_pca_2d = pca_2d.transform(model.cluster_centers_)
        centers_pca_3d = pca_3d.transform(model.cluster_centers_)
            
        centers_2d = []
        centers_3d = []
        
        for i, (center_2d, center_3d) in enumerate(zip(centers_pca_2d, centers_pca_3d)):
            check_stop()
            centers_2d.append({
                "x": float(center_2d[0]),
                "y": float(center_2d[1]),
                "cluster": i
            })
            
            centers_3d.append({
                "x": float(center_3d[0]),
                "y": float(center_3d[1]),
                "z": float(center_3d[2]),
                "cluster": i
            })

        check_stop()

        # Prepare metrics
        metrics = {
            "silhouette_score": float(silhouette),
            "calinski_harabasz_score": float(calinski),
            "davies_bouldin_score": float(davies),
            "inertia": float(model.inertia_),
            "n_iter": int(model.n_iter_),
            "cluster_info": cluster_info,
            "visualization_data": {
                "2d": {
                    "points": points_2d,
                    "centers": centers_2d,
                    "explained_variance": pca_2d.explained_variance_ratio_.tolist()
                },
                "3d": {
                    "points": points_3d,
                    "centers": centers_3d,
                    "explained_variance": pca_3d.explained_variance_ratio_.tolist()
                }
            },
            "feature_names": feature_columns,
            "n_samples": len(X_scaled),
            "n_features": X_scaled.shape[1],
            "date_columns_excluded": [col for col in detect_date_columns(df) if col != request.date_column] if request.date_column else detect_date_columns(df)
        }

        check_stop()

        # Serialize the model
        model_bytes = io.BytesIO()
        joblib.dump({
            'model': model,
            'scaler': scaler if request.use_scaling else None,
            'feature_names': feature_columns,
            'date_columns_excluded': metrics["date_columns_excluded"]
        }, model_bytes)
        model_bytes.seek(0)
        model_base64 = base64.b64encode(model_bytes.read()).decode('utf-8')
        
        check_stop()

        # Prepare the response with all the necessary data
        response_data = {
            "status": "success",
            "model_type": "kmeans",
            "model_object": model_base64,
            "metrics": convert_numpy_types(metrics),
            "timestamp": datetime.now().isoformat(),
            "visualization_data": {
                "2d": {
                    "points": points_2d,
                    "centers": centers_2d,
                    "explained_variance": pca_2d.explained_variance_ratio_.tolist()
                },
                "3d": {
                    "points": points_3d,
                    "centers": centers_3d,
                    "explained_variance": pca_3d.explained_variance_ratio_.tolist()
                }
            },
            "training_info": {
                "training_samples": len(X_scaled),
                "feature_scaling": "StandardScaler applied" if request.use_scaling else "No scaling applied",
                "n_clusters": request.n_clusters,
                "n_init": request.n_init,
                "max_iter": request.max_iter,
                "date_columns_excluded": metrics["date_columns_excluded"],
                "date_column_provided": request.date_column if request.date_column else "None"
            }
        }

        logger.info("=== KMEANS TRAINING COMPLETED SUCCESSFULLY ===")
        logger.info(f"📊 Silhouette Score: {silhouette:.4f}, Inertia: {model.inertia_:.2f}")
        if metrics["date_columns_excluded"]:
            logger.info(f"🚫 Colonnes date exclues: {metrics['date_columns_excluded']}")
        
        return response_data
        
    except HTTPException as he:
        # ✅ Propager l'exception d'arrêt utilisateur
        if he.detail == "Training stopped by user":
            logger.info(f"🛑 KMeans training {training_id} stopped by user")
        raise
    except Exception as e:
        logger.error(f"❌ Error in train_kmeans: {str(e)}", exc_info=True)
        raise HTTPException(
            status_code=500,
            detail={
                "error_message": str(e),
                "error_type": type(e).__name__,
            }
        )

# ==================== ROUTE PRINCIPALE ====================
@router.post("/train-kmeans")
async def train_kmeans(
    request: TrainKMeansRequest,
    background_tasks: BackgroundTasks = None,
    current_user_id: str = Depends(get_current_user2)
):
    # ========== 1. MODE ASYNCHRONE (BACKGROUND) - AVEC ARRÊT RÉEL ==========
    if hasattr(request, 'training_id') and request.training_id and background_tasks is not None:
        training_id = request.training_id
        
        # ✅ CRITIQUE: Initialiser le flag d'arrêt
        training_stop_flags[training_id] = False
        
        def train_in_background():
            import asyncio
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)
            
            try:
                # Créer une nouvelle requête SANS training_id pour éviter la boucle
                new_request = request.copy()
                new_request.training_id = None
        
                # ✅ CRITIQUE: Exécuter l'entraînement avec vérification d'arrêt
                result = loop.run_until_complete(
                    train_kmeans_with_stop_check(new_request, None, current_user_id, training_id)
                )
        
                # ✅ Marquer comme complété SEULEMENT si pas arrêté par l'utilisateur
                if training_id in active_trainings and not training_stop_flags.get(training_id, False):
                    active_trainings[training_id]['completed'] = True
                    active_trainings[training_id]['result'] = result
                    _safe_set_training_result(training_id, result)
                    logger.info(f"✅ KMeans training {training_id} completed successfully")
                
            except Exception as e:
                # ✅ Gestion spéciale pour l'arrêt utilisateur
                error_msg = str(e)
                if "Training stopped by user" in error_msg:
                    logger.info(f"🛑 KMeans training {training_id} was stopped by user")
                    if training_id in active_trainings:
                        active_trainings[training_id]['completed'] = True
                        active_trainings[training_id]['error'] = "Training stopped by user"
                        active_trainings[training_id]['result'] = None
                        _safe_set_training_error(training_id, 'Training stopped by user', stopped=True)
                else:
                    logger.error(f"❌ Erreur dans train_kmeans background: {error_msg}")
                    if training_id in active_trainings:
                        error_result = {
                            "status": "error",
                            "error_message": error_msg,
                            "error_type": type(e).__name__
                        }
                        active_trainings[training_id]['completed'] = True
                        active_trainings[training_id]['result'] = error_result
                        active_trainings[training_id]['error'] = error_msg
                        _safe_set_training_error(training_id, error_msg, stopped=False)
            finally:
                # ✅ Nettoyer le flag d'arrêt
                if training_id in training_stop_flags:
                    del training_stop_flags[training_id]
                loop.close()
        
        from concurrent.futures import Future
        future = Future()
        
        active_trainings[training_id] = {
            'future': future,
            'user_id': current_user_id,
            'start_time': datetime.now(),
            'model_type': 'kmeans',
            'completed': False,
            'result': None,
            'error': None,
            'retrieved': False
        }
        
        background_tasks.add_task(train_in_background)
        
        # ✅ RETOURNER IMMÉDIATEMENT
        return {
            "status": "training_started",
            "training_id": training_id,
            "message": "KMeans training started in background"
        }
    
    # ========== 2. MODE SYNCHRONE (EXÉCUTION NORMALE) ==========
    return await train_kmeans_with_stop_check(request, background_tasks, current_user_id, None)
'''@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@'''

