class OutlierDetectionRequest(BaseModel):
    bdName: str
    columns: List[str]
    method: Literal['kmeans', 'isolation', 'dbscan'] = 'kmeans'
    params: dict = {
        'nClusters': 2,            # Pour KMeans
        'contamination': 0.05,     # Pour Isolation Forest
        'nEstimators': 100,        # Pour Isolation Forest
        'eps': 0.5,                # Pour DBSCAN
        'minPts': 5,               # Pour DBSCAN
        'distancePercentile': 95,  # Pour KMeans (seuil de distance)
        'useStandardization': True,
    }

@router.post("/detect-outliers")
async def detect_outliers(
    request: OutlierDetectionRequest,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Détection multivariée anti-leakage :
      - fit scaler + modèle UNIQUEMENT sur split_type='train'
      - outliers renvoyés = IDs train uniquement
      - PCA calculée sur le train (échantillon ≤ 2000 pour l'affichage)
    """
    try:
        # Validation des paramètres
        if request.method == 'kmeans':
            n_clusters = request.params.get('nClusters', 2)
            if n_clusters < 2:
                raise HTTPException(400, "Le nombre de clusters doit être ≥ 2")
            distance_percentile = float(request.params.get('distancePercentile', 95))
            if not 80 <= distance_percentile <= 99.9:
                raise HTTPException(400, "distancePercentile doit être entre 80 et 99.9")
        elif request.method == 'isolation':
            contamination = request.params.get('contamination', 0.05)
            if not 0.01 <= contamination <= 0.5:
                raise HTTPException(400, "La contamination doit être entre 0.01 et 0.5")
            
            n_estimators = request.params.get('nEstimators', 100)
            if n_estimators < 10:
                raise HTTPException(400, "Le nombre d'arbres doit être ≥ 10")
        elif request.method == 'dbscan':
            eps = request.params.get('eps', 0.5)
            if eps <= 0:
                raise HTTPException(400, "eps doit être > 0")
            
            min_pts = request.params.get('minPts', 5)
            if min_pts < 1:
                raise HTTPException(400, "minPts doit être ≥ 1")

        with get_db_connection() as conn:
            cur = conn.cursor()
            table_name = request.bdName.lower()
            
            cur.execute("""
                SELECT 1 FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            if not cur.fetchone():
                raise HTTPException(403, "Accès non autorisé")

            # split_type si présent (anti-leakage) ; sinon fallback sur toute la table
            has_split = table_has_split_type(cur, table_name)
            data_scope = "train_only" if has_split else "full_dataset_no_split"

            if not request.columns:
                raise HTTPException(400, "Sélectionnez au moins une colonne numérique")

            # Vérifier que les colonnes existent
            cur.execute("""
                SELECT column_name FROM information_schema.columns
                WHERE table_name = %s
            """, (table_name,))
            existing = {r[0] for r in cur.fetchall()}
            missing = [c for c in request.columns if c not in existing]
            if missing:
                raise HTTPException(400, f"Colonnes introuvables: {missing}")

            select_cols = (["id", "split_type"] if has_split else ["id"]) + list(request.columns)
            query = sql.SQL("SELECT {} FROM {}").format(
                sql.SQL(',').join(map(sql.Identifier, select_cols)),
                sql.Identifier(table_name),
            )
            cur.execute(query)
            rows = cur.fetchall()
            
            if not rows:
                raise HTTPException(400, "Aucune donnée trouvée")

            train_ids = []
            train_features = []
            for row in rows:
                row_id = row[0]
                if has_split:
                    split_val = row[1]
                    feat_vals = row[2:]
                    if str(split_val).lower() != 'train':
                        continue
                else:
                    feat_vals = row[1:]
                try:
                    feats = [float(v) for v in feat_vals]
                    if any(v != v for v in feats):  # NaN check
                        continue
                    train_ids.append(int(row_id))
                    train_features.append(feats)
                except (TypeError, ValueError):
                    continue

            if len(train_features) < 5:
                raise HTTPException(
                    400,
                    f"Not enough valid rows for detection (got {len(train_features)}, need ≥ 5). "
                    + ("Make sure the dataset is split and selected columns are numeric."
                       if has_split else
                       "Make sure selected columns are numeric.")
                )

            X_train = np.array(train_features, dtype=float)
            
            use_standardization = request.params.get("useStandardization", True)
            if use_standardization:
                scaler = StandardScaler()
                X_processed = scaler.fit_transform(X_train)
            else:
                X_processed = X_train.copy()
                logger.info("Using raw train data without standardization")
            
            outliers = []
            clusters = []
            centroids = []
            threshold = None
            n_train = len(train_ids)
            
            if request.method == 'kmeans':
                n_clusters = int(request.params.get('nClusters', 2))
                n_clusters = min(n_clusters, max(2, n_train - 1))
                distance_percentile = float(request.params.get('distancePercentile', 95))
                distance_percentile = float(np.clip(distance_percentile, 80.0, 99.9))

                kmeans = KMeans(n_clusters=n_clusters, random_state=42, n_init='auto')
                cluster_labels = kmeans.fit_predict(X_processed)
                distances = kmeans.transform(X_processed)
                min_distances = np.min(distances, axis=1)
                threshold = float(np.percentile(min_distances, distance_percentile))
                outlier_idx = np.where(min_distances > threshold)[0]
                # Plus sévères d'abord (distance au centroïde décroissante)
                outlier_idx = outlier_idx[np.argsort(-min_distances[outlier_idx])]
                outliers = [train_ids[i] for i in outlier_idx]
                clusters = cluster_labels.tolist()
                centroids = kmeans.cluster_centers_.tolist()
                
            elif request.method == 'isolation':
                contamination = float(request.params.get('contamination', 0.05))
                # contamination ne peut pas dépasser (n-1)/n
                max_cont = max(0.01, min(0.5, (n_train - 1) / float(n_train)))
                contamination = min(contamination, max_cont)
                clf = IsolationForest(
                    contamination=contamination,
                    n_estimators=int(request.params.get('nEstimators', 100)),
                    random_state=42
                )
                preds = clf.fit_predict(X_processed)
                scores = -clf.score_samples(X_processed)
                outlier_idx = np.where(preds == -1)[0]
                # Plus sévères d'abord (score d'anomalie décroissant)
                outlier_idx = outlier_idx[np.argsort(-scores[outlier_idx])]
                outliers = [train_ids[i] for i in outlier_idx]
                clusters = (preds == 1).astype(int).tolist()
                threshold = float(np.percentile(scores, 100 * (1 - contamination)))
                
            elif request.method == 'dbscan':
                # DBSCAN n'a pas de predict() : détection uniquement sur le train
                eps = float(request.params.get('eps', 0.5))
                min_samples = int(request.params.get('minPts', 5))
                dbscan = DBSCAN(eps=eps, min_samples=min_samples)
                cluster_labels = dbscan.fit_predict(X_processed)
                outlier_idx = np.where(cluster_labels == -1)[0]
                outliers = [train_ids[i] for i in outlier_idx]
                clusters = cluster_labels.tolist()
                centroids = []
                threshold = None

            outlier_id_set = set(outliers)

            # PCA sur le train (même preprocessing que la détection), échantillon ≤ 2000 pour l'UI
            pca = PCA(n_components=min(2, X_processed.shape[1], X_processed.shape[0]))
            if X_processed.shape[1] < 2 or X_processed.shape[0] < 2:
                pca_projection = [[0.0, 0.0] for _ in range(n_train)]
                explained = [1.0, 0.0]
                pca_ids = train_ids
                pca_is_outlier = [tid in outlier_id_set for tid in train_ids]
            else:
                pca_full = pca.fit_transform(X_processed)
                explained = pca.explained_variance_ratio_.tolist()
                if len(explained) == 1:
                    explained = [explained[0], 0.0]
                    pca_full = np.column_stack([pca_full.ravel(), np.zeros(len(pca_full))])

                max_points = 2000
                if n_train <= max_points:
                    sample_idx = np.arange(n_train)
                else:
                    rng = np.random.RandomState(42)
                    out_idx = [i for i, tid in enumerate(train_ids) if tid in outlier_id_set]
                    normal_idx = [i for i, tid in enumerate(train_ids) if tid not in outlier_id_set]
                    keep_out = out_idx[: max_points // 2]
                    n_norm = max_points - len(keep_out)
                    if len(normal_idx) > n_norm:
                        keep_norm = rng.choice(normal_idx, size=n_norm, replace=False).tolist()
                    else:
                        keep_norm = normal_idx
                    sample_idx = np.array(keep_out + keep_norm, dtype=int)

                pca_projection = pca_full[sample_idx].tolist()
                pca_ids = [train_ids[i] for i in sample_idx]
                pca_is_outlier = [train_ids[i] in outlier_id_set for i in sample_idx]
            
            return {
                "outliers": outliers,
                "clusters": clusters,
                "centroids": centroids,
                "threshold": threshold,
                "pca_projection": pca_projection,
                "pca_ids": pca_ids,
                "pca_is_outlier": pca_is_outlier,
                "explained_variance": explained if isinstance(explained, list) else list(explained),
                "method": request.method,
                "used_standardization": use_standardization,
                "details": {
                    "n_outliers": len(outliers),
                    "n_samples": n_train,
                    "outlier_ratio": (len(outliers) / n_train) if n_train else 0.0,
                    "columns_used": request.columns,
                    "params_used": request.params,
                    "data_used": data_scope,
                    "pca_display_points": len(pca_projection),
                }
            }
            
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error in outlier detection: {str(e)}", exc_info=True)
        raise HTTPException(500, f"Internal error: {str(e)}")


class HandleOutliersRequest(BaseModel):
    bdName: str
    outliers: List[int]
