@router.post("/get-outliers-data")
async def get_outliers_data(
    request: OutlierDataRequest,
    current_user_id: str = Depends(get_current_user2)
):
    try:
        with get_db_connection() as conn:
            cur = conn.cursor()
            table_name = request.bdName.lower()
            
            # Vérifier les permissions
            cur.execute("""
                SELECT 1 FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            if not cur.fetchone():
                raise HTTPException(403, "Accès non autorisé")
            
            # Get all column names in order
            cur.execute(f"""
                SELECT column_name FROM information_schema.columns
                WHERE table_name = %s
                ORDER BY ordinal_position
            """, [table_name])
            columns = [row[0] for row in cur.fetchall()]
            
            # Fetch the outlier data with all columns
            query = sql.SQL("SELECT {} FROM {} WHERE id = ANY(%s)").format(
                sql.SQL(',').join(map(sql.Identifier, columns)),
                sql.Identifier(table_name)
            )
            cur.execute(query, [request.outlierIds])
            
            # Format results with all columns
            results = []
            for row in cur.fetchall():
                record = {}
                for i, col in enumerate(columns):
                    record[col] = row[i]
                results.append(record)
            
            return results
            
    except Exception as e:
        raise HTTPException(500, f"Erreur de récupération des données: {str(e)}")
    

    



class DeleteOutliersRequest(BaseModel):
    bdName: str
    outlierIds: List[int]

@router.post("/delete-outliers")
async def delete_outliers(
    request: DeleteOutliersRequest,
    current_user_id: str = Depends(get_current_user2)
):
    try:
        with get_db_connection() as conn:
            cur = conn.cursor()
            table_name = request.bdName.lower()
            
            # Vérifier les permissions
            cur.execute("""
                SELECT 1 FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            if not cur.fetchone():
                raise HTTPException(403, "Accès non autorisé")
            
            # 1. Supprimer les outliers UNIQUEMENT dans le train (anti-leakage)
            cur.execute("""
                SELECT 1 FROM information_schema.columns
                WHERE table_name = %s AND column_name = 'split_type'
            """, (table_name,))
            has_split = cur.fetchone() is not None

            if has_split:
                cur.execute(
                    sql.SQL(
                        "DELETE FROM {} WHERE id = ANY(%s) AND split_type = 'train'"
                    ).format(sql.Identifier(table_name)),
                    [request.outlierIds]
                )
            else:
                cur.execute(
                    sql.SQL("DELETE FROM {} WHERE id = ANY(%s)").format(
                        sql.Identifier(table_name)
                    ),
                    [request.outlierIds]
                )
            deleted_count = cur.rowcount
            
            # 2. Créer une table temporaire avec les données restantes
            temp_table = f"temp_{table_name}"
            cur.execute(
                sql.SQL("CREATE TEMP TABLE {} AS SELECT * FROM {} WITH NO DATA").format(
                    sql.Identifier(temp_table),
                    sql.Identifier(table_name)
                )
            )
            
            # 3. Copier les données avec nouveaux IDs séquentiels
            cur.execute(
                sql.SQL("""
                    INSERT INTO {} 
                    SELECT 
                        ROW_NUMBER() OVER () as id,
                        {columns}
                    FROM {source_table}
                    ORDER BY id
                """).format(
                    sql.Identifier(temp_table),
                    columns=sql.SQL(',').join([
                        sql.Identifier(col) 
                        for col in get_table_columns(cur, table_name) 
                        if col != 'id'
                    ]),
                    source_table=sql.Identifier(table_name)
                )
            )
            
            # 4. Vider et recopier la table originale
            cur.execute(sql.SQL("TRUNCATE TABLE {}").format(sql.Identifier(table_name)))
            
            cur.execute(
                sql.SQL("INSERT INTO {} SELECT * FROM {}").format(
                    sql.Identifier(table_name),
                    sql.Identifier(temp_table)
                )
            )
            
            # 5. Supprimer la table temporaire
            cur.execute(sql.SQL("DROP TABLE {}").format(sql.Identifier(temp_table)))
            
            conn.commit()
            return {
                "message": "Outliers successfully deleted",
                "deleted_count": deleted_count,
                "train_only": has_split,
            }
            
    except Exception as e:
        conn.rollback()
        raise HTTPException(500, f"Erreur lors de la suppression: {str(e)}")




        
