@router.post("/update-stage")
async def update_stage(
    data: dict = Body(...),
    current_user_id: str = Depends(get_current_user2)
):
    """
    Met à jour le stage d'une table avec vérification de propriété
    Requiert:
    - bdName: Nom de la table
    - newStage: Nouveau stage (ex: "target_selection")
    """
    try:
        # 1. Validation des données
        if not data.get('bdName') or not data.get('newStage'):
            raise HTTPException(400, "bdName et newStage sont requis")

        table_name = data['bdName'].lower()
        new_stage = data['newStage']

        with get_db_connection() as conn:
            cur = conn.cursor()

            cur.execute("""
                SELECT 1 FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))

            if not cur.fetchone():
                raise HTTPException(403, "Table not found or access denied")

            cur.execute("""
                UPDATE user_tables_metadata
                SET stage = %s,
                    updated_at = NOW()
                WHERE table_name = %s AND owner_id = %s
                RETURNING stage, updated_at
            """, (new_stage, table_name, current_user_id))

            updated_data = cur.fetchone()
            conn.commit()

            return {
                "status": "success",
                "table": table_name,
                "new_stage": updated_data[0],
                "updated_at": updated_data[1].isoformat()
            }

    except psycopg2.Error as e:
        if conn:
            conn.rollback()
        raise HTTPException(500, f"Erreur base de données: {e.pgerror}")
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(500, f"Server error: {str(e)}")
    


