# Configuration du logger
logger = logging.getLogger(__name__)



def _ensure_user_saved_models_pipeline_columns(cur, conn):
    """Add applied_actions / raw_input_columns / algorithm to user_saved_models if missing."""
    for column, ddl in (
        ("applied_actions", "ALTER TABLE user_saved_models ADD COLUMN applied_actions JSONB DEFAULT '[]'::jsonb"),
        ("raw_input_columns", "ALTER TABLE user_saved_models ADD COLUMN raw_input_columns TEXT[]"),
        ("algorithm", "ALTER TABLE user_saved_models ADD COLUMN algorithm VARCHAR(100)"),
    ):
        cur.execute(
            """
            SELECT 1 FROM information_schema.columns
            WHERE table_name = 'user_saved_models' AND column_name = %s
            """,
            (column,),
        )
        if not cur.fetchone():
            cur.execute(ddl)
            conn.commit()


_SKLEARN_CLASS_TO_ALGORITHM = {
    "Ridge": "ridge",
    "RidgeCV": "ridge",
    "LogisticRegression": "logistic",
    "RandomForestClassifier": "random_forest",
    "RandomForestRegressor": "random_forest",
    "SVC": "svm",
    "SVR": "svm",
    "KNeighborsClassifier": "knn",
    "KNeighborsRegressor": "knn",
    "LGBMClassifier": "lightgbm",
    "LGBMRegressor": "lightgbm",
    "KMeans": "kmeans",
    "IsolationForest": "isolation_forest",
    "OneClassSVM": "one_class_svm",
}


def _infer_algorithm_from_saved_file(model_path: str, model_type: str = None, framework: str = None):
    """Best-effort algorithm id for older saves that lack the algorithm column."""
    mt = (model_type or "").lower()
    fw = (framework or "").lower()
    if mt == "kmeans" or "kmean" in mt:
        return "kmeans"
    if mt == "pytorch_mlp" or fw == "pytorch":
        return "mlp"
    if not model_path or not os.path.exists(model_path):
        return None
    try:
        if str(model_path).endswith(".pt"):
            return "mlp"
        saved = joblib.load(model_path)
        if isinstance(saved, dict):
            meta = saved.get("metadata") or {}
            if meta.get("algorithm"):
                return str(meta["algorithm"]).strip().lower()
            if meta.get("kmeans_params") is not None or meta.get("model_type") == "kmeans":
                return "kmeans"
            obj = saved.get("model", saved)
        else:
            obj = saved
        # Nested wrappers
        if isinstance(obj, dict) and "model" in obj:
            obj = obj["model"]
        cls_name = type(obj).__name__
        return _SKLEARN_CLASS_TO_ALGORITHM.get(cls_name)
    except Exception:
        return None


def _resolve_algorithm(explicit, model_type=None, framework=None, kmeans_params=None, model_path=None):
    if explicit and str(explicit).strip():
        return str(explicit).strip().lower()
    if kmeans_params is not None:
        return "kmeans"
    mt = (model_type or "").lower()
    if mt in ("anomaly", "isolation_forest", "one_class_svm"):
        if "one_class" in mt or "ocsvm" in mt:
            return "one_class_svm"
        if "isolation" in mt:
            return "isolation_forest"
        return "isolation_forest"
    if (framework or "").lower() == "pytorch" or mt == "pytorch_mlp":
        return "mlp"
    if mt == "kmeans":
        return "kmeans"
    return _infer_algorithm_from_saved_file(model_path, model_type, framework)


def _fetch_dataset_applied_actions(cur, db_name: str, user_id: str):
    """Load applied_actions from dataset metadata (legacy + current table names)."""
    base = (db_name or "").replace("_numerized", "").replace("_backup", "").replace("_reset", "")
    for cand in (f"{base}_numerized", base):
        cur.execute(
            """
            SELECT applied_actions FROM user_tables_metadata
            WHERE table_name = %s AND owner_id = %s
            """,
            (cand, user_id),
        )
        row = cur.fetchone()
        if row and row[0]:
            return row[0] if isinstance(row[0], list) else list(row[0] or [])
    return []


def _find_predictable_model(obj, path=""):
    """Recursively find an object that exposes .predict()."""
    if obj is None:
        return None, path
    if hasattr(obj, "predict") and callable(getattr(obj, "predict", None)):
        # Avoid treating plain dicts / modules as models
        if not isinstance(obj, dict):
            return obj, path
    if isinstance(obj, dict):
        # Prefer common keys first
        for key in ("model", "estimator", "best_estimator_", "clf", "regressor", "classifier"):
            if key in obj:
                found, p = _find_predictable_model(obj[key], f"{path}.{key}" if path else key)
                if found is not None:
                    return found, p
        for k, v in obj.items():
            found, p = _find_predictable_model(v, f"{path}.{k}" if path else str(k))
            if found is not None:
                return found, p
    elif isinstance(obj, (list, tuple)):
        for i, item in enumerate(obj):
            found, p = _find_predictable_model(item, f"{path}[{i}]")
            if found is not None:
                return found, p
    return None, path


def _extract_sklearn_model_from_joblib(saved_data):
    """
    Same robust extraction used by /predict — supports nested dict wrappers.
    Returns (model, scaler_or_None, metadata_dict).
    """
    scaler = None
    metadata = {}

    if hasattr(saved_data, "predict") and not isinstance(saved_data, dict):
        return saved_data, None, {}

    if not isinstance(saved_data, dict):
        raise ValueError(f"Unsupported saved model type: {type(saved_data)}")

    metadata = dict(saved_data.get("metadata") or {})
    scaler = saved_data.get("scaler")

    # Direct model key
    if "model" in saved_data:
        raw = saved_data["model"]
        if isinstance(raw, dict):
            if scaler is None:
                scaler = raw.get("scaler")
            for k in ("algorithm", "model_type", "params", "feature_names", "target_excluded"):
                if k in raw and k not in metadata:
                    metadata[k] = raw[k]
            if raw.get("metadata") and isinstance(raw["metadata"], dict):
                for k, v in raw["metadata"].items():
                    metadata.setdefault(k, v)
        if hasattr(raw, "predict") and not isinstance(raw, dict):
            return raw, scaler, metadata
        found, path = _find_predictable_model(raw)
        if found is not None:
            logger.info(f"Extracted nested model at model{path}")
            return found, scaler, metadata

    found, path = _find_predictable_model(saved_data)
    if found is not None:
        logger.info(f"Extracted nested model at {path or 'root'}")
        return found, scaler, metadata

    raise ValueError(
        "Could not find a trainable estimator with predict() in the saved file. "
        f"Top-level keys: {list(saved_data.keys())}"
    )


def _is_anomaly_model(model=None, model_type=None, metadata=None, algorithm=None) -> bool:
    mt = str(model_type or "").lower()
    algo = str(algorithm or (metadata or {}).get("algorithm") or "").lower()
    meta_mt = str((metadata or {}).get("model_type") or "").lower()
    cls = type(model).__name__ if model is not None else ""
    return (
        mt == "anomaly"
        or meta_mt == "anomaly"
        or algo in ("isolation_forest", "one_class_svm", "anomaly")
        or cls in ("IsolationForest", "OneClassSVM")
        or "isolation" in algo
        or "one_class" in algo
    )


def _anomaly_predict_row(model, X, scaler=None):
    """
    Predict one/many rows for IsolationForest / OneClassSVM.
    Returns list of dicts: is_anomaly, anomaly_label, anomaly_score, predicted_label, prediction.
    """
    X_arr = np.asarray(X, dtype=float)
    if X_arr.ndim == 1:
        X_arr = X_arr.reshape(1, -1)
    if scaler is not None:
        X_arr = scaler.transform(X_arr)
    preds = model.predict(X_arr)
    scores = model.decision_function(X_arr)
    out = []
    for pred, score in zip(preds, scores):
        is_anom = int(pred) == -1
        label = "anomaly" if is_anom else "normal"
        out.append(
            {
                "is_anomaly": is_anom,
                "anomaly_label": label,
                "anomaly_score": float(score),
                "predicted_label": label,
                "predicted_class": label,
                "prediction": label,
                "encoded_class": int(pred),
                "score_interpretation": "Lower score ⇒ more anomalous / suspicious",
            }
        )
    return out


class SaveModelRequest(BaseModel):
    model_name: str
    db_name: str
    db_columns: List[str]
    r2_score: Optional[float] = None
    accuracy_score: Optional[float] = None
    # Client may still send this for UI compatibility; server IGNORES it and uses
    # the training_id pending store (anti-RCE). Kept optional for older clients.
    model_object: Optional[str] = None
    # Required: links save to the server-side trained model (5 min window)
    training_id: Optional[str] = None
    framework: Optional[str] = "sklearn"
    # Specific algorithm id: ridge, logistic, random_forest, svm, knn, lightgbm, mlp, kmeans
    algorithm: Optional[str] = None
    # Nouveaux champs pour KMeans
    visualization_data: Optional[Dict[str, Any]] = None
    cluster_info: Optional[List[Dict[str, Any]]] = None
    kmeans_params: Optional[Dict[str, Any]] = None
    silhouette_score: Optional[float] = None
    inertia: Optional[float] = None
    # Optional: FE may pass; otherwise loaded from dataset metadata at save time
    applied_actions: Optional[List[Dict[str, Any]]] = None
    raw_input_columns: Optional[List[str]] = None

@router.post("/save-model")
async def save_model(
    request: SaveModelRequest,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Save a trained machine learning model with its metadata.
    Model bytes come ONLY from the server pending store (training_id), never from
    client-supplied pickle (RCE protection). Save window: 5 minutes after training.
    """
    try:
        # === Validations ===
        if not request.model_name.strip():
            raise HTTPException(status_code=400, detail="Model name cannot be empty")
        if not request.db_name.strip():
            raise HTTPException(status_code=400, detail="Database name cannot be empty")
        if not request.db_columns:
            raise HTTPException(status_code=400, detail="Database columns cannot be empty")

        if not request.training_id or not str(request.training_id).strip():
            raise HTTPException(
                status_code=400,
                detail=(
                    "This trained model is no longer available to save. "
                    "Please train again, then save within 5 minutes."
                ),
            )

        pending = get_pending_save_model(str(request.training_id).strip(), current_user_id)
        if not pending:
            raise HTTPException(
                status_code=400,
                detail=(
                    "You can only save a model within 5 minutes after training finishes. "
                    "That time has passed (or the training session was lost). "
                    "Please train the model again, then save it right away."
                ),
            )

        # Trust server copy only — never deserialize client-provided model_object
        server_model_object = pending["model_object"]

        MAX_MODELS_PER_USER = 20

        # === Décodage des bytes du modèle (server-held bytes only) ===
        # PyTorch: write raw bytes (no torch.load).
        # Sklearn/KMeans: joblib.load of OUR training output to wrap metadata.
        try:
            model_bytes = base64.b64decode(server_model_object.encode('utf-8'))
            decoded_model = None

            if request.framework != "pytorch":
                decoded_model = joblib.load(io.BytesIO(model_bytes))
                if hasattr(decoded_model, 'predict') or (isinstance(decoded_model, dict) and 'model' in decoded_model):
                    logger.info("Scikit-learn model loaded for save (server pending store).")
                else:
                    logger.warning("Model object structure may not be standard")

        except Exception as e:
            logger.error(f"Model decoding/deserialization failed: {str(e)}")
            raise HTTPException(
                status_code=400,
                detail="Invalid model object"
            )

        # === Database operations ===
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Vérifier si la table existe
                cur.execute("""
                    SELECT EXISTS (
                        SELECT FROM information_schema.tables 
                        WHERE table_name = 'user_saved_models'
                    )
                """)
                table_exists = cur.fetchone()[0]

                # Créer la table si nécessaire avec les nouvelles colonnes pour KMeans
                if not table_exists:
                    cur.execute("""
                        CREATE TABLE user_saved_models (
                            id SERIAL PRIMARY KEY,
                            user_id VARCHAR(255) NOT NULL,
                            model_name VARCHAR(255) NOT NULL,
                            db_name VARCHAR(255) NOT NULL,
                            model_path TEXT NOT NULL UNIQUE,
                            db_columns TEXT[] NOT NULL,
                            r2_score FLOAT,
                            accuracy_score FLOAT,
                            silhouette_score FLOAT,
                            inertia FLOAT,
                            framework VARCHAR(50) DEFAULT 'sklearn',
                            model_type VARCHAR(50) DEFAULT 'unknown',
                            algorithm VARCHAR(100),
                            has_visualization_data BOOLEAN DEFAULT FALSE,
                            applied_actions JSONB DEFAULT '[]'::jsonb,
                            raw_input_columns TEXT[],
                            created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
                            CONSTRAINT unique_user_model UNIQUE(user_id, model_name)
                        );
                        CREATE INDEX idx_user_models ON user_saved_models(user_id);
                        CREATE INDEX idx_model_type ON user_saved_models(model_type);
                    """)
                    conn.commit()
                else:
                    # Ajouter les colonnes manquantes si elles n'existent pas
                    columns_to_check = [
                        'framework', 'model_type', 'has_visualization_data', 
                        'silhouette_score', 'inertia'
                    ]
                    
                    for column in columns_to_check:
                        cur.execute("""
                            SELECT column_name 
                            FROM information_schema.columns 
                            WHERE table_name = 'user_saved_models' 
                            AND column_name = %s
                        """, (column,))
                        if not cur.fetchone():
                            if column == 'framework':
                                cur.execute("""
                                    ALTER TABLE user_saved_models 
                                    ADD COLUMN framework VARCHAR(50) DEFAULT 'sklearn'
                                """)
                            elif column == 'model_type':
                                cur.execute("""
                                    ALTER TABLE user_saved_models 
                                    ADD COLUMN model_type VARCHAR(50) DEFAULT 'unknown'
                                """)
                            elif column == 'has_visualization_data':
                                cur.execute("""
                                    ALTER TABLE user_saved_models 
                                    ADD COLUMN has_visualization_data BOOLEAN DEFAULT FALSE
                                """)
                            elif column == 'silhouette_score':
                                cur.execute("""
                                    ALTER TABLE user_saved_models 
                                    ADD COLUMN silhouette_score FLOAT
                                """)
                            elif column == 'inertia':
                                cur.execute("""
                                    ALTER TABLE user_saved_models 
                                    ADD COLUMN inertia FLOAT
                                """)
                            conn.commit()

                _ensure_user_saved_models_pipeline_columns(cur, conn)

                # Soft quota: max 20 saved models per user
                cur.execute(
                    "SELECT COUNT(*) FROM user_saved_models WHERE user_id = %s",
                    (current_user_id,),
                )
                model_count = cur.fetchone()[0] or 0
                if model_count >= MAX_MODELS_PER_USER:
                    raise HTTPException(
                        status_code=400,
                        detail=(
                            f"Model limit reached ({model_count}/{MAX_MODELS_PER_USER}). "
                            "Delete one or more saved models from the Dashboard before saving a new one."
                        ),
                    )

                # Snapshot preprocessing pipeline with the model (single source of truth for predict)
                saved_actions = request.applied_actions
                if not saved_actions:
                    saved_actions = _fetch_dataset_applied_actions(cur, request.db_name, current_user_id)
                if not isinstance(saved_actions, list):
                    saved_actions = []

                # Infer target for raw column computation (best-effort)
                target_for_raw = None
                try:
                    base_db = request.db_name.replace("_numerized", "")
                    cur.execute(
                        """
                        SELECT target_column FROM user_tables_metadata
                        WHERE table_name = %s AND owner_id = %s
                        """,
                        (base_db, current_user_id),
                    )
                    trow = cur.fetchone()
                    if trow:
                        target_for_raw = trow[0]
                except Exception:
                    target_for_raw = None

                saved_raw_cols = request.raw_input_columns or infer_raw_input_columns(
                    request.db_columns, saved_actions, target_for_raw
                )

                # Préparer le répertoire des modèles (project root / saved_models)
                _here = os.path.dirname(os.path.abspath(__file__))
                _project_root = os.path.dirname(_here)
                models_dir = os.path.join(_project_root, "saved_models")
                os.makedirs(models_dir, exist_ok=True)

                # Générer un nom de fichier unique
                timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                safe_model_name = "".join(c if c.isalnum() else "_" for c in request.model_name)
                
                # Déterminer l'extension en fonction du framework
                if request.framework == "pytorch":
                    ext = "pt"
                else:
                    ext = "joblib"
                
                filename = f"{current_user_id}_{safe_model_name}_{timestamp}.{ext}"
                filepath = os.path.join(models_dir, filename)

                # Déterminer le type de modèle (problem family) + algorithm (specific algo)
                model_type = "unknown"
                algo_hint = (request.algorithm or "").strip().lower()
                if algo_hint in ("isolation_forest", "one_class_svm") or algo_hint == "anomaly":
                    model_type = "anomaly"
                elif request.kmeans_params is not None:
                    model_type = "kmeans"
                elif request.framework == "pytorch":
                    model_type = "pytorch_mlp"
                elif request.r2_score is not None:
                    model_type = "regression"
                elif request.accuracy_score is not None:
                    model_type = "classification"

                algorithm = _resolve_algorithm(
                    request.algorithm,
                    model_type=model_type,
                    framework=request.framework,
                    kmeans_params=request.kmeans_params,
                ) or "unknown"

                # === Sauvegarde sur disque ===
                try:
                    if request.framework == "pytorch":
                        # Sauvegarde brute des bytes pour PyTorch
                        with open(filepath, "wb") as f:
                            f.write(model_bytes)
                        
                        # Sauvegarde des métadonnées dans un fichier séparé
                        metadata = {
                            'model_name': request.model_name,
                            'db_name': request.db_name,
                            'db_columns': request.db_columns,
                            'r2_score': request.r2_score,
                            'accuracy_score': request.accuracy_score,
                            'created_at': datetime.now().isoformat(),
                            'created_by': current_user_id,
                            'framework': 'pytorch',
                            'model_type': model_type,
                            'algorithm': algorithm,
                            'applied_actions': saved_actions,
                            'raw_input_columns': saved_raw_cols,
                        }
                        metadata_path = filepath.replace(".pt", "_metadata.joblib")
                        joblib.dump(metadata, metadata_path)

                    else:
                        # Pour scikit-learn (y compris KMeans)
                        if request.kmeans_params is not None:
                            # Cas spécial pour KMeans - sauvegarder avec données de visualisation
                            model_data = {
                                'model': decoded_model,  # Utiliser le modèle déjà décodé
                                'metadata': {
                                    'model_name': request.model_name,
                                    'db_name': request.db_name,
                                    'db_columns': request.db_columns,
                                    'visualization_data': request.visualization_data,
                                    'cluster_info': request.cluster_info,
                                    'kmeans_params': request.kmeans_params,
                                    'silhouette_score': request.silhouette_score,
                                    'inertia': request.inertia,
                                    'created_at': datetime.now().isoformat(),
                                    'created_by': current_user_id,
                                    'model_type': 'kmeans',
                                    'algorithm': algorithm,
                                    'framework': 'scikit-learn',
                                    'applied_actions': saved_actions,
                                    'raw_input_columns': saved_raw_cols,
                                }
                            }
                        else:
                            # Pour les autres modèles scikit-learn
                            model_data = {
                                'model': decoded_model,  # Utiliser le modèle déjà décodé
                                'metadata': {
                                    'model_name': request.model_name,
                                    'db_name': request.db_name,
                                    'db_columns': request.db_columns,
                                    'r2_score': request.r2_score,
                                    'accuracy_score': request.accuracy_score,
                                    'created_at': datetime.now().isoformat(),
                                    'created_by': current_user_id,
                                    'model_type': model_type,
                                    'algorithm': algorithm,
                                    'framework': 'scikit-learn',
                                    'applied_actions': saved_actions,
                                    'raw_input_columns': saved_raw_cols,
                                }
                            }
                        
                        joblib.dump(model_data, filepath, compress=('zlib', 3))

                except Exception as e:
                    logger.error(f"Failed to save model to disk: {str(e)}")
                    raise HTTPException(status_code=500, detail="Failed to save model file")

                # === Sauvegarde en base ===
                try:
                    cur.execute("""
                        INSERT INTO user_saved_models 
                        (user_id, model_name, db_name, model_path, db_columns, 
                         r2_score, accuracy_score, silhouette_score, inertia,
                         framework, model_type, algorithm, has_visualization_data,
                         applied_actions, raw_input_columns)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, %s)
                        RETURNING id, model_path
                    """, (
                        current_user_id,
                        request.model_name,
                        request.db_name,
                        filepath,
                        request.db_columns,
                        request.r2_score,
                        request.accuracy_score,
                        request.silhouette_score,
                        request.inertia,
                        request.framework,
                        model_type,
                        algorithm,
                        request.visualization_data is not None,  # has_visualization_data
                        json.dumps(saved_actions),
                        saved_raw_cols,
                    ))

                    result = cur.fetchone()
                    model_id = result[0]
                    saved_path = result[1]
                    conn.commit()

                except Exception as e:
                    conn.rollback()
                    # Nettoyer le fichier si la sauvegarde en base a échoué
                    if os.path.exists(filepath):
                        try:
                            os.remove(filepath)
                            logger.info(f"Cleaned up model file after database error: {filepath}")
                        except Exception as cleanup_error:
                            logger.warning(f"Failed to clean up model file: {cleanup_error}")
                    
                    logger.error(f"Database operation failed: {str(e)}")
                    
                    # ✅ AMÉLIORATION : Meilleure détection des erreurs de contrainte unique
                    error_msg = str(e).lower()
                    if "unique_user_model" in error_msg or "duplicate key" in error_msg:
                        raise HTTPException(
                            status_code=400,
                            detail=f"You already have a model named '{request.model_name}'. Please choose a different name."
                        )
                    elif "unique constraint" in error_msg:
                        raise HTTPException(
                            status_code=400,
                            detail="A model with this name already exists for your account."
                        )
                    else:
                        raise HTTPException(status_code=500, detail="Failed to save model metadata")

        # Model successfully persisted — drop pending server copy
        if request.training_id:
            consume_pending_save_model(str(request.training_id).strip(), current_user_id)

        return {
            "status": "success",
            "model_id": model_id,
            "model_path": saved_path,
            "model_name": request.model_name,
            "db_name": request.db_name,
            "framework": request.framework,
            "model_type": model_type,
            "algorithm": algorithm,
            "has_visualization_data": request.visualization_data is not None,
            "saved_at": datetime.now().isoformat()
        }

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Unexpected error saving model: {str(e)}", exc_info=True)
        raise HTTPException(status_code=500, detail=f"An unexpected error occurred: {str(e)}")


@router.get("/get-saved-models")
async def get_saved_models(
    userId: str = Query(...),
    current_user_id: str = Depends(get_current_user2)
):
    """Return the saved models with the new metadata"""
    try:
        if userId != current_user_id:
            raise HTTPException(403, "Unauthorized access")

        with get_db_connection() as conn:
            with conn.cursor() as cur:
                _ensure_user_saved_models_pipeline_columns(cur, conn)
                cur.execute("""
                    SELECT 
                        id, 
                        model_name, 
                        db_name, 
                        model_path, 
                        db_columns, 
                        r2_score,
                        accuracy_score,
                        silhouette_score,
                        inertia,
                        framework,
                        model_type,
                        algorithm,
                        created_at
                    FROM user_saved_models 
                    WHERE user_id = %s
                    ORDER BY created_at DESC
                """, (userId,))
                
                models = []
                for row in cur.fetchall():
                    (model_id, model_name, db_name, model_path, 
                     db_columns, r2_score, accuracy_score, silhouette_score, inertia,
                     framework, model_type, algorithm, created_at) = row

                    resolved_algo = _resolve_algorithm(
                        algorithm,
                        model_type=model_type,
                        framework=framework,
                        model_path=model_path,
                    )
                    # Persist inferred algorithm for next time (best-effort)
                    if resolved_algo and not algorithm:
                        try:
                            cur.execute(
                                "UPDATE user_saved_models SET algorithm = %s WHERE id = %s AND user_id = %s",
                                (resolved_algo, model_id, userId),
                            )
                            conn.commit()
                        except Exception:
                            conn.rollback()
                    
                    models.append({
                        "id": model_id,
                        "model_name": model_name,
                        "db_name": db_name,
                        "model_path": model_path,
                        "db_columns": db_columns,
                        "r2_score": r2_score,
                        "accuracy_score": accuracy_score,
                        "silhouette_score": silhouette_score,
                        "inertia": inertia,
                        "framework": framework,
                        "model_type": model_type,
                        "algorithm": resolved_algo or algorithm or "unknown",
                        "timestamp": created_at.isoformat() if created_at else None
                    })
                
                return {"status": "success", "models": models}
                
    except Exception as e:
        raise HTTPException(500, detail=str(e))


@router.get("/download-model")
async def download_model(
    modelId: int = Query(...),
    current_user_id: str = Depends(get_current_user2),
):
    """Download a saved model file (.joblib or .pt) as stored on disk."""
    try:
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT model_name, model_path, framework, algorithm
                    FROM user_saved_models
                    WHERE id = %s AND user_id = %s
                    """,
                    (modelId, current_user_id),
                )
                row = cur.fetchone()
                if not row:
                    raise HTTPException(404, detail="Model not found")
                model_name, model_path, framework, algorithm = row

        if not model_path or not os.path.exists(model_path):
            raise HTTPException(404, detail="Model file not found on disk")

        # Prefer stored extension; fall back from path
        _, ext = os.path.splitext(model_path)
        ext = (ext or ".joblib").lower()
        safe_name = "".join(c if c.isalnum() or c in "-_" else "_" for c in (model_name or "model"))
        download_name = f"{safe_name}{ext}"
        media = (
            "application/octet-stream"
            if ext == ".pt"
            else "application/octet-stream"
        )
        return FileResponse(
            path=model_path,
            filename=download_name,
            media_type=media,
        )
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(500, detail=f"Failed to download model: {e}")


@router.get("/download-dataset-csv")
async def download_dataset_csv(
    dbName: str = Query(...),
    current_user_id: str = Depends(get_current_user2),
):
    """Download the current dataset table as CSV (current saved state)."""
    import re as _re
    from psycopg2 import sql as _sql

    table = (dbName or "").strip().lower()
    if not _re.match(r"^[a-z][a-z0-9_]*$", table):
        raise HTTPException(400, detail="Invalid dataset name")

    try:
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT 1 FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                    """,
                    (table, current_user_id),
                )
                if not cur.fetchone():
                    raise HTTPException(404, detail="Dataset not found or access denied")

                cur.execute(
                    """
                    SELECT 1 FROM information_schema.tables
                    WHERE table_schema = 'public' AND table_name = %s
                    """,
                    (table,),
                )
                if not cur.fetchone():
                    raise HTTPException(404, detail="Dataset table does not exist")

                query = _sql.SQL("SELECT * FROM {}").format(_sql.Identifier(table))
                df = pd.read_sql_query(query.as_string(conn), conn)

        if "id" in df.columns:
            df = df.drop(columns=["id"])

        buf = io.StringIO()
        df.to_csv(buf, index=False)
        content = buf.getvalue()
        return StreamingResponse(
            iter([content]),
            media_type="text/csv; charset=utf-8",
            headers={
                "Content-Disposition": f'attachment; filename="{table}.csv"'
            },
        )
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(500, detail=f"Failed to export dataset CSV: {e}")


@router.delete("/delete-model")
async def delete_model(
    request: Request,
    current_user_id: str = Depends(get_current_user2)
):
    """Delete a saved model and its file (path taken from DB only)."""
    try:
        data = await request.json()
        model_id = data.get("modelId")
        
        if not model_id:
            raise HTTPException(400, "Model ID is required")
        
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Vérifier que l'utilisateur possède ce modèle
                cur.execute("""
                    SELECT user_id, model_path 
                    FROM user_saved_models 
                    WHERE id = %s
                """, (model_id,))
                
                model_data = cur.fetchone()
                if not model_data:
                    raise HTTPException(404, "Model not found")
                
                user_id, db_model_path = model_data
                
                if user_id != current_user_id:
                    raise HTTPException(403, "Unauthorized to delete this model")

                # Never trust client modelPath — delete only the path stored in DB
                model_path = db_model_path
                
                if model_path and os.path.exists(model_path):
                    try:
                        os.remove(model_path)
        
                        if model_path.endswith('.pt'):  # PyTorch
                            metadata_path = model_path.replace('.pt', '_metadata.joblib')
                            if os.path.exists(metadata_path):
                                os.remove(metadata_path)
                
                        elif model_path.endswith('.joblib'):  # Scikit-learn
                            base_path = model_path.replace('.joblib', '')
                            visualization_files = [
                                f"{base_path}_clusters.png",
                                f"{base_path}_silhouette.png",
                                f"{base_path}_visualization.joblib"
                            ]
                            
                            for viz_file in visualization_files:
                                if os.path.exists(viz_file):
                                    os.remove(viz_file)
                    
                    except Exception as e:
                        logger.warning(f"Failed to delete model file {model_path}: {str(e)}")
                
                cur.execute("""
                    DELETE FROM user_saved_models 
                    WHERE id = %s AND user_id = %s
                """, (model_id, current_user_id))
                
                conn.commit()
                
                return {
                    "status": "success",
                    "message": "Model deleted successfully",
                    "deleted_model_id": model_id
                }
                
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error deleting model: {str(e)}")
        raise HTTPException(500, "Failed to delete model")





@router.post("/predict")
async def make_prediction(
    request: Request,
    current_user_id: str = Depends(get_current_user2)
):
    
    try:
        data = await request.json()
        model_id = data.get("modelId")
        input_data = data.get("inputData")
        target_column = data.get("targetColumn")
        expected_features = data.get("expectedFeatures", [])
        feature_count = data.get("featureCount", 0)
        # Default: apply server-side pipeline on raw inputs (new architecture)
        apply_pipeline = data.get("applyPipeline", True)
        decision_threshold = data.get("decisionThreshold", 0.5)
        try:
            decision_threshold = float(decision_threshold)
        except (TypeError, ValueError):
            decision_threshold = 0.5
        decision_threshold = max(0.01, min(0.99, decision_threshold))

        logger.info(f"🎯 Prediction request - Model ID: {model_id}, User: {current_user_id}")

        model_applied_actions = []
        model_raw_input_columns = None

        # Récupération des infos du modèle
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                _ensure_user_saved_models_pipeline_columns(cur, conn)
                cur.execute("""
                    SELECT id, model_name, model_path, db_columns, db_name, framework, model_type,
                           applied_actions, raw_input_columns
                    FROM user_saved_models
                    WHERE id = %s AND user_id = %s
                """, (model_id, current_user_id))
                
                model_data = cur.fetchone()
                if not model_data:
                    logger.error(f"❌ Model not found - ID: {model_id}, User: {current_user_id}")
                    raise HTTPException(status_code=404, detail="Model not found")
                
                (model_id, model_name, model_path, db_columns, db_name, framework, model_type,
                 model_applied_actions, model_raw_input_columns) = model_data
                model_applied_actions = model_applied_actions or []
                logger.info(f"📦 Model found - Name: {model_name}, Type: {model_type}, Path: {model_path}, Framework: {framework}")

                if not os.path.exists(model_path):
                    logger.error(f"❌ Model file not found at: {model_path}")
                    raise HTTPException(status_code=404, detail="Model file not found")

                # Legacy models: fall back to live dataset metadata
                if not model_applied_actions:
                    model_applied_actions = _fetch_dataset_applied_actions(cur, db_name, current_user_id)
                    logger.info(f"📎 Loaded {len(model_applied_actions)} actions from dataset metadata (legacy)")

        # ==================== RÉCUPÉRATION DU LABEL ENCODING MAPPING ====================
        applied_actions = model_applied_actions or []
        reverse_label_mapping, label_mapping = extract_target_label_maps(
            applied_actions, target_column
        )
        if label_mapping:
            logger.info(f"🎯 Label mapping found: {label_mapping}")
            logger.info(f"🔄 Reverse mapping keys: {list(reverse_label_mapping.keys())}")

        transform_steps = []
        transformed_preview = None

        # Chargement du modèle selon le framework
        model = None
        scaler = None
        model_metadata = {}
        
        if framework == "pytorch":
            try:
                device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
                loaded_data = torch.load(model_path, map_location=device, weights_only=False)
                
                logger.info(f"🔍 Loaded PyTorch data type: {type(loaded_data)}")
                
                # CAS 1: C'est déjà un modèle PyTorch (nn.Module)
                if hasattr(loaded_data, 'eval') and hasattr(loaded_data, 'forward'):
                    model = loaded_data
                    model.eval()
                    logger.info(f"✅ Loaded as direct PyTorch model - Type: {type(model)}")
                
                # CAS 2: C'est un dictionnaire avec state_dict
                elif isinstance(loaded_data, dict):
                    logger.info(f"📋 Dictionary keys: {list(loaded_data.keys())}")
                    
                    # Extraire les métadonnées si elles sont incluses
                    if 'feature_names' in loaded_data:
                        model_metadata['feature_names'] = loaded_data['feature_names']
                    if 'is_classification' in loaded_data:
                        model_metadata['is_classification'] = loaded_data['is_classification']
                    if 'problem_type' in loaded_data:
                        model_metadata['problem_type'] = loaded_data['problem_type']
                    if 'class_names' in loaded_data:
                        model_metadata['class_names'] = loaded_data['class_names']
                    if 'final_parameters' in loaded_data:
                        model_metadata['final_parameters'] = loaded_data['final_parameters']
                    if 'scaler' in loaded_data:
                        scaler = loaded_data['scaler']
                    
                    # Ajouter le label mapping aux métadonnées si disponible
                    if label_mapping:
                        model_metadata['label_mapping'] = label_mapping
                        model_metadata['reverse_label_mapping'] = reverse_label_mapping
                    
                    # SOUS-CAS 2A: Format standard avec model_state_dict et model_config
                    if 'model_state_dict' in loaded_data and 'model_config' in loaded_data:
                        model_config = loaded_data['model_config']
                        state_dict = loaded_data['model_state_dict']
                        
                        # Reconstruire le modèle MLP
                        import torch.nn as nn
                        
                        class PyTorchMLP(nn.Module):
                            def __init__(self, layers, activation='relu', dropout_rate=0.0):
                                super(PyTorchMLP, self).__init__()
                                self.layer_list = nn.ModuleList()
                                
                                for i in range(len(layers) - 1):
                                    self.layer_list.append(nn.Linear(layers[i], layers[i+1]))
                                
                                self.activation_name = activation
                                if activation == 'relu':
                                    self.activation = nn.ReLU()
                                elif activation == 'sigmoid':
                                    self.activation = nn.Sigmoid()
                                elif activation == 'tanh':
                                    self.activation = nn.Tanh()
                                elif activation == 'leaky_relu':
                                    self.activation = nn.LeakyReLU()
                                else:
                                    self.activation = nn.ReLU()
                                
                                self.dropout = nn.Dropout(dropout_rate) if dropout_rate > 0 else None
                                
                            def forward(self, x):
                                for i, layer in enumerate(self.layer_list):
                                    x = layer(x)
                                    if i < len(self.layer_list) - 1:
                                        x = self.activation(x)
                                        if self.dropout:
                                            x = self.dropout(x)
                                return x
                        
                        model = PyTorchMLP(**model_config)
                        model.load_state_dict(state_dict)
                        model.eval()
                        
                        if 'metadata' in loaded_data:
                            model_metadata.update(loaded_data['metadata'])
                        
                        logger.info(f"✅ MLP reconstructed from state_dict - Layers: {model_config.get('layers', 'N/A')}")
                    
                    # SOUS-CAS 2B: Format avec state_dict direct
                    elif 'state_dict' in loaded_data:
                        state_dict = loaded_data['state_dict']
                        model_config = loaded_data.get('model_config', {})
                        
                        import torch.nn as nn
                        
                        class PyTorchMLP(nn.Module):
                            def __init__(self, layers, activation='relu', dropout_rate=0.0):
                                super(PyTorchMLP, self).__init__()
                                self.layer_list = nn.ModuleList()
                                for i in range(len(layers) - 1):
                                    self.layer_list.append(nn.Linear(layers[i], layers[i+1]))
                                self.activation_name = activation
                                if activation == 'relu':
                                    self.activation = nn.ReLU()
                                elif activation == 'sigmoid':
                                    self.activation = nn.Sigmoid()
                                elif activation == 'tanh':
                                    self.activation = nn.Tanh()
                                else:
                                    self.activation = nn.ReLU()
                                self.dropout = nn.Dropout(dropout_rate) if dropout_rate > 0 else None
                                
                            def forward(self, x):
                                for i, layer in enumerate(self.layer_list):
                                    x = layer(x)
                                    if i < len(self.layer_list) - 1:
                                        x = self.activation(x)
                                        if self.dropout:
                                            x = self.dropout(x)
                                return x
                        
                        model = PyTorchMLP(**model_config)
                        model.load_state_dict(state_dict)
                        model.eval()
                        
                        if 'metadata' in loaded_data:
                            model_metadata.update(loaded_data['metadata'])
                            
                        logger.info(f"✅ MLP reconstructed from state_dict (format 2)")
                    
                    # SOUS-CAS 2C: Format avec architecture imbriquée
                    elif 'model' in loaded_data and isinstance(loaded_data['model'], dict):
                        model_dict = loaded_data['model']
                        if 'state_dict' in model_dict and 'config' in model_dict:
                            state_dict = model_dict['state_dict']
                            model_config = model_dict['config']
                            
                            import torch.nn as nn
                            class PyTorchMLP(nn.Module):
                                def __init__(self, layers, **kwargs):
                                    super(PyTorchMLP, self).__init__()
                                    self.layer_list = nn.ModuleList()
                                    for i in range(len(layers) - 1):
                                        self.layer_list.append(nn.Linear(layers[i], layers[i+1]))
                                    self.activation = nn.ReLU()
                                    
                                def forward(self, x):
                                    for i, layer in enumerate(self.layer_list):
                                        x = layer(x)
                                        if i < len(self.layer_list) - 1:
                                            x = self.activation(x)
                                    return x
                            
                            model = PyTorchMLP(**model_config)
                            model.load_state_dict(state_dict)
                            model.eval()
                            
                            if 'metadata' in loaded_data:
                                model_metadata.update(loaded_data['metadata'])
                                
                            logger.info(f"✅ MLP reconstructed from nested structure")
                    
                    # SOUS-CAS 2D: Format inconnu
                    else:
                        logger.warning(f"⚠️ Unknown dictionary format. Trying to find nn.Module in values...")
                        for key, value in loaded_data.items():
                            if hasattr(value, 'eval') and hasattr(value, 'forward'):
                                model = value
                                model.eval()
                                logger.info(f"✅ Found nn.Module in key: {key}")
                                break
                        
                        if model is None:
                            logger.error("❌ No nn.Module found in PyTorch file")
                            raise HTTPException(
                                status_code=500, 
                                detail=f"Unsupported PyTorch model format. Keys: {list(loaded_data.keys())}"
                            )
                
                # CAS 3: Format inconnu
                else:
                    logger.error(f"❌ Unknown PyTorch model format: {type(loaded_data)}")
                    raise HTTPException(
                        status_code=500, 
                        detail=f"Unsupported PyTorch model format: {type(loaded_data)}"
                    )
                
                # Charger les métadonnées séparées si elles existent
                metadata_path = model_path.replace(".pt", "_metadata.joblib")
                if os.path.exists(metadata_path):
                    try:
                        additional_metadata = joblib.load(metadata_path)
                        model_metadata.update(additional_metadata)
                        logger.info(f"✅ Loaded additional PyTorch model metadata")
                    except Exception as e:
                        logger.warning(f"⚠️ Could not load additional metadata: {str(e)}")
                
            except Exception as e:
                logger.error(f"❌ Failed to load PyTorch model: {str(e)}")
                raise HTTPException(status_code=500, detail=f"Failed to load PyTorch model: {str(e)}")
        
        else:
            # ==================== CHARGEMENT SCIKIT-LEARN ====================
            try:
                saved_data = joblib.load(model_path)
                logger.info(f"🔍 Loaded data structure: {type(saved_data)}")
                
                if not isinstance(saved_data, dict):
                    logger.error("❌ Invalid model data structure - expected dictionary")
                    raise HTTPException(status_code=500, detail="Model data corrupted")
                
                logger.info(f"📋 Saved data keys: {list(saved_data.keys())}")
                
                # Extraction robuste du modèle
                if 'model' in saved_data:
                    raw_model = saved_data['model']
                    scaler = saved_data.get('scaler')
                    model_metadata = saved_data.get('metadata', {}) or {}
                    logger.info(f"🔍 Raw model type from saved_data: {type(raw_model)}")
                    
                    # Nested train wrappers (KMeans / anomaly): {model, scaler, feature_names, ...}
                    if isinstance(raw_model, dict):
                        if scaler is None:
                            scaler = raw_model.get('scaler')
                        for _k in ('algorithm', 'model_type', 'params', 'feature_names', 'target_excluded'):
                            if _k in raw_model and _k not in model_metadata:
                                model_metadata[_k] = raw_model[_k]

                    # Ajouter le label mapping aux métadonnées
                    if label_mapping:
                        model_metadata['label_mapping'] = label_mapping
                        model_metadata['reverse_label_mapping'] = reverse_label_mapping
                    
                    # Cas 1: Le modèle est déjà un objet scikit-learn valide
                    if hasattr(raw_model, 'predict'):
                        model = raw_model
                        logger.info(f"✅ Model is directly usable - Type: {type(model)}")
                    
                    # Cas 2: Le modèle est un dictionnaire
                    elif isinstance(raw_model, dict):
                        logger.info(f"🔍 Model is a dictionary, searching for actual model...")
                        logger.info(f"🔍 Dictionary keys: {list(raw_model.keys())}")
                        
                        found_model = False
                        for key, value in raw_model.items():
                            if hasattr(value, 'predict'):
                                model = value
                                found_model = True
                                logger.info(f"✅ Found actual model in key '{key}' - Type: {type(model)}")
                                break
                        
                        if not found_model:
                            def find_model_in_dict(obj, path=""):
                                if hasattr(obj, 'predict'):
                                    return obj, path
                                elif isinstance(obj, dict):
                                    for k, v in obj.items():
                                        result = find_model_in_dict(v, f"{path}.{k}" if path else k)
                                        if result[0]:
                                            return result
                                elif isinstance(obj, (list, tuple)):
                                    for i, item in enumerate(obj):
                                        result = find_model_in_dict(item, f"{path}[{i}]")
                                        if result[0]:
                                            return result
                                return None, path
                            
                            found_model, model_path_found = find_model_in_dict(raw_model)
                            if found_model:
                                model = found_model
                                logger.info(f"✅ Found model in nested structure at '{model_path_found}' - Type: {type(model)}")
                            else:
                                logger.error("❌ No valid model found in dictionary structure")
                                raise HTTPException(status_code=500, detail="No valid model found in saved data")
                    
                    else:
                        logger.error(f"❌ Unknown model structure: {type(raw_model)}")
                        raise HTTPException(status_code=500, detail=f"Unknown model structure: {type(raw_model)}")
                    
                elif hasattr(saved_data, 'predict'):
                    model = saved_data
                    logger.info(f"✅ Loaded model directly - Type: {type(model)}")
                else:
                    logger.error("❌ Unknown model structure in saved file")
                    raise HTTPException(status_code=500, detail="Unknown model structure")
                
                if not hasattr(model, 'predict'):
                    logger.error(f"❌ Final model validation failed. Model type: {type(model)}")
                    raise HTTPException(status_code=500, detail="Invalid model object - missing predict method")
                
                logger.info(f"✅ Scikit-learn model loaded and validated successfully - Type: {type(model)}")
                
            except HTTPException:
                raise
            except Exception as e:
                logger.error(f"❌ Failed to load scikit-learn model: {str(e)}")
                raise HTTPException(status_code=500, detail=f"Failed to load model: {str(e)}")

        # ==================== DÉTERMINER LES COLONNES À UTILISER ====================
        is_anomaly_pred = _is_anomaly_model(model, model_type, model_metadata)
        meta_features = model_metadata.get("feature_names") if isinstance(model_metadata, dict) else None
        target_excluded = None
        if isinstance(model_metadata, dict):
            target_excluded = model_metadata.get("target_excluded")

        if meta_features:
            required_columns = [c for c in meta_features if c not in ("split_type", "id")]
            logger.info(f"📊 Using frozen feature_names from model file: {required_columns}")
        elif expected_features:
            required_columns = [c for c in expected_features if c != target_column]
            logger.info(f"📊 Using expected features from frontend: {required_columns}")
        else:
            if model_type == "kmeans":
                required_columns = list(db_columns or [])
            else:
                required_columns = [col for col in (db_columns or []) if col != target_column]
            logger.info(f"📊 Using saved DB columns: {required_columns}")

        # Anomaly / explicit exclusions: never feed target into the model
        drop_targets = {t for t in (target_column, target_excluded) if t}
        if drop_targets:
            required_columns = [c for c in required_columns if c not in drop_targets]

        # ==================== APPLY SHARED PIPELINE (raw → features) ====================
        working_input = dict(input_data or {})
        # Strip target from raw input so it cannot leak into features
        for t in drop_targets:
            working_input.pop(t, None)

        if apply_pipeline and applied_actions:
            try:
                # Always pass dataset target so label_encoding(target) is skipped by the pipeline.
                # For anomaly, target is still stripped from features afterward (never used to score).
                transformed_list, transform_steps = apply_actions_to_records(
                    [working_input],
                    applied_actions,
                    target_column=target_column,
                )
                working_input = transformed_list[0]
                for t in drop_targets:
                    working_input.pop(t, None)
                transformed_preview = {
                    k: working_input.get(k) for k in required_columns if k in working_input
                }
                logger.info(f"🔧 Applied {len(applied_actions)} actions from model pipeline")
            except Exception as e:
                logger.error(f"❌ Pipeline transform failed: {e}")
                raise HTTPException(status_code=400, detail=f"Preprocessing pipeline failed: {str(e)}")

        # Fill missing final features with 0 (e.g. unmatched one-hot)
        for col in required_columns:
            if col not in working_input:
                working_input[col] = 0

        missing_columns = [col for col in required_columns if col not in working_input]
        if missing_columns:
            logger.error(f"❌ Missing columns after pipeline: {missing_columns}")
            raise HTTPException(
                status_code=400,
                detail=f"Missing columns after preprocessing: {missing_columns}"
            )

        try:
            input_array = build_feature_matrix(
                [working_input], required_columns, target_column=target_column
            )
            input_values = input_array[0].tolist()
        except Exception as e:
            logger.error(f"❌ Invalid feature matrix: {e}")
            raise HTTPException(status_code=400, detail=str(e))

        logger.info(f"📊 Final input values prepared: {input_values}")
        logger.info(f"📊 Number of features: {len(input_values)}")

        # ==================== PRÉDICTION SELON LE TYPE DE MODÈLE ====================
        try:
            prediction_result = {}
            
            if model_type == "kmeans":
                if not hasattr(model, 'predict'):
                    logger.error(f"❌ KMeans model validation failed. Model type: {type(model)}")
                    raise HTTPException(
                        status_code=500, 
                        detail="Invalid KMeans model object - missing predict method"
                    )
                
                input_array = np.array([input_values])
                
                if scaler is not None:
                    logger.info("🔧 Applying scaling to input data")
                    input_array = scaler.transform(input_array)
                
                cluster_prediction = model.predict(input_array)[0]
                visualization_data = model_metadata.get('visualization_data', {})
                cluster_info = model_metadata.get('cluster_info', [])
                
                prediction_result = {
                    "cluster": int(cluster_prediction),
                    "cluster_info": cluster_info[cluster_prediction] if cluster_info and cluster_prediction < len(cluster_info) else {},
                    "visualization_data": visualization_data,
                    "input_point": input_values
                }
                
                logger.info(f"✅ KMeans prediction successful: Cluster {cluster_prediction}")

            elif (
                _is_anomaly_model(model, model_type, model_metadata)
            ):
                if not hasattr(model, "predict"):
                    raise HTTPException(500, detail="Invalid anomaly model — missing predict()")

                input_array = np.array([input_values], dtype=float)
                anom = _anomaly_predict_row(model, input_array, scaler=scaler)[0]
                prediction_result = {
                    **anom,
                    "algorithm": model_metadata.get("algorithm")
                    or getattr(model, "__class__", type(model)).__name__,
                }
                logger.info(
                    "✅ Anomaly prediction: %s (score=%.4f)",
                    anom["anomaly_label"],
                    anom["anomaly_score"],
                )
                
            elif framework == "pytorch":
                # ==================== PRÉDICTION PYTORCH ====================
                try:
                    input_tensor = torch.FloatTensor([input_values])
                    
                    with torch.no_grad():
                        output = model(input_tensor)
                    
                    logger.info(f"🔍 PyTorch model output shape: {output.shape}, output: {output}")
                    
                    problem_type = model_metadata.get('problem_type', 'regression')
                    is_classification = model_metadata.get('is_classification', False)
                    class_names = model_metadata.get('class_names', [])
                    
                    # Si on a un label mapping, l'utiliser pour les noms de classes
                    if label_mapping and not class_names:
                        class_names = list(label_mapping.keys())
                        logger.info(f"📋 Using label mapping for class names: {class_names}")
                    
                    output_shape = output.shape
                    
                    if len(output_shape) == 2 and output_shape[1] > 1:
                        probabilities = torch.softmax(output, dim=1)
                        predicted_class_index = torch.argmax(output, dim=1).item()
                        prediction_value = predicted_class_index
                        
                        prob_dict = {}
                        for i in range(output_shape[1]):
                            if i < len(class_names):
                                class_label = class_names[i]
                            else:
                                class_label = reverse_label_mapping.get(str(i), f"class_{i}")
                            prob_dict[class_label] = float(probabilities[0][i])
                        
                        # Obtenir le nom de la classe prédite
                        predicted_class_name = class_names[predicted_class_index] if predicted_class_index < len(class_names) else reverse_label_mapping.get(str(predicted_class_index), str(predicted_class_index))
                        
                        prediction_result = {
                            "prediction": float(prediction_value),
                            "probabilities": prob_dict,
                            "predicted_class": predicted_class_name,
                            "confidence": float(torch.max(probabilities, dim=1)[0].item())
                        }
                        
                        logger.info(f"✅ PyTorch multiclass - Predicted: {predicted_class_name} (index: {predicted_class_index})")
                    
                    elif problem_type == 'binary_classification' or (is_classification and output_shape[1] == 1):
                        probability = torch.sigmoid(output).item()
                        prediction_value = 1 if probability >= decision_threshold else 0
                        
                        predicted_class_name = class_names[prediction_value] if prediction_value < len(class_names) else reverse_label_mapping.get(str(prediction_value), str(prediction_value))
                        
                        prediction_result = {
                            "prediction": float(prediction_value),
                            "probability": float(probability),
                            "predicted_class": predicted_class_name,
                            "predicted_label": predicted_class_name,
                            "confidence": float(probability if prediction_value == 1 else 1 - probability),
                            "decision_threshold": decision_threshold,
                        }
                        
                        logger.info(f"✅ PyTorch binary - Prediction: {predicted_class_name} (value: {prediction_value})")
                    
                    else:
                        if output.numel() == 1:
                            prediction_value = output.item()
                        else:
                            prediction_value = output[0].item() if len(output) > 0 else 0.0
                            
                        prediction_result = {
                            "prediction": float(prediction_value),
                            "output_values": output.tolist() if output.numel() > 1 else None
                        }
                        
                        logger.info(f"✅ PyTorch regression - Prediction: {prediction_value}")
                    
                except Exception as e:
                    logger.error(f"❌ PyTorch prediction error: {str(e)}")
                    raise HTTPException(status_code=500, detail=f"PyTorch prediction failed: {str(e)}")
                
            else:
                # ==================== PRÉDICTION SCIKIT-LEARN ====================
                if not hasattr(model, 'predict'):
                    logger.error(f"❌ Scikit-learn model validation failed. Model type: {type(model)}")
                    raise HTTPException(
                        status_code=500, 
                        detail="Invalid scikit-learn model object - missing predict method"
                    )
                
                input_array = np.array([input_values])
                logger.info(f"🔍 Input array shape: {input_array.shape}")
                
                if scaler is not None:
                    logger.info("🔧 Applying scaling to input data")
                    input_array = scaler.transform(input_array)
                    logger.info(f"🔍 Scaled input array: {input_array}")
                
                # Faire la prédiction
                prediction = model.predict(input_array)[0]
                logger.info(f"🔍 Raw prediction result: {prediction}, type: {type(prediction)}")
                
                # ==================== GESTION DES PROBABILITÉS ET DES NOMS DE CLASSES ====================
                if hasattr(model, 'predict_proba'):
                    try:
                        probabilities = model.predict_proba(input_array)[0]
                        logger.info(f"🔍 Probabilities: {probabilities}")
                        
                        # Récupérer les classes du modèle
                        model_classes = getattr(model, 'classes_', [])
                        logger.info(f"🔍 Model classes_: {model_classes}")
                        
                        # Récupérer les métadonnées
                        class_names = model_metadata.get('class_names', [])
                        
                        # Déterminer les noms de classes à afficher
                        effective_class_names = []
                        
                        if class_names and len(class_names) == len(probabilities):
                            effective_class_names = class_names
                            logger.info(f"📋 Using class_names from metadata: {effective_class_names}")
                        elif label_mapping:
                            # Utiliser le mapping inverse pour obtenir les labels
                            for i, cls_val in enumerate(model_classes):
                                cls_str = str(cls_val)
                                if cls_str in reverse_label_mapping:
                                    effective_class_names.append(reverse_label_mapping[cls_str])
                                else:
                                    effective_class_names.append(f"Class_{cls_val}")
                            logger.info(f"📋 Using label mapping for class names: {effective_class_names}")
                        else:
                            # Convertir les classes du modèle en strings
                            effective_class_names = [str(cls) for cls in model_classes]
                            logger.info(f"📋 Using model classes as strings: {effective_class_names}")
                        
                        # S'assurer que les tailles correspondent
                        if len(effective_class_names) != len(probabilities):
                            logger.warning(f"⚠️ Class names count ({len(effective_class_names)}) != probabilities count ({len(probabilities)})")
                            min_len = min(len(effective_class_names), len(probabilities))
                            effective_class_names = effective_class_names[:min_len]
                            probabilities = probabilities[:min_len]
                        
                        # Construire le dictionnaire des probabilités avec les vrais noms
                        prob_dict = {}
                        for i, prob in enumerate(probabilities):
                            class_label = effective_class_names[i] if i < len(effective_class_names) else f"class_{i}"
                            prob_dict[class_label] = float(prob)
                        
                        # Binary threshold override when 2 classes + user threshold ≠ 0.5
                        predicted_class_index = None
                        if len(probabilities) == 2:
                            # Treat index 1 as positive class probability
                            pos_prob = float(probabilities[1])
                            predicted_class_index = 1 if pos_prob >= decision_threshold else 0
                            prediction = model_classes[predicted_class_index] if len(model_classes) > predicted_class_index else predicted_class_index
                        elif isinstance(prediction, (int, np.integer)):
                            predicted_class_index = int(prediction)
                        elif isinstance(prediction, (float, np.floating)):
                            predicted_class_index = int(prediction)
                        else:
                            try:
                                predicted_class_index = list(model_classes).index(prediction)
                            except (ValueError, TypeError):
                                predicted_class_index = int(np.argmax(probabilities))
                        
                        if predicted_class_index is not None and predicted_class_index < len(effective_class_names):
                            predicted_class_name = effective_class_names[predicted_class_index]
                        else:
                            predicted_class_name = str(prediction)
                        
                        confidence = float(probabilities[predicted_class_index]) if predicted_class_index is not None else float(np.max(probabilities))
                        
                        prediction_result = {
                            "prediction": float(prediction) if isinstance(prediction, (int, float, np.number)) else str(prediction),
                            "probabilities": prob_dict,
                            "predicted_class": predicted_class_name,
                            "predicted_label": predicted_class_name,
                            "confidence": confidence,
                            "decision_threshold": decision_threshold if len(probabilities) == 2 else None,
                            "threshold_applied": len(probabilities) == 2,
                            "positive_class_prob": float(probabilities[1]) if len(probabilities) == 2 else None,
                            "positive_class_name": effective_class_names[1] if len(probabilities) == 2 and len(effective_class_names) > 1 else None,
                        }
                        
                        logger.info(f"✅ Classification - Predicted: {predicted_class_name} (raw: {prediction}), Confidence: {confidence:.4f}")
                        logger.info(f"📊 Probability distribution: {prob_dict}")
                        
                    except Exception as e:
                        logger.warning(f"⚠️ Could not get probabilities: {str(e)}")
                        # Essayer de trouver le nom de la classe même sans probabilités
                        predicted_class_name = str(prediction)
                        if label_mapping and str(prediction) in reverse_label_mapping:
                            predicted_class_name = reverse_label_mapping[str(prediction)]
                        elif isinstance(prediction, (int, np.integer)) and hasattr(model, 'classes_'):
                            model_classes = model.classes_
                            if prediction < len(model_classes):
                                class_val = model_classes[prediction]
                                if str(class_val) in reverse_label_mapping:
                                    predicted_class_name = reverse_label_mapping[str(class_val)]
                                else:
                                    predicted_class_name = str(class_val)
                        
                        prediction_result = {
                            "prediction": float(prediction) if isinstance(prediction, (int, float, np.number)) else str(prediction),
                            "predicted_class": predicted_class_name
                        }
                else:
                    # Modèle sans predict_proba (régression ou autre)
                    predicted_class_name = None
                    if label_mapping and str(prediction) in reverse_label_mapping:
                        predicted_class_name = reverse_label_mapping[str(prediction)]
                    
                    prediction_result = {
                        "prediction": float(prediction) if isinstance(prediction, (int, float, np.number)) else str(prediction)
                    }
                    
                    if predicted_class_name:
                        prediction_result["predicted_class"] = predicted_class_name
                    
                    logger.info(f"✅ Regression/basic prediction: {prediction}")
                
                # Ajouter le label mapping à la réponse pour référence
                if label_mapping:
                    prediction_result["label_mapping"] = label_mapping
                
                logger.info(f"✅ Scikit-learn prediction successful")

            # Enrich response (all model types)
            prediction_result["model_name"] = model_name
            prediction_result["model_type"] = model_type
            prediction_result["pipeline_applied"] = bool(apply_pipeline and applied_actions)
            prediction_result["pipeline_summary"] = pipeline_summary(applied_actions)
            if transform_steps:
                prediction_result["transformation_steps"] = [
                    {
                        "action": s.get("action"),
                        "column": s.get("column"),
                        "status": s.get("status"),
                        "message": s.get("message"),
                    }
                    for s in transform_steps
                ]
            if transformed_preview is not None:
                prediction_result["features_used"] = transformed_preview

            # Always expose both original label + encoded numerized value for classification
            raw_pred = prediction_result.get("prediction")
            if (
                not _is_anomaly_model(model, model_type, model_metadata)
                and model_type != "kmeans"
                and (
                    model_type == "classification"
                    or prediction_result.get("probabilities")
                    or (
                        prediction_result.get("predicted_class") is not None
                        and prediction_result.get("is_anomaly") is None
                    )
                )
            ):
                human, enc = decode_class_label(raw_pred, reverse_label_mapping)
                # Prefer already-decoded name if it looks non-numeric
                existing = prediction_result.get("predicted_class") or prediction_result.get("predicted_label")
                if existing is not None and not str(existing).replace(".", "", 1).isdigit():
                    human = str(existing)
                else:
                    # also try decoding existing if it was numeric
                    human2, _ = decode_class_label(existing if existing is not None else raw_pred, reverse_label_mapping)
                    human = human2
                prediction_result["predicted_label"] = human
                prediction_result["predicted_class"] = human
                prediction_result["encoded_class"] = enc if enc is not None else raw_pred
                prediction_result["encoded_value"] = prediction_result["encoded_class"]
                if label_mapping:
                    prediction_result["label_mapping"] = label_mapping
                    prediction_result["reverse_label_mapping"] = reverse_label_mapping
                # Remap probability keys to original labels when possible
                probs = prediction_result.get("probabilities")
                if isinstance(probs, dict) and reverse_label_mapping:
                    remapped = {}
                    for k, v in probs.items():
                        nice, _ = decode_class_label(k, reverse_label_mapping)
                        remapped[nice] = v
                    prediction_result["probabilities"] = remapped
                    prediction_result["probabilities_encoded"] = probs
            
            return prediction_result
            
        except Exception as e:
            logger.error(f"❌ Prediction failed: {str(e)}")
            raise HTTPException(
                status_code=500, 
                detail=f"Prediction computation failed: {str(e)}"
            )
            
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"❌ Unexpected error in prediction: {str(e)}")
        raise HTTPException(
            status_code=500, 
            detail=f"Unexpected prediction error: {str(e)}"
        )

@router.get("/model-inference-info")
async def model_inference_info(
    modelId: int = Query(...),
    current_user_id: str = Depends(get_current_user2),
):
    """Schema for Use Model: raw input columns + pipeline summary (no ML transforms on FE)."""
    with get_db_connection() as conn:
        with conn.cursor() as cur:
            _ensure_user_saved_models_pipeline_columns(cur, conn)
            cur.execute(
                """
                SELECT id, model_name, db_name, db_columns, model_type, framework,
                       r2_score, accuracy_score, applied_actions, raw_input_columns,
                       model_path
                FROM user_saved_models
                WHERE id = %s AND user_id = %s
                """,
                (modelId, current_user_id),
            )
            row = cur.fetchone()
            if not row:
                raise HTTPException(404, "Model not found")

            (mid, model_name, db_name, db_columns, model_type, framework,
             r2_score, accuracy_score, applied_actions, raw_input_columns,
             model_path) = row
            algorithm = None
            try:
                cur.execute(
                    "SELECT algorithm FROM user_saved_models WHERE id = %s AND user_id = %s",
                    (modelId, current_user_id),
                )
                arow = cur.fetchone()
                if arow:
                    algorithm = arow[0]
            except Exception:
                algorithm = None
            applied_actions = applied_actions or []
            if not applied_actions:
                applied_actions = _fetch_dataset_applied_actions(cur, db_name, current_user_id)

            target_column = None
            base = (db_name or "").replace("_numerized", "")
            for cand in (base, db_name, f"{base}_numerized"):
                if not cand:
                    continue
                cur.execute(
                    """
                    SELECT target_column FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                    """,
                    (cand, current_user_id),
                )
                trow = cur.fetchone()
                if trow and trow[0]:
                    target_column = trow[0]
                    break

            file_feature_names = None
            file_meta = {}
            is_anomaly = False
            try:
                if model_path and os.path.exists(model_path) and not str(model_path).endswith(".pt"):
                    saved = joblib.load(model_path)
                    _m, _s, file_meta = _extract_sklearn_model_from_joblib(saved)
                    file_feature_names = file_meta.get("feature_names")
                    is_anomaly = _is_anomaly_model(_m, model_type, file_meta, algorithm)
            except Exception as e:
                logger.warning("model-inference-info: could not inspect saved file: %s", e)
                is_anomaly = _is_anomaly_model(None, model_type, None, algorithm)

            feature_columns = list(file_feature_names or []) or [
                c for c in (db_columns or []) if c not in ("split_type", "id")
            ]
            target_excluded = file_meta.get("target_excluded") or target_column
            if target_excluded:
                feature_columns = [c for c in feature_columns if c != target_excluded]
            if target_column:
                feature_columns = [c for c in feature_columns if c != target_column]

            # Anomaly: never ask the user for the dataset target as an input feature
            raw_cols = list(raw_input_columns or []) or infer_raw_input_columns(
                feature_columns,
                applied_actions,
                None if is_anomaly else target_column,
            )
            if is_anomaly and target_column:
                raw_cols = [c for c in raw_cols if c != target_column]
            raw_cols = [c for c in raw_cols if c not in ("split_type", "id")]

            reverse_map, forward_map = extract_target_label_maps(
                applied_actions, None if is_anomaly else target_column
            )

            return {
                "model_id": mid,
                "model_name": model_name,
                "db_name": db_name,
                "model_type": model_type,
                "algorithm": algorithm or file_meta.get("algorithm"),
                "framework": framework,
                "r2_score": r2_score,
                "accuracy_score": accuracy_score,
                # For anomaly: still report dataset target for context, but not as a form field
                "target_column": None if is_anomaly else target_column,
                "dataset_target_column": target_column,
                "is_anomaly_model": is_anomaly,
                "feature_columns": feature_columns,
                "raw_input_columns": raw_cols,
                "applied_actions": applied_actions,
                "pipeline_summary": pipeline_summary(applied_actions),
                "has_pipeline": len(applied_actions) > 0,
                "label_mapping": {} if is_anomaly else forward_map,
                "reverse_label_mapping": {} if is_anomaly else reverse_map,
            }


@router.get("/sample-row")
async def sample_row(
    bdName: str = Query(...),
    split: str = Query("test"),
    random: bool = Query(True),
    modelId: Optional[int] = Query(None),
    limit: int = Query(1, ge=1, le=50),
    current_user_id: str = Depends(get_current_user2),
):
    """
    Return RAW example row(s) for the prediction form (default 1, up to 50).
    Prefers *_backup / *_reset (pre-transform) joined to test rows when possible.
    """
    base = bdName.replace("_numerized", "").replace("_backup", "").replace("_reset", "").lower()
    with get_db_connection() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT 1 FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
                """,
                (base, current_user_id),
            )
            if not cur.fetchone():
                raise HTTPException(403, "Dataset not found or not owned by user")

            candidates = [f"{base}_backup", f"{base}_reset", base]
            source_table = None
            for t in candidates:
                cur.execute(
                    """
                    SELECT EXISTS (
                        SELECT 1 FROM information_schema.tables
                        WHERE table_name = %s
                    )
                    """,
                    (t,),
                )
                if cur.fetchone()[0]:
                    source_table = t
                    break
            if not source_table:
                raise HTTPException(404, "No table available for sampling")

            cur.execute(
                """
                SELECT column_name FROM information_schema.columns
                WHERE table_name = %s
                ORDER BY ordinal_position
                """,
                (source_table,),
            )
            colnames = [r[0] for r in cur.fetchall()]
            has_split = "split_type" in colnames
            has_id = "id" in colnames
            order_sql = "ORDER BY RANDOM()" if random else "ORDER BY 1"
            source_note = source_table
            rows_raw = []

            if has_id and source_table != base:
                cur.execute(
                    "SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = %s)",
                    (base,),
                )
                if cur.fetchone()[0]:
                    cur.execute(
                        """
                        SELECT EXISTS (
                            SELECT 1 FROM information_schema.columns
                            WHERE table_name = %s AND column_name = 'split_type'
                        )
                        """,
                        (base,),
                    )
                    if cur.fetchone()[0] and split:
                        cur.execute(
                            f"""
                            SELECT s.*
                            FROM {source_table} s
                            INNER JOIN {base} m ON s.id = m.id
                            WHERE m.split_type = %s
                            {order_sql}
                            LIMIT %s
                            """,
                            (split, limit),
                        )
                        rows_raw = cur.fetchall()
                        if rows_raw:
                            source_note = f"{source_table} matched to {base}.{split}"

            if not rows_raw:
                if has_split and split and source_table == base:
                    cur.execute(
                        f"SELECT * FROM {source_table} WHERE split_type = %s {order_sql} LIMIT %s",
                        (split, limit),
                    )
                else:
                    cur.execute(f"SELECT * FROM {source_table} {order_sql} LIMIT %s", (limit,))
                rows_raw = cur.fetchall()

            if not rows_raw:
                raise HTTPException(404, f"No sample rows found (split={split})")

            keep = None
            if modelId is not None:
                try:
                    info = await model_inference_info(modelId=modelId, current_user_id=current_user_id)
                    keep = set(info.get("raw_input_columns") or [])
                except Exception:
                    keep = None

            rows = []
            for row in rows_raw:
                data = {colnames[i]: row[i] for i in range(min(len(colnames), len(row)))}
                data.pop("split_type", None)
                rid = data.pop("id", None)
                if keep:
                    data = {k: v for k, v in data.items() if k in keep}
                rows.append({"id": rid, "values": data})

            return {
                "rows": rows,
                "row": rows[0]["values"] if rows else {},
                "count": len(rows),
                "source": source_note,
                "split": split,
                "message": f"{len(rows)} example(s) from {source_note}"
                + (f" ({split} split)" if split else ""),
            }


@router.post("/predict-batch")
async def predict_batch(
    modelId: int = Query(...),
    decisionThreshold: float = Query(0.5),
    page: int = Query(1, ge=1),
    pageSize: int = Query(50, ge=10, le=100),
    file: UploadFile = File(...),
    current_user_id: str = Depends(get_current_user2),
):
    """
    Batch prediction with clear validation errors.
    - Checks expected column names
    - Keeps target column if present (display only — never used as a feature)
    - Skips bad rows with specific skip reasons
    - Anomaly models: scaler applied, labels mapped to normal/anomaly (not raw -1/1)
    """
    import uuid
    import tempfile
    from collections import Counter

    try:
        decisionThreshold = max(0.01, min(0.99, float(decisionThreshold)))

        with get_db_connection() as conn:
            with conn.cursor() as cur:
                _ensure_user_saved_models_pipeline_columns(cur, conn)
                cur.execute(
                    """
                    SELECT model_name, model_path, db_columns, db_name, framework, model_type,
                           applied_actions, raw_input_columns
                    FROM user_saved_models
                    WHERE id = %s AND user_id = %s
                    """,
                    (modelId, current_user_id),
                )
                row = cur.fetchone()
                if not row:
                    raise HTTPException(404, detail="Model not found")
                (model_name, model_path, db_columns, db_name, framework, model_type,
                 applied_actions, raw_input_columns) = row
                algorithm = None
                try:
                    cur.execute(
                        "SELECT algorithm FROM user_saved_models WHERE id = %s AND user_id = %s",
                        (modelId, current_user_id),
                    )
                    arow = cur.fetchone()
                    if arow:
                        algorithm = arow[0]
                except Exception:
                    algorithm = None
                applied_actions = applied_actions or _fetch_dataset_applied_actions(cur, db_name, current_user_id) or []

                target_column = None
                base = (db_name or "").replace("_numerized", "")
                for cand in (base, db_name, f"{base}_numerized"):
                    if not cand:
                        continue
                    cur.execute(
                        """
                        SELECT target_column FROM user_tables_metadata
                        WHERE table_name = %s AND owner_id = %s
                        """,
                        (cand, current_user_id),
                    )
                    trow = cur.fetchone()
                    if trow and trow[0]:
                        target_column = trow[0]
                        break

        if framework == "pytorch":
            raise HTTPException(400, detail="Batch prediction for PyTorch models is not enabled yet. Use single prediction.")

        if not os.path.exists(model_path):
            raise HTTPException(404, detail=f"Model file not found on disk: {model_path}")

        content = await file.read()
        if not content:
            raise HTTPException(400, detail="Uploaded file is empty.")

        try:
            df_raw = pd.read_csv(io.BytesIO(content))
        except Exception as e:
            raise HTTPException(
                400,
                detail=f"Could not read CSV. Check the file format (comma-separated, UTF-8). Details: {e}",
            )

        if df_raw.empty:
            raise HTTPException(400, detail="CSV has no data rows.")

        df_raw.columns = [str(c).strip() for c in df_raw.columns]
        csv_cols = list(df_raw.columns)

        try:
            saved = joblib.load(model_path)
            model, scaler, model_meta = _extract_sklearn_model_from_joblib(saved)
        except HTTPException:
            raise
        except Exception as e:
            raise HTTPException(
                500,
                detail=f"Could not load a usable model for batch prediction: {e}",
            )

        if not hasattr(model, "predict"):
            raise HTTPException(
                500,
                detail="Saved model object has no predict() method after extraction.",
            )

        is_anomaly = _is_anomaly_model(model, model_type, model_meta, algorithm)

        # Prefer frozen feature names from the saved artifact (excludes target for anomaly)
        feature_columns = list(model_meta.get("feature_names") or []) or [
            c for c in (db_columns or []) if c not in ("split_type", "id")
        ]
        # Never use dataset target as a model feature (anomaly / supervised)
        target_excluded = model_meta.get("target_excluded") or target_column
        if target_excluded:
            feature_columns = [c for c in feature_columns if c != target_excluded]
        if target_column:
            feature_columns = [c for c in feature_columns if c != target_column]

        expected_raw = list(raw_input_columns or []) or infer_raw_input_columns(
            feature_columns, applied_actions, target_column if not is_anomaly else None
        )
        # Anomaly: target must never be a required input feature
        if is_anomaly and target_column:
            expected_raw = [c for c in expected_raw if c != target_column]
        expected_raw = [c for c in expected_raw if c not in ("split_type", "id")]

        has_target_in_csv = bool(target_column and target_column in csv_cols)

        ignore = {target_column, "split_type", "id", None}
        required = [c for c in expected_raw if c not in ignore]
        # Also require feature columns if raw list is empty/wrong
        if not required:
            required = list(feature_columns)
        missing = [c for c in required if c not in csv_cols]
        extra = [c for c in csv_cols if c not in required and c not in ignore]

        if missing:
            raise HTTPException(
                400,
                detail=(
                    f"CSV is missing required columns expected by this model: {missing}. "
                    f"Expected columns: {required}. "
                    f"Your CSV columns: {csv_cols}."
                ),
            )

        reverse_map, _forward = extract_target_label_maps(
            applied_actions, None if is_anomaly else target_column
        )

        result_rows = []
        skip_log = []
        labels_ok = []
        threshold_applied_count = 0

        for idx, series in df_raw.iterrows():
            row_num = int(idx) + 2  # header is line 1
            row_dict = series.to_dict()

            useful = {k: v for k, v in row_dict.items() if k not in ignore}
            if all(pd.isna(v) or str(v).strip() == "" for v in useful.values()):
                skip_log.append({"row": row_num, "reason": "Empty row (all required fields blank)"})
                continue

            # Keep actual target for display only (never fed to the model)
            actual_target = None
            if has_target_in_csv:
                actual_target = row_dict.get(target_column)

            raw_input = {}
            type_errors = []
            for col in required:
                val = row_dict.get(col, "")
                if pd.isna(val) or str(val).strip() == "":
                    type_errors.append(f"'{col}' is empty")
                    continue
                raw_input[col] = val if not isinstance(val, (np.floating, float)) or not pd.isna(val) else ""

            if type_errors:
                skip_log.append({"row": row_num, "reason": "Missing values: " + "; ".join(type_errors)})
                continue

            try:
                # Pass real target_column so pipeline SKIPS target transforms (label_encoding…).
                # Target is still never used as a model feature (stripped below / build_feature_matrix).
                transformed_list, _steps = apply_actions_to_records(
                    [raw_input],
                    applied_actions,
                    target_column=target_column,
                )
                transformed = transformed_list[0]
            except Exception as e:
                skip_log.append({"row": row_num, "reason": f"Preprocessing failed: {e}"})
                continue

            # Strip target if it somehow appeared after transforms
            if target_column and target_column in transformed:
                transformed.pop(target_column, None)
            if target_excluded and target_excluded in transformed:
                transformed.pop(target_excluded, None)

            for c in feature_columns:
                if c not in transformed:
                    transformed[c] = 0

            try:
                X = build_feature_matrix(
                    [transformed],
                    feature_columns,
                    target_column=target_column,
                )
            except Exception as e:
                skip_log.append({"row": row_num, "reason": f"Invalid feature types after transform: {e}"})
                continue

            try:
                if is_anomaly:
                    anom = _anomaly_predict_row(model, X, scaler=scaler)[0]
                    human = anom["predicted_label"]
                    enc = anom["encoded_class"]
                    conf = None
                    pos_prob = None
                else:
                    # Supervised / clustering: keep prior behavior (no extra outer scaler
                    # unless we later unify loading). Pipeline transforms handle scaling.
                    pred = model.predict(X)[0]
                    conf = None
                    pos_prob = None
                    if hasattr(model, "predict_proba"):
                        try:
                            probs = model.predict_proba(X)[0]
                            if len(probs) == 2:
                                pos = float(probs[1])
                                pos_prob = pos
                                pred_idx = 1 if pos >= decisionThreshold else 0
                                classes = getattr(model, "classes_", np.array([0, 1]))
                                pred = classes[pred_idx]
                                conf = float(probs[pred_idx])
                                threshold_applied_count += 1
                            else:
                                conf = float(np.max(probs))
                        except Exception:
                            conf = None
                    human, enc = decode_class_label(pred, reverse_map)
                    anom = None
            except Exception as e:
                skip_log.append({"row": row_num, "reason": f"Model predict failed: {e}"})
                continue

            labels_ok.append(human)

            out_row = {c: raw_input.get(c, row_dict.get(c)) for c in required}
            if has_target_in_csv:
                # Display-only reference column (not used for prediction)
                out_row[f"actual_{target_column}"] = actual_target
            out_row["predicted_label"] = human
            out_row["encoded_class"] = enc
            out_row["prediction"] = human if is_anomaly else enc
            if is_anomaly and anom:
                out_row["is_anomaly"] = anom["is_anomaly"]
                out_row["anomaly_score"] = round(anom["anomaly_score"], 6)
            if conf is not None:
                out_row["confidence"] = round(conf, 4)
            if pos_prob is not None:
                out_row["positive_class_prob"] = round(pos_prob, 4)
                out_row["decision_threshold"] = decisionThreshold
            out_row["row_status"] = "ok"
            result_rows.append(out_row)

        if not result_rows:
            detail = "No rows could be predicted."
            if skip_log:
                reasons = "; ".join(f"row {s['row']}: {s['reason']}" for s in skip_log[:8])
                detail += " Skip reasons: " + reasons
            if extra:
                detail += f" Note: CSV also has unexpected columns (ignored): {extra}."
            raise HTTPException(400, detail=detail)

        out = pd.DataFrame(result_rows)
        dist = Counter(labels_ok)
        total_ok = len(result_rows)
        total_in = len(df_raw)
        normalish = {"normal", "benign", "legitimate", "0"}
        if is_anomaly:
            intrusion_count = sum(
                1 for lab in labels_ok if str(lab).strip().lower() in ("anomaly", "anomalous", "-1")
            )
        else:
            intrusion_count = sum(1 for lab in labels_ok if str(lab).strip().lower() not in normalish)

        batch_id = str(uuid.uuid4())
        tmp_dir = os.path.join(tempfile.gettempdir(), "automl_batch_preds")
        os.makedirs(tmp_dir, exist_ok=True)
        out_path = os.path.join(tmp_dir, f"{current_user_id}_{batch_id}.csv")
        out.to_csv(out_path, index=False)

        skip_path = os.path.join(tmp_dir, f"{current_user_id}_{batch_id}_skips.json")
        with open(skip_path, "w", encoding="utf-8") as sf:
            json.dump(skip_log, sf)

        start = (page - 1) * pageSize
        end = start + pageSize
        preview = out.iloc[start:end].replace({np.nan: None}).to_dict(orient="records")

        return {
            "batch_id": batch_id,
            "model_name": model_name,
            "model_type": model_type,
            "algorithm": algorithm or model_meta.get("algorithm"),
            "is_anomaly_model": is_anomaly,
            "rows_in_file": total_in,
            "rows_processed": total_ok,
            "rows_skipped": len(skip_log),
            "skipped": skip_log[:100],
            "has_target_column": has_target_in_csv,
            "target_column": target_column if has_target_in_csv else None,
            "target_used_as_feature": False,
            "expected_columns": required,
            "unexpected_columns_ignored": extra,
            "class_distribution": dict(dist),
            "intrusion_count": intrusion_count,
            "intrusion_rate": (intrusion_count / total_ok) if total_ok else 0,
            "page": page,
            "page_size": pageSize,
            "total_pages": max(1, (total_ok + pageSize - 1) // pageSize),
            "preview": preview,
            "decision_threshold": decisionThreshold,
            "threshold_applied": threshold_applied_count > 0,
            "threshold_applied_rows": threshold_applied_count,
            "download_token": batch_id,
            "pipeline_applied": len(applied_actions) > 0,
            "message": (
                f"Processed {total_ok}/{total_in} rows"
                + (f", skipped {len(skip_log)}" if skip_log else "")
                + (
                    ". Anomaly model: target column (if present) is display-only and never used as a feature"
                    if is_anomaly
                    else (
                        f". Binary decision threshold {decisionThreshold:.2f} applied on {threshold_applied_count} row(s)"
                        if threshold_applied_count > 0
                        else (
                            ". Detection threshold not applied (not binary classification with predict_proba)"
                            if total_ok > 0
                            else ""
                        )
                    )
                )
                + (f". Ignored unexpected columns: {extra}" if extra else "")
                + "."
            ),
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.exception("Batch prediction failed")
        # algorithm column may be missing on very old DBs — retry without it once
        if "algorithm" in str(e).lower() and "column" in str(e).lower():
            raise HTTPException(
                500,
                detail=(
                    f"Batch prediction failed (DB schema): {e}. "
                    "Restart the server so algorithm column migrations can run."
                ),
            )
        raise HTTPException(500, detail=f"Batch prediction failed: {type(e).__name__}: {e}")


@router.get("/predict-batch-download")
async def predict_batch_download(
    batchId: str = Query(...),
    current_user_id: str = Depends(get_current_user2),
):
    """Download full batch prediction CSV generated by /predict-batch."""
    import tempfile
    from fastapi.responses import FileResponse

    tmp_dir = os.path.join(tempfile.gettempdir(), "automl_batch_preds")
    path = os.path.join(tmp_dir, f"{current_user_id}_{batchId}.csv")
    if not os.path.exists(path):
        raise HTTPException(404, "Batch result expired or not found. Re-run batch prediction.")
    return FileResponse(path, filename=f"predictions_{batchId}.csv", media_type="text/csv")


@router.get("/predict-batch-preview")
async def predict_batch_preview(
    batchId: str = Query(...),
    page: int = Query(1, ge=1),
    pageSize: int = Query(25, ge=5, le=100),
    current_user_id: str = Depends(get_current_user2),
):
    """
    Paginate an already-computed batch CSV (no re-upload).
    Used by Use Model preview Prev/Next.
    """
    import tempfile

    tmp_dir = os.path.join(tempfile.gettempdir(), "automl_batch_preds")
    path = os.path.join(tmp_dir, f"{current_user_id}_{batchId}.csv")
    if not os.path.exists(path):
        raise HTTPException(
            404,
            detail="Batch result expired or not found. Run batch prediction again.",
        )

    try:
        df = pd.read_csv(path)
    except Exception as e:
        raise HTTPException(500, detail=f"Could not read batch result: {e}")

    total = len(df)
    total_pages = max(1, (total + pageSize - 1) // pageSize) if total else 1
    page = min(page, total_pages)
    start = (page - 1) * pageSize
    end = start + pageSize
    preview = df.iloc[start:end].replace({np.nan: None}).to_dict(orient="records")

    return {
        "batch_id": batchId,
        "page": page,
        "page_size": pageSize,
        "total_rows": total,
        "total_pages": total_pages,
        "preview": preview,
    }


@router.get("/get-applied-actions")
async def get_applied_actions(
    table_name: str = Query(...),
    current_user_id: str = Depends(get_current_user2)
):
    """Récupère les actions appliquées pour un dataset donné"""
    try:
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Alias interne : les actions sont désormais stockées sur la table originale.
                # On garde un repli sur "_numerized" pour les modèles/datasets créés avant ce changement.
                base_name = table_name.replace('_numerized', '')
                candidates = [f"{base_name}_numerized", base_name]

                result = None
                for cand in candidates:
                    cur.execute("""
                        SELECT applied_actions FROM user_tables_metadata
                        WHERE table_name = %s AND owner_id = %s
                    """, (cand.lower(), current_user_id))
                    row = cur.fetchone()
                    if row and row[0]:
                        result = row
                        break

                if not result:
                    return {"actions": []}

                return {"actions": result[0] if result[0] else []}
                
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/get-target-column")
async def get_target_column(
    dbName: str = Query(...),
    current_user_id: str = Depends(get_current_user2)
):
    """Récupère la target column pour un dataset donné"""
    try:
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Trouver le nom de la table originale (sans suffixe)
                base_table_name = dbName.replace('_numerized', '').replace('_backup', '').replace('_reset', '')
                
                cur.execute("""
                    SELECT target_column FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (base_table_name.lower(), current_user_id))
                
                result = cur.fetchone()
                if not result:
                    return {"target_column": None}
                
                return {"target_column": result[0]}
                
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/get-target-column-actions")
async def get_target_column_actions(
    dbName: str = Query(...),
    current_user_id: str = Depends(get_current_user2)
):
    """Récupère les actions appliquées spécifiquement à la target column"""
    try:
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Trouver le nom de la table originale
                base_table_name = dbName.replace('_numerized', '').replace('_backup', '').replace('_reset', '')
                
                # Récupérer la target column
                cur.execute("""
                    SELECT target_column FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (base_table_name.lower(), current_user_id))
                
                result = cur.fetchone()
                if not result or not result[0]:
                    return {"target_actions": []}
                
                target_column = result[0]
                
                # Récupérer les actions appliquées
                cur.execute("""
                    SELECT applied_actions FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (f"{base_table_name}_numerized", current_user_id))
                
                actions_result = cur.fetchone()
                if not actions_result:
                    return {"target_actions": []}
                
                applied_actions = actions_result[0] if actions_result[0] else []
                
                # Filtrer les actions qui concernent la target column
                # MAINTENANT on garde TOUTES les actions sur la target column
                target_actions = []
                for action in applied_actions:
                    if isinstance(action, dict):
                        source_column = action.get('source_column') or action.get('column')
                        if source_column == target_column:
                            target_actions.append(action)
                    elif isinstance(action, str):
                        # Pour les actions au format string "action:column"
                        parts = action.split(':')
                        if len(parts) > 1 and parts[1] == target_column:
                            target_actions.append(action)
                
                logger.info(f"🔍 Found {len(target_actions)} actions for target column '{target_column}': {target_actions}")
                return {"target_actions": target_actions}
                
    except Exception as e:
        logger.error(f"❌ Error fetching target column actions: {str(e)}")
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/get-target-column2")
async def get_target_column2(
    dbName: str = Query(...),
    current_user_id: str = Depends(get_current_user2)
):
    """Récupère la target column pour un dataset donné.

    For unsupervised datasets, target_column is stored as NULL and model_type='unsupervised'.
    The FE sentinel for that case is target_column="no-target-column".
    """
    try:
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Essayer plusieurs variations de noms de table
                table_variations = [
                    dbName.lower(),
                    dbName.replace('_numerized', '').lower(),
                    dbName.replace('_numerized', '_reset').lower(),
                    dbName.replace('_numerized', '_backup').lower()
                ]
                
                # CORRECTION: Utiliser owner_id au lieu de user_id
                # Créer une requête paramétrée pour toutes les variations
                placeholders = ','.join(['%s'] * len(table_variations))
                query = f"""
                    SELECT target_column, model_type FROM user_tables_metadata
                    WHERE table_name IN ({placeholders})
                    AND owner_id = %s  -- CORRECTION ICI: user_id → owner_id
                    ORDER BY 
                        CASE 
                            WHEN table_name = %s THEN 1
                            WHEN table_name = %s THEN 2
                            WHEN table_name = %s THEN 3
                            ELSE 4
                        END,
                        created_at DESC
                    LIMIT 1
                """
                
                params = table_variations + [current_user_id] + table_variations[:3]
                
                cur.execute(query, params)
                result = cur.fetchone()
                
                if not result:
                    return {
                        "target_column": None,
                        "model_type": None,
                        "is_unsupervised": False,
                    }

                target_col, model_type = result[0], result[1]
                is_unsupervised = (model_type == "unsupervised") or (
                    target_col is None and model_type == "unsupervised"
                )

                # Explicit unsupervised choice: NULL target + model_type unsupervised
                if target_col is None and model_type == "unsupervised":
                    return {
                        "target_column": "no-target-column",
                        "model_type": "unsupervised",
                        "is_unsupervised": True,
                    }

                if target_col:
                    return {
                        "target_column": target_col,
                        "model_type": model_type,
                        "is_unsupervised": bool(is_unsupervised),
                    }

                return {
                    "target_column": None,
                    "model_type": model_type,
                    "is_unsupervised": False,
                }
                
    except Exception as e:
        print(f"Error in get-target-column2: {str(e)}")
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=f"Internal server error: {str(e)}")
@router.get("/get-dataset-info")
async def get_dataset_info(
    bdName: str = Query(...),
    current_user_id: str = Depends(get_current_user2)
):
    """Récupère toutes les informations d'un dataset (colonnes et target column)"""
    try:
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                base_table_name = bdName.replace('_numerized', '').replace('_backup', '').replace('_reset', '')
                
                # Chercher les informations dans user_tables_metadata
                cur.execute("""
                    SELECT columns, target_column, split_strategy 
                    FROM user_tables_metadata
                    WHERE (table_name = %s OR table_name = %s) 
                    AND user_id = %s
                    ORDER BY table_name = %s DESC, created_at DESC
                    LIMIT 1
                """, (bdName.lower(), base_table_name.lower(), current_user_id, bdName.lower()))
                
                result = cur.fetchone()
                if not result:
                    raise HTTPException(status_code=404, detail="Dataset not found")
                
                columns, target_column, split_strategy = result
                
                # Si les colonnes sont stockées comme string, les convertir en array
                if isinstance(columns, str):
                    columns = columns.replace('{', '').replace('}', '').split(',')
                
                return {
                    "columns": columns,
                    "target_column": target_column,
                    "split_strategy": split_strategy,
                    "has_target_column": target_column is not None
                }
                
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))





@router.post("/update-applied-actions")
async def update_applied_actions(
    bdName: str = Body(..., embed=True),
    action: str = Body(..., embed=True),
    parameters: dict = Body({}, embed=True),
    current_user_id: str = Depends(get_current_user2)
):
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            
            # 1. Vérifier si la table existe
            cur.execute("""
                SELECT applied_actions FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
                FOR UPDATE
            """, (bdName.lower(), current_user_id))
            
            result = cur.fetchone()
            if not result:
                raise HTTPException(404, "Table not found")
            
            # 2. Récupérer les actions existantes
            existing_actions = result[0] if result[0] else []
            
            # 3. Formater l'action selon le type
            new_action = None
            
            if action.startswith("standard:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "standard_scaling",
                    "description": f"Standard scaling on {source_column}",
                    "source_column": source_column,
                    "parameters": {
                        "mean": parameters.get("mean"),
                        "std": parameters.get("std"),
                        "fitted_on_train": parameters.get("fitted_on_train", False),
                        "timestamp": datetime.now().isoformat()
                    }
                }
            elif action.startswith("minmax:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "minmax_normalization",
                    "description": f"MinMax normalization on {source_column}",
                    "source_column": source_column,
                    "parameters": {
                        "min": parameters.get("min"),
                        "max": parameters.get("max"),
                        "data_min": parameters.get("data_min"),
                        "data_max": parameters.get("data_max"),
                        "fitted_on_train": parameters.get("fitted_on_train", False),
                        "clip": parameters.get("clip", False),
                        "timestamp": datetime.now().isoformat()
                    }
                }
            elif action.startswith("regex_extract:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "regex_extraction",
                    "description": f"Regex extraction on {source_column}",
                    "source_column": source_column,
                    "pattern": parameters.get("pattern"),
                    "output_column": parameters.get("output_column"),
                    "parameters": {
                        "pattern": parameters.get("pattern"),
                        "output_column": parameters.get("output_column"),
                        "original_pattern": parameters.get("original_pattern"),
                        "case_insensitive": parameters.get("case_insensitive", False),
                        "extract_mode": parameters.get("extract_mode", "first"),
                        "cast_numeric": parameters.get("cast_numeric", False),
                        "delete_source": parameters.get("delete_source", False),
                        "validate_kind": parameters.get("validate_kind"),
                        "timestamp": datetime.now().isoformat(),
                    },
                    "timestamp": datetime.now().isoformat(),
                }
            elif action.startswith("label:"):
                source_column = action.split(":")[1]
    
                # Debug
                print(f"Received label encoding for {source_column}")
                print(f"Mapping received: {parameters.get('mapping')}")
                print(f"Categories received: {parameters.get('categories')}")
    
                new_action = {
                    "action": "label_encoding",
                    "description": f"Label encoding on {source_column}",
                    "source_column": source_column,
                    "parameters": {
                        "mapping": parameters.get("mapping", {}),
                        "categories": parameters.get("categories", []),
                        "timestamp": datetime.now().isoformat()
                    }
                }
            elif action.startswith("onehot:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "onehot_encoding",
                    "description": f"One-hot encoding on {source_column}",
                    "source_column": source_column,
                    "parameters": {
                        "categories": parameters.get("categories", []),
                        "new_columns": parameters.get("new_columns", []),
                        "timestamp": datetime.now().isoformat()
                    }
                }
            elif action.startswith("log_transform:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "log_transformation",
                    "description": f"Log transformation on {source_column}",
                    "source_column": source_column,
                    "parameters": {
                        "base": parameters.get("base", "natural"),
                        "offset": parameters.get("offset", 1),
                        "timestamp": datetime.now().isoformat()
                    }
                }
            elif action.startswith("delete:"):
                source_column = action.split(":")[1]
                new_action = {
                    "action": "column_deletion",
                    "description": f"Column deletion: {source_column}",
                    "source_column": source_column,
                    "timestamp": datetime.now().isoformat()
                }
            else:
                # Action générique
                new_action = {
                    "action": action,
                    "timestamp": datetime.now().isoformat(),
                    "parameters": parameters
                }
            
            # 4. Ajouter à la liste
            updated_actions = existing_actions + [new_action]
            
            # 5. Mettre à jour la base de données
            cur.execute("""
                UPDATE user_tables_metadata
                SET applied_actions = %s::jsonb,
                    updated_at = NOW()
                WHERE table_name = %s AND owner_id = %s
                RETURNING applied_actions
            """, (json.dumps(updated_actions), bdName.lower(), current_user_id))
            
            updated_result = cur.fetchone()
            conn.commit()
            
            if not updated_result:
                raise HTTPException(500, "Failed to verify update")
            
            return {
                "success": True,
                "current_actions": updated_result[0]
            }
            
        except Exception as e:
            conn.rollback()
            raise HTTPException(500, f"Error updating applied actions: {str(e)}")



