'''@@@@@@@@@@@@@@@@@@@@admin@@@@@@@@@@@@@@@@@@@@@'''
from datetime import timedelta  # used by platform-stats (users last 7 days)

def _admin_project_paths():
    """Backend dir + project root (parent of backend/)."""
    here = os.path.dirname(os.path.abspath(__file__))
    return here, os.path.dirname(here)


def _safe_unlink_model_files(model_path: str) -> bool:
    """
    Delete a saved model file and known sidecars.
    Prefer the absolute path stored in DB; fall back to project/backend saved_models.
    """
    if not model_path:
        return False

    here, project_root = _admin_project_paths()
    basename = os.path.basename(model_path)
    candidates = [
        model_path,
        os.path.join(project_root, "saved_models", basename),
        os.path.join(here, "saved_models", basename),
    ]

    deleted = False
    seen = set()
    for candidate in candidates:
        path = os.path.normpath(candidate)
        if path in seen:
            continue
        seen.add(path)
        if not os.path.isfile(path):
            continue
        try:
            os.remove(path)
            deleted = True
            if path.endswith(".pt"):
                meta = path[:-3] + "_metadata.joblib"
                if os.path.isfile(meta):
                    os.remove(meta)
            elif path.endswith(".joblib"):
                base = path[:-7]
                for suffix in ("_clusters.png", "_silhouette.png", "_visualization.joblib"):
                    viz = base + suffix
                    if os.path.isfile(viz):
                        os.remove(viz)
            break
        except Exception as unlink_err:
            print(f"Warning: failed to unlink model file {path}: {unlink_err}")
    return deleted


def _model_file_size_bytes(model_path: str):
    """Return on-disk size in bytes for a model path, or None if missing."""
    if not model_path:
        return None
    here, project_root = _admin_project_paths()
    basename = os.path.basename(model_path)
    for candidate in (
        model_path,
        os.path.join(project_root, "saved_models", basename),
        os.path.join(here, "saved_models", basename),
    ):
        path = os.path.normpath(candidate)
        if os.path.isfile(path):
            try:
                return os.path.getsize(path)
            except OSError:
                return None
    return None


def _saved_models_disk_usage_bytes() -> int:
    """Sum file sizes under project-root and backend saved_models dirs."""
    here, project_root = _admin_project_paths()
    total = 0
    for directory in (
        os.path.join(project_root, "saved_models"),
        os.path.join(here, "saved_models"),
    ):
        if not os.path.isdir(directory):
            continue
        try:
            for name in os.listdir(directory):
                path = os.path.join(directory, name)
                if os.path.isfile(path):
                    total += os.path.getsize(path)
        except OSError as err:
            print(f"Warning: disk usage scan failed for {directory}: {err}")
    return total


async def verify_admin(current_user: dict = Depends(get_current_user3)):
    """
    Vérifier si l'utilisateur est admin
    """
    try:
        user_id = current_user.get("user_id")
        user = db.users.find_one({"_id": ObjectId(user_id)})
        
        if user and user.get("is_admin"):
            return user_id
        else:
            raise HTTPException(status_code=403, detail="Admin access required")
    except Exception as e:
        raise HTTPException(status_code=403, detail="Admin access required")








