@router.post("/admin/dataset-info/{dataset_name}")
async def save_dataset_info(
    dataset_name: str,
    info_data: dict = Body(...),
    current_user_id: str = Depends(verify_admin)
):
    """
    Sauvegarder les informations d'un dataset (admin seulement)
    """
    try:
        dataset_info = info_data.get("dataset_info", "")
        
        with get_db_connection() as conn:
            cur = conn.cursor()
            
            # Vérifier si la colonne existe, sinon la créer
            cur.execute("""
                SELECT column_name 
                FROM information_schema.columns 
                WHERE table_name = 'user_tables_metadata' 
                AND column_name = 'dataset_info'
            """)
            
            has_column = cur.fetchone() is not None
            
            if not has_column:
                print("Creating dataset_info column...")
                cur.execute("""
                    ALTER TABLE user_tables_metadata 
                    ADD COLUMN dataset_info TEXT
                """)
            
            # Vérifier si le dataset existe
            cur.execute("""
                SELECT table_name FROM user_tables_metadata 
                WHERE table_name = %s
            """, (dataset_name,))
            
            if not cur.fetchone():
                raise HTTPException(status_code=404, detail="Dataset not found")
            
            # Mettre à jour les informations
            cur.execute("""
                UPDATE user_tables_metadata 
                SET dataset_info = %s,
                    updated_at = NOW()
                WHERE table_name = %s
                RETURNING dataset_info, updated_at
            """, (dataset_info, dataset_name))
            
            updated_data = cur.fetchone()
            conn.commit()
            
            return {
                "status": "success",
                "message": "Dataset information saved successfully",
                "dataset_info": updated_data[0],
                "updated_at": updated_data[1].isoformat()
            }
            
    except HTTPException:
        raise
    except Exception as e:
        if conn:
            conn.rollback()
        print(f"Error saving dataset info: {str(e)}")
        raise HTTPException(status_code=500, detail=f"Error saving dataset info: {str(e)}")

def _normalize_dataset_info_text(raw):
    """Return a plain display string from TEXT / JSONB / dict dataset_info, or None."""
    if raw is None:
        return None
    if isinstance(raw, bytes):
        try:
            raw = raw.decode("utf-8")
        except Exception:
            return None
    if isinstance(raw, dict):
        for key in ("text", "description", "info", "content"):
            if key in raw and raw[key]:
                return _normalize_dataset_info_text(raw[key])
        # Fallback: readable JSON
        try:
            s = json.dumps(raw, ensure_ascii=False)
            return s if s and s != "{}" and s != "null" else None
        except Exception:
            return None
    if isinstance(raw, (list, tuple)):
        try:
            s = json.dumps(raw, ensure_ascii=False)
            return s if s and s != "[]" else None
        except Exception:
            return None
    if isinstance(raw, str):
        s = raw.strip()
        if not s or s in ("null", "None", "{}", "[]"):
            return None
        if (s.startswith('"') and s.endswith('"')) or s.startswith("{") or s.startswith("["):
            try:
                parsed = json.loads(s)
                return _normalize_dataset_info_text(parsed)
            except Exception:
                pass
        return s
    s = str(raw).strip()
    return s or None


@router.get("/get-database-metadata")
async def get_database_metadata(
    dbName: str,
    current_user_id: str = Depends(get_current_user2)
):
    try:
        admin_user_ids = [
            str(u["_id"]) for u in db.users.find({"is_admin": True}, {"_id": 1})
        ]
        with get_db_connection() as conn:
            cur = conn.cursor()
            
            print(f"DEBUG - Fetching metadata for: {dbName}")
            
            cur.execute("""
                SELECT 
                    stage,
                    dataset_info,
                    target_column,
                    columns
                FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
            """, (dbName, current_user_id))
            
            result = cur.fetchone()
            
            if not result:
                print(f"DEBUG - Dataset {dbName} not found")
                return {
                    "stage": None,
                    "dataset_info": None,
                    "has_dataset_info": False,
                    "target_column": None
                }
            
            stage, dataset_info, target_column, columns = result
            info_text = _normalize_dataset_info_text(dataset_info)

            # Fallback for user copies of predefined datasets that missed dataset_info
            if not info_text and columns and admin_user_ids:
                try:
                    placeholders = ",".join(["%s"] * len(admin_user_ids))
                    cur.execute(
                        f"""
                        SELECT dataset_info
                        FROM user_tables_metadata
                        WHERE owner_id IN ({placeholders})
                          AND table_name !~ '_(reset|numerized|backup)$'
                          AND columns = %s
                          AND dataset_info IS NOT NULL
                        ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
                        LIMIT 1
                        """,
                        (*admin_user_ids, columns),
                    )
                    prow = cur.fetchone()
                    if prow:
                        info_text = _normalize_dataset_info_text(prow[0])
                except Exception as fb_err:
                    print(f"DEBUG - dataset_info fallback failed: {fb_err}")
            
            has_dataset_info = bool(info_text)
            print(f"DEBUG - has_dataset_info: {has_dataset_info}")
            
            return {
                "stage": stage,
                "dataset_info": info_text,
                "has_dataset_info": has_dataset_info,
                "target_column": target_column
            }
            
    except Exception as e:
        print(f"Error fetching metadata: {str(e)}")
        return {
            "stage": None,
            "dataset_info": None,
            "has_dataset_info": False,
            "target_column": None
        }


@router.get("/admin/platform-stats")
async def get_platform_stats(current_user_id: str = Depends(verify_admin)):
    """
    KPI plateforme pour l'onglet Vue d'ensemble (agrégats SQL + comptages Mongo).
    """
    try:
        total_users = db.users.count_documents({})
        total_admins = db.users.count_documents({"is_admin": True})
        week_ago = datetime.utcnow() - timedelta(days=7)
        # created_at may be missing on older docs; ObjectId timestamp is a fallback approximation
        recent_users = 0
        for u in db.users.find({}, {"created_at": 1, "createdAt": 1}):
            created = u.get("created_at") or u.get("createdAt")
            if created is None:
                try:
                    created = u["_id"].generation_time.replace(tzinfo=None)
                except Exception:
                    continue
            if getattr(created, "tzinfo", None) is not None:
                created = created.replace(tzinfo=None)
            try:
                if created >= week_ago:
                    recent_users += 1
            except Exception:
                continue

        with get_db_connection() as conn:
            cur = conn.cursor()
            cur.execute("SELECT COUNT(*) FROM user_tables_metadata")
            total_datasets = cur.fetchone()[0] or 0
            cur.execute("SELECT COUNT(*) FROM user_saved_models")
            total_models = cur.fetchone()[0] or 0
            cur.execute("""
                SELECT COALESCE(model_type, 'unknown') AS mt, COUNT(*) AS cnt
                FROM user_saved_models
                GROUP BY COALESCE(model_type, 'unknown')
                ORDER BY cnt DESC
            """)
            model_type_breakdown = [
                {"model_type": row[0], "count": row[1]} for row in cur.fetchall()
            ]
            cur.execute("""
                SELECT COALESCE(framework, 'unknown') AS fw, COUNT(*) AS cnt
                FROM user_saved_models
                GROUP BY COALESCE(framework, 'unknown')
                ORDER BY cnt DESC
            """)
            framework_breakdown = [
                {"framework": row[0], "count": row[1]} for row in cur.fetchall()
            ]

        disk_bytes = _saved_models_disk_usage_bytes()
        return {
            "total_users": total_users,
            "total_admins": total_admins,
            "users_registered_last_7_days": recent_users,
            "total_datasets": total_datasets,
            "total_models": total_models,
            "model_type_breakdown": model_type_breakdown,
            "framework_breakdown": framework_breakdown,
            "saved_models_disk_bytes": disk_bytes,
        }
    except Exception as e:
        print(f"Error in /admin/platform-stats: {str(e)}")
        raise HTTPException(status_code=500, detail=f"Error fetching platform stats: {str(e)}")


