@router.delete("/admin/users/{user_id}")
async def delete_user(user_id: str, current_user_id: str = Depends(verify_admin)):
    """
    Supprimer un utilisateur (admin seulement)
    """
    try:
        if user_id == current_user_id:
            raise HTTPException(status_code=400, detail="Cannot delete your own account")

        user_to_delete = db.users.find_one({"_id": ObjectId(user_id)})
        if user_to_delete and user_to_delete.get("is_admin"):
            raise HTTPException(status_code=400, detail="Cannot delete admin users")

        with get_db_connection() as conn:
            cur = conn.cursor()

            # Unlink model files before deleting DB rows (avoid orphans)
            cur.execute(
                "SELECT model_path FROM user_saved_models WHERE user_id = %s",
                (user_id,),
            )
            for (model_path,) in cur.fetchall():
                _safe_unlink_model_files(model_path)

            # Drop physical dataset tables
            cur.execute(
                "SELECT table_name FROM user_tables_metadata WHERE owner_id = %s",
                (user_id,),
            )
            for (table_name,) in cur.fetchall():
                try:
                    cur.execute(f"DROP TABLE IF EXISTS {table_name}")
                except Exception as drop_error:
                    print(f"Warning: Could not drop table {table_name}: {drop_error}")

            cur.execute("DELETE FROM user_saved_models WHERE user_id = %s", (user_id,))
            cur.execute("DELETE FROM user_tables_metadata WHERE owner_id = %s", (user_id,))
            conn.commit()

        result = db.users.delete_one({"_id": ObjectId(user_id)})
        if result.deleted_count == 0:
            raise HTTPException(status_code=404, detail="User not found")

        return {"message": "User deleted successfully"}

    except HTTPException:
        raise
    except Exception as e:
        print(f"Error deleting user: {str(e)}")
        raise HTTPException(status_code=500, detail="Error deleting user")


@router.delete("/admin/datasets")
async def delete_dataset(
    dataset_data: dict,
    current_user_id: str = Depends(verify_admin),
):
    """
    Supprimer un dataset (admin seulement)
    """
    try:
        dataset_name = dataset_data.get("datasetName")
        owner_id = dataset_data.get("ownerId")

        if not dataset_name or not owner_id:
            raise HTTPException(status_code=400, detail="Dataset name and owner ID are required")

        with get_db_connection() as conn:
            cur = conn.cursor()

            cur.execute(
                "SELECT table_name FROM user_tables_metadata WHERE table_name = %s AND owner_id = %s",
                (dataset_name, owner_id),
            )
            if not cur.fetchone():
                raise HTTPException(status_code=404, detail="Dataset not found")

            cur.execute(
                "SELECT model_path FROM user_saved_models WHERE db_name = %s AND user_id = %s",
                (dataset_name, owner_id),
            )
            for (model_path,) in cur.fetchall():
                _safe_unlink_model_files(model_path)

            cur.execute(
                "DELETE FROM user_saved_models WHERE db_name = %s AND user_id = %s",
                (dataset_name, owner_id),
            )
            cur.execute(
                "DELETE FROM user_tables_metadata WHERE table_name = %s AND owner_id = %s",
                (dataset_name, owner_id),
            )

            try:
                cur.execute(f"DROP TABLE IF EXISTS {dataset_name}")
            except Exception as drop_error:
                print(f"Warning: Could not drop table {dataset_name}: {drop_error}")

            conn.commit()

        return {"message": "Dataset deleted successfully"}

    except HTTPException:
        raise
    except Exception as e:
        print(f"Error deleting dataset: {str(e)}")
        raise HTTPException(status_code=500, detail="Error deleting dataset")


