@router.get("/predefined-datasets")
async def get_predefined_datasets(current_user_id: str = Depends(get_current_user2)):
    """
    List datasets owned by any admin (is_admin=True), excluding aux tables.
    """
    try:
        print("🔍 Fetching predefined datasets with stats...")

        admin_users = list(db.users.find({"is_admin": True}, {"_id": 1}))
        admin_user_ids = [str(user["_id"]) for user in admin_users]
        if not admin_user_ids:
            return {"datasets": []}

        with get_db_connection() as conn:
            cur = conn.cursor()

            placeholders = ",".join(["%s"] * len(admin_user_ids))
            query = f"""
                SELECT
                    table_name,
                    columns,
                    created_at
                FROM user_tables_metadata
                WHERE owner_id IN ({placeholders})
                AND table_name !~ '_(reset|numerized|backup)$'
                ORDER BY created_at DESC
            """

            cur.execute(query, admin_user_ids)
            results = cur.fetchall()

            print(f"📊 Found {len(results)} predefined datasets (all admins)")

            datasets = []
            for row in results:
                table_name, columns, created_at = row

                # Récupérer les statistiques pour chaque table
                try:
                    # Compter le nombre de lignes
                    count_query = sql.SQL("SELECT COUNT(*) FROM {}").format(
                        sql.Identifier(table_name)
                    )

                    cur.execute(count_query)
                    row_count = cur.fetchone()[0]

                    # Compter le nombre de colonnes (sans la colonne 'id')
                    cur.execute("""
                        SELECT COUNT(column_name)
                        FROM information_schema.columns
                        WHERE table_name = %s
                        AND column_name != 'id'
                    """, (table_name,))

                    column_count = cur.fetchone()[0]

                    print(f"✅ Adding: {table_name} - {row_count} rows, {column_count} columns")

                    datasets.append({
                        "id": f"predefined_{table_name}",
                        "table_name": table_name,
                        "columns": columns,
                        "row_count": row_count,
                        "column_count": column_count,
                        "created_at": created_at,
                        "type": "predefined"
                    })

                except Exception as e:
                    print(f"⚠️ Error getting stats for {table_name}: {str(e)}")
                    # Si on ne peut pas récupérer les stats, on met des valeurs par défaut
                    datasets.append({
                        "id": f"predefined_{table_name}",
                        "table_name": table_name,
                        "columns": columns,
                        "row_count": 0,
                        "column_count": len(columns) if columns else 0,
                        "created_at": created_at,
                        "type": "predefined"
                    })

            print(f"🎯 Final datasets count: {len(datasets)}")
            return {"datasets": datasets}

    except Exception as e:
        print(f"❌ Error: {str(e)}")
        raise HTTPException(status_code=500, detail=f"Error fetching datasets: {str(e)}")
async def get_admin_dataset_data(
    table_name: str,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Récupérer les données d'un dataset admin
    """
    try:
        # 1. Chercher les admins dans MongoDB
        admin_users = list(db.users.find({"is_admin": True}, {"_id": 1}))
        admin_user_ids = [str(user["_id"]) for user in admin_users]
        
        if not admin_user_ids:
            raise HTTPException(status_code=404, detail="No admin users found")
        
        # 2. Vérifier que la table appartient à un admin
        with get_db_connection() as conn:
            cur = conn.cursor()
            
            placeholders = ','.join(['%s'] * len(admin_user_ids))
            query = f"""
                SELECT owner_id FROM user_tables_metadata 
                WHERE table_name = %s 
                AND owner_id IN ({placeholders})
            """
            
            cur.execute(query, [table_name] + admin_user_ids)
            result = cur.fetchone()
            
            if not result:
                raise HTTPException(status_code=404, detail="Predefined dataset not found")
            
            # 3. Récupérer les colonnes
            cur.execute("""
                SELECT column_name 
                FROM information_schema.columns 
                WHERE table_name = %s
                ORDER BY ordinal_position
            """, (table_name,))
            
            all_columns = [row[0] for row in cur.fetchall()]
            data_columns = [col for col in all_columns if col != 'id']
            
            # 4. Récupérer TOUTES les données
            query = sql.SQL("SELECT {} FROM {}").format(
                sql.SQL(", ").join(map(sql.Identifier, all_columns)),
                sql.Identifier(table_name)
            )
            
            cur.execute(query)
            rows_data = cur.fetchall()
            
            # 5. Formater les données
            rows = []
            for row in rows_data:
                row_dict = {'id': row[0]}
                for i, col in enumerate(data_columns, 1):
                    row_dict[f"col{i-1}"] = row[i]
                rows.append(row_dict)

            return {
                "name": table_name,
                "columns": data_columns,
                "rows": rows
            }
            
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Error fetching dataset data: {str(e)}")

