@router.post("/duplicate-predefined-dataset")
async def duplicate_predefined_dataset(
    request: dict,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Dupliquer un dataset prédéfini avec un nouveau nom pour l'utilisateur courant
    """
    try:
        original_table_name = request.get('original_table_name')
        new_dataset_name = normalize_dataset_name(request.get('new_dataset_name') or "")
        
        print(f"🔧 Duplication request: {original_table_name} -> {new_dataset_name} for user {current_user_id}")
        
        if not original_table_name or not new_dataset_name:
            raise HTTPException(status_code=400, detail="Original table name and new dataset name are required")
        
        validate_normalized_dataset_name(new_dataset_name)

        admin_user_ids = [
            str(u["_id"]) for u in db.users.find({"is_admin": True}, {"_id": 1})
        ]
        if not admin_user_ids:
            raise HTTPException(status_code=404, detail="No admin predefined datasets available")
        
        # UTILISER le context manager correctement
        with get_db_connection() as conn:
            cur = conn.cursor()

            placeholders = ",".join(["%s"] * len(admin_user_ids))
            cur.execute(
                f"""
                SELECT 1 FROM user_tables_metadata
                WHERE table_name = %s
                  AND owner_id IN ({placeholders})
                  AND table_name !~ '_(reset|numerized|backup)$'
                """,
                [original_table_name] + admin_user_ids,
            )
            if not cur.fetchone():
                raise HTTPException(status_code=404, detail="Predefined dataset not found")
            
            # 1. Vérifier que la table originale existe
            cur.execute("""
                SELECT 1 FROM information_schema.tables 
                WHERE table_name = %s
            """, (original_table_name,))
            
            if not cur.fetchone():
                raise HTTPException(status_code=404, detail="Original dataset not found")
            
            print(f"🔧 Original table {original_table_name} exists")
            
            # 2. Vérifier que le nouveau nom n'existe pas déjà pour cet utilisateur
            cur.execute("""
                SELECT 1 FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (new_dataset_name, current_user_id))
            
            if cur.fetchone():
                raise HTTPException(status_code=400, detail="Dataset name already exists for this user")
            
            print(f"🔧 Dataset name {new_dataset_name} is available")
            
            # 3. Récupérer la structure de la table originale
            cur.execute("""
                SELECT column_name, data_type 
                FROM information_schema.columns 
                WHERE table_name = %s 
                ORDER BY ordinal_position
            """, (original_table_name,))
            
            columns_info = cur.fetchall()
            print(f"🔧 Found {len(columns_info)} columns in original table")
            
            # 4. Récupérer les données de la table originale
            cur.execute(sql.SQL("SELECT * FROM {}").format(sql.Identifier(original_table_name)))
            original_data = cur.fetchall()
            print(f"🔧 Found {len(original_data)} rows in original table")
            
            # 5. Créer la table principale avec le nouveau nom
            column_defs = []
            for col_info in columns_info:
                col_name, data_type = col_info
                if col_name == 'id':
                    column_defs.append("id SERIAL PRIMARY KEY")
                else:
                    column_defs.append(f'"{col_name}" {data_type}')
            
            create_main_sql = f"CREATE TABLE {new_dataset_name} ({', '.join(column_defs)})"
            print(f"🔧 Creating main table: {create_main_sql}")
            cur.execute(create_main_sql)
            
            # 6. Créer la table _backup
            create_backup_sql = f"CREATE TABLE {new_dataset_name}_backup ({', '.join(column_defs)})"
            print(f"🔧 Creating backup table: {create_backup_sql}")
            cur.execute(create_backup_sql)
            
            # 7. Créer la table _reset
            create_reset_sql = f"CREATE TABLE {new_dataset_name}_reset ({', '.join(column_defs)})"
            print(f"🔧 Creating reset table: {create_reset_sql}")
            cur.execute(create_reset_sql)
            
            # 8. Insérer les données dans les trois tables
            if original_data:
                # Préparer les noms de colonnes (sauf id qui est auto-généré)
                data_columns = [col[0] for col in columns_info if col[0] != 'id']
                if data_columns:  # S'assurer qu'il y a des colonnes de données
                    placeholders = ', '.join(['%s'] * len(data_columns))
                    columns_str = ', '.join([f'"{col}"' for col in data_columns])
                    
                    # SQL pour l'insertion
                    insert_sql = f"INSERT INTO {{table_name}} ({columns_str}) VALUES ({placeholders})"
                    
                    # Insérer dans la table principale
                    print(f"🔧 Inserting {len(original_data)} rows into main table")
                    for i, row in enumerate(original_data):
                        # Exclure la première colonne (id) car elle est auto-générée
                        data_values = row[1:] if len(row) > 1 else []
                        cur.execute(insert_sql.format(table_name=new_dataset_name), data_values)
                    
                    # Insérer dans la table _backup
                    print(f"🔧 Inserting {len(original_data)} rows into backup table")
                    for i, row in enumerate(original_data):
                        data_values = row[1:] if len(row) > 1 else []
                        cur.execute(insert_sql.format(table_name=f"{new_dataset_name}_backup"), data_values)
                    
                    # Insérer dans la table _reset
                    print(f"🔧 Inserting {len(original_data)} rows into reset table")
                    for i, row in enumerate(original_data):
                        data_values = row[1:] if len(row) > 1 else []
                        cur.execute(insert_sql.format(table_name=f"{new_dataset_name}_reset"), data_values)
            
            # 9. Enregistrer les métadonnées pour les trois tables
            column_names = [col[0] for col in columns_info if col[0] != 'id']

            # Copy admin description / target from the predefined source when present
            source_dataset_info = None
            source_target = None
            source_model_type = None
            try:
                cur.execute(
                    """
                    SELECT dataset_info, target_column, model_type
                    FROM user_tables_metadata
                    WHERE table_name = %s
                    ORDER BY created_at DESC NULLS LAST
                    LIMIT 1
                    """,
                    (original_table_name,),
                )
                src_meta = cur.fetchone()
                if src_meta:
                    source_dataset_info = _normalize_dataset_info_text(src_meta[0])
                    source_target = src_meta[1]
                    source_model_type = src_meta[2]
            except Exception as meta_err:
                print(f"⚠️ Could not copy dataset_info from predefined source: {meta_err}")
            
            # Métadonnées table principale
            cur.execute("""
                INSERT INTO user_tables_metadata 
                (table_name, owner_id, columns, created_at, target_column, model_type, updated_at, stage, applied_actions, dataset_info)
                VALUES (%s, %s, %s, NOW(), %s, %s, NULL, 'target_selection', NULL, %s)
            """, (
                new_dataset_name,
                current_user_id,
                column_names,
                source_target,
                source_model_type,
                source_dataset_info,
            ))
            
            # Métadonnées table _backup
            cur.execute("""
                INSERT INTO user_tables_metadata 
                (table_name, owner_id, columns, created_at, target_column, model_type, updated_at, stage, applied_actions, dataset_info)
                VALUES (%s, %s, %s, NOW(), %s, %s, NULL, 'target_selection', NULL, %s)
            """, (
                f"{new_dataset_name}_backup",
                current_user_id,
                column_names,
                source_target,
                source_model_type,
                source_dataset_info,
            ))
            
            # Métadonnées table _reset
            cur.execute("""
                INSERT INTO user_tables_metadata 
                (table_name, owner_id, columns, created_at, target_column, model_type, updated_at, stage, applied_actions, dataset_info)
                VALUES (%s, %s, %s, NOW(), %s, %s, NULL, 'target_selection', NULL, %s)
            """, (
                f"{new_dataset_name}_reset",
                current_user_id,
                column_names,
                source_target,
                source_model_type,
                source_dataset_info,
            ))
            
            conn.commit()
            print(f"✅ Successfully duplicated dataset {original_table_name} to {new_dataset_name}")
            print(f"✅ Created tables: {new_dataset_name}, {new_dataset_name}_backup, {new_dataset_name}_reset")
            print(f"✅ Copied dataset_info: {bool(source_dataset_info)}")
            
            return {
                "status": "success",
                "message": "Dataset duplicated successfully",
                "main_table": new_dataset_name,
                "backup_table": f"{new_dataset_name}_backup",
                "reset_table": f"{new_dataset_name}_reset",
                "columns": column_names,
                "rows_copied": len(original_data),
                "has_dataset_info": bool(source_dataset_info),
            }
            
    except HTTPException:
        # Les HTTPException sont déjà gérées
        raise
    except Exception as e:
        print(f"❌ Error duplicating dataset: {str(e)}")
        import traceback
        print(f"❌ Traceback: {traceback.format_exc()}")
        raise HTTPException(status_code=500, detail=f"Error duplicating dataset: {str(e)}")



























@router.get("/detect-problem-type")
async def detect_problem_type(
    bdName: str,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Détection robuste du type de problème (classification/Regression/unsupervised)
    avec la même logique que train_svm
    """
    try:
        logger.info(f"🔍 DETECTION STARTED for dataset: {bdName}")
        
        # Vérification des permissions
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Récupération de la colonne cible
                cur.execute("""
                    SELECT target_column 
                    FROM user_tables_metadata
                    WHERE table_name = %s AND owner_id = %s
                """, (bdName.lower(), current_user_id))
                
                target_info = cur.fetchone()
                
                # Si pas de target column → unsupervised
                if not target_info or not target_info[0]:
                    logger.info("❌ No target column - UNSUPERVISED")
                    return {
                        "problem_type": "unsupervised",
                        "is_classification": False,
                        "has_target": False,
                        "reason": "No target column defined in dataset",
                        "target_column": None
                    }
                
                target_column = target_info[0]
                logger.info(f"🎯 Target column found: {target_column}")
                
                # Vérification que la target existe dans la table
                cur.execute("""
                    SELECT 1 FROM information_schema.columns
                    WHERE table_name = %s AND column_name = %s
                """, (bdName.lower(), target_column))
                
                if not cur.fetchone():
                    logger.warning("⚠️ Target column not found in table - UNSUPERVISED")
                    return {
                        "problem_type": "unsupervised", 
                        "is_classification": False,
                        "has_target": False,
                        "reason": f"Target column '{target_column}' not found in dataset",
                        "target_column": target_column
                    }
                
                # Métriques sur TOUT le dataset
                cur.execute(sql.SQL("""
                    SELECT
                        COUNT(*) FILTER (
                            WHERE {target_col} IS NOT NULL
                              AND BTRIM({target_col}::text) <> ''
                        ) AS total_samples,
                        COUNT(DISTINCT BTRIM({target_col}::text)) FILTER (
                            WHERE {target_col} IS NOT NULL
                              AND BTRIM({target_col}::text) <> ''
                        ) AS unique_values
                    FROM {table}
                """).format(
                    target_col=sql.Identifier(target_column),
                    table=sql.Identifier(bdName.lower())
                ))
                total_samples, unique_values = cur.fetchone()
                total_samples = int(total_samples or 0)
                unique_values = int(unique_values or 0)

                # Échantillon pour numericité + distribution
                cur.execute(sql.SQL("""
                    SELECT {target_col} FROM {table}
                    WHERE {target_col} IS NOT NULL AND BTRIM({target_col}::text) <> ''
                    LIMIT 5000
                """).format(
                    target_col=sql.Identifier(target_column),
                    table=sql.Identifier(bdName.lower())
                ))
                rows = cur.fetchall()
                target_values = [row[0] for row in rows if row[0] is not None]
        
        if total_samples == 0 or not target_values:
            logger.warning("⚠️ No target values found - UNSUPERVISED")
            return {
                "problem_type": "unsupervised",
                "is_classification": False,
                "has_target": True,
                "reason": "Target column exists but contains no values",
                "target_column": target_column
            }
        
        target_series = pd.Series(target_values)
        
        try:
            pd.to_numeric(target_series, errors='raise')
            target_is_numeric = True
        except (ValueError, TypeError):
            target_is_numeric = False
        
        unique_ratio = (unique_values / total_samples) * 100 if total_samples > 0 else 0.0
        
        if total_samples <= 30:
            threshold = 25.0
        elif total_samples <= 100:
            threshold = 15.0
        else:
            threshold = 5.0
        
        # Classification UNIQUEMENT si faible cardinalité (ratio ET plafond d'uniques).
        # Ne PAS forcer classification pour du texte haute cardinalité (ex. 142/150 = 94%).
        is_classification = (unique_values <= 200) and (unique_ratio <= threshold)
        
        is_likely_id = False
        if target_is_numeric and unique_ratio > 80:
            numeric_values = pd.to_numeric(target_series, errors='coerce').dropna()
            if len(numeric_values) > 1:
                sorted_values = np.sort(numeric_values.unique())
                differences = np.diff(sorted_values)
                if len(differences) > 0 and np.all(differences == 1):
                    is_likely_id = True
                    is_classification = False
        
        if is_classification:
            problem_type = "classification"
        elif target_is_numeric:
            problem_type = "regression"
        else:
            # Texte / catégories trop nombreuses pour une cible de classification fiable
            problem_type = "unsupervised"
        
        logger.info(f"📊 DETECTION RESULTS:")
        logger.info(f"   - Target: {target_column}")
        logger.info(f"   - Unique values: {unique_values}/{total_samples} ({unique_ratio:.1f}%)")
        logger.info(f"   - Is numeric: {target_is_numeric}")
        logger.info(f"   - Threshold: {threshold}%")
        logger.info(f"   - Final decision: {problem_type.upper()}")
        
        class_distribution = []
        # Toujours renvoyer une distribution utile si peu d'uniques (même si on ne suggère pas classif)
        if unique_values <= 200:
            counts = target_series.astype(str).value_counts()
            total = int(counts.sum()) or 1
            for label, cnt in counts.items():
                class_distribution.append({
                    "label": str(label),
                    "count": int(cnt),
                    "percentage": round(float(cnt) / total * 100, 2),
                })
        
        if is_classification:
            reason = (
                f"Unique ratio {unique_ratio:.1f}% <= threshold {threshold}% "
                f"({unique_values} unique / {total_samples} rows)"
            )
        elif problem_type == "regression":
            reason = (
                f"Unique ratio {unique_ratio:.1f}% > threshold {threshold}% "
                f"({unique_values} unique / {total_samples} rows) — numeric target → regression"
            )
        else:
            reason = (
                f"Unique ratio {unique_ratio:.1f}% > threshold {threshold}% "
                f"({unique_values} unique / {total_samples} rows) — high-cardinality non-numeric target"
            )
        
        return {
            "problem_type": problem_type,
            "is_classification": is_classification,
            "has_target": True,
            "target_column": target_column,
            "detection_metrics": {
                "unique_values": int(unique_values),
                "total_samples": int(total_samples),
                "unique_ratio": float(unique_ratio),
                "threshold_used": threshold,
                "target_is_numeric": target_is_numeric,
                "is_likely_id": is_likely_id
            },
            "class_distribution": class_distribution,
            "reason": reason
        }
        
    except Exception as e:
        logger.error(f"❌ Error in problem type detection: {str(e)}")
        raise HTTPException(
            status_code=500,
            detail=f"Problem type detection failed: {str(e)}"
        )






@router.post("/synchronize-numerized-to-original")
async def synchronize_numerized_to_original(data: dict, current_user_id: str = Depends(get_current_user2)):
    original_bd_name = data.get("originalBdName")
    numerized_bd_name = data.get("numerizedBdName")
    
    if not original_bd_name or not numerized_bd_name:
        raise HTTPException(400, "Original and numerized database names are required")

    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            
            # 1. Vérifier que l'utilisateur a accès aux deux tables
            cur.execute("""
                SELECT table_name FROM user_tables_metadata 
                WHERE table_name IN (%s, %s) AND owner_id = %s
            """, (original_bd_name.lower(), numerized_bd_name.lower(), current_user_id))
            
            accessible_tables = [row[0] for row in cur.fetchall()]
            if original_bd_name.lower() not in accessible_tables:
                raise HTTPException(403, "Access denied to original table")
            if numerized_bd_name.lower() not in accessible_tables:
                raise HTTPException(403, "Access denied to numerized table")

            # 2. Obtenir la structure de la table numerized
            cur.execute("""
                SELECT column_name 
                FROM information_schema.columns 
                WHERE table_name = %s 
                ORDER BY ordinal_position
            """, (numerized_bd_name.lower(),))
            
            numerized_columns = [row[0] for row in cur.fetchall()]
            
            # 3. Supprimer et recréer la table originale avec la structure numerized
            # Sauvegarder d'abord les métadonnées si nécessaire
            cur.execute("""
                SELECT columns FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (original_bd_name.lower(), current_user_id))
            
            original_metadata = cur.fetchone()
            
            # Supprimer l'ancienne table originale
            cur.execute(sql.SQL("DROP TABLE IF EXISTS {}").format(
                sql.Identifier(original_bd_name.lower())
            ))
            
            # Créer la nouvelle table avec la structure de numerized
            cur.execute(sql.SQL("CREATE TABLE {} AS SELECT * FROM {}").format(
                sql.Identifier(original_bd_name.lower()),
                sql.Identifier(numerized_bd_name.lower())
            ))
            
            # 4. Mettre à jour les métadonnées
            cur.execute("""
                UPDATE user_tables_metadata 
                SET columns = %s, updated_at = NOW()
                WHERE table_name = %s AND owner_id = %s
            """, (numerized_columns, original_bd_name.lower(), current_user_id))
            
            conn.commit()
            
            return {
                "success": True,
                "message": f"Successfully synchronized {numerized_bd_name} to {original_bd_name}",
                "columns_copied": numerized_columns,
                "rows_copied": cur.rowcount if cur.rowcount else 0
            }
            
        except psycopg2.Error as e:
            conn.rollback()
            raise HTTPException(500, f"Database error: {e.pgerror}")
        except Exception as e:
            conn.rollback()
            raise HTTPException(500, f"Synchronization error: {str(e)}")

@router.post("/synchronize-numerized-to-original-complete")
async def synchronize_numerized_to_original_complete(
    request: dict,
    current_user_id: str = Depends(get_current_user2)
):
    try:
        original_bd_name = request.get('originalBdName', '').lower()
        numerized_bd_name = request.get('numerizedBdName', '').lower()
        
        if not original_bd_name or not numerized_bd_name:
            raise HTTPException(400, "Missing required parameters")
        
        with get_db_connection() as conn:
            cur = conn.cursor()
            
            # Vérifier que la table numerized existe
            cur.execute("""
                SELECT 1 FROM information_schema.tables 
                WHERE table_name = %s
            """, (numerized_bd_name,))
            
            if not cur.fetchone():
                raise HTTPException(404, f"Table {numerized_bd_name} not found")
            
            # Vérifier que la table originale existe
            cur.execute("""
                SELECT 1 FROM information_schema.tables 
                WHERE table_name = %s
            """, (original_bd_name,))
            
            if not cur.fetchone():
                raise HTTPException(404, f"Table {original_bd_name} not found")
            
            # Récupérer les métadonnées de la table numerized
            cur.execute("""
                SELECT columns, target_column, model_type, applied_actions, stage, modification_history
                FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (numerized_bd_name, current_user_id))
            
            metadata = cur.fetchone()
            if not metadata:
                raise HTTPException(404, f"Metadata for {numerized_bd_name} not found")
            
            columns, target_column, model_type, applied_actions, stage, modification_history = metadata
            
            # 🔧 FIX: S'assurer que applied_actions est un tableau JSONB valide
            if applied_actions is None:
                applied_actions = []  # Convertir None en tableau vide
            elif isinstance(applied_actions, str):
                # Si c'est une string, essayer de la parser
                try:
                    applied_actions = json.loads(applied_actions)
                except:
                    applied_actions = []
            elif not isinstance(applied_actions, list):
                # Si ce n'est pas une liste, le convertir en liste
                applied_actions = []
            
            # 🔧 FIX: S'assurer que chaque action a la structure correcte
            cleaned_actions = []
            for action in applied_actions:
                if isinstance(action, dict):
                    # S'assurer que les champs requis existent
                    cleaned_action = {
                        "action": action.get("action", "unknown"),
                        "parameters": action.get("parameters", {}),
                        "description": action.get("description", ""),
                        "source_column": action.get("source_column", "")
                    }
                    cleaned_actions.append(cleaned_action)
            
            # Mettre à jour les métadonnées de la table originale
            cur.execute("""
                UPDATE user_tables_metadata
                SET columns = %s,
                    target_column = %s,
                    model_type = %s,
                    applied_actions = %s,
                    stage = %s,
                    modification_history = %s,
                    updated_at = NOW()
                WHERE table_name = %s AND owner_id = %s
            """, (
                columns,
                target_column,
                model_type,
                json.dumps(cleaned_actions),  # 🔧 Convertir en JSON valide
                stage,
                modification_history,
                original_bd_name,
                current_user_id
            ))
            
            conn.commit()
            
            return {
                "status": "success",
                "message": "Métadonnées synchronisées avec succès",
                "applied_actions_count": len(cleaned_actions)
            }
            
    except Exception as e:
        logger.error(f"Error synchronizing metadata: {str(e)}")
        import traceback
        traceback.print_exc()
        raise HTTPException(500, f"Erreur: {str(e)}")


@router.post("/save-dataset-copy")
async def save_dataset_copy(
    source_db: str = Body(..., embed=True),
    copy_name: str = Body(..., embed=True),
    copy_type: str = Body(..., embed=True),
    overwrite: bool = Body(False, embed=True),
    current_user_id: str = Depends(get_current_user2)
):
    import json
    import re
    
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            source_table = normalize_table_ident(
                normalize_dataset_name(source_db) or source_db
            )
            target_base_name = normalize_dataset_name(copy_name)

            print(f"Starting copy process: {source_table} -> {target_base_name}, overwrite: {overwrite}")

            # ==================== NAME VALIDATION ====================
            validate_normalized_dataset_name(target_base_name)
            target_base_name = normalize_table_ident(target_base_name)

            if len(target_base_name) > 63:  # PostgreSQL limit
                error_msg = "Dataset name is too long. Maximum 63 characters allowed."
                print(error_msg)
                raise HTTPException(status_code=400, detail=error_msg)

            # ==================== DATASET LIMIT CHECK ====================
            if not overwrite:
                cur.execute("""
                    SELECT COUNT(*) FROM user_tables_metadata
                    WHERE owner_id = %s
                    AND table_name !~ '_(reset|numerized|backup)$'
                """, (current_user_id,))

                dataset_count = cur.fetchone()[0]
                print(f"Current dataset count: {dataset_count}")

                if dataset_count >= 10:
                    raise HTTPException(
                        status_code=400,
                        detail={
                            "type": "limit_reached",
                            "message": (
                                f"Dataset limit reached ({dataset_count}/10). "
                                "Delete datasets from the Dashboard, then try again."
                            ),
                            "count": dataset_count,
                            "limit": 10,
                        },
                    )
            
            # ==================== EXISTING NAME CHECK ====================
            versions_to_check = [
                target_base_name,
                f"{target_base_name}_numerized",
                f"{target_base_name}_backup", 
                f"{target_base_name}_reset"
            ]
            
            existing_tables = []
            for table_name in versions_to_check:
                cur.execute("""
                    SELECT EXISTS (
                        SELECT 1 FROM information_schema.tables 
                        WHERE table_name = %s
                    )
                """, [table_name])
                
                table_exists = cur.fetchone()[0]
                print(f"Checking table {table_name}: exists = {table_exists}")
                
                if table_exists:
                    existing_tables.append(table_name)
            
            print(f"Existing tables found: {existing_tables}")
            
            if existing_tables and not overwrite:
                error_response = {
                    "type": "name_exists",
                    "message": f"Dataset name already exists: {', '.join(existing_tables)}",
                    "existing_tables": existing_tables,
                    "suggested_name": f"{target_base_name}_new"
                }
                print(f"Name conflict detected: {error_response}")
                raise HTTPException(status_code=400, detail=error_response)
            
            # Ownership on source working table
            if not user_owns_table(cur, source_table, current_user_id):
                raise HTTPException(status_code=403, detail="Access denied to source dataset")

            # Ensure reset checkpoint exists so Save As always includes it
            ensure_checkpoint_exists(cur, source_table, current_user_id)

            # ==================== VERSIONS TO COPY ====================
            versions_to_copy = [
                {"source": source_table, "target": target_base_name},
                {"source": f"{source_table}_numerized", "target": f"{target_base_name}_numerized"},
                {"source": f"{source_table}_backup", "target": f"{target_base_name}_backup"},
                {"source": f"{source_table}_reset", "target": f"{target_base_name}_reset"},
            ]

            print(f"Versions to copy: {versions_to_copy}")

            created_copies = []
            skipped_copies = []

            # ==================== COPY LOOP ====================
            for version in versions_to_copy:
                source_table_name = version["source"]
                target_table_name = version["target"]

                print(f"Processing: {source_table_name} -> {target_table_name}")

                if not physical_table_exists(cur, source_table_name):
                    skipped_copies.append(source_table_name)
                    continue

                try:
                    replace_table_from(cur, source_table_name, target_table_name)
                except Exception as table_error:
                    error_msg = (
                        f"Error creating table '{target_table_name}'. "
                        "The name may contain invalid characters."
                    )
                    print(f"Table creation error: {str(table_error)}")
                    conn.rollback()
                    raise HTTPException(status_code=400, detail=error_msg)

                upsert_metadata_from_source(
                    cur, source_table_name, target_table_name, current_user_id
                )
                created_copies.append(target_table_name)
                print(f"Successfully created {target_table_name}")
            
            # ==================== FINAL VALIDATION ====================
            conn.commit()
            print(f"Commit successful. Created: {created_copies}, Skipped: {skipped_copies}")
            
            response_data = {
                "status": "success",
                "message": f"Successfully {'overwritten' if overwrite else 'created'} {len(created_copies)} dataset copies",
                "created_copies": created_copies,
                "skipped_copies": skipped_copies,
                "base_name": target_base_name,
                "action": "overwritten" if overwrite else "created"
            }
            
            print(f"Final response: {response_data}")
            return response_data

        except HTTPException:
            # Re-raise HTTP exceptions
            conn.rollback()
            raise
            
        except Exception as e:
            print(f"Unexpected error: {str(e)}")
            print(f"Error type: {type(e)}")
            import traceback
            print(f"Traceback: {traceback.format_exc()}")
            conn.rollback()
            
            # Specific table name error handling
            error_str = str(e).lower()
            if any(keyword in error_str for keyword in ["trailing junk", "numeric literal", "syntax error", "invalid name"]):
                error_msg = "Invalid dataset name. After cleanup, use only letters, numbers and underscores (spaces become underscores)."
                raise HTTPException(status_code=400, detail=error_msg)
            else:
                raise HTTPException(status_code=500, detail=f"Save copy error: {str(e)}")







from pydantic import BaseModel
from fastapi import HTTPException, Depends

class ResetDatasetRequest(BaseModel):
    bdName: str
@router.post("/reset-dataset-complete")
async def reset_dataset_complete(
    request: ResetDatasetRequest,
    current_user_id: str = Depends(get_current_user2)
):
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            table_name = request.bdName.lower()
            reset_table_name = f"{request.bdName.lower()}_reset"

            print(f"🔁 Resetting dataset: {table_name} from {reset_table_name}")

            # 1. Vérifier que la table de reset existe
            cur.execute("""
                SELECT EXISTS (
                    SELECT FROM information_schema.tables 
                    WHERE table_name = %s
                )
            """, (reset_table_name,))
            
            if not cur.fetchone()[0]:
                raise HTTPException(404, f"Reset version '{reset_table_name}' not found")

            # 2. SUPPRIMER COMPLÈTEMENT la table originale
            cur.execute(f"DROP TABLE IF EXISTS {table_name}")

            # 3. Créer une nouvelle table avec les données de reset
            cur.execute(f"CREATE TABLE {table_name} AS SELECT * FROM {reset_table_name}")

            conn.commit()
            return {
                "message": f"Dataset '{request.bdName}' completely reset from backup", 
                "status": "success"
            }

        except psycopg2.Error as e:
            if conn:
                conn.rollback()
            raise HTTPException(500, f"PostgreSQL error: {e.pgerror}")
        except Exception as e:
            if conn:
                conn.rollback()
            raise HTTPException(500, f"Unexpected error: {str(e)}")



@router.post("/reset-id-column")
async def reset_id_column(
    bdName: str = Body(..., embed=True),
    idColumnName: str = Body("id", embed=True),
    current_user_id: str = Depends(get_current_user2)
):
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            table_name = bdName.lower()

            # Vérifier que la table existe
            cur.execute("""
                SELECT 1 FROM information_schema.tables 
                WHERE table_name = %s
            """, [table_name])
            if not cur.fetchone():
                raise HTTPException(404, "Table not found")

            # Vérifier que la colonne ID existe
            cur.execute("""
                SELECT column_name FROM information_schema.columns 
                WHERE table_name = %s AND column_name = %s
            """, [table_name, idColumnName])
            if not cur.fetchone():
                raise HTTPException(404, f"Column {idColumnName} not found")

            # ✅ CORRECTION: Méthode alternative sans utiliser ctid
            # 1. Créer une table temporaire avec les nouvelles IDs
            temp_table = f"temp_{table_name}_{int(time.time())}"
            
            cur.execute(f"""
                CREATE TEMPORARY TABLE {temp_table} AS 
                SELECT *, ROW_NUMBER() OVER (ORDER BY {idColumnName}) as new_id 
                FROM {table_name}
            """)
            
            # 2. Mettre à jour la table originale avec les nouvelles IDs
            cur.execute(f"""
                UPDATE {table_name} 
                SET {idColumnName} = t.new_id
                FROM {temp_table} t
                WHERE {table_name}.{idColumnName} = t.{idColumnName}
            """)
            
            # 3. Supprimer la table temporaire
            cur.execute(f"DROP TABLE {temp_table}")
            
            conn.commit()
            
            return {
                "success": True,
                "message": f"Column {idColumnName} reset with sequential values",
                "rows_updated": cur.rowcount
            }

        except Exception as e:
            conn.rollback()
            raise HTTPException(500, f"Reset ID error: {str(e)}")


@router.post("/create-empty-numerized")
async def create_empty_numerized(
    bdName: str = Body(..., embed=True),
    target_db: str = Body(..., embed=True),
    current_user_id: str = Depends(get_current_user2)
):
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            source_table = bdName.lower()
            target_table = target_db.lower()

            # Vérifier si la table cible existe déjà
            cur.execute("""
                SELECT 1 FROM information_schema.tables 
                WHERE table_name = %s
            """, [target_table])
            
            if cur.fetchone():
                return {"success": True, "message": "Table numerized already exists"}

            # Créer une table vide avec la même structure que la source
            # Si la source n'existe pas, créer une structure par défaut
            cur.execute("""
                SELECT column_name, data_type 
                FROM information_schema.columns 
                WHERE table_name = %s 
                ORDER BY ordinal_position
            """, [source_table])
            
            source_columns = cur.fetchall()
            
            if not source_columns:
                # Structure par défaut si la source n'existe pas
                create_query = f"""
                    CREATE TABLE {target_table} (
                        id SERIAL PRIMARY KEY,
                        data_column TEXT
                    )
                """
            else:
                # Créer avec la structure de la source
                columns_def = []
                for col_name, data_type in source_columns:
                    if data_type == 'integer':
                        col_def = f'"{col_name}" INTEGER'
                    elif data_type == 'numeric':
                        col_def = f'"{col_name}" NUMERIC'
                    else:
                        col_def = f'"{col_name}" TEXT'
                    columns_def.append(col_def)
                
                create_query = f"CREATE TABLE {target_table} ({', '.join(columns_def)})"

            cur.execute(create_query)

            # Ajouter aux métadonnées
            cur.execute("""
                INSERT INTO user_tables_metadata
                (table_name, owner_id, columns, created_at)
                VALUES (%s, %s, %s, NOW())
            """, (target_table, current_user_id, [col[0] for col in source_columns] if source_columns else ['id', 'data_column']))

            conn.commit()
            
            return {
                "success": True,
                "message": f"Empty numerized table created: {target_table}",
                "action": "created"
            }

        except Exception as e:
            conn.rollback()
            raise HTTPException(500, f"Create empty numerized error: {str(e)}")










































@router.post("/validate-timeseries-split")
async def validate_timeseries_split(
    request: dict,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Valide que la colonne date existe et est correctement formatée pour TimeSeriesSplit
    """
    try:
        bdName = request.get("bdName")
        date_column = request.get("date_column")
        
        if not bdName or not date_column:
            return {"valid": False, "error": "Missing parameters"}
        
        with get_db_connection() as conn:
            with conn.cursor() as cur:
                # Vérifier que la colonne existe
                cur.execute("""
                    SELECT column_name 
                    FROM information_schema.columns 
                    WHERE table_name = %s AND column_name = %s
                """, (bdName.lower(), date_column.lower()))
                
                if not cur.fetchone():
                    return {"valid": False, "error": f"Column {date_column} not found"}
                
                # Récupérer un échantillon pour vérifier le format date
                cur.execute(f"""
                    SELECT {date_column}
                    FROM {bdName.lower()}
                    WHERE {date_column} IS NOT NULL
                    LIMIT 10
                """)
                
                samples = [row[0] for row in cur.fetchall()]
                
                date_count = 0
                for sample in samples:
                    try:
                        pd.to_datetime(sample)
                        date_count += 1
                    except:
                        pass
                
                is_date_column = date_count / len(samples) > 0.8 if samples else False
                
                return {
                    "valid": is_date_column,
                    "date_column": date_column,
                    "samples": samples[:3],
                    "message": "Valid date column" if is_date_column else "Column does not contain valid dates"
                }
                
    except Exception as e:
        return {"valid": False, "error": str(e)}
















