# ==================== CORRECTION: Modèles Pydantic alignés avec le frontend ====================

class ColumnStatsRequest(BaseModel):
    bdName: str
    columnIndex: int  # Index de colonne (1-based pour correspondre au frontend)
    useTrainOnly: bool = False  # Pour calculer stats seulement sur train split


class ValueCountsRequest(BaseModel):
    bdName: str
    column_name: str
    search_term: str = ""
    min_value: Optional[Union[float, str]] = None  # Accepte string ou float
    max_value: Optional[Union[float, str]] = None
    min_pct: Optional[float] = None  # Fréquence min (% du total des lignes)
    max_pct: Optional[float] = None  # Fréquence max (% du total des lignes)
    page: int = 0
    page_size: int = 50

class ReplaceValuesRequest(BaseModel):
    bdName: str
    column_name: str
    old_values: List[str]
    new_value: Any = None  # Accepte n'importe quel type (str, int, float, bool, None)
    dry_run: bool = False
    
    class Config:
        # Permet d'accepter n'importe quel type
        arbitrary_types_allowed = True

class DeleteRowsRequest(BaseModel):
    bdName: str
    column_name: str
    values_to_delete: List[str]

class ColumnPreviewRequest(BaseModel):
    bdName: str
    column_name: str
    page: int = 0
    page_size: int = 100
    search_term: str = ""


