@router.post("/column-stats")
async def get_column_stats(
    request: dict,  # Changé pour accepter un dictionnaire
    current_user_id: str = Depends(get_current_user2)
):
    """
    Calcule les statistiques complètes d'une colonne directement en base de données
    Accepte soit column_name soit columnIndex comme paramètre
    """
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            
            # Récupérer les paramètres (support des deux formats)
            bdName = request.get('bdName')
            
            # Accepter soit column_name soit columnIndex
            column_name = request.get('column_name') or request.get('columnIndex')
            
            if not bdName:
                raise HTTPException(400, "bdName is required")
            
            if not column_name:
                raise HTTPException(400, "column_name or columnIndex is required")
            
            table_name = bdName.lower()
            
            print(f"📊 Calculating stats for {table_name}.{column_name}")

            # Vérifier l'accès
            cur.execute("""
                SELECT 1 FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            
            if not cur.fetchone():
                raise HTTPException(404, "Table not found or access denied")

            # Vérifier que la colonne existe
            cur.execute("""
                SELECT data_type 
                FROM information_schema.columns 
                WHERE table_name = %s AND column_name = %s
            """, (table_name, column_name))
            
            col_type_info = cur.fetchone()
            if not col_type_info:
                raise HTTPException(404, f"Column '{column_name}' not found in table '{table_name}'")
            
            data_type = col_type_info[0]
            
            # Types numériques PostgreSQL
            numeric_types = ['integer', 'bigint', 'numeric', 'double precision', 'real', 'float', 'decimal', 'smallint']
            is_numeric = data_type in numeric_types

            # Compter total des lignes
            cur.execute(f'SELECT COUNT(*) FROM "{table_name}"')
            total_rows = cur.fetchone()[0]

            # Compter les valeurs non vides
            cur.execute(f'''
                SELECT COUNT(*) FROM "{table_name}" 
                WHERE "{column_name}" IS NOT NULL 
                AND "{column_name}"::text != ''
                AND LOWER("{column_name}"::text) NOT IN ('null', 'nan', 'none', 'na', 'n/a')
            ''')
            non_empty_count = cur.fetchone()[0]
            empty_count = total_rows - non_empty_count

            # Compter les valeurs uniques
            cur.execute(f'''
                SELECT COUNT(DISTINCT "{column_name}") 
                FROM "{table_name}" 
                WHERE "{column_name}" IS NOT NULL
            ''')
            unique_count = cur.fetchone()[0]

            stats = {
                "totalRows": total_rows,
                "nonEmptyCount": non_empty_count,
                "emptyCount": empty_count,
                "uniqueValues": unique_count,
                "isNumeric": is_numeric,
                "dataType": data_type
            }

            # Statistiques numériques si applicable
            if is_numeric:
                try:
                    cur.execute(f'''
                        WITH numeric_values AS (
                            SELECT 
                                CASE 
                                    WHEN "{column_name}"::text ~ '^[0-9\.\-]+$' 
                                    THEN "{column_name}"::numeric 
                                    ELSE NULL 
                                END as num_val
                            FROM "{table_name}"
                            WHERE "{column_name}" IS NOT NULL 
                        )
                        SELECT 
                            MIN(num_val),
                            MAX(num_val),
                            AVG(num_val),
                            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY num_val) as median,
                            COUNT(num_val) as numeric_count
                        FROM numeric_values
                        WHERE num_val IS NOT NULL
                    ''')
                    
                    numeric_stats = cur.fetchone()
                    if numeric_stats and numeric_stats[0] is not None:
                        stats.update({
                            "min": float(numeric_stats[0]) if numeric_stats[0] is not None else None,
                            "max": float(numeric_stats[1]) if numeric_stats[1] is not None else None,
                            "mean": float(numeric_stats[2]) if numeric_stats[2] is not None else None,
                            "median": float(numeric_stats[3]) if numeric_stats[3] is not None else None,
                            "numericCount": numeric_stats[4] if numeric_stats[4] is not None else 0
                        })
                    else:
                        stats.update({
                            "min": None,
                            "max": None,
                            "mean": None,
                            "median": None,
                            "numericCount": 0,
                            "warning": "No valid numeric values found in column"
                        })
                        
                except Exception as e:
                    print(f"⚠️ Error calculating numeric stats: {e}")
                    stats.update({
                        "min": None,
                        "max": None,
                        "mean": None,
                        "median": None,
                        "numericError": str(e)
                    })

            print(f"✅ Stats calculated successfully for {column_name}")
            print(f"   Total rows: {total_rows}, Unique: {unique_count}")
            
            return stats

        except HTTPException:
            raise
        except Exception as e:
            print(f"❌ Error calculating stats: {str(e)}")
            import traceback
            traceback.print_exc()
            raise HTTPException(500, f"Error calculating column statistics: {str(e)}")
@router.post("/column-value-counts")
async def get_column_value_counts(
    request: ValueCountsRequest,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Récupère la distribution des valeurs d'une colonne avec pagination et filtres
    """
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            table_name = request.bdName.lower()
            column_name = request.column_name

            print(f"📊 Getting value counts for {table_name}.{column_name}")
            print(f"   Filters: search='{request.search_term}', min={request.min_value}, max={request.max_value}, page={request.page}")

            # Vérifier l'accès
            cur.execute("""
                SELECT 1 FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            
            if not cur.fetchone():
                raise HTTPException(404, "Table not found or access denied")

            # Obtenir le type de données
            cur.execute("""
                SELECT data_type 
                FROM information_schema.columns 
                WHERE table_name = %s AND column_name = %s
            """, (table_name, column_name))
            
            col_type_info = cur.fetchone()
            if not col_type_info:
                raise HTTPException(404, f"Column {column_name} not found")
            
            data_type = col_type_info[0]
            is_numeric = data_type in ['integer', 'bigint', 'numeric', 'double precision', 'real']

            # Compter le total des lignes pour les pourcentages
            cur.execute(f'SELECT COUNT(*) FROM "{table_name}"')
            total_rows = cur.fetchone()[0]

            # Construire la requête de base pour les comptages
            # Traiter les valeurs NULL/empty comme '[Empty]'
            base_query = f'''
                SELECT 
                    CASE 
                        WHEN "{column_name}" IS NULL OR "{column_name}"::text = '' OR "{column_name}"::text = 'null' 
                        THEN '[Empty]' 
                        ELSE "{column_name}"::text 
                    END as value,
                    COUNT(*) as count
                FROM "{table_name}"
                WHERE 1=1
            '''
            
            params = []

            # Ajouter les filtres
            if request.search_term:
                base_query += f' AND "{column_name}"::text ILIKE %s'
                params.append(f'%{request.search_term}%')
            
            if is_numeric:
                # Convertir min_value/max_value en float si ce sont des strings
                min_val = None
                max_val = None
                
                if request.min_value is not None and request.min_value != "":
                    try:
                        min_val = float(request.min_value)
                        base_query += f' AND CAST("{column_name}" AS numeric) >= %s'
                        params.append(min_val)
                    except (ValueError, TypeError):
                        pass
                
                if request.max_value is not None and request.max_value != "":
                    try:
                        max_val = float(request.max_value)
                        base_query += f' AND CAST("{column_name}" AS numeric) <= %s'
                        params.append(max_val)
                    except (ValueError, TypeError):
                        pass

            base_query += ' GROUP BY value'

            # Filtre par fréquence relative (% du total des lignes)
            having_clauses = []
            if request.min_pct is not None:
                try:
                    min_pct = float(request.min_pct)
                    having_clauses.append('(COUNT(*)::float / %s * 100) >= %s')
                    params.extend([total_rows, min_pct])
                except (ValueError, TypeError):
                    pass
            if request.max_pct is not None:
                try:
                    max_pct = float(request.max_pct)
                    having_clauses.append('(COUNT(*)::float / %s * 100) <= %s')
                    params.extend([total_rows, max_pct])
                except (ValueError, TypeError):
                    pass
            if having_clauses:
                base_query += ' HAVING ' + ' AND '.join(having_clauses)

            # Compter le nombre total de valeurs distinctes (pour pagination)
            count_query = f"SELECT COUNT(*) FROM ({base_query}) as subquery"
            cur.execute(count_query, params)
            total_distinct_values = cur.fetchone()[0]

            # Récupérer les données paginées
            data_query = base_query + ' ORDER BY count DESC, value LIMIT %s OFFSET %s'
            params_page = params + [request.page_size, request.page * request.page_size]
            
            cur.execute(data_query, params_page)
            results = cur.fetchall()

            # Formater les résultats
            value_counts = [{"value": row[0], "count": row[1]} for row in results]

            print(f"✅ Found {len(value_counts)} values, total distinct: {total_distinct_values}")

            return {
                "value_counts": value_counts,
                "total_distinct": total_distinct_values,
                "total_rows": total_rows,
                "page": request.page,
                "page_size": request.page_size,
                "has_more": (request.page + 1) * request.page_size < total_distinct_values
            }

        except Exception as e:
            print(f"❌ Error getting value counts: {str(e)}")
            raise HTTPException(500, f"Error getting value counts: {str(e)}")


@router.post("/group-rare-categories")
async def group_rare_categories(
    request: dict,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Regroupe les catégories rares d'une colonne en une seule valeur (ex. 'Other').
    Utile pour colonnes à forte cardinalité (service, port, protocole…).

    Body:
      bdName, column_name, threshold_pct (défaut 1.0), new_value (défaut 'Other')
    Une catégorie est rare si count / total_rows * 100 < threshold_pct.
    """
    bd_name = (request.get("bdName") or "").lower()
    column_name = request.get("column_name")
    threshold_pct = float(request.get("threshold_pct", 1.0))
    new_value = request.get("new_value", "Other")

    if not bd_name or not column_name:
        raise HTTPException(400, "bdName and column_name are required")
    if threshold_pct <= 0 or threshold_pct >= 50:
        raise HTTPException(400, "threshold_pct must be between 0 and 50")

    with get_db_connection() as conn:
        try:
            cur = conn.cursor()

            cur.execute("""
                SELECT 1 FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
            """, (bd_name, current_user_id))
            if not cur.fetchone():
                raise HTTPException(404, "Table not found or access denied")

            cur.execute(f'SELECT COUNT(*) FROM "{bd_name}"')
            total_rows = cur.fetchone()[0] or 0
            if total_rows == 0:
                return {"status": "success", "rare_categories": 0, "affected_rows": 0}

            cur.execute(f'''
                SELECT "{column_name}"::text AS val, COUNT(*) AS cnt
                FROM "{bd_name}"
                WHERE "{column_name}" IS NOT NULL
                  AND TRIM("{column_name}"::text) <> ''
                  AND LOWER(TRIM("{column_name}"::text)) NOT IN ('null', 'none', 'nan')
                GROUP BY "{column_name}"::text
                HAVING (COUNT(*)::float / %s * 100) < %s
            ''', (total_rows, threshold_pct))

            rare_vals = [row[0] for row in cur.fetchall()]
            if not rare_vals:
                return {
                    "status": "success",
                    "message": "No rare categories found under this threshold",
                    "rare_categories": 0,
                    "affected_rows": 0,
                    "threshold_pct": threshold_pct,
                }

            cur.execute(
                sql.SQL("""
                    UPDATE {}
                    SET {} = %s
                    WHERE {}::text = ANY(%s)
                """).format(
                    sql.Identifier(bd_name),
                    sql.Identifier(column_name),
                    sql.Identifier(column_name),
                ),
                (str(new_value), rare_vals),
            )
            affected = cur.rowcount
            conn.commit()

            return {
                "status": "success",
                "message": f"Grouped {len(rare_vals)} rare categories into '{new_value}'",
                "rare_categories": len(rare_vals),
                "affected_rows": affected,
                "threshold_pct": threshold_pct,
                "new_value": new_value,
                "grouped_values_sample": rare_vals[:30],
            }
        except HTTPException:
            raise
        except Exception as e:
            conn.rollback()
            raise HTTPException(500, f"Error grouping rare categories: {str(e)}")


@router.post("/replace-values")
async def replace_values(
    request: ReplaceValuesRequest,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Remplace des valeurs directement en base de données
    """
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            table_name = request.bdName.lower()
            column_name = request.column_name

            print(f"🔄 Replacing values in {table_name}.{column_name}")
            print(f"   Old values: {request.old_values}")
            print(f"   New value: {request.new_value} (type: {type(request.new_value)})")

            # Vérifier l'accès
            cur.execute("""
                SELECT 1 FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            
            if not cur.fetchone():
                raise HTTPException(404, "Table not found or access denied")

            # Vérifier le type de la colonne
            cur.execute("""
                SELECT data_type 
                FROM information_schema.columns 
                WHERE table_name = %s AND column_name = %s
            """, (table_name, column_name))
            
            col_type_info = cur.fetchone()
            if not col_type_info:
                raise HTTPException(404, f"Column {column_name} not found")
            
            col_type = col_type_info[0]
            print(f"   Column type: {col_type}")
            
            # Déterminer si la colonne est numérique
            numeric_types = ['integer', 'bigint', 'numeric', 'double precision', 'real', 'float', 'decimal', 'smallint']
            is_numeric = col_type in numeric_types
            
            # Déterminer si la colonne est texte
            text_types = ['text', 'character varying', 'varchar', 'char', 'character']
            is_text = col_type in text_types

            # ✅ SOLUTION: Valider la nouvelle valeur selon le type de colonne
            new_value_for_db = request.new_value
            validation_error = None
            
            # Liste des valeurs considérées comme "vides" (acceptées pour tous les types)
            EMPTY_VALUES = ['', 'none', 'null', 'na', 'n/a', 'nan', 'NULL', 'None', 'NaN']
            
            # Vérifier si c'est une valeur vide (toujours acceptée)
            is_empty_value = False
            if new_value_for_db is None:
                is_empty_value = True
            elif isinstance(new_value_for_db, str) and new_value_for_db.strip().lower() in EMPTY_VALUES:
                is_empty_value = True
                new_value_for_db = None  # NULL en SQL
                print(f"   ✅ Interprété comme NULL (vide)")
            
            # VALIDATION POUR COLONNES NUMÉRIQUES
            if is_numeric and not is_empty_value:
                # Essayer de convertir en nombre
                try:
                    if isinstance(new_value_for_db, (int, float)):
                        # Déjà un nombre, pas besoin de conversion
                        pass
                    elif isinstance(new_value_for_db, str):
                        # Nettoyer la chaîne
                        cleaned = new_value_for_db.strip().replace(',', '.')
                        float(cleaned)  # Test de conversion
                    else:
                        float(new_value_for_db)  # Test de conversion
                except (ValueError, TypeError):
                    validation_error = f"Cannot replace with text value '{new_value_for_db}' in numeric column '{column_name}'. Please enter a valid number or empty value (null)."
                    print(f"   ❌ {validation_error}")
            
            # VALIDATION POUR COLONNES TEXTE (pas de validation spéciale, tout est accepté)
            # VALIDATION POUR AUTRES TYPES (boolean, date, etc.)
            elif not is_numeric and not is_text and not is_empty_value:
                # Pour les autres types, vérifier si la valeur peut être convertie
                # Cette partie peut être améliorée selon vos besoins
                pass
            
            # Si erreur de validation, renvoyer une erreur claire
            if validation_error:
                raise HTTPException(400, validation_error)

            # Construire les conditions WHERE
            conditions = []
            params = []
            
            for val in request.old_values:
                if val == '[Empty]' or val is None:
                    conditions.append(f'("{column_name}" IS NULL OR "{column_name}"::text = %s)')
                    params.append('')
                else:
                    conditions.append(f'"{column_name}"::text = %s')
                    params.append(str(val))

            if not conditions:
                return {"affected_rows": 0, "message": "No values to replace"}

            where_clause = " OR ".join(conditions)
            
            # Compter les lignes affectées
            count_query = f'SELECT COUNT(*) FROM "{table_name}" WHERE {where_clause}'
            cur.execute(count_query, params)
            affected_rows = cur.fetchone()[0]

            if request.dry_run:
                return {"affected_rows": affected_rows, "dry_run": True}

            # EXÉCUTION DE LA MISE À JOUR
            if affected_rows > 0:
                
                # CAS 1: Colonne numérique
                if is_numeric:
                    
                    if new_value_for_db is None:
                        # CAS: Mettre à NULL (vide) - TOUJOURS possible
                        update_query = f'UPDATE "{table_name}" SET "{column_name}" = NULL WHERE {where_clause}'
                        cur.execute(update_query, params)
                        print(f"   ✅ Mise à NULL sur colonne numérique")
                        
                    else:
                        # CAS: Remplacer par une valeur numérique (déjà validée)
                        try:
                            # Convertir en float pour PostgreSQL
                            if isinstance(new_value_for_db, str):
                                numeric_value = float(new_value_for_db.strip().replace(',', '.'))
                            else:
                                numeric_value = float(new_value_for_db)
                                
                            update_query = f'UPDATE "{table_name}" SET "{column_name}" = %s WHERE {where_clause}'
                            cur.execute(update_query, [numeric_value] + params)
                            print(f"   ✅ Mise à jour avec valeur numérique: {numeric_value}")
                            
                        except (ValueError, TypeError) as e:
                            # Ne devrait pas arriver car déjà validé, mais sécurité
                            conn.rollback()
                            raise HTTPException(400, f"Invalid numeric value: {new_value_for_db}")
                
                # CAS 2: Colonne texte
                elif is_text:
                    # Pour les colonnes texte, on peut stocker n'importe quoi
                    if new_value_for_db is None:
                        update_query = f'UPDATE "{table_name}" SET "{column_name}" = NULL WHERE {where_clause}'
                        cur.execute(update_query, params)
                    else:
                        update_query = f'UPDATE "{table_name}" SET "{column_name}" = %s WHERE {where_clause}'
                        cur.execute(update_query, [str(new_value_for_db)] + params)
                    print(f"   ✅ Mise à jour sur colonne texte")
                
                # CAS 3: Autres types (boolean, date, etc.)
                else:
                    if new_value_for_db is None:
                        update_query = f'UPDATE "{table_name}" SET "{column_name}" = NULL WHERE {where_clause}'
                        cur.execute(update_query, params)
                    else:
                        # Laisser PostgreSQL gérer la conversion
                        update_query = f'UPDATE "{table_name}" SET "{column_name}" = %s WHERE {where_clause}'
                        cur.execute(update_query, [new_value_for_db] + params)
                    print(f"   ✅ Mise à jour sur colonne type {col_type}")
                
                conn.commit()

                # Mettre à jour les métadonnées
                try:
                    cur.execute("""
                        UPDATE user_tables_metadata
                        SET updated_at = NOW()
                        WHERE table_name = %s AND owner_id = %s
                    """, (table_name, current_user_id))
                    conn.commit()
                except:
                    pass

                print(f"✅ Replaced {affected_rows} rows")

            return {
                "affected_rows": affected_rows,
                "message": f"Successfully replaced {affected_rows} rows"
            }

        except HTTPException:
            raise
        except Exception as e:
            conn.rollback()
            print(f"❌ Error replacing values: {str(e)}")
            import traceback
            traceback.print_exc()
            raise HTTPException(500, f"Error replacing values: {str(e)}")         
@router.post("/delete-rows")
async def delete_rows(
    request: DeleteRowsRequest,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Supprime les lignes où la colonne a certaines valeurs
    """
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            table_name = request.bdName.lower()
            column_name = request.column_name

            print(f"🗑️ Deleting rows from {table_name} where {column_name} in {request.values_to_delete}")

            # Vérifier l'accès
            cur.execute("""
                SELECT 1 FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            
            if not cur.fetchone():
                raise HTTPException(404, "Table not found or access denied")

            # ✅ SOLUTION : Obtenir le type de la colonne
            cur.execute("""
                SELECT data_type 
                FROM information_schema.columns 
                WHERE table_name = %s AND column_name = %s
            """, (table_name, column_name))
            
            result = cur.fetchone()
            if not result:
                raise HTTPException(404, f"Column {column_name} not found")
            
            col_type = result[0]
            print(f"   Column type: {col_type}")

            # ✅ Construire les conditions selon le type
            conditions = []
            params = []

            for val in request.values_to_delete:
                # CAS 1: Valeur '[Empty]' - représente les valeurs NULL/vides
                if val == '[Empty]':
                    if col_type in ['double precision', 'numeric', 'integer', 'bigint', 'real', 'float']:
                        # Pour les colonnes numériques : seulement IS NULL
                        conditions.append(f'"{column_name}" IS NULL')
                        print(f"   ✅ Condition NULL pour colonne numérique")
                    else:
                        # Pour les colonnes texte : NULL OU chaîne vide
                        conditions.append(f'("{column_name}" IS NULL OR "{column_name}" = %s)')
                        params.append('')
                        print(f"   ✅ Condition NULL ou vide pour colonne texte")
                
                # CAS 2: Valeur spécifique
                else:
                    if col_type in ['double precision', 'numeric', 'integer', 'bigint', 'real', 'float']:
                        # Pour les colonnes numériques, on convertit la valeur en nombre
                        try:
                            numeric_val = float(val)
                            conditions.append(f'"{column_name}" = %s')
                            params.append(numeric_val)
                            print(f"   ✅ Condition numérique: {numeric_val}")
                        except ValueError:
                            # Si ce n'est pas un nombre valide, ignorer ou chercher en texte
                            print(f"   ⚠️ Valeur '{val}' non numérique, recherche en texte")
                            conditions.append(f'"{column_name}"::text = %s')
                            params.append(str(val))
                    else:
                        # Pour les colonnes texte, comparaison directe
                        conditions.append(f'"{column_name}" = %s')
                        params.append(str(val))

            if not conditions:
                return {"deleted_rows": 0, "message": "No valid conditions"}

            # Construire la clause WHERE
            where_clause = " OR ".join(conditions)
            
            # Compter d'abord (optionnel)
            count_query = f'SELECT COUNT(*) FROM "{table_name}" WHERE {where_clause}'
            cur.execute(count_query, params)
            count = cur.fetchone()[0]
            print(f"   Found {count} rows to delete")

            if count == 0:
                return {"deleted_rows": 0, "message": "No matching rows found"}

            # Exécuter la suppression
            delete_query = f'DELETE FROM "{table_name}" WHERE {where_clause}'
            cur.execute(delete_query, params)
            deleted_rows = cur.rowcount
            
            conn.commit()
            
            print(f"✅ Deleted {deleted_rows} rows")

            return {
                "deleted_rows": deleted_rows,
                "message": f"Successfully deleted {deleted_rows} rows"
            }

        except Exception as e:
            conn.rollback()
            print(f"❌ Error deleting rows: {str(e)}")
            import traceback
            traceback.print_exc()
            raise HTTPException(500, f"Error deleting rows: {str(e)}")

@router.post("/column-preview")
async def get_column_preview(
    request: ColumnPreviewRequest,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Récupère un aperçu paginé des valeurs d'une colonne
    """
    with get_db_connection() as conn:
        try:
            cur = conn.cursor()
            table_name = request.bdName.lower()
            column_name = request.column_name

            print(f"👁️ Getting column preview for {table_name}.{column_name}")

            # Vérifier l'accès
            cur.execute("""
                SELECT 1 FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            
            if not cur.fetchone():
                raise HTTPException(404, "Table not found or access denied")

            # Construire la requête
            query = f'''
                SELECT id, "{column_name}" as value
                FROM "{table_name}"
            '''
            params = []

            if request.search_term:
                query += f' WHERE "{column_name}"::text ILIKE %s'
                params.append(f'%{request.search_term}%')

            query += ' ORDER BY id LIMIT %s OFFSET %s'
            params.extend([request.page_size, request.page * request.page_size])

            cur.execute(query, params)
            rows = cur.fetchall()

            # Compter le total
            count_query = f'SELECT COUNT(*) FROM "{table_name}"'
            if request.search_term:
                count_query += f' WHERE "{column_name}"::text ILIKE %s'
                cur.execute(count_query, [f'%{request.search_term}%'])
            else:
                cur.execute(count_query)
            total_rows = cur.fetchone()[0]

            print(f"✅ Found {len(rows)} rows for preview")

            return {
                "rows": [{"id": r[0], "value": r[1]} for r in rows],
                "total_rows": total_rows,
                "page": request.page,
                "page_size": request.page_size,
                "has_more": (request.page + 1) * request.page_size < total_rows
            }

        except Exception as e:
            print(f"❌ Error getting column preview: {str(e)}")
            raise HTTPException(500, f"Error getting column preview: {str(e)}")


