def is_empty_value(value):
    if value is None:
        return True
    if isinstance(value, str) and value.strip() == "":
        return True
    if isinstance(value, (list, dict)) and not value:
        return True
    if str(value).lower() == "null":
        return True
    return False

class DeleteRowsWithEmptyValuesRequest(BaseModel):
    bdName: str

@router.post("/delete-rows-with-empty-values")
async def delete_rows_with_empty_values(
    request: DeleteRowsWithEmptyValuesRequest,
    current_user_id: str = Depends(get_current_user2)
):
    try:
        with get_db_connection() as conn:
            cur = conn.cursor()

            # Vérifier l'accès
            table_name = request.bdName.lower()
            original_table_name = table_name.replace('_numerized', '')
            
            cur.execute("""
                SELECT 1 FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (original_table_name, current_user_id))
            
            if not cur.fetchone():
                raise HTTPException(status_code=403, detail="Access denied")

            # 1. Obtenir TOUTES les colonnes (y compris split_type mais sans id)
            cur.execute("""
                SELECT column_name 
                FROM information_schema.columns 
                WHERE table_name = %s 
                AND column_name != 'id'
                ORDER BY ordinal_position
            """, (table_name,))
            
            all_columns = [row[0] for row in cur.fetchall()]
            
            # Colonnes pour la vérification des valeurs vides (exclure split_type)
            check_columns = [col for col in all_columns if col != 'split_type']
            
            if not all_columns:
                return {"status": "success", "message": "Aucune colonne à vérifier", "deleted_count": 0}

            # 2. Créer une table temporaire sans les lignes vides
            temp_table = f"temp_{table_name}_{uuid.uuid4().hex[:8]}"
            
            # Construire la condition WHERE (uniquement sur les colonnes à vérifier)
            conditions = []
            for col in check_columns:
                conditions.append(
                    sql.SQL("({col} IS NULL OR {col}::text = '' OR {col}::text = 'null' OR {col}::text = '[]' OR {col}::text = '{{}}')").format(
                        col=sql.Identifier(col)
                    )
                )
            
            # 3. Compter les lignes à supprimer
            count_query = sql.SQL("SELECT COUNT(*) FROM {} WHERE (").format(
                sql.Identifier(table_name)
            ) + sql.SQL(" OR ").join(conditions) + sql.SQL(")")
            
            cur.execute(count_query)
            rows_to_delete = cur.fetchone()[0]
            
            if rows_to_delete == 0:
                return {"status": "success", "message": "Aucune ligne avec valeurs vides", "deleted_count": 0}
            
            # 4. Créer la table temporaire avec les données valides (TOUTES les colonnes)
            create_temp_query = sql.SQL("""
                CREATE TEMPORARY TABLE {} AS 
                SELECT * FROM {} 
                WHERE NOT (
            """).format(
                sql.Identifier(temp_table),
                sql.Identifier(table_name)
            ) + sql.SQL(" OR ").join(conditions) + sql.SQL(")")
            
            cur.execute(create_temp_query)
            
            # 5. Supprimer toutes les lignes de la table originale
            cur.execute(sql.SQL("TRUNCATE TABLE {}").format(sql.Identifier(table_name)))
            
            # 6. Réinsérer les données valides depuis la table temporaire avec réinitialisation des IDs
            # Préparer les identifiants de colonnes pour l'insertion (TOUTES les colonnes)
            all_column_identifiers = [sql.Identifier(col) for col in all_columns]
            
            insert_query = sql.SQL("""
                INSERT INTO {} (id, {})
                SELECT 
                    ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) as new_id,
                    {}
                FROM {}
            """).format(
                sql.Identifier(table_name),
                sql.SQL(', ').join(all_column_identifiers),
                sql.SQL(', ').join([sql.Identifier(col) for col in all_columns]),
                sql.Identifier(temp_table)
            )
            
            cur.execute(insert_query)
            
            # 7. Mettre à jour la séquence d'auto-incrémentation pour l'ID
            # setval(0) is invalid (sequence min is 1) — happens if table ends empty
            cur.execute(
                sql.SQL("SELECT COALESCE(MAX(id), 0) FROM {}").format(
                    sql.Identifier(table_name)
                )
            )
            max_id = int(cur.fetchone()[0] or 0)
            cur.execute(
                "SELECT pg_get_serial_sequence(%s, 'id')",
                (table_name,),
            )
            seq_row = cur.fetchone()
            seq_name = seq_row[0] if seq_row else None
            if seq_name:
                if max_id < 1:
                    cur.execute("SELECT setval(%s::regclass, 1, false)", (seq_name,))
                else:
                    cur.execute("SELECT setval(%s::regclass, %s)", (seq_name, max_id))
            
            # 8. Supprimer la table temporaire
            cur.execute(sql.SQL("DROP TABLE IF EXISTS {}").format(sql.Identifier(temp_table)))
            
            conn.commit()
            
            return {
                "status": "success", 
                "message": f"{rows_to_delete} lignes avec valeurs vides supprimées",
                "deleted_count": rows_to_delete
            }
            
    except psycopg2.Error as e:
        if conn:
            conn.rollback()
        # Supprimer la table temporaire si elle existe
        try:
            if 'temp_table' in locals():
                cur.execute(sql.SQL("DROP TABLE IF EXISTS {}").format(sql.Identifier(temp_table)))
        except:
            pass
        raise HTTPException(status_code=500, detail=f"DB error: {str(e)}")
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Erreur: {str(e)}")

