@router.post("/delete-column")
async def delete_column(
    request: dict,
    current_user_id: str = Depends(get_current_user2)
):
    try:
        with get_db_connection() as conn:
            cur = conn.cursor()

            # 1. Normaliser les noms — accepte columnName (str) ou columnNames (list)
            original_table_name = request['originalBdName'].replace('_numerized', '').lower()
            current_table_name = request.get('currentBdName', original_table_name).lower()
            raw_cols = request.get('columnNames') or request.get('columnName')
            if raw_cols is None:
                raise HTTPException(400, "columnName or columnNames is required")
            if isinstance(raw_cols, str):
                columns_to_delete = [raw_cols]
            else:
                columns_to_delete = list(raw_cols)
            if not columns_to_delete:
                raise HTTPException(400, "No columns to delete")

            target_table = original_table_name
            numerized_exists = True

            cur.execute("""
                SELECT target_column FROM user_tables_metadata 
                WHERE table_name = %s AND owner_id = %s
            """, (original_table_name, current_user_id))
            
            metadata = cur.fetchone()
            if not metadata:
                raise HTTPException(403, "Access denied à la table originale")

            protected_columns = {'split_type', 'id'}
            target_col = (metadata[0] or "").lower()
            deleted = []

            for column_to_delete in columns_to_delete:
                col_l = str(column_to_delete).lower().strip()
                if not col_l:
                    continue
                if target_col and col_l == target_col:
                    raise HTTPException(400, f"Cannot delete target column '{column_to_delete}'")
                if col_l in protected_columns:
                    raise HTTPException(400, f"Cannot delete system column '{column_to_delete}'")

                cur.execute("""
                    SELECT column_name 
                    FROM information_schema.columns 
                    WHERE table_name = %s 
                    AND lower(column_name) = %s
                """, (target_table, col_l))
                
                column_info = cur.fetchone()
                if not column_info:
                    raise HTTPException(400, f"Column '{column_to_delete}' does not exist")

                exact_column_name = column_info[0]
                cur.execute(sql.SQL("""
                    ALTER TABLE {} 
                    DROP COLUMN IF EXISTS {}
                """).format(
                    sql.Identifier(target_table),
                    sql.Identifier(exact_column_name)
                ))
                deleted.append(exact_column_name)

            cur.execute("""
                UPDATE user_tables_metadata
                SET columns = (
                    SELECT array_agg(column_name::text)
                    FROM information_schema.columns
                    WHERE table_name = %s 
                    AND column_name != 'id'
                    AND column_name != 'split_type'
                )
                WHERE table_name = %s AND owner_id = %s
            """, (target_table, target_table, current_user_id))
            
            conn.commit()

            return {
                "status": "success",
                "message": f"Deleted column(s): {', '.join(deleted)}",
                "deleted_columns": deleted,
                "new_bd_name": target_table,
                "action": "updated"
            }

    except psycopg2.Error as e:
        if conn:
            conn.rollback()
        raise HTTPException(500, f"DB error: {e.pgerror}")
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(500, f"Unexpected error: {str(e)}")


@router.post("/rename-column")
async def rename_column(
    request: dict,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Renomme une colonne du dataset via ALTER TABLE ... RENAME COLUMN.

    Body attendu: { "bdName": str, "oldName": str, "newName": str }

    - Opère sur la table principale (état courant de la préparation).
    - Protège les colonnes système (id, split_type).
    - Valide le nouveau nom (identifiant PostgreSQL sûr, non déjà utilisé).
    - Met à jour user_tables_metadata.columns et target_column si nécessaire.
    - Propage le renommage aux variantes courantes (_numerized, _reset) si elles
      possèdent la colonne, afin de garder l'état cohérent. Le snapshot _backup
      (version originale) est laissé intact.
    """
    conn = None
    try:
        base_table = str(request.get('bdName', '')).replace('_numerized', '').lower().strip()
        old_name = str(request.get('oldName', '')).strip()
        new_name = str(request.get('newName', '')).strip()

        if not base_table or not old_name or not new_name:
            raise HTTPException(400, "bdName, oldName et newName sont obligatoires")

        # ---- Validation du nouveau nom ----
        new_name_norm = new_name.lower()
        protected_columns = ['id', 'split_type']

        if new_name_norm in protected_columns:
            raise HTTPException(400, f"'{new_name}' is a reserved system column name")

        if new_name_norm[0].isdigit():
            raise HTTPException(400, "Column name cannot start with a number")

        if ' ' in new_name_norm:
            raise HTTPException(400, "Column name cannot contain spaces. Use underscores (_) instead.")

        if not re.match(r'^[a-z][a-z0-9_]*$', new_name_norm):
            raise HTTPException(400, "Column name contains invalid characters. Only lowercase letters, numbers and underscores are allowed, and must start with a letter.")

        if len(new_name_norm) > 63:  # PostgreSQL limit
            raise HTTPException(400, "Column name is too long. Maximum 63 characters allowed.")

        if old_name.lower() in protected_columns:
            raise HTTPException(400, f"Cannot rename system column '{old_name}'")

        with get_db_connection() as conn:
            cur = conn.cursor()

            # ---- Vérification ownership sur la table principale ----
            cur.execute("""
                SELECT target_column FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
            """, (base_table, current_user_id))
            metadata = cur.fetchone()
            if not metadata:
                raise HTTPException(403, "Access denied to this dataset")

            current_target = (metadata[0] or "").strip()

            # ---- Récupérer le nom exact (respect de la casse) de la colonne source ----
            cur.execute("""
                SELECT column_name FROM information_schema.columns
                WHERE table_name = %s AND lower(column_name) = %s
            """, (base_table, old_name.lower()))
            col_info = cur.fetchone()
            if not col_info:
                raise HTTPException(400, f"Column '{old_name}' does not exist in {base_table}")
            exact_old_name = col_info[0]

            # ---- Le nouveau nom ne doit pas déjà exister (sauf si identique en casse) ----
            if new_name_norm != exact_old_name.lower():
                cur.execute("""
                    SELECT 1 FROM information_schema.columns
                    WHERE table_name = %s AND lower(column_name) = %s
                """, (base_table, new_name_norm))
                if cur.fetchone():
                    raise HTTPException(400, f"A column named '{new_name}' already exists")

            # ---- Renommer dans la table principale + variantes courantes ----
            variants = [base_table, f"{base_table}_numerized", f"{base_table}_reset"]
            renamed_in = []
            for tbl in variants:
                # La table existe-t-elle ?
                cur.execute("""
                    SELECT 1 FROM information_schema.tables WHERE table_name = %s
                """, (tbl,))
                if not cur.fetchone():
                    continue
                # La colonne (nom exact) existe-t-elle dans cette variante ?
                cur.execute("""
                    SELECT column_name FROM information_schema.columns
                    WHERE table_name = %s AND lower(column_name) = %s
                """, (tbl, exact_old_name.lower()))
                variant_col = cur.fetchone()
                if not variant_col:
                    continue
                cur.execute(sql.SQL("ALTER TABLE {} RENAME COLUMN {} TO {}").format(
                    sql.Identifier(tbl),
                    sql.Identifier(variant_col[0]),
                    sql.Identifier(new_name_norm)
                ))
                renamed_in.append(tbl)

            # ---- Mise à jour des métadonnées (columns + target_column) ----
            target_updated = False
            new_target = current_target
            if current_target and current_target.lower() == exact_old_name.lower():
                new_target = new_name_norm
                target_updated = True

            for tbl in [base_table, f"{base_table}_reset"]:
                cur.execute("""
                    SELECT 1 FROM user_tables_metadata WHERE table_name = %s AND owner_id = %s
                """, (tbl, current_user_id))
                if not cur.fetchone():
                    continue
                cur.execute("""
                    UPDATE user_tables_metadata
                    SET columns = (
                        SELECT array_agg(column_name::text)
                        FROM information_schema.columns
                        WHERE table_name = %s
                        AND column_name != 'id'
                        AND column_name != 'split_type'
                    ),
                    target_column = %s
                    WHERE table_name = %s AND owner_id = %s
                """, (tbl, new_target if new_target else None, tbl, current_user_id))

            conn.commit()

            return {
                "status": "success",
                "message": f"Column '{exact_old_name}' renamed to '{new_name_norm}'",
                "old_name": exact_old_name,
                "new_name": new_name_norm,
                "renamed_in": renamed_in,
                "target_column_updated": target_updated,
                "new_target_column": new_target if target_updated else None
            }

    except psycopg2.Error as e:
        if conn:
            conn.rollback()
        raise HTTPException(500, f"DB error: {e.pgerror}")
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(500, f"Unexpected error: {str(e)}")


def _eda_safe_number(x):
    """Convertit une valeur numpy/pandas en float JSON-safe (None si NaN/inf)."""
    try:
        if x is None:
            return None
        val = float(x)
        if val != val or val in (float('inf'), float('-inf')):
            return None
        return val
    except (ValueError, TypeError):
        return None


@router.post("/eda-analysis")
async def eda_analysis(
    request: dict,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Analyse exploratoire (EDA) entièrement calculée côté serveur (PostgreSQL + pandas).

    Body attendu:
      {
        "bdName": str,
        "useTrainOnly": bool (optionnel, défaut False),
        "maxBins": int (optionnel, défaut 20),
        "topK": int (optionnel, défaut 10)
      }

    Anti data-leakage : si useTrainOnly est demandé ET que la colonne split_type
    existe, l'analyse est restreinte au sous-ensemble d'entraînement. Sinon elle
    porte sur l'ensemble du dataset. Le frontend décide de la portée (dataset
    complet avant split, train uniquement après split).

    Retourne : types de colonnes, statistiques descriptives, distributions,
    valeurs manquantes et corrélations (Pearson sur colonnes numériques).
    """
    try:
        bdName = str(request.get('bdName', '')).strip()
        use_train_only = bool(request.get('useTrainOnly', False))
        max_bins = int(request.get('maxBins', 20) or 20)
        top_k = int(request.get('topK', 10) or 10)
        max_bins = max(2, min(max_bins, 50))
        top_k = max(3, min(top_k, 30))

        if not bdName:
            raise HTTPException(400, "bdName is required")

        table_name = bdName.lower()

        with get_db_connection() as conn:
            cur = conn.cursor()

            # Ownership
            cur.execute("""
                SELECT columns FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
            """, (table_name, current_user_id))
            if not cur.fetchone():
                raise HTTPException(404, "Table not found or access denied")

            # Existence de split_type
            cur.execute("""
                SELECT 1 FROM information_schema.columns
                WHERE table_name = %s AND column_name = 'split_type'
            """, (table_name,))
            has_split = cur.fetchone() is not None

            scope = 'train' if (use_train_only and has_split) else 'all'
            where_clause = " WHERE split_type = 'train'" if scope == 'train' else ""

            cur.execute(sql.SQL("SELECT * FROM {}" ).format(sql.Identifier(table_name)).as_string(cur) + where_clause)
            db_columns = [desc[0] for desc in cur.description]
            rows = cur.fetchall()

        df = pd.DataFrame(rows, columns=db_columns)

        # Retirer les colonnes système
        for sys_col in ['id', 'split_type']:
            if sys_col in df.columns:
                df = df.drop(columns=[sys_col])

        total_rows = int(len(df))
        analysis_columns = list(df.columns)

        # ---- Détection de type + coercition numérique par colonne ----
        numeric_series = {}     # name -> pd.Series (float)
        column_types = {}       # name -> type string

        for col in analysis_columns:
            s = df[col]
            non_null = s.dropna()
            nunique = int(non_null.nunique())

            if pd.api.types.is_bool_dtype(s) or pd.api.types.is_numeric_dtype(s):
                # Toujours stocker en float pour éviter "numpy boolean subtract"
                coerced = pd.to_numeric(s, errors='coerce').astype('float64')
                numeric_series[col] = coerced
                if nunique <= 2:
                    column_types[col] = 'boolean'
                elif nunique <= 200 and nunique / max(len(non_null), 1) <= 0.05:
                    column_types[col] = 'categorical'
                else:
                    column_types[col] = 'numerical'
                continue

            # Colonnes texte : tenter une coercition numérique
            cleaned = non_null.astype(str).str.replace(r'[$€£¥%,\s]', '', regex=True)
            coerced_nonnull = pd.to_numeric(cleaned, errors='coerce')
            success_ratio = (coerced_nonnull.notna().sum() / len(non_null)) if len(non_null) > 0 else 0

            if success_ratio > 0.8:
                full_cleaned = s.astype(str).str.replace(r'[$€£¥%,\s]', '', regex=True)
                coerced_full = pd.to_numeric(full_cleaned, errors='coerce').astype('float64')
                numeric_series[col] = coerced_full
                num_unique = int(coerced_full.dropna().nunique())
                if num_unique <= 2:
                    column_types[col] = 'boolean'
                elif num_unique <= 200 and num_unique / max(len(non_null), 1) <= 0.05:
                    column_types[col] = 'categorical'
                else:
                    column_types[col] = 'numerical'
            else:
                if nunique <= 2:
                    column_types[col] = 'boolean'
                elif nunique <= 200 and (len(non_null) == 0 or nunique / len(non_null) <= 0.05):
                    column_types[col] = 'categorical'
                elif nunique <= 50 or (len(non_null) > 0 and nunique / len(non_null) <= 0.5):
                    column_types[col] = 'categorical'
                else:
                    column_types[col] = 'text'

        # ---- Statistiques descriptives + distributions par colonne ----
        columns_report = []
        columns_with_missing = []
        total_missing = 0

        for col in analysis_columns:
            s = df[col]
            missing = int(s.isna().sum())
            total_missing += missing
            missing_pct = round((missing / total_rows) * 100, 2) if total_rows else 0.0
            count = total_rows - missing
            unique = int(s.dropna().nunique())
            ctype = column_types[col]

            if missing > 0:
                columns_with_missing.append({
                    "name": col, "missing": missing, "missing_pct": missing_pct
                })

            entry = {
                "name": col,
                "type": ctype,
                "count": count,
                "missing": missing,
                "missing_pct": missing_pct,
                "unique": unique,
                "numeric": None,
                "categorical": None,
                "distribution": None,
            }

            if ctype in ('numerical', 'boolean') and col in numeric_series:
                # Cast explicite en float : les bool numpy ne supportent pas `arr - mean`
                # (erreur "numpy boolean subtract").
                num = pd.to_numeric(numeric_series[col], errors='coerce').dropna().astype(float)
                if len(num) > 0:
                    entry["numeric"] = {
                        "mean": _eda_safe_number(num.mean()),
                        "std": _eda_safe_number(num.std()),
                        "min": _eda_safe_number(num.min()),
                        "q1": _eda_safe_number(num.quantile(0.25)),
                        "median": _eda_safe_number(num.median()),
                        "q3": _eda_safe_number(num.quantile(0.75)),
                        "max": _eda_safe_number(num.max()),
                        "skew": _eda_safe_number(num.skew()) if len(num) > 2 else None,
                    }
                    try:
                        counts, edges = np.histogram(num.to_numpy(dtype=float), bins=min(max_bins, max(1, unique)))
                        bins = []
                        for i in range(len(counts)):
                            bins.append({
                                "start": _eda_safe_number(edges[i]),
                                "end": _eda_safe_number(edges[i + 1]),
                                "count": int(counts[i]),
                            })
                        entry["distribution"] = {"kind": "histogram", "bins": bins}
                    except Exception:
                        entry["distribution"] = None
            else:
                vc = s.dropna().astype(str).value_counts().head(top_k)
                top_values = [{"value": str(idx), "count": int(cnt)} for idx, cnt in vc.items()]
                if len(top_values) > 0:
                    entry["categorical"] = {
                        "top": top_values[0]["value"],
                        "top_freq": top_values[0]["count"],
                        "top_values": top_values,
                    }
                    entry["distribution"] = {"kind": "categories", "top_values": top_values}

            columns_report.append(entry)

        # ---- Corrélations (Pearson) sur TOUTES les colonnes à contenu numérique
        # (y compris categorical numériques / boolean 0-1 stockés dans numeric_series)
        numeric_cols = [c for c in analysis_columns if c in numeric_series]
        correlations = None
        if len(numeric_cols) >= 2:
            num_df = pd.DataFrame({c: pd.to_numeric(numeric_series[c], errors='coerce') for c in numeric_cols})
            try:
                corr = num_df.corr(method='pearson')
                matrix = []
                for r in numeric_cols:
                    matrix.append([_eda_safe_number(corr.loc[r, cc]) for cc in numeric_cols])
                correlations = {"columns": numeric_cols, "matrix": matrix}
            except Exception:
                correlations = None

        total_cells = total_rows * len(analysis_columns)
        columns_with_missing.sort(key=lambda x: x["missing"], reverse=True)

        return {
            "status": "success",
            "bdName": bdName,
            "scope": scope,
            "has_split": has_split,
            "row_count": total_rows,
            "column_count": len(analysis_columns),
            "numeric_columns": numeric_cols,
            "categorical_columns": [c for c in analysis_columns if column_types[c] in ('categorical', 'boolean', 'text')],
            "columns": columns_report,
            "missing_summary": {
                "total_cells": total_cells,
                "total_missing": int(total_missing),
                "missing_pct": round((total_missing / total_cells) * 100, 2) if total_cells else 0.0,
                "columns_with_missing": columns_with_missing,
            },
            "correlations": correlations,
        }

    except HTTPException:
        raise
    except psycopg2.Error as e:
        raise HTTPException(500, f"DB error: {e.pgerror}")
    except Exception as e:
        raise HTTPException(500, f"EDA error: {str(e)}")


def extract_with_format(value, date_format):
    """Extrait les composants de date en suivant strictement le format spécifié"""
    if pd.isna(value) or not date_format:
        return {}
    
    value = str(value).strip()
    result = {}
    
    # Analyser le format pour connaître l'ordre des composants
    components = []
    i = 0
    n = len(date_format)
    while i < n:
        char = date_format[i]
        if char in ['d', 'M', 'y', 'h', 'm', 's']:
            start = i
            while i < n and date_format[i] == char:
                i += 1
            components.append((char, i - start))  # (type, longueur)
        else:
            i += 1
    
    # Extraire les valeurs en suivant l'ordre du format
    pos = 0
    for comp_type, length in components:
        # Extraire les chiffres
        digits = []
        while pos < len(value) and len(digits) < length and value[pos].isdigit():
            digits.append(value[pos])
            pos += 1
        
        # Passer les séparateurs
        while pos < len(value) and not value[pos].isdigit():
            pos += 1
        
        if digits:
            num_value = int(''.join(digits))
            if comp_type == 'd':
                result['day'] = num_value
            elif comp_type == 'M':
                result['month'] = num_value
            elif comp_type == 'y':
                result['year'] = 2000 + num_value if length <= 2 else num_value
            elif comp_type == 'h':
                result['hour'] = num_value
            elif comp_type == 'm':
                result['minute'] = num_value
            elif comp_type == 's':
                result['second'] = num_value
    
    return result
def extract_date_components(value, date_format, components):
    """Extrait manuellement les composants de date sans utiliser .dt"""
    if pd.isna(value) or not date_format:
        return {}
    
    value = str(value)
    format_chars = list(date_format.lower())
    value_chars = list(value)
    
    # Aligner les caractères du format avec la valeur
    fmt_to_val = {}
    i = j = 0
    while i < len(format_chars) and j < len(value_chars):
        if format_chars[i] in ['d', 'm', 'y', 'h', 'm', 's']:
            fmt_to_val.setdefault(format_chars[i], []).append(value_chars[j])
            i += 1
            j += 1
        else:
            # Ignorer les séparateurs
            if value_chars[j] == format_chars[i]:
                i += 1
                j += 1
            else:
                j += 1
    
    # Extraire les composants demandés
    result = {}
    if 'y' in components and 'y' in fmt_to_val:
        year = ''.join(fmt_to_val['y'])
        result['year'] = int(year) if year.isdigit() else None
    
    if 'm' in components and 'm' in fmt_to_val:
        month = ''.join(fmt_to_val['m'])
        result['month'] = int(month) if month.isdigit() else None
    
    if 'd' in components and 'd' in fmt_to_val:
        day = ''.join(fmt_to_val['d'])
        result['day'] = int(day) if day.isdigit() else None
    
    if 'h' in components and 'h' in fmt_to_val:
        hour = ''.join(fmt_to_val['h'])
        result['hour'] = int(hour) if hour.isdigit() else None
    
    if 'm' in components and 'm' in fmt_to_val:
        minute = ''.join(fmt_to_val['m'])
        result['minute'] = int(minute) if minute.isdigit() else None
    
    if 's' in components and 's' in fmt_to_val:
        second = ''.join(fmt_to_val['s'])
        result['second'] = int(second) if second.isdigit() else None
    
    return result





def prepare_dataframe(columns, rows):
    """
    Convertit les données brutes en DataFrame pandas
    Args:
        columns: Liste des noms de colonnes
        rows: Liste de lignes (chaque ligne est un dictionnaire avec col0, col1, etc.)
    Returns:
        pd.DataFrame bien structuré
    """
    # Création d'un dictionnaire {nom_colonne: valeurs}
    data_dict = {
        col: [row.get(f"col{i}", None) for row in rows]
        for i, col in enumerate(columns)
    }
    return pd.DataFrame(data_dict)




