@router.post("/test-regex-pattern")
async def test_regex_pattern(
    request: dict,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Test a pattern with the SAME Python engine used by /regex-extract and predict replay.
    Returns coverage, matched samples, and unmatched samples.
    """
    try:
        from backend.regex_extract_engine import (
            RegexPatternError,
            count_capturing_groups,
            extract_from_text,
            extract_column_values,
            infer_validation_kind,
            validate_pattern_safety,
        )

        bd_name = (request.get("bdName") or "").lower()
        column_name = request.get("columnName")
        pattern = request.get("pattern") or ""
        case_insensitive = bool(request.get("caseInsensitive", False))
        sample_limit = max(1, min(int(request.get("sampleLimit", 8)), 50))
        extract_mode = (request.get("extractMode") or "first").lower()
        cast_numeric = bool(request.get("castNumeric", False))
        validate_kind = request.get("validateKind") or infer_validation_kind(
            request.get("presetId"), pattern
        )

        if not bd_name or not column_name or not pattern:
            raise HTTPException(400, "bdName, columnName and pattern are required")

        try:
            safe_pattern = validate_pattern_safety(pattern)
        except RegexPatternError as exc:
            raise HTTPException(400, str(exc)) from exc

        group_count = count_capturing_groups(safe_pattern)

        with get_db_connection() as conn:
            cur = conn.cursor()
            cur.execute("""
                SELECT 1 FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
            """, (bd_name, current_user_id))
            if not cur.fetchone():
                raise HTTPException(403, "Access denied")

            cur.execute("""
                SELECT column_name FROM information_schema.columns
                WHERE table_name = %s AND LOWER(column_name) = LOWER(%s)
            """, (bd_name, column_name))
            col_row = cur.fetchone()
            if not col_row:
                raise HTTPException(404, f"Column '{column_name}' not found")
            exact_col = col_row[0]

            cur.execute(
                sql.SQL("SELECT id, {col}::text FROM {table} ORDER BY id").format(
                    col=sql.Identifier(exact_col),
                    table=sql.Identifier(bd_name),
                )
            )
            rows = cur.fetchall()
            ids = [r[0] for r in rows]
            values = [r[1] for r in rows]

            result = extract_column_values(
                values,
                safe_pattern,
                case_insensitive=case_insensitive,
                extract_mode=extract_mode,
                cast_numeric=cast_numeric,
                validate_kind=validate_kind,
                normalize=True,
            )

            samples = []
            unmatched_samples = []
            for row_id, original, groups in zip(ids, values, result["rows"]):
                matched = any(
                    g is not None and str(g).strip() != "" and str(g) != "0"
                    for g in (groups or [])
                )
                # more reliable: re-check with extract_from_text matched flag
                one = extract_from_text(
                    original,
                    safe_pattern,
                    case_insensitive=case_insensitive,
                    extract_mode=extract_mode,
                    cast_numeric=cast_numeric,
                    validate_kind=validate_kind,
                    normalize=True,
                )
                if one["matched"]:
                    if len(samples) < sample_limit:
                        g_list = ["" if g is None else str(g) for g in (one["groups"] or [])]
                        samples.append({
                            "id": row_id,
                            "original": original,
                            "full_match": g_list[0] if g_list else None,
                            "groups": g_list,
                        })
                else:
                    if (
                        original is not None
                        and str(original).strip() != ""
                        and len(unmatched_samples) < sample_limit
                    ):
                        unmatched_samples.append({
                            "id": row_id,
                            "original": original,
                        })

            return {
                "status": "success",
                "engine": "python_re",
                "pattern": safe_pattern,
                "case_insensitive": case_insensitive,
                "extract_mode": extract_mode,
                "group_count": max(group_count, 1) if result["matched_rows"] else group_count,
                "capturing_groups": group_count,
                "total_rows": result["total_rows"],
                "matched_rows": result["matched_rows"],
                "unmatched_rows": result["unmatched_rows"],
                "match_pct": result["match_pct"],
                "invalid_count": result["invalid_count"],
                "invalid_rate": result["invalid_rate"],
                "validate_kind": validate_kind,
                "samples": samples,
                "unmatched_samples": unmatched_samples,
            }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Regex test failed: {e}")
        raise HTTPException(500, f"Regex test failed: {str(e)}")


@router.post("/regex-extract")
async def regex_extract(
    request: dict,
    current_user_id: str = Depends(get_current_user2)
):
    """
    Regex extraction via the unified Python engine (same as predict replay).
    Options: caseInsensitive, deleteSource (default False), castNumeric, extractMode,
    validateKind / presetId.
    """
    logger.info(f"Received regex-extract request: {request}")
    conn = None

    try:
        from backend.regex_extract_engine import (
            RegexPatternError,
            count_capturing_groups,
            extract_column_values,
            infer_validation_kind,
            normalize_international_number,
            validate_pattern_safety,
        )

        required_params = ["bdName", "columnName", "pattern"]
        missing_params = [p for p in required_params if p not in request]
        if missing_params:
            raise HTTPException(400, f"Missing parameters: {', '.join(missing_params)}")

        target_table = request["bdName"].lower()
        column_name = request["columnName"]
        pattern = request["pattern"]
        case_insensitive = bool(request.get("caseInsensitive", False))
        delete_source = bool(request.get("deleteSource", False))
        cast_numeric = bool(request.get("castNumeric", False))
        extract_mode = (request.get("extractMode") or "first").lower()
        if extract_mode not in ("first", "all_concat", "all_count"):
            extract_mode = "first"
        validate_kind = request.get("validateKind") or infer_validation_kind(
            request.get("presetId"), pattern
        )

        try:
            safe_pattern = validate_pattern_safety(pattern)
        except RegexPatternError as exc:
            raise HTTPException(400, str(exc)) from exc

        group_count = count_capturing_groups(safe_pattern)
        effective_groups = 1 if extract_mode == "all_count" else max(group_count, 1)

        with get_db_connection() as conn:
            cur = conn.cursor()

            cur.execute("""
                SELECT 1 FROM information_schema.tables WHERE table_name = %s
            """, (target_table,))
            if not cur.fetchone():
                raise HTTPException(404, f"Table '{target_table}' not found")

            cur.execute("""
                SELECT 1 FROM user_tables_metadata
                WHERE table_name = %s AND owner_id = %s
            """, (target_table, current_user_id))
            if not cur.fetchone():
                raise HTTPException(403, "Access denied to this table")

            cur.execute("""
                SELECT column_name FROM information_schema.columns
                WHERE table_name = %s AND LOWER(column_name) = LOWER(%s)
            """, (target_table, column_name))
            column_info = cur.fetchone()
            if not column_info:
                raise HTTPException(404, f"Column '{column_name}' not found")
            exact_column_name = column_info[0]

            output_columns = list(request.get("outputColumns") or [])
            if extract_mode == "all_count":
                if not output_columns:
                    output_columns = [f"{exact_column_name}_match_count"]
                else:
                    output_columns = output_columns[:1]
            else:
                if not output_columns:
                    output_columns = [
                        f"{exact_column_name}_group_{i+1}" for i in range(effective_groups)
                    ]
                else:
                    while len(output_columns) < effective_groups:
                        output_columns.append(
                            f"{exact_column_name}_group_{len(output_columns)+1}"
                        )
                    output_columns = output_columns[:effective_groups]

            # Fetch source values
            cur.execute(
                sql.SQL("SELECT id, {col}::text FROM {table} ORDER BY id").format(
                    col=sql.Identifier(exact_column_name),
                    table=sql.Identifier(target_table),
                )
            )
            db_rows = cur.fetchall()
            ids = [r[0] for r in db_rows]
            values = [r[1] for r in db_rows]

            result = extract_column_values(
                values,
                safe_pattern,
                case_insensitive=case_insensitive,
                extract_mode=extract_mode,
                cast_numeric=cast_numeric or extract_mode == "all_count",
                validate_kind=validate_kind,
                normalize=True,
                n_groups=effective_groups,
            )

            # Create output columns (TEXT first; cast later if needed)
            for col_name in output_columns:
                cur.execute(sql.SQL("""
                    ALTER TABLE {} ADD COLUMN IF NOT EXISTS {} TEXT
                """).format(
                    sql.Identifier(target_table),
                    sql.Identifier(col_name),
                ))

            # Batch update extracted values
            set_parts = [
                sql.SQL("{} = %s").format(sql.Identifier(c)) for c in output_columns
            ]
            update_sql = sql.SQL(
                "UPDATE {table} SET {sets} WHERE id = %s"
            ).format(
                table=sql.Identifier(target_table),
                sets=sql.SQL(", ").join(set_parts),
            )
            batch = []
            for row_id, groups in zip(ids, result["rows"]):
                cells = []
                for g in groups:
                    if g is None:
                        cells.append(None)
                    else:
                        cells.append(str(g))
                while len(cells) < len(output_columns):
                    cells.append(None)
                batch.append(tuple(cells[: len(output_columns)] + [row_id]))
            if batch:
                cur.executemany(update_sql.as_string(conn), batch)

            casted = []
            should_try_cast = cast_numeric or extract_mode == "all_count"
            if should_try_cast:
                for col_name in output_columns:
                    # Normalize international numbers in-place then cast when all numeric
                    cur.execute(
                        sql.SQL("SELECT id, {c}::text FROM {table} WHERE {c} IS NOT NULL").format(
                            c=sql.Identifier(col_name),
                            table=sql.Identifier(target_table),
                        )
                    )
                    col_rows = cur.fetchall()
                    numeric_ok = True
                    normalized_batch = []
                    nn = 0
                    for rid, raw in col_rows:
                        if raw is None or str(raw).strip() == "":
                            continue
                        nn += 1
                        # skip concat multi-values
                        if " | " in str(raw):
                            numeric_ok = False
                            break
                        num = normalize_international_number(raw)
                        if num is None:
                            numeric_ok = False
                            break
                        normalized_batch.append((str(num), rid))
                    if numeric_ok and nn > 0:
                        cur.executemany(
                            sql.SQL(
                                "UPDATE {table} SET {c} = %s WHERE id = %s"
                            ).format(
                                table=sql.Identifier(target_table),
                                c=sql.Identifier(col_name),
                            ).as_string(conn),
                            normalized_batch,
                        )
                        tmp = f"__tmp_cast_{abs(hash(col_name)) % 10**8}"
                        cur.execute(sql.SQL("""
                            ALTER TABLE {table} ADD COLUMN {tmp} DOUBLE PRECISION
                        """).format(
                            table=sql.Identifier(target_table),
                            tmp=sql.Identifier(tmp),
                        ))
                        cur.execute(sql.SQL("""
                            UPDATE {table}
                            SET {tmp} = NULLIF(BTRIM({c}::text), '')::double precision
                        """).format(
                            table=sql.Identifier(target_table),
                            tmp=sql.Identifier(tmp),
                            c=sql.Identifier(col_name),
                        ))
                        cur.execute(sql.SQL("""
                            ALTER TABLE {table} DROP COLUMN {c}
                        """).format(
                            table=sql.Identifier(target_table),
                            c=sql.Identifier(col_name),
                        ))
                        cur.execute(sql.SQL("""
                            ALTER TABLE {table} RENAME COLUMN {tmp} TO {c}
                        """).format(
                            table=sql.Identifier(target_table),
                            tmp=sql.Identifier(tmp),
                            c=sql.Identifier(col_name),
                        ))
                        casted.append(col_name)

            if delete_source and exact_column_name not in ("id", "split_type"):
                cur.execute(sql.SQL("""
                    ALTER TABLE {} DROP COLUMN IF EXISTS {}
                """).format(
                    sql.Identifier(target_table),
                    sql.Identifier(exact_column_name),
                ))

            cur.execute("""
                UPDATE user_tables_metadata
                SET columns = (
                    SELECT array_agg(column_name::text)
                    FROM information_schema.columns
                    WHERE table_name = %s
                    AND column_name != 'id'
                    AND column_name != 'split_type'
                ),
                updated_at = NOW()
                WHERE table_name = %s AND owner_id = %s
            """, (target_table, target_table, current_user_id))

            conn.commit()

            logger.info(
                "regex-extract metrics table=%s matched=%s/%s (%.2f%%) invalid=%s (%.2f%%) mode=%s",
                target_table,
                result["matched_rows"],
                result["total_rows"],
                result["match_pct"],
                result["invalid_count"],
                result["invalid_rate"],
                extract_mode,
            )

            return {
                "status": "success",
                "message": f"{len(output_columns)} column(s) created successfully",
                "engine": "python_re",
                "columns_created": output_columns,
                "pattern": safe_pattern,
                "extracted_groups": effective_groups,
                "target_table": target_table,
                "case_insensitive": case_insensitive,
                "extract_mode": extract_mode,
                "deleted_source": delete_source,
                "casted_numeric": casted,
                "validate_kind": validate_kind,
                "metrics": {
                    "total_rows": result["total_rows"],
                    "matched_rows": result["matched_rows"],
                    "unmatched_rows": result["unmatched_rows"],
                    "match_pct": result["match_pct"],
                    "invalid_count": result["invalid_count"],
                    "invalid_rate": result["invalid_rate"],
                    "affected_rows": result["matched_rows"],
                },
                "action": "updated_existing",
            }

    except HTTPException:
        raise
    except psycopg2.Error as e:
        if conn:
            try:
                conn.rollback()
            except Exception:
                pass
        logger.error(f"PostgreSQL error: {e.pgerror}")
        raise HTTPException(500, f"Database error: {e.pgerror}")
    except Exception as e:
        if conn:
            try:
                conn.rollback()
            except Exception:
                pass
        logger.error(f"Extraction error: {str(e)}")
        raise HTTPException(500, f"Extraction error: {str(e)}")

