from fastapi import Query, HTTPException, Depends
from pydantic import BaseModel
from typing import List, Dict, Any, Optional
import numpy as np
import re

class ColumnTypeResponse(BaseModel):
    column_name: str
    data_type: str  # 'numeric', 'categorical', 'text'
    unique_count: int
    total_rows: int
    unique_ratio: float
    sample_values: List[Any]
    has_nulls: bool
    null_count: int
    numeric_stats: Optional[Dict[str, float]] = None
    recommendation: str

